/// The repair horizon before this node has measured a repair (wave 5, W2):
/// a hole is published as a gap once it is this old.
const REPAIR_HORIZON_INITIAL_MS: u64 = 60;
/// The measured horizon (twice the 90th percentile of the repairs that this
/// node saw) is kept within these bounds, and never above the gap hold.
const REPAIR_HORIZON_MIN_MS: u64 = 10;
const REPAIR_HORIZON_MAX_MS: u64 = 250;
/// A part stored this soon after a later part is a reordering or the other
/// parent's copy, not a repair: it is not a repair delay. Two parents and
/// 1 % loss make many such fills of well under a millisecond, which would
/// otherwise hold the 90th percentile, and so the horizon, at the floor.
const REPAIR_REORDER_GRACE_US: u64 = 2_000;
/// The measured horizon is never shorter than the burst copy delay of the
/// long-haul lanes (`--relay-burst-copy-ms`) plus this: a part that a burst
/// took comes as its copy that much later, and must not be a gap by then.
const REPAIR_HORIZON_BURST_COPY_MARGIN_MS: u64 = 10;
/// Repairs that the measured horizon is computed from: the newest of them.
const REPAIR_DELAY_SAMPLES: usize = 128;
/// Gaps remembered for each stream's playlist: the oldest are forgotten.
const MAX_GAP_PARTS_PER_STREAM: usize = 4_096;
/// Wide holes a stream keeps on record (`LiveTsCache::wide_hole_resume`).
const WIDE_HOLE_RECORDS: usize = 8;

/// `--canonical-repair-horizon`: how long a hole may hold back the
/// contiguous watermark of a stream (the playlist and the cache-mesh push)
/// before the parts behind it are published and the hole is marked as a
/// gap. `Off` keeps the gap hold (`--canonical-gap-hold-ms`) as before.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepairHorizon {
    Off,
    /// Twice the repair delay that this node measures, within
    /// [`REPAIR_HORIZON_MIN_MS`, `REPAIR_HORIZON_MAX_MS`].
    Auto,
    Fixed(u64),
}

impl RepairHorizon {
    const OFF_CODE: u64 = u64::MAX;

    fn code(self) -> u64 {
        match self {
            Self::Off => Self::OFF_CODE,
            Self::Auto => 0,
            Self::Fixed(ms) => ms.clamp(1, Self::OFF_CODE - 1),
        }
    }

    fn from_code(code: u64) -> Self {
        match code {
            Self::OFF_CODE => Self::Off,
            0 => Self::Auto,
            ms => Self::Fixed(ms),
        }
    }

    fn as_str(self) -> String {
        match self {
            Self::Off => "off".into(),
            Self::Auto => "auto".into(),
            Self::Fixed(ms) => ms.to_string(),
        }
    }
}

impl std::str::FromStr for RepairHorizon {
    type Err = String;

    fn from_str(value: &str) -> std::result::Result<Self, Self::Err> {
        match value.trim() {
            "off" | "false" | "0" => Ok(Self::Off),
            "auto" | "true" => Ok(Self::Auto),
            ms => ms
                .parse::<u64>()
                .map(Self::Fixed)
                .map_err(|_| format!("expected auto, off or milliseconds, got {ms:?}")),
        }
    }
}

/// Told (stream, source epoch) when a stream takes up a source epoch.
type SourceEpochObserver = Arc<dyn Fn(u64, u64) + Send + Sync>;

/// The repair delays that a node has seen: for each part that arrived after
/// a later part of its stream, how long after that later part.
#[derive(Debug, Default)]
struct RepairDelays {
    samples_us: VecDeque<u64>,
    total: u64,
}

impl RepairDelays {
    fn record(&mut self, delay_us: u64) {
        if self.samples_us.len() == REPAIR_DELAY_SAMPLES {
            self.samples_us.pop_front();
        }
        self.samples_us.push_back(delay_us);
        self.total = self.total.saturating_add(1);
    }

    /// The 90th percentile of the newest samples.
    fn p90_us(&self) -> Option<u64> {
        if self.samples_us.is_empty() {
            return None;
        }
        let mut sorted: Vec<u64> = self.samples_us.iter().copied().collect();
        sorted.sort_unstable();
        let index = (sorted.len() * 9).div_ceil(10).saturating_sub(1);
        sorted.get(index).copied()
    }

    /// Twice the 90th percentile within the bounds, or the initial horizon.
    fn horizon_us(&self) -> u64 {
        match self.p90_us() {
            Some(p90_us) => p90_us
                .saturating_mul(2)
                .clamp(REPAIR_HORIZON_MIN_MS * 1_000, REPAIR_HORIZON_MAX_MS * 1_000),
            None => REPAIR_HORIZON_INITIAL_MS * 1_000,
        }
    }
}
const REPLICA_REQUEST_MIN_INTERVAL_MS: u64 = 1_000;
/// With --edge-hole-distance-ms, how long a waiting request waits before it
/// first asks the parents for a hole itself, the backstop of the trigger's
/// two looks: twice the distance (by then the trigger has asked one parent,
/// and is asking both), and at least the grace of the stream's parts. After
/// that first request it asks again every grace, as without the trigger.
fn edge_hole_backstop(distance: Duration, part_us: u64) -> Duration {
    distance
        .saturating_mul(2)
        .max(edge_hole_repair_grace(part_us))
}
/// Time an edge waits for a requested part that both parents normally deliver
/// within a millisecond of each other before it treats the part as a hole.
const EDGE_HOLE_REPAIR_GRACE_MS: u64 = 15;
/// How often a node of the cache network says hello to its peers. A parent
/// with media to send is heard with every datagram.
const CACHE_MESH_ANNOUNCE_MS: u64 = 100;
/// Default for --edge-parents-silent-ms. An edge that has heard none of its
/// parents for this long has lost them: its private network, or every
/// distributor. It answers 503 for a part or a playlist reload that it would
/// otherwise hold, so that a reader moves at once and does not wait out its
/// own timeout. It is above the canonical gap hold of a long-haul
/// distributor (400 ms in deploy, at most the 1 s default) plus a long-haul
/// round trip: 400 ms tripped while parents were alive but slow to decode,
/// and moved UDP clients between edges every few milliseconds.
const EDGE_PARENTS_SILENT_MS: u64 = 1_500;
/// Default of --client-udp-region-hold-ms (Phase AM item 11).
const DEFAULT_CLIENT_UDP_REGION_HOLD_MS: u64 = 2_000;
/// How long an answer of a failover region is reused (Phase AM item 11).
const FAILOVER_PROBE_CACHE: Duration = Duration::from_secs(1);
/// How long a failover region has to answer.
const FAILOVER_PROBE_TIMEOUT: Duration = Duration::from_millis(800);
/// Default of --edge-liveness-cache-us: far below the parents' silence that
/// counts, and long enough that a thousand requests a second ask the mesh
/// a few hundred times.
const DEFAULT_EDGE_LIVENESS_CACHE_US: u64 = 5_000;
/// The longest that a part request ahead of the stream waits at a time
/// with --edge-part-wait-due before it looks at the parents again.
const EDGE_PART_WAIT_SLICE_MS: u64 = 100;
/// Minimum time between two hole repair requests for one stream: ten parts
/// of the stream, from 5 ms up to this, and no less than one part of up to
/// 100 ms.
const EDGE_HOLE_REPAIR_MIN_INTERVAL_MS: u64 = 50;
/// Shortest interval between two hole repair requests for one stream.
const EDGE_HOLE_REPAIR_MIN_INTERVAL_FLOOR_US: u64 = 5_000;
/// Shortest grace before a missing part is a hole: both parents deliver
/// within about a millisecond of each other.
const EDGE_HOLE_REPAIR_MIN_GRACE_US: u64 = 3_000;
/// Most holes in a row that one repair request asks for.
const EDGE_HOLE_REPAIR_MAX_RUN: u32 = 64;

/// Time an edge waits for a part that is not here before it asks a parent
/// for it: three parts of the stream, from 3 ms to 15 ms. At 5 ms parts
/// that is the 15 ms that it always was; at 2.5 ms it is PART-HOLD-BACK.
fn edge_hole_repair_grace(part_us: u64) -> Duration {
    Duration::from_micros(part_us.saturating_mul(3).clamp(
        EDGE_HOLE_REPAIR_MIN_GRACE_US,
        EDGE_HOLE_REPAIR_GRACE_MS * 1_000,
    ))
}

/// How long a part request waits before it looks again for a hole to
/// repair (--edge-part-wait-due): a part that is not yet due (ahead of the
/// newest part `head`) until it is due, `seq - head` parts later, plus the
/// grace, and at most `slice`; a part behind the newest part (a hole) the
/// grace.
fn part_wait_until_due(
    head: Option<u64>,
    seq: u64,
    part_us: u64,
    grace: Duration,
    slice: Duration,
) -> Duration {
    match head {
        Some(head) if seq > head => {
            let due = Duration::from_micros((seq - head).saturating_mul(part_us.max(1)));
            due.saturating_add(grace).min(slice).max(grace)
        }
        _ => grace,
    }
}

/// Whether the parents are lost, as an edge last asked, and when.
#[derive(Debug)]
struct LivenessCache {
    ttl_us: u64,
    /// When the answer was taken (0: never), and the answer.
    asked_unix_us: AtomicU64,
    lost: AtomicBool,
}

impl LivenessCache {
    fn new(ttl_us: u64) -> Self {
        Self {
            ttl_us,
            asked_unix_us: AtomicU64::new(0),
            lost: AtomicBool::new(false),
        }
    }

    /// The answer, if it is at most the TTL old.
    fn get(&self, now_us: u64) -> Option<bool> {
        if self.ttl_us == 0 {
            return None;
        }
        let asked = self.asked_unix_us.load(Ordering::Acquire);
        (asked != 0 && now_us.saturating_sub(asked) < self.ttl_us)
            .then(|| self.lost.load(Ordering::Acquire))
    }

    fn set(&self, now_us: u64, lost: bool) {
        if self.ttl_us == 0 {
            return;
        }
        // The answer first, then its time: a reader that sees the new time
        // sees the new answer.
        self.lost.store(lost, Ordering::Release);
        self.asked_unix_us.store(now_us.max(1), Ordering::Release);
    }
}

/// Minimum time between two hole repair requests for a stream with parts
/// of `part_us`. 50 ms at 5 ms parts, as before; shorter for smaller parts,
/// whose holes come more often at the same loss.
fn edge_hole_repair_min_interval(part_us: u64) -> Duration {
    let interval_us = part_us
        .saturating_mul(10)
        .clamp(
            EDGE_HOLE_REPAIR_MIN_INTERVAL_FLOOR_US,
            EDGE_HOLE_REPAIR_MIN_INTERVAL_MS * 1_000,
        )
        .max(part_us.min(100_000));
    Duration::from_micros(interval_us)
}

/// Parts of `part_us` in the hole repair window, at least two.
fn edge_hole_repair_window_parts(part_us: u64) -> usize {
    usize::try_from((EDGE_HOLE_REPAIR_WINDOW_MS * 1_000 / part_us.max(1)).max(2))
        .unwrap_or(usize::MAX)
}
/// A parent answers a repair request with every part from the hole to its
/// newest part. Holes older than this window are left to the once-a-second
/// replica request, so one repair answer stays small.
const EDGE_HOLE_REPAIR_WINDOW_MS: u64 = 500;
/// How often an edge looks for playlists whose readers have gone.
const PLAYLIST_DEMAND_SWEEP_MS: u64 = 500;
/// --cache-mesh-warm-total-kbps (wave 8 stage 5, AM 13): a distributor's
/// warm-up windows together, twice one child's default allowance.
const DEFAULT_CACHE_MESH_WARM_TOTAL_KBPS: u64 = 40_000;
/// A hole that holds the contiguous watermark longer than this counts as a
/// watermark stall (the repair horizon's clamp, AM 13 / R5).
const WATERMARK_STALL_US: u64 = 250_000;
/// Longest wait for the first parts of a playlist that an edge has just
/// subscribed to, before it answers the request that created the demand.
const PLAYLIST_WARM_WAIT_MS: u64 = 4_000;
