const MAX_TIMED_HOP_JOURNAL_CAPACITY: usize = 1 << 20;

/// Capacity of a hop journal that holds `seconds` of parts of `part_us`:
/// never less than the fixed default of 262,144 events, which was sized for
/// 200 parts a second, and never more than about 90 MB of events.
fn hop_journal_capacity_for(part_us: u64, seconds: u64) -> usize {
    let parts_per_second = 1_000_000_u64.div_ceil(part_us.max(1));
    let events = parts_per_second
        .saturating_mul(HOP_JOURNAL_EVENTS_PER_PART)
        .saturating_mul(seconds);
    usize::try_from(events)
        .unwrap_or(usize::MAX)
        .clamp(DEFAULT_HOP_JOURNAL_CAPACITY, MAX_TIMED_HOP_JOURNAL_CAPACITY)
}
/// Shortest stretch of a playlist over which its bit rate is measured. A
/// copy that is still warming holds a second or less, and one key frame in
/// that second reads as a much higher rate than the stream has.
const MIN_BITRATE_WINDOW_MS: u64 = 4_000;
/// How often a node without its own measurement of a playlist asks what
/// rate the region advertises for it.
const PLAYLIST_RATE_LOOKUP_INTERVAL_MS: u64 = 500;
/// Requests a second that one worker thread of a small node is charged for.
/// Measured on a 1 vCPU node: forty readers of 5 ms parts, 8,080 requests a
/// second over HTTP/2 and TLS, took 76% of the processor, and sixty readers
/// all stalled. With 8,000 and admission at 85% a node admits 33 such
/// readers, which leaves room for readers on far paths, who cost more, and
/// for the connections of a crowd.
const DEFAULT_REQUESTS_PER_WORKER: u64 = 8_000;
/// How long an entry point uses one reading of the advertisements of its
/// region.
const REGIONAL_VIEW_TTL: Duration = Duration::from_millis(100);
/// Edges of a region that hold a playlist while it has readers.
const DEFAULT_PLAYLIST_COPIES: usize = 2;
/// An edge that holds this many playlists takes no standby copy: the slots
/// that are left are for playlists that its own readers ask for.
const STANDBY_PLAYLIST_LIMIT: usize = 10;

/// The standby limit of an edge that holds at most `max_playlists`.
fn standby_playlist_limit(max_playlists: usize) -> usize {
    (max_playlists * STANDBY_PLAYLIST_LIMIT / MAX_EDGE_PLAYLISTS).max(1)
}
/// A stream that has had no part for this long gives up its playlist slot
/// to a new stream when the node is full.
const STREAM_SLOT_IDLE_MS: u64 = 10_000;
/// Playlist slots of the live cache of a node, unless `--playlist-slots`
/// says otherwise.
const DEFAULT_PLAYLIST_SLOTS: usize = 16;
/// Most playlists that an edge holds for its readers at one time, with the
/// default number of slots. One slot is the default stream of the node.
const MAX_EDGE_PLAYLISTS: usize = DEFAULT_PLAYLIST_SLOTS - 1;
/// Segments that the playlist of a stamped stream holds at least: six whole
/// segments, which a player that does not use parts needs, and the open one.
const PLAYLIST_WINDOW_SEGMENTS: u64 = 7;
/// Fewest parts in the playlist window of a stream whose parts are longer
/// than the nominal part of the node.
const MIN_STREAM_WINDOW_PARTS: usize = 32;
/// Sessions whose assigned cache an entry point remembers.
const MAX_REMEMBERED_ASSIGNMENTS: usize = 50_000;
/// How long an entry point remembers the cache of a session that is silent.
const REMEMBERED_ASSIGNMENT_MS: u64 = 120_000;

/// Wave 9 C4: movers are apportioned against those an entry point placed
/// in this window (a paced drain sends its movers over 2 s), at most this
/// many remembered.
const RECENT_MOVERS_WINDOW: Duration = Duration::from_secs(5);
const MAX_RECENT_MOVERS: usize = 4_096;

/// Wave 9 C4: pending readers are kept this long at most (longer than any
/// egress window counts them).
const PENDING_LOAD_KEEP: Duration = Duration::from_secs(60);
const MESH_EVENTS_PATH: &str = "/api/mesh/events";
/// What one UDP listener costs an edge of `region` (permille), as the
/// rebalance reckons it (wave 9 C1): the median of load over UDP
/// subscribers among the region's edges with at least 4 subscribers.
/// `None` when no edge has that many.
fn region_listener_permille(snapshots: &[MeshSnapshot], region: &str) -> Option<f64> {
    let mut costs = snapshots
        .iter()
        .filter(|snapshot| snapshot.node.region == region)
        .filter_map(|snapshot| {
            let edge = snapshot.edge_service.as_ref()?;
            let subscribers = edge.udp_subscribers.filter(|count| *count >= 4)?;
            (edge.cache_mesh_role == "edge" && edge.load_permille > 0)
                .then(|| f64::from(edge.load_permille) / subscribers as f64)
        })
        .collect::<Vec<_>>();
    if costs.is_empty() {
        return None;
    }
    costs.sort_by(f64::total_cmp);
    Some(costs[costs.len() / 2])
}

