#[derive(Debug, Clone, PartialEq, Eq)]
struct AudioEpochDatagram {
    session_id: Option<u64>,
    bytes: Bytes,
}

fn parse_audio_epoch_subscription(payload: &[u8]) -> Option<Option<u64>> {
    if payload == AUDIO_EPOCH_SUBSCRIPTION {
        return Some(None);
    }
    let session = payload.strip_prefix(AUDIO_EPOCH_SUBSCRIPTION_V2_PREFIX)?;
    let session = std::str::from_utf8(session).ok()?;
    if session.is_empty() || !session.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    session.parse().ok().map(Some)
}

fn parse_native_audio_session_message(payload: &[u8], prefix: &[u8]) -> Option<u64> {
    let session = payload.strip_prefix(prefix)?;
    let session = std::str::from_utf8(session).ok()?;
    if session.is_empty() || !session.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    session.parse().ok()
}

#[derive(Debug, Clone, Copy)]
struct NativeAudioSubscription {
    session_id: Option<u64>,
    expires_at: Instant,
}

#[derive(Debug, Default)]
struct NativeAudioRelay {
    subscriptions: HashMap<SocketAddr, NativeAudioSubscription>,
}

impl NativeAudioRelay {
    fn has_subscriptions(&self) -> bool {
        !self.subscriptions.is_empty()
    }

    fn expire(&mut self, now: Instant) {
        self.subscriptions
            .retain(|_, subscription| subscription.expires_at > now);
    }

    async fn handle_control(
        &mut self,
        socket: &UdpSocket,
        peer: SocketAddr,
        payload: &[u8],
    ) -> bool {
        if payload == NATIVE_AUDIO_SUBSCRIBE {
            self.subscriptions.insert(
                peer,
                NativeAudioSubscription {
                    session_id: None,
                    expires_at: Instant::now() + NATIVE_AUDIO_SUBSCRIPTION_TTL,
                },
            );
            if let Err(error) = socket.send_to(NATIVE_AUDIO_SUBSCRIBE_ACK, peer).await {
                warn!(peer = %peer, error = %error, "failed to acknowledge native audio relay subscription");
            }
            return true;
        }
        if let Some(session_id) =
            parse_native_audio_session_message(payload, NATIVE_AUDIO_SUBSCRIBE_V2_PREFIX)
        {
            self.subscriptions.insert(
                peer,
                NativeAudioSubscription {
                    session_id: Some(session_id),
                    expires_at: Instant::now() + NATIVE_AUDIO_SUBSCRIPTION_TTL,
                },
            );
            let mut ack = Vec::with_capacity(NATIVE_AUDIO_SUBSCRIBE_ACK_V2_PREFIX.len() + 20);
            ack.extend_from_slice(NATIVE_AUDIO_SUBSCRIBE_ACK_V2_PREFIX);
            ack.extend_from_slice(session_id.to_string().as_bytes());
            if let Err(error) = socket.send_to(&ack, peer).await {
                warn!(peer = %peer, session_id, error = %error, "failed to acknowledge session-scoped native audio relay subscription");
            }
            return true;
        }
        if payload.starts_with(NATIVE_AUDIO_SUBSCRIBE_V2_PREFIX) {
            warn!(peer = %peer, "ignored malformed session-scoped native audio relay subscription");
            return true;
        }
        if payload == NATIVE_AUDIO_UNSUBSCRIBE {
            self.subscriptions.remove(&peer);
            return true;
        }
        if let Some(session_id) =
            parse_native_audio_session_message(payload, NATIVE_AUDIO_UNSUBSCRIBE_V2_PREFIX)
        {
            if self
                .subscriptions
                .get(&peer)
                .is_some_and(|subscription| subscription.session_id == Some(session_id))
            {
                self.subscriptions.remove(&peer);
            }
            return true;
        }
        if payload.starts_with(NATIVE_AUDIO_UNSUBSCRIBE_V2_PREFIX) {
            warn!(peer = %peer, "ignored malformed session-scoped native audio relay unsubscription");
            return true;
        }
        false
    }

    fn forward(&self, socket: &UdpSocket, datagram: &[u8], session_id: Option<u64>) {
        for (target, subscription) in &self.subscriptions {
            if subscription.session_id.is_some() && subscription.session_id != session_id {
                continue;
            }
            match socket.try_send_to(datagram, *target) {
                Ok(sent) if sent == datagram.len() => {}
                Ok(sent) => warn!(
                    target = %target,
                    sent,
                    expected = datagram.len(),
                    "native audio relay sent a partial datagram"
                ),
                Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                    debug!(target = %target, "native audio relay skipped a datagram under socket backpressure");
                }
                Err(error) => {
                    warn!(target = %target, error = %error, "native audio relay send failed")
                }
            }
        }
    }
}
// Canonical envelopes are fully authenticated and validated before entering
// the live cache. Retain the exact envelope after a fixed index so retries
// still compare every canonical byte, while hot LL-HLS reads can return a
// checked Bytes slice instead of decoding, allocating, and hashing the object
// again for every customer. The slot is built and read by
// `av_mesh::canonical_slot`, which the fast-lane UDP client runs too.
use av_mesh::canonical_slot::{
    encode_canonical_live_slot, LiveMediaKind, CANONICAL_LIVE_SLOT_HEADER_LEN,
    CANONICAL_LIVE_SLOT_MAGIC, MESH_FMP4_SLOT_HEADER_LEN, MESH_FMP4_SLOT_MAGIC,
};
const TELEMETRY_TAG: [u8; 4] = *b"AVMT";
const CONTROL_TAG: [u8; 4] = *b"AVMC";
const DEFAULT_TELEMETRY_STALE_MS: u64 = 30_000;
/// The most that the clock of a node is taken to be wrong by. A first
/// advertisement that says it is older than this is old.
const MAX_CLOCK_ERROR_MS: u64 = 60_000;
const RAW_MESH_MAX_FRAME_BYTES: usize = 16 * 1024 * 1024;
const MESH_STORAGE_WARN_PCT: u64 = 85;
const MESH_STORAGE_ERROR_PCT: u64 = 95;
const MESH_MIN_STALE_INGEST_ALERT_MS: u64 = 5_000;
const MESH_STREAM_LAG_WARN_PARTS: u64 = 6;
const CANONICAL_EPOCH_ACTIVATION_WARN_US: u64 = 10_000_000;
const RELAY_PROCESSING_P95_WARN_US: u64 = 1_000;
const MESH_ACTIVITY_LIMIT: usize = 64;
const EDGE_RECENT_RESPONSE_LIMIT: usize = 32;
const EDGE_RECENT_SUCCESS_INTERVAL_MS: u64 = 100;
const EDGE_RESPONSE_DURATION_BUCKETS_US: [u64; 13] = [
    100, 250, 500, 1_000, 2_500, 5_000, 10_000, 25_000, 50_000, 100_000, 250_000, 500_000,
    1_000_000,
];
const PUBLICATION_AVAILABILITY_BUCKETS_US: [u64; 16] = [
    1_000, 2_500, 5_000, 10_000, 25_000, 50_000, 75_000, 100_000, 125_000, 150_000, 175_000,
    200_000, 250_000, 500_000, 1_000_000, 2_000_000,
];

fn is_multichannel_audio_transport_datagram(datagram: &[u8]) -> bool {
    datagram.starts_with(MULTICHANNEL_AUDIO_TRANSPORT_MAGIC)
}

enum LiveSlotPayload {
    Fmp4 { init: Option<Bytes>, media: Bytes },
    Opaque { media: Bytes, kind: LiveMediaKind },
    Invalid,
}

impl LiveSlotPayload {
    fn decode(payload: Bytes) -> Self {
        Self::decode_inner(payload, None)
    }

    fn decode_for_stream(payload: Bytes, stream_id: u64) -> Self {
        Self::decode_inner(payload, Some(stream_id))
    }

    fn decode_inner(payload: Bytes, expected_stream_id: Option<u64>) -> Self {
        if payload.starts_with(CANONICAL_LIVE_SLOT_MAGIC) {
            return Self::decode_canonical_live_slot(payload, expected_stream_id)
                .unwrap_or(Self::Invalid);
        }
        if payload.starts_with(&WIRE_MAGIC) {
            let Ok(object) = media_object::decode(&payload) else {
                return Self::Invalid;
            };
            if expected_stream_id
                .is_some_and(|stream_id| object.key().stream() != stream_id.to_string())
            {
                return Self::Invalid;
            }
            let is_fmp4 = object
                .metadata()
                .get("container")
                .is_some_and(|container| container.as_slice() == b"fmp4");
            let is_fmp4_slot = object
                .metadata()
                .get("payload-format")
                .is_some_and(|format| format.as_slice() == b"fmp4-slot-v1");
            let is_opaque = object
                .metadata()
                .get("container")
                .is_some_and(|container| container.as_slice() == b"opaque")
                && object
                    .metadata()
                    .get("payload-format")
                    .is_some_and(|format| format.as_slice() == b"opaque-part-v1");
            let object_payload = Bytes::copy_from_slice(object.payload());
            return match object.kind() {
                ObjectKind::Media if is_fmp4 && is_fmp4_slot => {
                    Self::decode_fmp4_slot(object_payload).unwrap_or(Self::Invalid)
                }
                ObjectKind::Media if is_fmp4 => Self::Fmp4 {
                    init: None,
                    media: object_payload,
                },
                ObjectKind::Media if is_opaque => Self::Opaque {
                    media: object_payload,
                    kind: LiveMediaKind::Opaque,
                },
                ObjectKind::Media => Self::Opaque {
                    media: object_payload,
                    kind: LiveMediaKind::Ts,
                },
                ObjectKind::Initialization | ObjectKind::CodecConfiguration if is_fmp4 => {
                    Self::Fmp4 {
                        init: Some(object_payload),
                        media: Bytes::new(),
                    }
                }
                ObjectKind::Initialization
                | ObjectKind::CodecConfiguration
                | ObjectKind::Discontinuity => Self::Invalid,
            };
        }
        Self::decode_fmp4_slot(payload.clone()).unwrap_or(Self::Opaque {
            media: payload,
            kind: LiveMediaKind::Ts,
        })
    }

    fn decode_canonical_live_slot(payload: Bytes, expected_stream_id: Option<u64>) -> Option<Self> {
        let view =
            av_mesh::canonical_slot::decode_canonical_live_slot(&payload, expected_stream_id)?;
        match view.kind {
            LiveMediaKind::Fmp4 => Some(Self::Fmp4 {
                init: view.init,
                media: view.media,
            }),
            kind => Some(Self::Opaque {
                media: view.media,
                kind,
            }),
        }
    }

    fn decode_fmp4_slot(payload: Bytes) -> Option<Self> {
        let (media, init) = av_mesh::canonical_slot::decode_fmp4_slot(&payload)?;
        Some(Self::Fmp4 { init, media })
    }

    fn media_kind(&self) -> LiveMediaKind {
        match self {
            Self::Fmp4 { .. } => LiveMediaKind::Fmp4,
            Self::Opaque { kind, .. } => *kind,
            Self::Invalid => LiveMediaKind::Ts,
        }
    }

    fn init(&self) -> Option<Bytes> {
        match self {
            Self::Fmp4 { init, .. } => init.clone(),
            Self::Opaque { .. } | Self::Invalid => None,
        }
    }

    fn media(&self) -> Bytes {
        match self {
            Self::Fmp4 { media, .. } => media.clone(),
            Self::Opaque { media, .. } => media.clone(),
            Self::Invalid => Bytes::new(),
        }
    }

    fn has_media(&self) -> bool {
        match self {
            Self::Fmp4 { media, .. } => !media.is_empty(),
            Self::Opaque { media, .. } => !media.is_empty(),
            Self::Invalid => false,
        }
    }
}

#[derive(Debug)]
struct ReboxedLiveAudio {
    init: Bytes,
    media: Bytes,
    /// Duration of the part in microseconds, from the sample counts and
    /// the sample rate of its SoundKit frames.
    duration_us: u32,
}

fn rebox_soundkit_v2_bundle(payload: &[u8], sequence: u64) -> Result<ReboxedLiveAudio> {
    if payload.len() < SOUNDKIT_V2_BUNDLE_HEADER_LEN
        || !payload.starts_with(SOUNDKIT_V2_BUNDLE_MAGIC)
    {
        bail!("Soundkit v2 bundle has an invalid header");
    }
    let codec = match payload[8] {
        1 => SoundKitFmp4Codec::Flac,
        2 => SoundKitFmp4Codec::Opus,
        tag => bail!("Soundkit v2 bundle has unsupported codec tag {tag}"),
    };
    let epoch_count = u64::from_be_bytes(payload[9..17].try_into().unwrap());
    let base_group_id = u16::from_be_bytes(payload[17..19].try_into().unwrap());
    let track_count = u16::from_be_bytes(payload[19..21].try_into().unwrap());
    if epoch_count == 0 || track_count == 0 {
        bail!("Soundkit v2 bundle declares no epochs or tracks");
    }
    if track_count != 1 {
        bail!(
            "Soundkit v2 HLS publication currently requires one track per canonical stream; bundle has {track_count}"
        );
    }

    let mut offset = SOUNDKIT_V2_BUNDLE_HEADER_LEN;
    let mut framed = Vec::new();
    // The samples and sample rate of the epochs, from the SoundKit frame
    // header that starts each of them.
    let mut bundle_samples = 0_u64;
    let mut sample_rate = 0_u32;
    for epoch in 0..epoch_count {
        let entry_header_end = offset
            .checked_add(6)
            .context("Soundkit v2 bundle entry header overflow")?;
        if entry_header_end > payload.len() {
            bail!("Soundkit v2 bundle ended before epoch {epoch}");
        }
        let group_id = u16::from_be_bytes(payload[offset..offset + 2].try_into().unwrap());
        let frame_len =
            u32::from_be_bytes(payload[offset + 2..entry_header_end].try_into().unwrap()) as usize;
        if group_id != base_group_id {
            bail!("Soundkit v2 bundle epoch {epoch} changed group identity");
        }
        offset = entry_header_end;
        let frame_end = offset
            .checked_add(frame_len)
            .context("Soundkit v2 bundle frame length overflow")?;
        if frame_end > payload.len() {
            bail!("Soundkit v2 bundle epoch {epoch} frame is truncated");
        }
        if let Ok(header) = FrameHeaderV2::decode(&mut &payload[offset..frame_end]) {
            let frame_count = u64::from(header.frame_count());
            bundle_samples = bundle_samples.saturating_add(frame_count);
            if sample_rate == 0 {
                sample_rate = header.sample_rate();
            }
            // The fMP4 boxer writes FLAC on a millisecond clock, each frame
            // rounded to a whole millisecond: a 2.5 ms frame becomes 3 ms and
            // the parts overlap. Refuse it rather than publish that timeline.
            // Opus is on a 48 kHz clock and is made exact below.
            let rate = u64::from(header.sample_rate());
            if codec == SoundKitFmp4Codec::Flac
                && rate > 0
                && !frame_count.saturating_mul(1_000).is_multiple_of(rate)
            {
                bail!(
                    "Soundkit v2 FLAC frames of {frame_count} samples at {rate} Hz are not a whole \
                     millisecond; the fMP4 boxer keeps FLAC on a millisecond clock"
                );
            }
        }
        framed.extend_from_slice(&payload[offset..frame_end]);
        offset = frame_end;
    }
    if offset != payload.len() {
        bail!("Soundkit v2 bundle has trailing bytes");
    }

    // The publication timeline: every part of the stream holds as many
    // samples as this one. A bundle whose frame headers cannot be read keeps
    // the old timeline of 5 ms epochs.
    let start_pts_ms = if bundle_samples > 0 && sample_rate > 0 {
        sequence
            .checked_mul(bundle_samples)
            .and_then(|samples| samples.checked_mul(1_000))
            .map(|millis| millis / u64::from(sample_rate))
    } else {
        sequence
            .checked_mul(epoch_count)
            .and_then(|value| value.checked_mul(SOUNDKIT_V2_EPOCH_DURATION_MS))
    }
    .context("Soundkit v2 publication timeline overflow")?;
    let reboxed = rebox_soundkit_v2(
        &framed,
        ReboxOptions {
            sequence: u32::try_from(sequence).context("fMP4 sequence exceeds u32")?,
            include_init: true,
            start_pts_ms: Some(start_pts_ms),
        },
    )
    .map_err(|error| anyhow!("Soundkit v2 rebox failed: {error}"))?;
    if reboxed.codec != codec {
        bail!(
            "Soundkit v2 bundle codec {} disagrees with framed codec {}",
            codec.name(),
            reboxed.codec.name()
        );
    }
    let mut media = reboxed.media;
    if codec == SoundKitFmp4Codec::Opus && bundle_samples > 0 && sample_rate > 0 {
        // The boxer takes the start in whole milliseconds and puts the
        // first packet at that millisecond on its 48 kHz clock, so 2.5 ms
        // parts would start at 0, 2, 5, 7 ms and overlap or leave gaps. The
        // packet durations it writes are exact samples; the start is set
        // here to the exact sample of the part.
        let decode_time =
            u128::from(sequence) * u128::from(bundle_samples) * 48_000 / u128::from(sample_rate);
        let decode_time =
            u64::try_from(decode_time).context("Soundkit v2 publication timeline overflow")?;
        let mut patched = media.to_vec();
        set_fmp4_base_media_decode_time(&mut patched, decode_time)?;
        media = Bytes::from(patched);
    }
    Ok(ReboxedLiveAudio {
        init: reboxed
            .init
            .context("Soundkit v2 rebox did not return fMP4 initialization")?,
        duration_us: soundkit_duration_us(reboxed.frame_count, reboxed.sample_rate)
            .unwrap_or_else(|| reboxed.duration_ms.saturating_mul(1_000)),
        media,
    })
}

/// The boxes directly inside `data`, as (type, start of the box, start of
/// its payload, end of the box).
fn fmp4_child_boxes(data: &[u8]) -> Result<Vec<([u8; 4], usize, usize, usize)>> {
    let mut boxes = Vec::new();
    let mut offset = 0;
    while offset < data.len() {
        let header = data
            .get(offset..offset + 8)
            .context("fMP4 box header is truncated")?;
        let size32 = u32::from_be_bytes(header[..4].try_into().unwrap()) as usize;
        let kind: [u8; 4] = header[4..8].try_into().unwrap();
        let (size, payload) = match size32 {
            0 => (data.len() - offset, offset + 8),
            1 => {
                let large = data
                    .get(offset + 8..offset + 16)
                    .context("fMP4 large box header is truncated")?;
                (
                    usize::try_from(u64::from_be_bytes(large.try_into().unwrap()))
                        .context("fMP4 box is too large")?,
                    offset + 16,
                )
            }
            size => (size, offset + 8),
        };
        let end = offset.checked_add(size).context("fMP4 box size overflow")?;
        if size < payload - offset || end > data.len() {
            bail!(
                "fMP4 box {} has an invalid size",
                String::from_utf8_lossy(&kind)
            );
        }
        boxes.push((kind, offset, payload, end));
        offset = end;
    }
    Ok(boxes)
}

/// Set the baseMediaDecodeTime of every `tfdt` of an fMP4 fragment.
fn set_fmp4_base_media_decode_time(media: &mut [u8], decode_time: u64) -> Result<()> {
    let mut patched = 0;
    for (kind, _, moof_payload, moof_end) in fmp4_child_boxes(media)? {
        if &kind != b"moof" {
            continue;
        }
        for (kind, _, traf_payload, traf_end) in fmp4_child_boxes(&media[moof_payload..moof_end])? {
            if &kind != b"traf" {
                continue;
            }
            let traf = moof_payload + traf_payload..moof_payload + traf_end;
            for (kind, _, payload, end) in fmp4_child_boxes(&media[traf.clone()])? {
                if &kind != b"tfdt" {
                    continue;
                }
                let tfdt = &mut media[traf.start + payload..traf.start + end];
                match tfdt.first() {
                    Some(0) if tfdt.len() >= 8 => {
                        let value = u32::try_from(decode_time)
                            .context("fMP4 decode time does not fit a version 0 tfdt")?;
                        tfdt[4..8].copy_from_slice(&value.to_be_bytes());
                    }
                    Some(1) if tfdt.len() >= 12 => {
                        tfdt[4..12].copy_from_slice(&decode_time.to_be_bytes());
                    }
                    _ => bail!("fMP4 tfdt is malformed"),
                }
                patched += 1;
            }
        }
    }
    if patched == 0 {
        bail!("fMP4 fragment has no tfdt");
    }
    Ok(())
}

/// `samples` at `sample_rate` in microseconds, rounded: 120 samples at
/// 48 kHz are 2500 µs. `None` for no samples or no rate.
fn soundkit_duration_us(samples: u64, sample_rate: u32) -> Option<u32> {
    let sample_rate = u64::from(sample_rate);
    if samples == 0 || sample_rate == 0 {
        return None;
    }
    let us = samples
        .saturating_mul(1_000_000)
        .saturating_add(sample_rate / 2)
        / sample_rate;
    u32::try_from(us).ok()
}

/// A stored part slot as a reader takes it: its media, the slot's hash, its
/// kind and its init segment. `None` for a slot without media.
fn decode_part_slot(
    stream_id: u64,
    bytes: Bytes,
    hash: u64,
) -> Option<(Bytes, u64, LiveMediaKind, Option<Bytes>)> {
    let slot = LiveSlotPayload::decode_for_stream(bytes, stream_id);
    slot.has_media()
        .then(|| (slot.media(), hash, slot.media_kind(), slot.init()))
}

fn encode_fmp4_slot(init: &[u8], media: &[u8]) -> Result<Bytes> {
    let init_len = u32::try_from(init.len()).context("fMP4 init is too large")?;
    let media_len = u32::try_from(media.len()).context("fMP4 fragment is too large")?;
    let mut slot = BytesMut::with_capacity(MESH_FMP4_SLOT_HEADER_LEN + init.len() + media.len());
    slot.put_slice(MESH_FMP4_SLOT_MAGIC);
    slot.put_u32(init_len);
    slot.put_u32(media_len);
    slot.put_slice(init);
    slot.put_slice(media);
    Ok(slot.freeze())
}

fn decode_canonical_stream_object(payload: &[u8]) -> Result<Option<MediaObject>> {
    if !payload.starts_with(&WIRE_MAGIC) {
        return Ok(None);
    }
    media_object::decode(payload)
        .map(Some)
        .context("invalid canonical media-object envelope")
}

#[derive(Debug, Clone, Parser)]
#[command(
    name = "av-mesh",
    version = av_mesh::build::VERSION,
    about = "Run a local AV mesh node"
)]
struct Args {
    #[arg(long, default_value = "uk")]
    region: String,

    #[arg(long)]
    node_id: Option<String>,

    #[arg(long, default_value = "127.0.0.1:9101")]
    mesh_bind: SocketAddr,

    /// A cache-mesh peer, as host:port of its --mesh-bind. The mesh takes
    /// datagrams only from authorized peers: the peers listed here and those
    /// that private-subnet discovery adds. A node that is not listed is not
    /// learned from its hello, so a distributor lists its edges and an edge
    /// lists its distributors.
    #[arg(long = "peer")]
    peers: Vec<String>,

    #[arg(long, default_value_t = DEFAULT_MESH_SYNC_INTERVAL_MS)]
    mesh_sync_interval_ms: u64,

    /// Part events that the hop journal keeps in memory and serves on
    /// /api/hops. Zero turns the journal off. Unset, the journal holds
    /// --hop-journal-seconds of parts of --part-us (see
    /// `hop_journal_capacity_for`).
    #[arg(long, env = "NEEDLETAIL_HOP_JOURNAL_CAPACITY")]
    hop_journal_capacity: Option<usize>,

    /// Seconds of parts that the hop journal holds when
    /// --hop-journal-capacity is not given.
    #[arg(
        long,
        env = "NEEDLETAIL_HOP_JOURNAL_SECONDS",
        default_value_t = DEFAULT_HOP_JOURNAL_SECONDS
    )]
    hop_journal_seconds: u64,

    /// Events that the stall journal keeps in memory and serves on
    /// /api/stalls: the times a tick thread woke late, a class thread's
    /// pass, wake or batch was late, a tee lagged or a send was slow, each
    /// dated and with its cause (see `stall_journal`). Zero turns the
    /// journal and its tick threads off.
    #[arg(
        long,
        env = "NEEDLETAIL_STALL_JOURNAL_CAPACITY",
        default_value_t = stall_journal::DEFAULT_CAPACITY
    )]
    stall_journal_capacity: usize,

    /// The period in microseconds of the stall journal's tick threads: one
    /// thread on each CPU the process may run on, at normal scheduling,
    /// that sleeps to a deadline every period and books how late it woke.
    /// Zero starts none; the journal then holds no tick, and nothing in it
    /// can be told to be a stopped CPU.
    #[arg(
        long,
        env = "NEEDLETAIL_STALL_TICK_US",
        default_value_t = stall_journal::DEFAULT_TICK_US
    )]
    stall_tick_us: u64,

    /// Forward a RelaySession datagram to every downstream child with a
    /// non-blocking send first, and wait only for the children whose socket
    /// was full. `false` awaits each child's send in turn.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_FORWARD_NONBLOCKING",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_forward_nonblocking: bool,

    /// Hand a datagram to every child that shares a source socket (children
    /// given the same non-zero --relay-forward bind) in one `sendmmsg` call,
    /// and replay warm sources to a promoted child the same way. Children
    /// with binds of their own keep one send each, since a child knows its
    /// parent by the source address. Applies with
    /// --relay-forward-nonblocking. Inert when no two children share a bind,
    /// as in the Linode deploy, which gives every carrier link its own
    /// (ECMP-hunted) source port: /api/mesh reports
    /// mesh_transport.fast_path.relay_forward_batch_effective.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_FORWARD_BATCH",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_forward_batch: bool,

    /// SO_BUSY_POLL budget in µs for the sockets that receive media: the
    /// relay ingest sockets and the cache-mesh socket. 0 (the default)
    /// turns it off. The node receives after epoll reports a socket
    /// readable, so the budget only adds one NAPI poll to the last receive
    /// of each drain; the wait busy-polls only when the host sets
    /// net.core.busy_poll (reported as host_busy_poll_us). Kept for a lab
    /// A/B; no gain has been measured. Raising it needs CAP_NET_ADMIN; a
    /// refusal is reported in /api/mesh (mesh_transport.fast_path) and the
    /// node runs without it.
    #[arg(
        long,
        env = "NEEDLETAIL_BUSY_POLL_US",
        default_value_t = fast_path::DEFAULT_BUSY_POLL_US
    )]
    busy_poll_us: u32,

    /// Run the relay ingest and the cache mesh on a runtime of one thread
    /// pinned to this CPU, apart from the readers and the rest of the node.
    /// Unset, they share the main runtime as before.
    #[arg(long, env = "NEEDLETAIL_MEDIA_CPU")]
    media_cpu: Option<usize>,

    /// Run the RelaySession ingest of a relay or distributor (a node with
    /// --relay-controlled-local) on the fast plane: one OS thread per
    /// traffic class owns its receive sockets and forwards each symbol to
    /// the children before anything decodes it; a tokio tee behind it
    /// validates, decodes and commits. Audio streams arrive on the relay
    /// ports, video streams on the ports plus --relay-class-port-offset, so
    /// a 4K object never holds an audio symbol back. `false` keeps the
    /// single receive loop that decodes before it forwards.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_CLASS_THREADS",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_class_threads: bool,

    /// Port offset of the video class: a node with --relay-class-threads
    /// takes video streams on its relay ports plus this, and sends a
    /// child's video to the child's port plus this. Every node of a mesh
    /// uses the same offset. 0 keeps one port per relay socket.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_CLASS_PORT_OFFSET",
        default_value_t = DEFAULT_CLASS_PORT_OFFSET
    )]
    relay_class_port_offset: u16,

    /// CPUs of the fast-plane threads as `AUDIO,VIDEO` (for example `0,1`).
    /// Empty leaves them unpinned, which a shared host (the namespace lab)
    /// needs; the Linode deploy pins them.
    #[arg(long, env = "NEEDLETAIL_RELAY_CLASS_CPUS", default_value = "", value_parser = parse_class_cpus)]
    relay_class_cpus: ClassCpus,

    /// Run the audio fast-plane thread at SCHED_FIFO 10 and the video one at
    /// nice -10. Without the privilege they run as normal threads, which the
    /// node says once at start.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_CLASS_REALTIME",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_class_realtime: bool,

    /// Wave 8: when the audio class thread is refused SCHED_FIFO (no
    /// CAP_SYS_NICE, as in the local namespace lab), every other thread of
    /// the process is made this much nicer, so that the ingest still comes
    /// first, as at real-time priority on a deployed node. 0 (default):
    /// off, all at the process's nice value, as before (wave 8 review:
    /// under overload it cost parts, 9.4 k missing against 2.0 k, and a
    /// deployed node at real-time priority never takes this path, so a
    /// lab A/B with it measures a setup no node runs).
    #[arg(long, env = "NEEDLETAIL_RELAY_CLASS_FALLBACK_NICE", default_value_t = 0)]
    relay_class_fallback_nice: i32,

    /// SO_BUSY_POLL, in µs, on the audio fast-plane thread's receive
    /// sockets (forwarders and edges): with the host's net.core.busy_poll
    /// above zero, the thread's poll() polls the device queue for that long
    /// before it sleeps, instead of waiting for the interrupt and the
    /// wake-up (`relay_first -> relay_woken` in the hop journal). An A/B
    /// for a lab (wave 5, W1): it spends a CPU on the audio thread while it
    /// polls. Above net.core.busy_read it needs CAP_NET_ADMIN; a refusal is
    /// logged once and the sockets run without it. 0 (the default) leaves
    /// busy polling off.
    #[arg(long, env = "NEEDLETAIL_FAST_BUSY_POLL_US", default_value_t = 0)]
    fast_busy_poll_us: u32,

    /// The video fast-plane thread hands each child a batch's 4K symbols as
    /// UDP GSO messages (UDP_SEGMENT, up to 64 symbols in one pass through
    /// the stack) instead of one send per symbol per child. The per-symbol,
    /// per-child send was what saturated the relays at 25 Mbit/s 4K. A host
    /// without UDP GSO is detected on the first send and the thread goes on
    /// without it. `false` sends every symbol on its own.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_VIDEO_GSO",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_video_gso: bool,

    /// Wave 9 D: the video fast-plane sockets take UDP GRO. A parent's GSO
    /// burst (a 4K part's symbols, up to 64 in one message) reaches the
    /// socket as one receive message that the thread cuts into its symbols,
    /// instead of one queue entry, one segmentation and one copy per symbol;
    /// on a NIC, its GRO joins a flow's symbols of one interrupt the same way.
    /// A host that refuses it is logged once per socket and reads one symbol
    /// per message. `false`: one datagram per message, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_VIDEO_GRO",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_video_gro: bool,

    /// Burst copies on the long-haul lanes (wave 5, W2): the audio
    /// fast-plane thread sends every audio source symbol that it forwards
    /// to a compiled child (--relay-forward: the long-haul forwarders, a
    /// relay's distributors) once more, this many milliseconds later, so
    /// that a burst of loss shorter than that cannot take a part (its
    /// source and the repair right behind it) at the next forwarder. The
    /// child drops the copy of a symbol that came. Costs the audio sources
    /// again on those lanes; lease children (edges) get no copy. 0: no
    /// copies. Needs --relay-class-threads.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_BURST_COPY_MS",
        default_value_t = fast_plane::burst_copy::DEFAULT_BURST_COPY_MS
    )]
    relay_burst_copy_ms: u64,

    /// Wave 7 item 2: a repair-lane child of the fast plane (a compiled
    /// child given `:repair`) takes the source symbol of a one-symbol audio
    /// object as well. The contributor sends a 1 ms part as one symbol with
    /// no repair on a clean path; without this the repair lane carries
    /// nothing of it, and the long-haul child has one parent's copy only.
    /// `false`: repair only, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_REPAIR_LANE_SINGLE_SYMBOL",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_repair_lane_single_symbol: bool,

    /// Wave 7 review: the one symbol that a repair-lane child takes of a
    /// one-symbol audio object (--relay-repair-lane-single-symbol) gets the
    /// burst copy too (--relay-burst-copy-ms later), as the source lane's
    /// does. Before wave 7 a long-haul child got four copies of a 1 ms part
    /// (the source and its burst copy from one first forwarder, two
    /// contributor repair copies from the other); with copies sized to the
    /// contributor lanes' loss (none on a clean VLAN) it got three, and
    /// nothing sizes them to the long haul's loss. This keeps four, with
    /// time diversity on both paths. `false`: no burst copy on the repair
    /// lane.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_REPAIR_LANE_BURST_COPY",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_repair_lane_burst_copy: bool,

    /// Wave 7 item 2: the audio fast-plane thread measures the loss of each
    /// parent lane whose parent sends ledgers (RLL1, the contributor: the
    /// datagrams it sent on the lane), less this node's own receive-queue
    /// drops, and reports it to the parent (RLR1 version 2, 16 bytes: when
    /// it changes, and once a second while ledgers arrive, zero included).
    /// The contributor sizes the copies of a one-symbol audio part to it
    /// (av-contrib --relay-audio-copies measured). Needs
    /// --relay-class-threads.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_LOSS_REPORT",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_loss_report: bool,

    /// Wave 7 item 5: renditions of one source, `;`-separated groups of
    /// `,`-separated stream ids (the DAW lane's FLAC, Opus and PCM from base
    /// stream 2001 are "2001,3001,4001"). A forwarder sends a rendition of a
    /// group on a compiled (long-haul) lane only when the child's subtree
    /// reads it, reads no rendition of the group (a source nobody reads
    /// stays live), or has not reported its demand for 2 s (fails open).
    /// The contributor takes the same flag for its own lanes. Empty (the
    /// default for now): nothing is held back. Not yet the default: the
    /// first reader of a held rendition waited 3.8 s for its first part in
    /// London, and in New York joined at the stale head of the held stream
    /// and counted every part since as missing.
    #[arg(long, env = "NEEDLETAIL_RELAY_DEMAND_RENDITIONS", default_value = "")]
    relay_demand_renditions: fast_plane::demand::RenditionGroups,

    /// Wave 7 item 5: report this node's demand to its relay parents every
    /// 250 ms (RLD1: the streams that its cache-mesh children lease, that
    /// it subscribes to, and that its compiled children report). Needs
    /// --relay-class-threads.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_DEMAND_REPORT",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_demand_report: bool,

    /// Wave 8 review (F-I1): an edge, or a forwarder slot
    /// (--cache-mesh-upstream-demand), sends RLD1 demand reports to its
    /// relay parents too. Their parents are lease parents, whose
    /// --relay-lease-bind sockets only send: the reports queued there until
    /// the kernel dropped them (the referee's UdpRcvbufErrors at every
    /// dist-a), and a lease parent knows its children's demand from their
    /// cache-mesh leases anyway. `false` (default): only a node whose relay
    /// parents are compiled (long-haul) parents reports.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_DEMAND_REPORT_LEASE_PARENTS",
        default_value_t = false,
        action = clap::ArgAction::Set
    )]
    relay_demand_report_lease_parents: bool,

    /// Wave 8 review (F-I1): a forwarder reads and counts whatever arrives
    /// on its --relay-lease-bind sockets (fast_plane.lease_children.inbound
    /// in /api/stats), so that nothing queues there. `false`: nothing reads
    /// them, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_LEASE_DRAIN_INBOUND",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_lease_drain_inbound: bool,

    /// Datagrams each class's tee holds before the fast plane drops its tee
    /// copy (counted as tee_dropped; forwarding is never held back).
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_CLASS_TEE_CAPACITY",
        default_value_t = fast_plane::relay::DEFAULT_TEE_CAPACITY
    )]
    relay_class_tee_capacity: usize,

    /// MiB of the video class's tee ring, which a 4K stream's symbols fill
    /// by their bytes long before its entries run out at the old 16 MB.
    /// Its first 16 MB (--relay-class-tee-capacity x 256 B) is pinned at
    /// start with the other rings; the rest is faulted in and locked off
    /// the class thread when the first video datagram comes, so a node
    /// that carries no video never holds it.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_VIDEO_TEE_MB",
        default_value_t = fast_plane::relay::DEFAULT_VIDEO_TEE_BYTES >> 20
    )]
    relay_video_tee_mb: usize,

    /// Milliseconds of its stream that a video RelaySession socket of the
    /// fast plane holds: once a second its receive buffer grows to this
    /// long of the busiest second it has had, from --udp-socket-buffer-bytes
    /// up to --relay-video-socket-buffer-max-mb, and never shrinks. The 8
    /// MiB default held 0.3 s at 247 Mbit/s of 4K, less than a stalled
    /// node's class thread is away. Past net.core.rmem_max it needs
    /// CAP_NET_ADMIN. 0 leaves the sockets as made.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_VIDEO_SOCKET_BUFFER_MS",
        default_value_t = fast_plane::relay::DEFAULT_VIDEO_SOCKET_BUFFER_MS
    )]
    relay_video_socket_buffer_ms: u64,

    /// MiB a video socket's receive buffer may be asked for at most (the
    /// kernel books twice that in buffer memory while it is full).
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_VIDEO_SOCKET_BUFFER_MAX_MB",
        default_value_t = fast_plane::relay::DEFAULT_VIDEO_SOCKET_BUFFER_MAX_BYTES >> 20
    )]
    relay_video_socket_buffer_max_mb: usize,

    /// Feed every cache-mesh playlist lease that this node serves on the
    /// fast plane as well: a forwarder with --relay-class-threads sends the
    /// contributor's RLS1 symbols of a leased stream to the child (an edge)
    /// as they arrive, after its compiled children, from
    /// --relay-lease-bind. Audio in full to every child, video in full to
    /// --relay-lease-primary-children and as repair to the others. Inert
    /// without --relay-lease-bind. `false` leaves the edges to the cache
    /// mesh alone.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_LEASE_CHILDREN",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_lease_children: bool,

    /// Wave 7 item 4: what a forwarder still pushes over the cache mesh of
    /// an audio stream to a lease child that its fast plane feeds the
    /// stream (an edge takes the contributor's RLS1 symbols from both of
    /// its forwarders already). `none` (the default): no live push of
    /// such a pair; the edge keeps its lease, its warm-up window and its
    /// hole repair (replica requests). `secondary`: only the edge's
    /// secondary forwarder pushes. `all`: every leased pair is pushed, as
    /// before. Video streams follow --cache-mesh-fast-plane-video-push.
    /// Inert without lease children.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_FAST_PLANE_PUSH",
        value_enum,
        default_value_t = CacheMeshFastPlanePush::Nothing
    )]
    cache_mesh_fast_plane_push: CacheMeshFastPlanePush,

    /// Wave 8 stage 3: the same for a video stream. An edge with a lease at
    /// both of its forwarders took a 4K stream four ways: the primary's
    /// RLS1 sources and the secondary's repair on the fast plane, and a
    /// full cache-mesh push from each forwarder (3.6 times the stream on
    /// its link; at 160-247 Mbit/s every edge dropped at its cache-mesh
    /// video socket, as the referee's did in wave 7). `none` (the default):
    /// no live push of a video stream to an edge that the fast plane feeds
    /// it to; the edge has the primary's sources and the secondary's repair,
    /// its failover promotes the secondary's sources when the primary goes
    /// silent, and its hole repair (replica requests) and warm-up window
    /// stay. `secondary`: the forwarder that feeds the edge the sources (its
    /// primary, or one whose failover promoted it) does not push; the other,
    /// which feeds it repair only, does. `all`: as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_FAST_PLANE_VIDEO_PUSH",
        value_enum,
        default_value_t = CacheMeshFastPlanePush::Nothing
    )]
    cache_mesh_fast_plane_video_push: CacheMeshFastPlanePush,

    /// Source address of the symbols to lease children (an audio socket
    /// and its video twin on it): each edge binds it as its parent
    /// (--relay-primary-peer or --relay-secondary-peer).
    #[arg(long, env = "NEEDLETAIL_RELAY_LEASE_BIND")]
    relay_lease_bind: Option<SocketAddr>,

    /// A lease child's RLS1 ports as `PRIMARY,SECONDARY`: the first when
    /// this node is the child's primary forwarder, the second when it is its
    /// secondary. Video goes to each plus --relay-class-port-offset.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_LEASE_CHILD_PORTS",
        default_value = "22001,22002",
        value_parser = fast_plane::lease::parse_child_ports
    )]
    relay_lease_child_ports: [u16; 2],

    /// The lease children (by address) that this node is the primary
    /// forwarder for: they take video streams in full, the other children
    /// take their repair until they promote this node (RLF1 to
    /// --relay-lease-failover-bind).
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_LEASE_PRIMARY_CHILDREN",
        value_delimiter = ','
    )]
    relay_lease_primary_children: Vec<std::net::IpAddr>,

    /// Lease children fed at most; further children are refused, logged and
    /// counted, and keep the cache mesh.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_MAX_LEASE_CHILDREN",
        default_value_t = fast_plane::lease::DEFAULT_MAX_LEASE_CHILDREN
    )]
    relay_max_lease_children: usize,

    /// Where the failover controllers of lease children promote this node
    /// for their video (RLF1); the child is the controller's address.
    #[arg(long, env = "NEEDLETAIL_RELAY_LEASE_FAILOVER_BIND")]
    relay_lease_failover_bind: Option<SocketAddr>,

    /// Wave 8 stage 5 (AM 12): a lease child's Subscribe says where this
    /// forwarder stands in the child's ranking of the playlist's parents;
    /// rank 0 makes it the child's primary for that stream (video in full,
    /// the first child port), any other rank its secondary. So an edge's
    /// fast-plane parents follow its ranking of the live distributors,
    /// stream by stream, a joining distributor slot included. A lease
    /// without a rank keeps --relay-lease-primary-children. `false`
    /// (default): the fixed list decides, as before. Off by default (wave 8
    /// review): an edge's failover controller watches its primary socket,
    /// not each parent, and promotes its one configured secondary, so with
    /// the ranked rule a killed rank-0 parent left its streams' video as
    /// repair alone for 2-3.7 s (another parent's rank-0 streams kept the
    /// socket busy). Audio goes in full to every lease child either way.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_LEASE_RANKED",
        default_value_t = false,
        action = clap::ArgAction::Set
    )]
    relay_lease_ranked: bool,

    /// Wave 8 stage 5 (AM 12): an edge with --relay-controlled-local admits
    /// the RelaySession symbols of every distributor among its cache-mesh
    /// --peer addresses, at the port of its primary parent (every
    /// forwarder's --relay-lease-bind port), beside its two configured
    /// parents: a distributor that its ranking makes a parent of a stream
    /// (a slot that joined) feeds it on the fast plane. `false` admits the
    /// two configured parents alone, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_RANKED_PARENTS",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_ranked_parents: bool,

    /// Wave 8 stage 5 (AM 12): a distributor whose relay parents are lease
    /// parents (a forwarder slot, dist-c: a fast-plane lease child of its
    /// region's dist-a and dist-b) subscribes at its cache-mesh parent
    /// distributors (its non-edge --peer addresses) to every playlist that
    /// its own children lease from it, and keeps the subscription while
    /// they do (--cache-mesh-demand-idle-ms after the last). Its parents'
    /// fast planes then feed it each stream as they feed an edge. Off by
    /// default: a distributor of the contributor's lanes or of the
    /// compiled relay tree must never subscribe to its peers.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_UPSTREAM_DEMAND",
        default_value_t = false,
        action = clap::ArgAction::Set
    )]
    cache_mesh_upstream_demand: bool,

    /// An edge (--cache-mesh-role edge) with --relay-controlled-local takes
    /// its parents' RelaySession symbols on the fast plane: the class
    /// threads on its relay ports, a tee that commits each object into the
    /// edge's cache with the forwarders' own commit (byte for byte the part
    /// the cache mesh carries), beside the cache mesh. `false` runs the edge
    /// on the cache mesh alone: its relay flags are ignored.
    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_FAST_INGEST",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    edge_fast_ingest: bool,

    /// Split the cache mesh by class: video playlists' parts travel on a
    /// second socket at the mesh port plus this offset, with receive and
    /// sync tasks of their own, so a 4K part never holds an audio part
    /// back. A stream is video when it arrived on a video relay port, had a
    /// video object, or came over a parent's class socket. Every node of a
    /// mesh uses the same offset. 0 keeps one socket.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_CLASS_PORT_OFFSET",
        default_value_t = DEFAULT_CLASS_PORT_OFFSET
    )]
    cache_mesh_class_port_offset: u16,

    #[arg(long, default_value_t = DEFAULT_MESH_FEC_REPAIR_SYMBOLS)]
    mesh_repair_symbols: u32,

    #[arg(long, default_value_t = DEFAULT_MESH_FEC_REPAIR_RATIO)]
    mesh_repair_ratio: f32,

    #[arg(long, default_value_t = DEFAULT_MESH_FEC_MAX_REPAIR_SYMBOLS)]
    mesh_max_repair_symbols: u32,

    #[arg(long, default_value_t = DEFAULT_MESH_FEC_SYMBOL_SIZE)]
    mesh_symbol_size: u16,

    /// Largest cache-mesh symbol for a large object. A part that needs more
    /// than 64 symbols of --mesh-symbol-size uses a multiple of it, up to
    /// this size. Zero keeps one symbol size for every object.
    #[arg(long, env = "NEEDLETAIL_MESH_MAX_SYMBOL_SIZE", default_value_t = 0)]
    mesh_max_symbol_size: u16,

    #[cfg(feature = "private-subnet-discovery")]
    #[arg(long)]
    private_subnet_discovery: bool,

    #[cfg(feature = "private-subnet-discovery")]
    #[arg(long, default_value_t = 12345)]
    private_discovery_broadcast_port: u16,

    #[cfg(feature = "private-subnet-discovery")]
    #[arg(long)]
    private_discovery_mesh_port: Option<u16>,

    #[arg(long, default_value = "127.0.0.1:12001")]
    fec_bind: SocketAddr,

    /// Requested receive and send buffer size for high-rate UDP ingest sockets.
    /// The effective size can be clamped by host kernel limits and is reported
    /// at startup.
    #[arg(
        long,
        env = "NEEDLETAIL_UDP_SOCKET_BUFFER_BYTES",
        default_value_t = DEFAULT_UDP_SOCKET_BUFFER_BYTES
    )]
    udp_socket_buffer_bytes: usize,

    /// Enable deterministic direct-UDP RelaySession qualification. The peer
    /// address bindings below identify controlled endpoints and derive bounded
    /// object announcements from the first validated symbol.
    #[arg(long)]
    relay_controlled_local: bool,

    #[arg(long)]
    relay_primary_peer: Option<SocketAddr>,

    /// Primary RelaySession receive socket. During the transition this equals
    /// `--fec-bind`, so RLS1 and legacy RQD2 coexist on the first socket.
    #[arg(long)]
    relay_primary_bind: Option<SocketAddr>,

    #[arg(long)]
    relay_secondary_peer: Option<SocketAddr>,

    /// Independent secondary repair-lane receive socket owned by the same
    /// object assembler and LL-HLS cache.
    #[arg(long)]
    relay_secondary_bind: Option<SocketAddr>,

    #[arg(long, default_value = "av-contrib-primary")]
    relay_primary_id: String,

    /// Admit source plus repair intent on a fully seeded primary relationship.
    /// This is used by a warm backbone relay that can be activated immediately.
    #[arg(long)]
    relay_primary_promoted: bool,

    #[arg(long, default_value = "av-contrib-secondary")]
    relay_secondary_id: String,

    /// Admit both source and repair intent on the warm secondary carrier while
    /// it is fully seeded for immediate promotion.
    #[arg(long)]
    relay_secondary_promoted: bool,

    #[arg(long, default_value_t = 1)]
    relay_topology_generation: u64,

    #[arg(long, default_value_t = 1)]
    relay_subscription_id: u64,

    /// The media budget, in milliseconds. A part's deadline is a point on
    /// the timeline of its stream, never compared with this node's clock: a
    /// part is shed when the head of its stream here has passed its deadline
    /// by this much (a sender that was frozen and has resumed), and a stream
    /// that arrives late as a whole is taken. A source datagram held back
    /// from a warm child is kept this long from its receipt.
    #[arg(long, default_value_t = DEFAULT_RELAY_MEDIA_DEADLINE_MS)]
    relay_media_deadline_ms: u64,

    /// Forward newly admitted RelaySession symbols to one subscribed child.
    /// Repeat as `BIND=TARGET,ROLE`, where ROLE is source, repair, or all. Each
    /// child gets a stable source socket and an explicit compiled symbol lane.
    #[arg(long = "relay-forward", value_parser = parse_relay_forward_endpoint)]
    relay_forwards: Vec<RelayForwardEndpoint>,

    /// Controlled-private qualification listener for leased warm-secondary
    /// promotion. Repeat as `BIND=CONTROLLER_PEER,FORWARD_TARGET`. Public
    /// deployments carry the same command on an authenticated control stream.
    #[arg(
        long = "relay-failover-listener",
        value_parser = parse_relay_failover_listener_endpoint
    )]
    relay_failover_listeners: Vec<RelayFailoverListenerEndpoint>,

    /// Edge-side controlled-private failover controller as `BIND=TARGET`.
    #[arg(
        long = "relay-failover-controller",
        value_parser = parse_relay_failover_controller_endpoint
    )]
    relay_failover_controller: Option<RelayFailoverControllerEndpoint>,

    /// Promote the warm secondary after this much primary-source silence.
    #[arg(long, default_value_t = DEFAULT_RELAY_PRIMARY_SILENCE_MS)]
    relay_primary_silence_ms: u64,

    /// Keep both source paths active for this continuous primary recovery
    /// window before demoting the warm secondary.
    #[arg(long, default_value_t = DEFAULT_RELAY_PRIMARY_RECOVERY_MS)]
    relay_primary_recovery_ms: u64,

    /// Maximum age of a repair symbol that proves the secondary is warm.
    #[arg(long, default_value_t = DEFAULT_RELAY_SECONDARY_WARM_MS)]
    relay_secondary_warm_ms: u64,

    /// Wave 8 stage 3 (S6): a lane switch must not double video in a loop.
    /// A promotion of the warm secondary sends the child the sources from
    /// both parents until the primary has been back for
    /// --relay-primary-recovery-ms, which loads both parents and the child;
    /// a primary that stalls again and again (an overloaded forwarder) would
    /// switch each time. With this flag each promotion within the last 30 s
    /// doubles the primary silence that the next one needs (at most 8 times
    /// --relay-primary-silence-ms); a promotion that waits is counted
    /// (deferred_promotions). The first promotion is as fast as before.
    /// `false` (default): every silence promotes, as before. Off by default
    /// (wave 8 review): S6 turned out not to be a repair storm, the backoff
    /// was never measured in a lab, and the referee's London pattern (three
    /// stalls of 568-695 ms in 30 s) would leave the third one, which needs
    /// 1 s of silence, as a whole video gap.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_FAILOVER_PROMOTION_BACKOFF",
        default_value_t = false,
        action = clap::ArgAction::Set
    )]
    relay_failover_promotion_backoff: bool,

    #[arg(long, default_value_t = DEFAULT_RELAY_FAILOVER_HEARTBEAT_MS)]
    relay_failover_heartbeat_ms: u64,

    #[arg(long, default_value_t = DEFAULT_RELAY_FAILOVER_LEASE_MS)]
    relay_failover_lease_ms: u64,

    /// Hard fanout bound for explicitly compiled downstream subscriptions.
    #[arg(
        long,
        default_value_t = DEFAULT_MAX_RELAY_DOWNSTREAM_CHILDREN
    )]
    relay_max_downstream_children: usize,

    #[arg(long, default_value = "127.0.0.1:12101")]
    media_fec_bind: SocketAddr,

    /// Serve clients RaptorQ FEC UDP on this address: every part that this
    /// node's cache holds, as LL-HLS serves it (see `client_udp`). Every
    /// node of a region uses the same port; the assignment API names it.
    #[arg(long)]
    client_udp_bind: Option<SocketAddr>,

    /// RaptorQ symbol size of the client UDP datagrams.
    #[arg(long, default_value_t = av_mesh::client_udp::DEFAULT_SYMBOL_SIZE)]
    client_udp_symbol_size: u16,

    /// Forward the parts that reach this node over the cache mesh to its UDP
    /// clients as their datagrams arrive (`true`), or only once each part is
    /// in the cache (`false`).
    #[arg(long, default_value_t = true, action = clap::ArgAction::Set)]
    client_udp_cut_through: bool,

    /// Run the edge's cut-through on a thread of its own per class, fed by
    /// a queue, instead of inline on the cache-mesh receive task. Off by
    /// default: with the class-split mesh the audio cut-through already has
    /// a receive task of its own, and the thread's wake-up added about
    /// 0.08 ms at the median to 2.5 ms Opus parts in the loopback test,
    /// where the cache-fed sender then often sends a one-symbol part first.
    /// Kept for a lab A/B of the first-run edge stalls under 4K load.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_CUT_THROUGH_THREAD",
        default_value_t = false,
        action = clap::ArgAction::Set
    )]
    client_udp_cut_through_thread: bool,

    /// Serve clients from a pair of sockets on the client port: audio
    /// streams from one at SO_PRIORITY 6, video streams from the other, so
    /// that a 4K burst never sits ahead of audio. Both read control. `false`
    /// keeps one socket.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_CLASS_SOCKETS",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_class_sockets: bool,

    /// Client UDP subscriptions that this node takes at most.
    #[arg(long, default_value_t = 4_096)]
    client_udp_max_subscribers: usize,

    /// A client datagram that finds the client socket full waits in a queue
    /// of its client for this long, and leaves when the socket can take it,
    /// instead of being dropped (or, for the cache-fed sender, holding up
    /// every client of the stream). Older ones are dropped and counted. 0
    /// is the behaviour from before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_SEND_QUEUE_MS",
        default_value_t = edge_udp::DEFAULT_SEND_QUEUE_MS
    )]
    client_udp_send_queue_ms: u64,

    /// Playout deadline of a client UDP subscriber: a part further than
    /// this behind the edge's newest part is too old to play. A subscriber
    /// that is further behind (after a move, or a backlog) jumps to the
    /// oldest part within it, and a hole is repaired only while it is
    /// within it, not for HOLE_WAIT each. 0 is the behaviour from before
    /// (resume anywhere in the window, wait HOLE_WAIT for each hole).
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_PLAYOUT_MS",
        default_value_t = edge_udp::DEFAULT_PLAYOUT_MS
    )]
    client_udp_playout_ms: u64,

    /// A client UDP subscriber that this edge took less than this long ago
    /// is not sent away because the edge lost its parents, and a client
    /// that this edge sent away for that reason and that comes back within
    /// it is taken: a client is not moved back and forth between edges
    /// that lost their parents together. 0 is the behaviour from before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_MOVE_HOLD_DOWN_MS",
        default_value_t = edge_udp::DEFAULT_MOVE_HOLD_DOWN_MS
    )]
    client_udp_move_hold_down_ms: u64,

    /// Hand the datagrams of a part for all of its UDP clients to the
    /// kernel in one sendmmsg, not one sendto each. `false` is the
    /// behaviour from before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_BATCH_SEND",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_batch_send: bool,

    /// A cut-through part of at most this many bytes has its client repair
    /// encoded and sent where it decoded (the cache-mesh receive task or the
    /// cut-through thread), not on a thread of the blocking pool woken for
    /// each part. 0 is the behaviour from before. Only with a send queue
    /// (--client-udp-send-queue-ms above 0): without one every part goes to
    /// the blocking pool, where a full socket may be waited on.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_INLINE_COMPLETE_BYTES",
        default_value_t = edge_udp::DEFAULT_INLINE_COMPLETE_BYTES
    )]
    client_udp_inline_complete_bytes: usize,

    /// With --client-udp-batch-send, a client's datagrams of a part leave
    /// as one UDP GSO message (UDP_SEGMENT): one pass through the kernel's
    /// stack for the part's repair instead of one per datagram. A host that
    /// refuses GSO is sent to without it. `false` is the behaviour from
    /// before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_GSO",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_gso: bool,

    /// The fast client lane: a node whose class threads take RelaySession
    /// symbols (an edge fed by the fast plane) sends each symbol on to the
    /// UDP clients that ask for it (`SUB ... F1`) as it arrives, the
    /// contributor's own RaptorQ datagram with its block id rewritten, from
    /// the same thread, in one sendmmsg per class per batch, and tops their
    /// repair up from the decoded object. The cache-fed lane keeps the init
    /// segment, older parts and gaps, and skips the parts the fast lane
    /// carried. While the lane runs, cut-through is off. `false` keeps the
    /// cache-fed lane (and cut-through) alone, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_FAST_LANE",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_fast_lane: bool,

    /// This edge's rank among the edges a client may move between: its own
    /// fast-lane repair takes repair ordinals 256 + 64 * rank onwards, apart
    /// from the contributor's and other edges'.
    #[arg(long, env = "NEEDLETAIL_CLIENT_UDP_EDGE_RANK", default_value_t = 0)]
    client_udp_edge_rank: u32,

    /// Pace each 4K client of the fast lane at this percent of its stream's
    /// rate (measured by the video thread from the symbols it takes): each
    /// client's symbols leave in GSO messages of about a millisecond of that
    /// rate, each with an earliest departure (SO_TXTIME), which the host's
    /// fq qdisc keeps, so a client gets a frame at its rate and not at the
    /// NIC's line rate. No timer runs on the thread. Other qdiscs send at
    /// once; audio is never paced. 0 sends video at once, as before. The
    /// default 600 % spreads a 60 fps frame over about 2.8 ms (125 %, the
    /// first default, over 13 ms: up to the delay bound later at every edge).
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_VIDEO_PACE_PERCENT",
        default_value_t = fast_plane::edge_clients::VideoPacing::default().percent
    )]
    client_udp_video_pace_percent: u32,

    /// A paced 4K message never departs later than this after the video
    /// thread hands it to the kernel: a burst above the pacing rate (a
    /// keyframe, a burst from upstream) is delayed at most this much
    /// (default 2 ms; it was 8).
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_VIDEO_PACE_MAX_MS",
        default_value_t = fast_plane::edge_clients::VideoPacing::default().max_delay_us / 1_000
    )]
    client_udp_video_pace_max_ms: u64,

    /// The compact client lane (`av_mesh::client_compact`): a client that
    /// asks for it (`SUB ... C<copies>.<window>.<repair>`) gets each part
    /// that fits one datagram as one compact datagram (20 bytes of header,
    /// no RaptorQ), with the copies and the repair across parts that it
    /// asks for, and the parts it asks for again (`NACK`) from the edge's
    /// ring. About 1.2x the source rate on a clean path instead of about
    /// 4x to 40x. `false` gives such a client the RaptorQ lane, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_COMPACT",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_compact: bool,

    /// Parts on the compact lane in the short form (wave 7 item 9) to the
    /// clients that ask for it (`C...7`): a 7-byte header (the flags in the
    /// first byte, the part number's low 16 bits and the publication time's
    /// low 24 bits) instead of 11. A 1 ms Opus part of 56 bytes is 91 bytes
    /// with IPv4 and UDP instead of 95. Gaps and window repair keep the long
    /// form; a client reads both. `false` sends every client the long form.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_COMPACT_SHORT_HEADER",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_compact_short_header: bool,

    /// A one-symbol part that the edge's fast plane decoded from repair
    /// alone (its source symbol was lost upstream) goes to the compact
    /// clients at once, made from the decoded envelope (low-latency wave 5
    /// review). `false` leaves it to the cache-fed lane, which goes part by
    /// part behind any hole, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_COMPACT_TOP_UP",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_compact_top_up: bool,
    /// The edge's fast lane marks its compact datagrams (a flag bit outside
    /// the canonical form), so that a client counts the parts of each lane
    /// (wave 6: the compact lane's reports said every part came cache-fed).
    /// `false` sends them unmarked, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_COMPACT_MARK_FAST_LANE",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_compact_mark_fast_lane: bool,

    /// Fan-out threads of the edge's audio class thread (wave 7 item 10):
    /// a batch of more than --client-udp-fanout-inline-sends sends to fast-
    /// lane clients goes to these threads, each with the sends of its own
    /// clients, and one that is a few batches behind has its sends shed
    /// (the cache-fed lane serves those parts) rather than hold the class
    /// thread: the ingest of the edge (and its LL-HLS commit) never drops a
    /// part because of the fan-out. 0 sends every batch from the class
    /// thread, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_FANOUT_THREADS",
        default_value_t = fast_plane::edge_clients::DEFAULT_FANOUT_THREADS
    )]
    client_udp_fanout_threads: usize,

    /// The most sends of a batch that the audio class thread makes itself
    /// with fan-out threads (a batch for a few clients needs no hand-off).
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_FANOUT_INLINE_SENDS",
        default_value_t = fast_plane::edge_clients::DEFAULT_FANOUT_INLINE_SENDS
    )]
    client_udp_fanout_inline_sends: usize,

    /// Wave 8 (B4): with fan-out threads, the audio class thread sends one
    /// shard of each handed-off batch itself (the batch splits threads + 1
    /// ways): those clients wait for no hand-off, and a batch wakes one
    /// thread fewer. `false`: every shard to the threads, as in wave 7.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_FANOUT_INLINE_SHARD",
        default_value_t = fast_plane::edge_clients::DEFAULT_FANOUT_INLINE_SHARD,
        action = clap::ArgAction::Set
    )]
    client_udp_fanout_inline_shard: bool,

    /// Wave 8: the nice value of the audio fan-out threads, above the
    /// runtime's threads (HTTP, SUB admission, NACK answers, the cache-fed
    /// lane) and below the real-time class thread. Where the kernel refuses
    /// it (no CAP_SYS_NICE), they keep the class thread's nice value, above
    /// the threads --relay-class-fallback-nice made nicer. 99: the process's
    /// own nice value, as in wave 7.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_FANOUT_NICE",
        default_value_t = fast_plane::edge_clients::DEFAULT_FANOUT_NICE,
        allow_negative_numbers = true
    )]
    client_udp_fanout_nice: i32,

    /// D 7.8 (the stall hunt's no_arena_warm arm): the MB of its heap that
    /// an edge's audio class thread grows, touches and gives back before it
    /// is made real-time (the fan-out fix's warm-up of its glibc arena). 0:
    /// no warm-up; `class_arena_warm_bytes` then reads 0. Nodes without the
    /// client fast lane warm nothing either way.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_CLASS_ARENA_WARM_MB",
        default_value_t = (fast_plane::edge_clients::CLASS_ARENA_WARM_BYTES >> 20) as u64
    )]
    relay_class_arena_warm_mb: u64,

    /// The fast lane sends from send-only twins of the client sockets (the
    /// same address, in their SO_REUSEPORT group) that the runtime watches
    /// for reading only (wave 7 item 10). A socket that the runtime watches
    /// for writing wakes it as the kernel frees each datagram sent: with
    /// hundreds of clients of 1 ms parts that cost the runtime's threads
    /// about as much as the sends. `false` sends from the client sockets,
    /// as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_SEND_TWINS",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_send_twins: bool,

    /// Time to first audio (wave 7 item 8): a UDP subscription is admitted
    /// as soon as the edge holds a part of the stream, woken by the part's
    /// arrival. `false` waits, as a playlist request does, until the edge's
    /// copy of the playlist is playable (a whole segment; up to 4 s for a
    /// copy that the subscription opened) and looks for a part every 20 ms,
    /// as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_ADMIT_ON_FIRST_PART",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_admit_on_first_part: bool,

    /// A new UDP subscriber gets the part it starts at (the newest) with its
    /// `OK`, not when the stream's sender next looks, which can be a part
    /// later (wave 7 item 8). `false` as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_FIRST_PART_AT_ONCE",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_first_part_at_once: bool,

    /// With --client-udp-admit-on-first-part: a UDP subscriber is admitted
    /// at the newest part only if it arrived at this edge within this many
    /// ms (or four of the stream's parts, if longer). A stale head (the last
    /// part before a rendition was held back, or before an earlier demand
    /// lapsed) is not a start: the subscription waits for a newer part, up
    /// to its 4 s, and only then takes the stale one (wave 7 review: a New
    /// York client joined at a head kept from before a hold and counted
    /// 34,662 parts missing). 0: any part, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_FRESH_HEAD_MS",
        default_value_t = edge_udp::DEFAULT_FRESH_HEAD_MS
    )]
    client_udp_fresh_head_ms: u64,

    /// Wave 8 S1: the audio class thread (real time) takes no lock that
    /// ordinary tasks hold. Its batches' window repair, which takes the
    /// subscriber table's lock, goes to a repair thread, and the NACK answers
    /// are collected under that lock and sent after it is released, so SUB
    /// admission, NACK storms and the cache-fed lane never hold the lock
    /// across sends while the class thread waits. `false`: the class thread
    /// runs its window repair itself and NACK answers are sent under the
    /// lock, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_REPAIR_THREAD",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_repair_thread: bool,

    /// Wave 8 S3: a burst of new UDP subscriptions (the start of a step, a
    /// region's clients moving at once) rebuilds the fast lane's client
    /// snapshot once a batch, not once a subscriber under the subscriber
    /// table's lock (each rebuild reads every subscriber), and admission
    /// does not log each subscription. `false`: one rebuild and log line
    /// per subscription, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_BATCHED_ADMISSION",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_batched_admission: bool,

    /// Wave 8 S2: a client that moves here from another edge resumes at the
    /// part that it names while this edge's cache holds it, even if it is
    /// older than the playout deadline (--client-udp-playout-ms): the parts
    /// it lost to the old edge's stall come late, not missing. `false`:
    /// such a client resumes at the oldest part within the deadline, as
    /// before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_RESUME_FROM_REQUEST",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_resume_from_request: bool,

    /// Wave 8: the NACKed parts a second that an edge answers at most, all
    /// its clients together (each client also has its own budget). A NACK
    /// storm from the clients of an overloaded edge (parts late or shed)
    /// must not take the CPU that its sends need. 0: no cap, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_NACK_EDGE_RATE",
        default_value_t = edge_udp::DEFAULT_NACK_EDGE_RATE
    )]
    client_udp_nack_edge_rate: u32,

    /// Wave 9 (cold start): the stream's UDP sender keeps the playlist's
    /// demand without waiting for this edge's copy to be playable. Its first
    /// look used to wait, up to 4 s, for a whole segment as an LL-HLS
    /// reader's first playlist request does, and on an edge taking a new
    /// copy the parts between a new subscriber's first part and the fast
    /// lane's first part for it came 200-300 ms late. `false`: the wait, as
    /// before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_PROMPT_SENDER",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_prompt_sender: bool,

    /// Wave 9 B (time to first audio under loss): a node with a client UDP
    /// port answers a client's `ASSIGN` there with the assignment that
    /// `/api/assignment` gives over HTTPS, in one datagram each way, which
    /// the client repeats on its own schedule. Over HTTPS a lost SYN waits a
    /// second for TCP's retransmission (1.2-2.8 s to first audio at 5 %
    /// loss in wave 8). `false`: `ASSIGN` is not answered, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_ASSIGN",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_assign: bool,

    /// B 2.3: assignment confirmations (`ASSIGN` with this node's token)
    /// taken from one address a second at most; more are counted in
    /// `assignment_confirms_limited` and charge nothing. Labs that run
    /// needletail-load set 4096: a load host confirms for every listener
    /// it runs from one address.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_ASSIGN_CONFIRMS_PER_SOURCE",
        default_value_t = edge_udp::DEFAULT_ASSIGN_CONFIRMS_PER_SOURCE
    )]
    client_udp_assign_confirms_per_source: u32,

    /// Wave 9 (cold start): a forwarder's audio thread sends a lease child
    /// that is new to a stream (an edge taking a new copy) the stream's last
    /// whole one-symbol part, which carries the descriptor of the compact
    /// parts (RLC1), before its first compact part. Without it the child
    /// drops every compact part ("unknown descriptor") until the
    /// contributor's next whole part (--relay-compact-whole-ms, 100 ms) and
    /// serves its new listeners from the cache mesh meanwhile. `false`: as
    /// before.
    #[arg(
        long,
        env = "NEEDLETAIL_RELAY_LEASE_DESCRIPTORS",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    relay_lease_descriptors: bool,

    /// D 2.3: what the long-lived rings are pinned with. `rings` (the
    /// default): each ring that a class thread or a journal writes (the hop
    /// and stall journals, the first-arrival tables, the receive batches,
    /// the tee rings) is faulted in (with --prefault) and locked with
    /// `mlock` when it is made, before the class threads run; a lock the
    /// memlock limit refuses is counted (`/api/mesh/local` `memory`
    /// `lock_refused_bytes`) and the ring stays faulted in. `off`: nothing
    /// is locked. Replaces --mlock-all (mlockall), removed.
    #[arg(long, env = "NEEDLETAIL_MLOCK", value_enum, default_value_t = memory::LockMode::Rings)]
    mlock: memory::LockMode,

    /// D 2.4: the boot check's record (`needletail-nodecheck boot --out`,
    /// `/run/needletail/node-warm.json`), read once at start into
    /// `node_warm` of `/api/mesh/local` and `/api/node`. A node given a
    /// file whose verdict is not `complete` (or that it cannot read) is
    /// never ready. Unset: no check is configured.
    #[arg(long, env = "NEEDLETAIL_NODE_WARM_FILE")]
    node_warm_file: Option<PathBuf>,

    /// Wave 9 (cold start): glibc's heap trim threshold fixed at 256 MB and
    /// mmap threshold at 32 MB, so freed memory stays in the heaps for the
    /// next allocation instead of going back to the kernel and returning as
    /// page faults. `false`: glibc's dynamic thresholds, as before.
    #[arg(long, env = "NEEDLETAIL_MALLOC_TUNE", default_value_t = true, action = clap::ArgAction::Set)]
    malloc_tune: bool,

    /// Wave 9 (cold start): fault in the pages of preallocated rings (the
    /// ones --mlock names) at start-up, not one by one while the first
    /// session fills them. `false`: as before.
    #[arg(long, env = "NEEDLETAIL_PREFAULT", default_value_t = true, action = clap::ArgAction::Set)]
    prefault: bool,

    /// Phase AM item 8: the bytes that the client UDP lanes send (every
    /// lane, with IP and UDP headers) count in the egress that this node
    /// measures, so in its advertised load_permille and free capacity, its
    /// overload and the admission of readers. `false`: HTTP responses only,
    /// as before (a UDP-only edge then advertises no load).
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_EGRESS_LOAD",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_egress_load: bool,

    /// Wave 8 review: the client UDP datagrams a second that make this edge
    /// full (its CPU, not its NIC: a g6-dedicated-2 sends ~390 listeners of
    /// 1 ms parts, ~400,000 datagrams a second, at a few hundred Mbit/s).
    /// With it, each client datagram counts in the load as at least
    /// --egress-capacity-bps / 8 / this many bytes, so that
    /// load_permille reaches 1,000 when the datagram rate does, whatever
    /// the capacity in bits (an autoscaler's 700 permille then means a full
    /// CPU). 0: bytes alone, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_DATAGRAM_CAPACITY",
        default_value_t = 0
    )]
    client_udp_datagram_capacity: u64,

    /// Wave 9 C2: an edge's load_permille (and so the free capacity that
    /// the entry points see) is at least its process's CPU over its
    /// available CPUs (affinity and cgroup quota), so that LL-HLS readers
    /// and any per-listener work that its bytes do not show count: a lab
    /// edge with 3 readers of 1 ms parts read 300-570 permille by bytes at
    /// 135-148 % of its 200 % CPU. `false`: bytes, datagrams and sessions
    /// alone, as before.
    #[arg(long, env = "NEEDLETAIL_CPU_LOAD", default_value_t = true, action = clap::ArgAction::Set)]
    cpu_load: bool,

    /// Wave 9 C2: the share of its available CPUs, in percent, at which an
    /// edge's CPU term reads 1,000 permille (as the egress term reads 1,000
    /// at --egress-admission-percent of the capacity).
    #[arg(
        long,
        env = "NEEDLETAIL_CPU_LOAD_FULL_PERCENT",
        default_value_t = edge_admission::DEFAULT_CPU_LOAD_FULL_PERCENT,
        value_parser = clap::value_parser!(u8).range(1..=100)
    )]
    cpu_load_full_percent: u8,

    /// Wave 9 C2: the CPU term is the mean over this many ms.
    #[arg(
        long,
        env = "NEEDLETAIL_CPU_LOAD_WINDOW_MS",
        default_value_t = edge_admission::DEFAULT_CPU_LOAD_WINDOW_MS
    )]
    cpu_load_window_ms: u64,

    /// Phase AM item 8: a new UDP subscription is refused (`edge-busy`)
    /// while this edge's egress is overloaded, as a new HLS session is. A
    /// client that moves here (it names its next part) is still taken.
    /// `false`: only --client-udp-max-subscribers refuses, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_ADMIT_BY_LOAD",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_admit_by_load: bool,

    /// Phase AM item 9: a draining edge sends its UDP subscribers `MOVE
    /// draining` spread over this many ms (a share every 50 ms), so that
    /// the edges they move to are not all asked at once. 0: all at once at
    /// the next housekeeping tick, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_DRAIN_SPREAD_MS",
        default_value_t = edge_udp::DEFAULT_DRAIN_SPREAD_MS
    )]
    client_udp_drain_spread_ms: u64,

    /// B rule 1: a UDP subscriber that this edge has sent `MOVE` (a drain,
    /// a rebalance, lost parents) is still served this many ms, until its
    /// `UNSUB`, so that its client moves make-before-break; `MOVE` goes to it
    /// again every 250 ms. 0: removed at the `MOVE`, as before (for A/B
    /// runs only).
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_MOVE_GRACE_MS",
        default_value_t = edge_udp::DEFAULT_MOVE_GRACE_MS
    )]
    client_udp_move_grace_ms: u64,

    /// Wave 8 review: while a stream has no new part, an edge sends its UDP
    /// subscribers `WAIT` this often, under the clients' 200 ms move
    /// silence, so that a quiet stream (a contributor gap, a failover
    /// promotion) does not move every listener of every edge at once. 0:
    /// every 300 ms, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_KEEPALIVE_MS",
        default_value_t = edge_udp::DEFAULT_KEEPALIVE_MS
    )]
    client_udp_keepalive_ms: u64,

    /// Phase AM item 11: when the parents' silence is region-wide (the
    /// edge holds its UDP clients, --edge-region-silence-holds) for this
    /// many ms and a --failover-entry region answers with a fresh copy of
    /// the stream, the edge sends its clients `MOVE region-lost` (they go
    /// to the failover region, the last entry of their assignment). The
    /// neighbour is asked over HTTPS, trusting the certificates of --cert
    /// for the name --telemetry-dns-name. 0: held for as long as the
    /// silence lasts, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_REGION_HOLD_MS",
        default_value_t = DEFAULT_CLIENT_UDP_REGION_HOLD_MS
    )]
    client_udp_region_hold_ms: u64,

    /// Wave 8 review: a failover region counts as fresh for `MOVE
    /// region-lost` only when it holds parts newer than this region's head
    /// by half the hold (it ingests the stream itself; a region that gets
    /// it through the lost one has live nodes and a stale head). `false`:
    /// any live cache that holds the playlist, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_REGION_HEAD_CHECK",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_region_head_check: bool,

    /// An edge that has heard none of its cache-mesh parents for this long
    /// has lost them: it answers 503 for a part or a playlist reload that it
    /// would otherwise hold, and moves its UDP clients. Keep it above the
    /// canonical gap hold of the distributors plus a long-haul round trip,
    /// so that a parent that holds a hole is not taken for a lost one. 0
    /// never treats the parents as lost.
    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_PARENTS_SILENT_MS",
        default_value_t = EDGE_PARENTS_SILENT_MS
    )]
    edge_parents_silent_ms: u64,

    /// An edge whose parents went silent does not send its readers away
    /// when every other edge of its region that it hears says the same: the
    /// silence is region-wide (the source, or the long-haul path) and no
    /// other edge of the region would do better. `false` is the behaviour
    /// from before.
    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_REGION_SILENCE_HOLDS",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    edge_region_silence_holds: bool,

    /// A part request ahead of the edge's newest part waits for the part
    /// until it is due (its distance from the newest part, in parts of the
    /// stream, plus the hole repair grace; at most
    /// EDGE_PART_WAIT_SLICE_MS at a time) instead of waking every hole
    /// repair grace (3 ms at 1 ms parts) to look again. `false` is the
    /// behaviour from before.
    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_PART_WAIT_DUE",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    edge_part_wait_due: bool,

    /// An edge finds a hole by part distance: part N is a hole when a part
    /// this far later (in time, at least two parts) has arrived and N has
    /// not. It asks its cache-mesh parents for the missing run at once, from
    /// the fast-plane tee (or, without the fast plane, as the cache mesh
    /// applies parts), and a reader that waits for a part no longer asks on
    /// a grace timer (3-15 ms) at first: only after twice the distance, as a
    /// backstop, and then on the grace timer, of both parents. A part that
    /// is still missing at twice the distance is asked of both parents. 0
    /// is the behaviour from before (the grace timer).
    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_HOLE_DISTANCE_MS",
        default_value_t = edge_holes::DEFAULT_EDGE_HOLE_DISTANCE_MS
    )]
    edge_hole_distance_ms: u64,

    /// An edge answers whether it has lost its parents from an answer at
    /// most this old (microseconds), instead of asking the cache mesh for
    /// every request. 0 asks for every request (the behaviour from before).
    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_LIVENESS_CACHE_US",
        default_value_t = DEFAULT_EDGE_LIVENESS_CACHE_US
    )]
    edge_liveness_cache_us: u64,

    /// A playlist render reads only the slots of the window written since
    /// the last render, and knows the others from it, instead of reading
    /// and decoding every part of the window (12,000 at 1 ms parts) each
    /// time. `false` is the behaviour from before.
    #[arg(
        long,
        env = "NEEDLETAIL_PLAYLIST_SCAN_MEMO",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    playlist_scan_memo: bool,

    #[arg(long, default_value_t = 9444)]
    http_port: u16,

    #[arg(long)]
    playback_base_url: Option<String>,

    /// The physical host this node runs on (the deploy renders the first 12
    /// hex of the Linode instance's host_uuid). An edge advertises it, and
    /// an entry point gives a listener's second leg to an edge on another
    /// host when one is eligible: two instances on one host stop together.
    #[arg(long)]
    host_tag: Option<String>,

    /// Peak bandwidth for each duplicate stream in the failover playlist.
    #[arg(
        long,
        env = "NEEDLETAIL_HLS_FAILOVER_BANDWIDTH_BPS",
        default_value_t = DEFAULT_HLS_FAILOVER_BANDWIDTH_BPS
    )]
    hls_failover_bandwidth_bps: u64,

    /// Adaptive HLS rendition. Repeat as
    /// MASTER_STREAM:STREAM:BANDWIDTH:AVERAGE_BANDWIDTH:WIDTHxHEIGHT:FRAME_RATE_MILLIHERTZ.
    /// Only renditions with fresh media and an initialization segment are
    /// advertised. Include the master stream itself to describe the source
    /// rendition.
    #[arg(
        long = "hls-rendition",
        env = "NEEDLETAIL_HLS_RENDITIONS",
        value_delimiter = ';',
        value_parser = parse_hls_rendition_spec
    )]
    hls_renditions: Vec<HlsRenditionSpec>,

    /// Stop advertising a configured rendition after this much ingest silence.
    #[arg(
        long,
        env = "NEEDLETAIL_HLS_RENDITION_STALE_MS",
        default_value_t = DEFAULT_HLS_RENDITION_STALE_MS
    )]
    hls_rendition_stale_ms: u64,

    #[arg(long)]
    edge_websocket: bool,

    /// Enable HTTP/3 for HLS and other HTTP routes.
    #[arg(long, env = "NEEDLETAIL_EDGE_HTTP3")]
    edge_http3: bool,

    #[arg(long)]
    edge_webtransport: bool,

    #[arg(long)]
    raw_tcp_port: Option<u16>,

    #[arg(long)]
    raw_tcp_tls: bool,

    #[arg(long)]
    cert: Option<PathBuf>,

    #[arg(long)]
    key: Option<PathBuf>,

    #[arg(long, default_value_t = DEFAULT_STREAM_ID)]
    stream_id: u64,

    /// Nominal part of the node in microseconds: the PART-TARGET of a stream
    /// that declares none, and the unit in which segments and windows given
    /// as time are counted. Default 2500, one 2.5 ms Opus frame. Wins over
    /// --part-ms when both are given.
    #[arg(long = "part-us", env = "AV_LL_HLS_PART_US")]
    part_us_arg: Option<u64>,

    /// The nominal part in whole milliseconds. Kept as an alias of
    /// --part-us.
    #[arg(long, env = "AV_LL_HLS_PART_MS")]
    part_ms: Option<u64>,

    /// The nominal part in microseconds, resolved from --part-us and
    /// --part-ms by `normalized`.
    #[arg(skip)]
    part_us: u64,

    /// Default duration represented by one blocking LL-HLS tail response.
    /// The cache remains at part granularity.
    #[arg(long, env = "AV_LL_HLS_RESPONSE_MS")]
    response_ms: Option<u64>,

    /// Nominal segment of a stream without stamps, in milliseconds. Counted
    /// in parts of --part-us. --parts-per-segment wins when given.
    #[arg(long, env = "AV_LL_HLS_SEGMENT_MS", default_value_t = DEFAULT_SEGMENT_MS)]
    segment_ms: u64,

    /// The playlist window and the ring of the cache, in milliseconds.
    /// Counted in parts of --part-us. --window-parts wins when given.
    #[arg(long, env = "AV_LL_HLS_WINDOW_MS", default_value_t = DEFAULT_WINDOW_MS)]
    window_ms: u64,

    /// Parts in a nominal segment. Overrides --segment-ms.
    #[arg(long = "parts-per-segment")]
    parts_per_segment_arg: Option<usize>,

    /// Parts in the playlist window. Overrides --window-ms.
    #[arg(long = "window-parts")]
    window_parts_arg: Option<usize>,

    /// Parts in a nominal segment, resolved by `normalized`.
    #[arg(skip)]
    parts_per_segment: usize,

    /// Parts in the playlist window, resolved by `normalized`.
    #[arg(skip)]
    window_parts: usize,

    /// The shortest part that a stream may carry on this node, in
    /// microseconds. The cache ring of each playlist slot holds the window
    /// and three target durations after it in parts this short, so a stream
    /// of 0.25 ms PCM on a node of 2.5 ms nominal parts keeps a playlist as
    /// long in time as any other. At the defaults that is 60,000 slots of
    /// about 110 bytes of index per playlist slot. 0 sizes the ring for four
    /// windows of nominal parts only, as before.
    #[arg(long, env = "AV_LL_HLS_MIN_PART_US", default_value_t = DEFAULT_MIN_PART_US)]
    min_part_us: u64,

    /// Slots of the cache ring of one playlist, resolved by `normalized`.
    #[arg(skip)]
    ring_parts: usize,

    /// A floor for PART-HOLD-BACK in milliseconds. PART-HOLD-BACK is three
    /// part targets, or this floor when it is larger. 0 keeps three part
    /// targets.
    #[arg(long, env = "AV_LL_HLS_PART_HOLD_BACK_MS", default_value_t = 0)]
    part_hold_back_ms: u64,

    /// How long one unrecovered canonical object may hold back the contiguous
    /// watermark that gates cache-mesh replication before the watermark skips
    /// past it. Converted to parts with --part-ms. Keep it at or above the
    /// contributor relay media deadline. 0 disables gap skipping. With
    /// --canonical-repair-horizon (on by default) a hole is skipped after
    /// the horizon, which this only bounds.
    #[arg(
        long,
        env = "NEEDLETAIL_CANONICAL_GAP_HOLD_MS",
        default_value_t = DEFAULT_CANONICAL_GAP_HOLD_MS
    )]
    canonical_gap_hold_ms: u64,

    /// The repair horizon of the live path (wave 5, W2): a hole holds back
    /// the contiguous watermark (the LL-HLS playlist, the cache-mesh push,
    /// the cache-fed UDP lane) only this long, measured in time from the
    /// first part after it; then the parts behind it are published and the
    /// hole is listed as a gap (EXT-X-PART ... GAP=YES, the UDP gap object).
    /// A repair that comes later still fills the hole in the cache. `auto`:
    /// twice the 90th percentile of the repair delays this node measures
    /// (parts stored at least 2 ms after a later part; 60 ms before the
    /// first), at most 250 ms and at least --relay-burst-copy-ms plus 10 ms
    /// (10 ms without burst copies), so that a burst copy is never late for
    /// it. A number: that many
    /// milliseconds. `off`: the gap hold alone, as before. Never longer
    /// than --canonical-gap-hold-ms, and nothing is skipped when that is 0.
    #[arg(
        long,
        env = "NEEDLETAIL_CANONICAL_REPAIR_HORIZON",
        default_value = "auto"
    )]
    canonical_repair_horizon: RepairHorizon,

    /// The largest part (and initialization) a cache slot takes, in KiB; a
    /// larger part is refused by every cache (never in a playlist, never
    /// answered to a NACK) and reaches UDP clients only on the fast lane.
    /// Wave 9 D: 8 MiB (2 MiB before): the first frame of a 4K encode at
    /// 160-300 Mbit/s is 4.6-5.9 MB, and a 4K IDR at 300 Mbit/s ~1.7 MB. A
    /// limit, not an allocation.
    #[arg(long, default_value_t = 8192)]
    slot_kb: usize,

    /// Playlists that this node can hold at one time. A relay and a
    /// distributor hold every stream that passes through them, so this is
    /// the number of streams of a region. An edge holds one playlist less
    /// for its readers: one slot is the default stream of the node. A slot
    /// costs about 112 bytes of index per ring entry until it holds media:
    /// about 7 MB with the ring of the defaults (see --min-part-us).
    #[arg(
        long,
        env = "NEEDLETAIL_PLAYLIST_SLOTS",
        default_value_t = DEFAULT_PLAYLIST_SLOTS
    )]
    playlist_slots: usize,

    #[arg(long, default_value = "eu")]
    continent: String,

    /// Cache-plane role. Edges receive from regional distributors and do not forward cache data.
    #[arg(long, value_enum, default_value_t = CacheMeshRoleArg::Edge)]
    cache_mesh_role: CacheMeshRoleArg,

    /// Optional cache-plane region. This can differ from the telemetry region.
    #[arg(long, env = "NEEDLETAIL_CACHE_MESH_REGION")]
    cache_mesh_region: Option<String>,

    /// Maximum regional parent distributors queried by one cache request.
    #[arg(long, env = "NEEDLETAIL_CACHE_MESH_MAX_PARENTS", default_value_t = 2)]
    cache_mesh_max_parents: usize,

    /// Maximum child edges served by one distributor sync tick.
    #[arg(long, env = "NEEDLETAIL_CACHE_MESH_MAX_CHILDREN", default_value_t = 8)]
    cache_mesh_max_children: usize,

    /// Which playlists a distributor pushes to an edge. `demand` pushes a
    /// playlist only while the edge has readers for it. `all` pushes every
    /// playlist to every edge. The `peer` role always uses `all`.
    #[arg(
        long,
        value_enum,
        env = "NEEDLETAIL_CACHE_MESH_REPLICATION",
        default_value_t = CacheMeshReplicationArg::Demand
    )]
    cache_mesh_replication: CacheMeshReplicationArg,

    /// How long a distributor keeps pushing a playlist after the last
    /// subscription from an edge. The edge renews three times in this period.
    #[arg(long, env = "NEEDLETAIL_CACHE_MESH_LEASE_MS", default_value_t = 5_000)]
    cache_mesh_lease_ms: u64,

    /// An edge releases a playlist this long after the last request for it.
    /// The distributors stop pushing it and the edge drops its copy.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_DEMAND_IDLE_MS",
        default_value_t = 30_000
    )]
    cache_mesh_demand_idle_ms: u64,

    /// Parts that a new copy of a playlist receives before the live part.
    /// Zero uses --window-parts.
    #[arg(long, env = "NEEDLETAIL_CACHE_MESH_WARM_PARTS", default_value_t = 0)]
    cache_mesh_warm_parts: usize,

    /// Rate limit for warming a new copy, for each edge, in kbit/s. Live
    /// parts are not limited. Zero sends the warm-up window at once. A
    /// one-vCPU edge that warms a 4K copy at 50 Mbit/s stops serving its
    /// readers for about a second, so the default is 20 Mbit/s.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_WARM_KBPS",
        default_value_t = 20_000
    )]
    cache_mesh_warm_kbps: u64,

    /// Wave 8 stage 5 (AM 13): rate limit for the warm-up windows of all
    /// children of this node together, in kbit/s, on top of each child's
    /// --cache-mesh-warm-kbps. When many edges warm at once (edges join,
    /// or the readers of a lost edge move to the others) a distributor
    /// sends at most this, the children taking turns. Zero: no total limit.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_WARM_TOTAL_KBPS",
        default_value_t = DEFAULT_CACHE_MESH_WARM_TOTAL_KBPS
    )]
    cache_mesh_warm_total_kbps: u64,

    /// Wave 8 stage 5 (AM 12): this node's Subscribe frames say where each
    /// parent stands in its ranking of the playlist's parents (see
    /// --relay-lease-ranked). `false` sends the frame of before (a node of
    /// before refuses the longer one).
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_SUBSCRIBE_RANK",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    cache_mesh_subscribe_rank: bool,

    /// Wave 8 stage 5 (AM 12): a renewal that finds a playlist's ranked
    /// parents changed (a distributor joined and ranks higher, or one is
    /// draining) releases the parents that left the set at once, instead
    /// of letting them feed this node until the lease lapses.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_RELEASE_UNRANKED_PARENTS",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    cache_mesh_release_unranked_parents: bool,

    /// Wave 8 stage 5 (AM 12): a distributor that drains (POST
    /// /api/control/drain-node) says so in its cache-mesh hellos, and its
    /// children rank it after every live distributor that does not, so it
    /// loses its leases (and its fast-plane lease children) at their next
    /// renewal. `false`: a child ranks a draining parent as any other.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_AVOID_DRAINING_PARENTS",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    cache_mesh_avoid_draining_parents: bool,

    /// Wave 8 review: when more live distributors than the two parents
    /// asked are ranked (a slot joined), a new subscription asks its second
    /// parent for the warm-up window too: a slot ranked first holds a new
    /// playlist only from its own subscription on. With two distributors,
    /// only the first parent, as before. `false`: only the first always.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_WARM_SECOND_PARENT",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    cache_mesh_warm_second_parent: bool,

    /// Wave 9 D: the warm-up window that a distributor sends a new copy of a
    /// video playlist, in parts: `window` sends what the child asks for (the
    /// audio window, --cache-mesh-warm-parts), as before. Default 0: a video
    /// copy starts at the live part. A 4K copy warmed at the audio window's
    /// length was minutes of parts trickled at --cache-mesh-warm-kbps for the
    /// whole run, after its readers had started live, each part in one burst
    /// (a 5.9 MB first frame of a clip filled an edge's video receive queue);
    /// a reader or a moved client that needs an earlier part asks for it
    /// (hole repair), and the fast plane feeds a video copy its live parts.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_VIDEO_WARM_PARTS",
        default_value = "0",
        value_parser = parse_video_warm_parts
    )]
    cache_mesh_video_warm_parts: VideoWarmParts,

    /// Wave 8 stage 5 (AM 13): a cache whose copy of a playlist is more
    /// than this many parts behind the newest copy in the region is
    /// stalled for it and takes no reader of it. Zero (the default) turns
    /// the check off: a cache's head part comes in its advertisement, once
    /// every --telemetry-interval-ms, so at 1 ms parts a healthy copy reads
    /// hundreds of parts behind one advertised later.
    #[arg(
        long,
        env = "NEEDLETAIL_ASSIGNMENT_MAX_HEAD_LAG_PARTS",
        default_value_t = 0
    )]
    assignment_max_head_lag_parts: u64,

    /// Wave 8 local proofs: a UDP client (`/api/assignment` naming its
    /// session) that no cache of this region has room for by the entry
    /// point's estimate is assigned in this region anyway (reason `spill`):
    /// any cache that is fresh, not draining, not overloaded and under full
    /// load, ranked by its session; the cache's own admission
    /// (--client-udp-admit-by-load) refuses what it cannot take, and the
    /// client asks again without it. The estimate counts the readers sent
    /// since a cache last advertised at an LL-HLS reader's charge, so a
    /// crowd of UDP clients starting at once used it up after ~40 an edge
    /// and the rest were sent to the failover region (London listeners
    /// played from New York). `false`: the failover region alone, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_ASSIGNMENT_UDP_IN_REGION",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    assignment_udp_in_region: bool,

    /// B 3.6: a playlist whose regional bit rate is above this is given one
    /// leg whatever a UDP listener asks (`p=` of its `ASSIGN`, `paths=` of
    /// /api/assignment): no second edge is asked to send or take a copy of
    /// a video feed. 1 ms PCM is 2.6 Mbit/s a leg.
    #[arg(
        long,
        env = "NEEDLETAIL_ASSIGNMENT_TWO_PATH_MAX_BPS",
        default_value_t = assignment::DEFAULT_TWO_PATH_MAX_BPS
    )]
    assignment_two_path_max_bps: u64,

    /// Wave 9 C4: a moving UDP client (one that names the edges it has
    /// just left: a drain, a kill, a rebalance) is assigned by each cache's
    /// headroom alone, the caches under --rebalance-target-permille first,
    /// and every cache's headroom counts the readers that this entry point
    /// sent it since its last advertisement: the movers spread over the
    /// survivors in proportion to their headroom (wave 8 proofs: the spread
    /// tiers sent 17 of 36 movers to the one survivor under 60 %, 1.42x
    /// the equal share). `false`: a mover is ranked as a new reader.
    #[arg(
        long,
        env = "NEEDLETAIL_ASSIGNMENT_MOVE_HEADROOM",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    assignment_move_headroom: bool,

    /// Wave 9 C1: an edge whose load is over this sheds UDP listeners to an
    /// edge of its region with room (`MOVE rebalance`,
    /// --client-udp-rebalance), and a moving client goes to a cache under
    /// it first (--assignment-move-headroom).
    #[arg(
        long,
        env = "NEEDLETAIL_REBALANCE_TARGET_PERMILLE",
        default_value_t = assignment::DEFAULT_REBALANCE_TARGET_PERMILLE
    )]
    rebalance_target_permille: u32,

    /// Wave 9 C1: an edge over --rebalance-target-permille sends UDP
    /// listeners to the edges of its region under the target less
    /// --client-udp-rebalance-margin-permille, a round every
    /// --client-udp-rebalance-interval-ms, paced over
    /// --client-udp-drain-spread-ms (MOVE rebalance; the client asks the
    /// assignment again without this edge, resumes from its oldest hole):
    /// no more than the receivers' room under the target, shared among the
    /// edges over it by their excess, so that a fresh edge takes the load
    /// that its region had before it joined without being overshot.
    /// `false`: listeners stay where they are, as before (only new
    /// arrivals reach a new edge).
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_REBALANCE",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_rebalance: bool,

    /// Wave 9 C1: an edge takes rebalanced listeners only while its load is
    /// under the target less this, and is filled to the target less half
    /// of it.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_REBALANCE_MARGIN_PERMILLE",
        default_value_t = edge_udp::DEFAULT_REBALANCE_MARGIN_PERMILLE
    )]
    client_udp_rebalance_margin_permille: u32,

    /// B rule R3: an edge also sends UDP listeners away when its load is
    /// over its region's mean by half of
    /// --client-udp-rebalance-margin-permille (it sheds to that, the target
    /// staying the ceiling), so that an edge that restarted or joined takes
    /// its share of listeners that hold two legs already. `false`: only
    /// over --rebalance-target-permille, as before.
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_REBALANCE_TO_MEAN",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    client_udp_rebalance_to_mean: bool,

    /// Wave 9 C1: ms between two rebalance rounds of an edge (each from the
    /// region's advertisements of that moment).
    #[arg(
        long,
        env = "NEEDLETAIL_CLIENT_UDP_REBALANCE_INTERVAL_MS",
        default_value_t = edge_udp::DEFAULT_REBALANCE_INTERVAL_MS
    )]
    client_udp_rebalance_interval_ms: u64,

    /// Entry point of a neighbouring region, as NAME=URL, for example
    /// `us-east=https://entry.us-east.example:443`. Repeat it. The
    /// Multivariant Playlist of this region lists each as the last pathway,
    /// so a reader that loses every cache of this region, or the region
    /// itself, moves to the neighbour.
    #[arg(
        long = "failover-entry",
        env = "NEEDLETAIL_FAILOVER_ENTRIES",
        value_delimiter = ','
    )]
    failover_entries: Vec<String>,

    /// Requests that this node answers in a second when its processor is
    /// full. A session is charged the larger of its bit rate and the share of
    /// the node that its requests take, so a node admits about forty readers
    /// of 5 ms parts for each vCPU. Zero takes 8,000 for each worker thread.
    #[arg(long, env = "NEEDLETAIL_EGRESS_REQUEST_CAPACITY", default_value_t = 0)]
    egress_request_capacity: u64,

    /// Threads that serve readers, beside the threads that carry the media.
    /// Zero takes as many as the media has.
    #[arg(long, env = "NEEDLETAIL_HTTP_WORKER_THREADS", default_value_t = 0)]
    http_worker_threads: usize,

    /// Edges of a region that hold each playlist that has readers. With two,
    /// a second edge takes a copy of a playlist as soon as one edge has a
    /// reader for it, so a reader whose cache fails moves to a cache that
    /// holds the playlist already. One keeps a copy only where readers are.
    #[arg(
        long,
        env = "NEEDLETAIL_PLAYLIST_COPIES",
        default_value_t = DEFAULT_PLAYLIST_COPIES
    )]
    playlist_copies: usize,

    /// Receive and send buffer of the cache-mesh socket. It must hold the
    /// largest part once for each parent. Zero uses --udp-socket-buffer-bytes.
    #[arg(
        long,
        env = "NEEDLETAIL_CACHE_MESH_SOCKET_BUFFER_BYTES",
        default_value_t = 0
    )]
    cache_mesh_socket_buffer_bytes: usize,

    /// Fault injection for tests: drop this many received cache-mesh datagrams
    /// in each million, as a lossy private network would.
    #[arg(
        long,
        hide = true,
        env = "NEEDLETAIL_CACHE_MESH_TEST_RECEIVE_LOSS_PPM",
        default_value_t = 0
    )]
    cache_mesh_test_receive_loss_ppm: u32,

    /// For the proof that two builds interoperate (C 2.1): this node speaks
    /// as a later build might. Its cache-mesh frames carry the next version,
    /// an unknown hello extension and longer subscribes, with a frame of an
    /// unknown kind each second; its telemetry snapshots and the control
    /// envelopes it publishes carry a field `x_future`.
    #[arg(
        long,
        hide = true,
        env = "NEEDLETAIL_CACHE_MESH_TEST_FUTURE_FRAMES",
        default_value_t = false,
        action = clap::ArgAction::Set
    )]
    cache_mesh_test_future_frames: bool,

    /// C 3.1: the node starts with the drain reason `start` and drops it by
    /// itself once warm: an edge takes no listener and a forwarder's hellos
    /// say draining until then. `false`: it serves from its start.
    #[arg(
        long,
        env = "NEEDLETAIL_START_DRAINED",
        default_value_t = true,
        action = clap::ArgAction::Set
    )]
    start_drained: bool,

    /// C 3.1: the longest an edge's start waits for its copies to be warm
    /// before it drops `start` anyway, and says so (`ready_forced`).
    #[arg(long, env = "NEEDLETAIL_START_WARM_MS", default_value_t = 4_000)]
    start_warm_ms: u64,

    /// C 3.2, B 3.12: the longest an edge waits on SIGTERM for its listeners
    /// and readers to leave. 0: --client-udp-drain-spread-ms +
    /// --client-udp-move-grace-ms + 2,000 (14,000 with their defaults).
    #[arg(long, env = "NEEDLETAIL_STOP_DRAIN_MS", default_value_t = 0)]
    stop_drain_ms: u64,

    /// C 3.2: how long a forwarder keeps forwarding after SIGTERM while its
    /// hellos say it is leaving (three hellos).
    #[arg(long, env = "NEEDLETAIL_STOP_LINGER_MS", default_value_t = 300)]
    stop_linger_ms: u64,

    /// C 2.2: where an operator's drain (`drain-node`, `close-node`) is kept
    /// until `resume-node`, so that it holds across a restart. None: it
    /// ends with the process.
    #[arg(long, env = "NEEDLETAIL_DRAIN_STATE_FILE")]
    drain_state_file: Option<PathBuf>,

    /// Most playback sessions that this node serves at one time. Zero sets
    /// no limit. A node at the limit rejects a new session and names other
    /// caches of the region.
    #[arg(long, env = "NEEDLETAIL_EDGE_SESSION_LIMIT", default_value_t = 0)]
    edge_session_limit: usize,

    /// Load, as a percentage of the admission limit, below which a cache
    /// that holds a playlist takes new readers before another cache adds a
    /// copy of it.
    #[arg(
        long,
        env = "NEEDLETAIL_ASSIGNMENT_SPREAD_PERCENT",
        default_value_t = 60
    )]
    assignment_spread_percent: u8,

    /// Caches named after the assigned cache, as the failover order.
    #[arg(long, env = "NEEDLETAIL_ASSIGNMENT_ALTERNATES", default_value_t = 2)]
    assignment_alternates: usize,

    /// Seconds after which a player reloads its Content Steering manifest.
    #[arg(long, env = "NEEDLETAIL_STEERING_TTL_SECONDS", default_value_t = 5)]
    steering_ttl_seconds: u64,

    #[arg(long, default_value_t = 51.5074)]
    latitude: f64,

    #[arg(long, default_value_t = -0.1278)]
    longitude: f64,

    #[arg(long, default_value_t = 100_000_000_000)]
    storage_bytes: u64,

    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_EGRESS_CAPACITY_BPS",
        default_value_t = DEFAULT_EGRESS_CAPACITY_BPS
    )]
    egress_capacity_bps: u64,

    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_EGRESS_ADMISSION_PERCENT",
        default_value_t = DEFAULT_ADMISSION_PERCENT
    )]
    egress_admission_percent: u8,

    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_EGRESS_RECOVERY_PERCENT",
        default_value_t = DEFAULT_RECOVERY_PERCENT
    )]
    egress_recovery_percent: u8,

    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_EGRESS_WINDOW_SECONDS",
        default_value_t = DEFAULT_WINDOW_SECONDS
    )]
    egress_window_seconds: u64,

    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_EGRESS_MIN_SUSTAINED_SECONDS",
        default_value_t = DEFAULT_MIN_SUSTAINED_SECONDS
    )]
    egress_min_sustained_seconds: u64,

    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_SESSION_IDLE_SECONDS",
        default_value_t = DEFAULT_SESSION_IDLE_SECONDS
    )]
    egress_session_idle_seconds: u64,

    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_MAX_SESSIONS",
        default_value_t = DEFAULT_MAX_SESSIONS
    )]
    egress_max_sessions: usize,

    /// Enable demand-based edge provisioning and idle edge draining.
    #[arg(long, env = "NEEDLETAIL_EDGE_LIFECYCLE")]
    edge_lifecycle: bool,

    #[arg(long, env = "NEEDLETAIL_EDGE_MIN_PER_REGION", default_value_t = 1)]
    edge_min_per_region: usize,

    #[arg(long, env = "NEEDLETAIL_EDGE_MAX_PER_REGION", default_value_t = 4)]
    edge_max_per_region: usize,

    #[arg(long, env = "NEEDLETAIL_EDGE_SCALE_UP_READERS", default_value_t = 80)]
    edge_scale_up_readers: u64,

    #[arg(long, env = "NEEDLETAIL_EDGE_IDLE_SECONDS", default_value_t = 900)]
    edge_idle_seconds: u64,

    #[arg(
        long,
        env = "NEEDLETAIL_EDGE_PROVISION_COOLDOWN_SECONDS",
        default_value_t = 30
    )]
    edge_provision_cooldown_seconds: u64,

    #[arg(long, default_value_t = 0)]
    baseline_per_region: usize,

    #[arg(long, default_value_t = 1)]
    baseline_per_continent: usize,

    #[arg(long, default_value_t = 300.0)]
    min_mirror_distance_km: f64,

    #[arg(long)]
    telemetry_bind: Option<SocketAddr>,

    #[arg(long = "telemetry-peer")]
    telemetry_peers: Vec<String>,

    /// Serve this quorum-elected canonical document from `/api/mesh`.
    #[arg(long, env = "NEEDLETAIL_OPERATIONS_SNAPSHOT_FILE")]
    operations_snapshot_file: Option<PathBuf>,

    /// Receive bounded RaptorQ fleet snapshots on this UDP socket.
    #[arg(long)]
    telemetry_fec_bind: Option<SocketAddr>,

    /// Send bounded RaptorQ fleet snapshots to this collector. Repeatable.
    #[arg(long = "telemetry-fec-target")]
    telemetry_fec_targets: Vec<String>,

    /// Total paced telemetry-FEC wire budget across all configured targets.
    #[arg(
        long,
        env = "NEEDLETAIL_TELEMETRY_FEC_RATE_BPS",
        default_value_t = DEFAULT_TELEMETRY_FEC_RATE_BPS
    )]
    telemetry_fec_rate_bps: u64,

    #[arg(long, default_value_t = DEFAULT_TELEMETRY_REPAIR_PERCENT)]
    telemetry_fec_repair_percent: u8,

    /// Publish snapshots only on FEC while retaining the TCP control channel.
    #[arg(long)]
    telemetry_snapshots_fec_only: bool,

    #[arg(long, default_value = "local.wavey.ai")]
    telemetry_dns_name: String,

    #[arg(long, default_value_t = Ipv4Addr::LOCALHOST)]
    telemetry_private_ipv4: Ipv4Addr,

    #[arg(
        long,
        env = "NEEDLETAIL_TELEMETRY_INTERVAL_MS",
        default_value_t = DEFAULT_TELEMETRY_INTERVAL_MS
    )]
    telemetry_interval_ms: u64,

    #[arg(long, default_value_t = DEFAULT_TELEMETRY_STALE_MS)]
    telemetry_stale_ms: u64,

    #[arg(long, default_value_t = 5000)]
    replication_plan_interval_ms: u64,

    #[arg(long)]
    provision_command: Option<String>,

    #[cfg(feature = "linode-provisioner")]
    #[arg(long)]
    linode_provision: bool,

    #[cfg(feature = "linode-provisioner")]
    #[arg(long)]
    linode_image_id: Option<String>,

    #[cfg(feature = "linode-provisioner")]
    #[arg(long)]
    linode_instance_type: Option<String>,

    #[cfg(feature = "linode-provisioner")]
    #[arg(long)]
    linode_domain_id: Option<u64>,

    #[cfg(feature = "linode-provisioner")]
    #[arg(long, default_value = "av-mesh")]
    linode_vlan_tag: String,

    #[cfg(feature = "linode-provisioner")]
    #[arg(long, default_value = "LINODE_API_TOKEN")]
    linode_token_env: String,

    #[cfg(feature = "linode-provisioner")]
    #[arg(long, default_value = "LINODE_PUB_KEY")]
    linode_pub_key_env: String,

    #[cfg(feature = "linode-provisioner")]
    #[arg(long = "linode-region-map", value_parser = parse_key_value)]
    linode_region_maps: Vec<(String, String)>,

    #[arg(long, default_value_t = 30_000)]
    provision_timeout_ms: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct UdpSocketBufferState {
    requested_bytes: usize,
    receive_bytes: usize,
    send_bytes: usize,
    receive_request_succeeded: bool,
    send_request_succeeded: bool,
    /// The host limit (net.core.rmem_max / wmem_max) capped the request and
    /// the node raised the buffers past it with SO_RCVBUFFORCE /
    /// SO_SNDBUFFORCE.
    forced: bool,
}

impl UdpSocketBufferState {
    const fn target_met(self) -> bool {
        self.receive_request_succeeded
            && self.send_request_succeeded
            && self.receive_bytes >= self.requested_bytes
            && self.send_bytes >= self.requested_bytes
    }
}

fn validate_udp_socket_buffer_target(bytes: usize) -> Result<()> {
    if bytes == 0 || bytes > i32::MAX as usize {
        bail!(
            "--udp-socket-buffer-bytes must be between 1 and {}",
            i32::MAX
        );
    }
    Ok(())
}

fn configure_udp_socket_buffers(
    socket: &impl std::os::fd::AsFd,
    requested_bytes: usize,
    purpose: &str,
) -> Result<UdpSocketBufferState> {
    validate_udp_socket_buffer_target(requested_bytes)?;
    let socket_ref = SockRef::from(socket);
    let receive_request_succeeded = match socket_ref.set_recv_buffer_size(requested_bytes) {
        Ok(()) => true,
        Err(error) => {
            warn!(
                purpose,
                requested_bytes,
                error = %error,
                "could not apply the UDP receive-buffer target; continuing with the kernel value"
            );
            false
        }
    };
    let send_request_succeeded = match socket_ref.set_send_buffer_size(requested_bytes) {
        Ok(()) => true,
        Err(error) => {
            warn!(
                purpose,
                requested_bytes,
                error = %error,
                "could not apply the UDP send-buffer target; continuing with the kernel value"
            );
            false
        }
    };
    let read_sizes = || -> Result<(usize, usize)> {
        Ok((
            socket_ref
                .recv_buffer_size()
                .context("failed to read the configured UDP receive-buffer size")?,
            socket_ref
                .send_buffer_size()
                .context("failed to read the configured UDP send-buffer size")?,
        ))
    };
    let (mut receive_bytes, mut send_bytes) = read_sizes()?;
    // A host with the stock limits caps both buffers at about 200 KB, which
    // a burst of small parts to every child fills. A node with
    // CAP_NET_ADMIN may go past the limit; without it nothing changes.
    let mut forced = false;
    if (receive_bytes < requested_bytes || send_bytes < requested_bytes)
        && fast_path::force_socket_buffers(socket, requested_bytes)
    {
        (receive_bytes, send_bytes) = read_sizes()?;
        forced = true;
    }
    Ok(UdpSocketBufferState {
        requested_bytes,
        receive_bytes,
        send_bytes,
        receive_request_succeeded,
        send_request_succeeded,
        forced,
    })
}

/// The edge's client sockets as an audio/video pair on one address, with
/// their send-only twins (`--client-udp-send-twins`).
#[cfg(test)]
fn bind_edge_class_sockets(
    bind: SocketAddr,
    buffer_bytes: usize,
    classes: &fast_plane::StreamClasses,
) -> Result<edge_udp::EdgeSockets> {
    bind_edge_class_sockets_with(bind, buffer_bytes, classes, true)
}

/// The edge's client sockets as an audio/video pair on one address, and
/// with `send_twins` a send-only twin of each for the fast lane.
fn bind_edge_class_sockets_with(
    bind: SocketAddr,
    buffer_bytes: usize,
    classes: &fast_plane::StreamClasses,
    send_twins: bool,
) -> Result<edge_udp::EdgeSockets> {
    let audio = fast_plane::sys::bind_reuseport(bind)
        .with_context(|| format!("failed to bind edge client UDP on {bind}"))?;
    let local = audio.local_addr()?;
    let video = fast_plane::sys::bind_reuseport(local)
        .with_context(|| format!("failed to bind the video twin of edge client UDP on {local}"))?;
    fast_plane::sys::set_priority(&audio, fast_plane::sys::AUDIO_SO_PRIORITY)?;
    let twins = if send_twins {
        let twin = || {
            fast_plane::sys::bind_reuseport(local).with_context(|| {
                format!("failed to bind a send-only twin of edge client UDP on {local}")
            })
        };
        let (audio_twin, video_twin) = (twin()?, twin()?);
        fast_plane::sys::set_priority(&audio_twin, fast_plane::sys::AUDIO_SO_PRIORITY)?;
        Some((audio_twin, video_twin))
    } else {
        None
    };
    for (socket, purpose) in [
        (&audio, "edge client UDP audio"),
        (&video, "edge client UDP video"),
    ]
    .into_iter()
    .chain(twins.iter().flat_map(|(audio_twin, video_twin)| {
        [
            (audio_twin, "edge client UDP audio send twin"),
            (video_twin, "edge client UDP video send twin"),
        ]
    })) {
        let state = configure_udp_socket_buffers(socket, buffer_bytes, purpose)?;
        if !state.target_met() {
            warn!(
                purpose,
                requested_bytes = buffer_bytes,
                actual_send_bytes = state.send_bytes,
                "UDP socket buffer target was limited by the operating system"
            );
        }
    }
    info!(
        bind = %local,
        send_twins = twins.is_some(),
        "edge client UDP: an audio and a video socket on one address"
    );
    let sockets = edge_udp::EdgeSockets::pair(
        UdpSocket::from_std(audio)?,
        UdpSocket::from_std(video)?,
        classes.clone(),
    );
    Ok(match twins {
        Some((audio_twin, video_twin)) => sockets.with_send_twins(audio_twin, video_twin),
        None => sockets,
    })
}

async fn bind_buffered_udp_ingress(
    bind: SocketAddr,
    requested_bytes: usize,
    purpose: &str,
) -> Result<UdpSocket> {
    let socket = UdpSocket::bind(bind)
        .await
        .with_context(|| format!("failed to bind {purpose} on {bind}"))?;
    let state = configure_udp_socket_buffers(&socket, requested_bytes, purpose)?;
    let bind = socket.local_addr()?;
    if state.target_met() {
        info!(
            purpose,
            %bind,
            requested_bytes = state.requested_bytes,
            actual_receive_bytes = state.receive_bytes,
            actual_send_bytes = state.send_bytes,
            forced_past_host_limit = state.forced,
            "UDP socket buffers configured"
        );
    } else {
        warn!(
            purpose,
            %bind,
            requested_bytes = state.requested_bytes,
            actual_receive_bytes = state.receive_bytes,
            actual_send_bytes = state.send_bytes,
            receive_request_succeeded = state.receive_request_succeeded,
            send_request_succeeded = state.send_request_succeeded,
            "UDP socket buffer target was limited by the operating system"
        );
    }
    Ok(socket)
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "av_mesh=info,playlists=info,web_service=info".into()),
        )
        .init();

    let args = Args::parse().normalized()?;
    // From here on SIGTERM and SIGINT are a stop the node makes itself.
    let mut stop = lifecycle::stop_signal().context("failed to listen for SIGTERM and SIGINT")?;
    // Wave 9 (cold start): memory before the first session, not in it.
    memory::configure(args.mlock, args.prefault);
    node_warm::install(args.node_warm_file.as_deref());
    match memory::tune_allocator(args.malloc_tune) {
        Ok(()) => info!(
            trim_threshold = memory::TRIM_THRESHOLD,
            mmap_threshold = memory::MMAP_THRESHOLD,
            "allocator keeps freed memory in its heaps"
        ),
        Err(reason) => info!(%reason, "allocator thresholds as glibc sets them"),
    }
    let mesh_peers = resolve_socket_addr_args("peer", &args.peers).await?;
    let mesh_peer_ips: Vec<std::net::IpAddr> = mesh_peers.iter().map(SocketAddr::ip).collect();
    let telemetry_peers = resolve_socket_addr_args("telemetry-peer", &args.telemetry_peers).await?;
    let mut telemetry_fec_targets =
        resolve_socket_addr_args("telemetry-fec-target", &args.telemetry_fec_targets).await?;
    telemetry_fec_targets.sort_unstable();
    telemetry_fec_targets.dedup();
    if telemetry_fec_targets.len() > MAX_TELEMETRY_FEC_TARGETS {
        bail!(
            "resolved telemetry FEC targets exceed the configured limit {}",
            MAX_TELEMETRY_FEC_TARGETS
        );
    }
    let node_id = args.node_id.clone().unwrap_or_else(|| args.region.clone());
    let node_profile = MeshNode {
        node_id: node_id.clone(),
        region: args.region.clone(),
        continent: args.continent.clone(),
        latitude: args.latitude,
        longitude: args.longitude,
        total_storage_bytes: args.storage_bytes,
        used_storage_bytes: 0,
        egress_capacity_bps: args.egress_capacity_bps,
        contributor_streams: 0,
        active_streams: 0,
        draining: false,
    };
    let replication_policy = ReplicationPolicy {
        baseline_per_region: args.baseline_per_region,
        baseline_per_continent: args.baseline_per_continent,
        min_mirror_distance_km: args.min_mirror_distance_km,
        ..ReplicationPolicy::default()
    };
    let control_plane = ControlPlane::default();
    let control_dispatch = ControlDispatch {
        future_fields: args.cache_mesh_test_future_frames,
        ..ControlDispatch::default()
    };
    let demand_tracker = DemandTracker::default();
    let telemetry_aggregator = TelemetryAggregator::new(args.telemetry_stale_ms);
    let telemetry_peer_monitor = TelemetryPeerMonitor::new(&telemetry_peers);
    let telemetry_fec_queue =
        (!telemetry_fec_targets.is_empty()).then(LatestTelemetryQueue::default);
    let telemetry_fec_monitor = TelemetryFecMonitor::new(
        args.telemetry_fec_bind,
        telemetry_fec_targets.len(),
        args.telemetry_interval_ms,
        args.telemetry_fec_rate_bps,
        telemetry_fec_queue.clone(),
    );
    let playback_base_url = args
        .playback_base_url
        .as_deref()
        .map(normalize_playback_base_url);
    let edge_load = EdgeLoad::new(EdgeAdmissionConfig {
        capacity_bps: args.egress_capacity_bps,
        admission_percent: args.egress_admission_percent,
        recovery_percent: args.egress_recovery_percent,
        window_seconds: args.egress_window_seconds,
        min_sustained_seconds: args.egress_min_sustained_seconds,
        session_idle_seconds: args.egress_session_idle_seconds,
        max_sessions: args.egress_max_sessions,
        session_limit: args.edge_session_limit,
        request_capacity_per_sec: args.egress_request_capacity(),
    });
    let edge_lifecycle_config = EdgeLifecycleConfig {
        enabled: args.edge_lifecycle,
        min_edges_per_region: args.edge_min_per_region,
        max_edges_per_region: args.edge_max_per_region,
        scale_up_active_readers: args.edge_scale_up_readers,
        idle_seconds: args.edge_idle_seconds,
        provision_cooldown_seconds: args.edge_provision_cooldown_seconds,
    }
    .normalized();
    let provision_executor = {
        let executor = ProvisionExecutor::new(
            args.provision_command.clone(),
            Duration::from_millis(args.provision_timeout_ms),
        );
        #[cfg(feature = "linode-provisioner")]
        let executor = executor.with_linode(args.linode_provision_config());
        executor
    };
    #[cfg(feature = "private-subnet-discovery")]
    let private_discovery_status = PrivateDiscoveryStatus::from_args(
        args.private_subnet_discovery,
        args.private_discovery_broadcast_port,
        args.private_discovery_mesh_port
            .unwrap_or_else(|| args.mesh_bind.port()),
    );
    #[cfg(not(feature = "private-subnet-discovery"))]
    let private_discovery_status = PrivateDiscoveryStatus::unavailable();
    let cache = LiveTsCache::with_ring(
        args.stream_id,
        Duration::from_micros(args.part_us),
        args.parts_per_segment,
        args.window_parts,
        args.slot_kb,
        args.playlist_slots.max(2),
        args.ring_parts,
    )
    .await;
    cache.set_canonical_gap_hold(Duration::from_millis(args.canonical_gap_hold_ms));
    cache.set_repair_horizon(args.canonical_repair_horizon);
    cache.set_repair_horizon_floor_for_burst_copy(Duration::from_millis(args.relay_burst_copy_ms));
    cache.set_playlist_scan_memo(args.playlist_scan_memo);
    cache.set_part_hold_back_floor(Duration::from_millis(args.part_hold_back_ms));
    let link_telemetry = Arc::new(LinkTelemetry::new(
        node_id.clone(),
        args.relay_primary_peer
            .map(|peer| (args.relay_primary_id.clone(), peer)),
        args.relay_secondary_peer
            .map(|peer| (args.relay_secondary_id.clone(), peer)),
    ));
    cache.set_link_telemetry(Arc::clone(&link_telemetry));
    let hop_journal = Arc::new(HopJournal::new(
        node_id.clone(),
        args.hop_journal_capacity
            .unwrap_or_else(|| hop_journal_capacity_for(args.part_us, args.hop_journal_seconds)),
    ));
    cache.set_hop_journal(Arc::clone(&hop_journal));
    // The stall journal runs from the node's first second: its ring is
    // faulted in and locked, and its tick threads start here, before any
    // thread of the node is pinned or made real-time.
    let stalls = stall_journal::install(Arc::new(StallJournal::new(
        node_id.clone(),
        args.stall_journal_capacity,
    )));
    let stall_ticks = stall_journal::spawn_ticks(stalls, TickConfig::every(args.stall_tick_us));
    info!(
        capacity = args.stall_journal_capacity,
        ring_locked = stalls.ring_locked(),
        tick_us = args.stall_tick_us,
        tick_threads = stall_ticks.threads().len(),
        tick_pinned = stall_ticks.pinned(),
        run_delay_known = stall_ticks.threads().iter().all(|thread| thread.run_delay),
        "stall journal"
    );
    {
        // D 2.3: the journals' rings are pinned; the class threads pin
        // theirs as they start.
        let memory = memory::report();
        info!(
            mode = ?memory.mode,
            prefaulted_bytes = memory.prefaulted_bytes,
            locked_bytes = memory.locked_bytes,
            lock_refused_bytes = memory.lock_refused_bytes,
            thp = memory.thp,
            "memory regions pinned"
        );
    }

    let mut mesh_transport = MeshTransportConfigSnapshot {
        sync_interval_ms: args.mesh_sync_interval_ms,
        min_repair_symbols: args.mesh_repair_symbols,
        repair_ratio: args.mesh_repair_ratio,
        max_repair_symbols: args.mesh_max_repair_symbols,
        symbol_size: args.mesh_symbol_size,
        fast_path: fast_path::FastPathSnapshot::default(),
    };
    let fast_path_report = fast_path::FastPath::new(args.busy_poll_us, args.relay_forward_batch);
    // With --media-cpu the relay ingest and the cache mesh run on a thread
    // of their own, pinned when the host allows it. Their sockets are bound
    // there too, so the media thread also drives their readiness.
    let media_runtime = match args.media_cpu {
        Some(cpu) => {
            let (runtime, pinned) =
                fast_path::MediaRuntime::start(cpu).context("failed to start the media thread")?;
            match &pinned {
                Ok(()) => info!(
                    cpu,
                    "relay ingest and cache mesh run on a thread pinned to this CPU"
                ),
                Err(error) => warn!(
                    cpu,
                    error, "media thread could not be pinned; it runs unpinned"
                ),
            }
            fast_path_report.record_media_cpu(cpu, pinned);
            Some(runtime)
        }
        None => None,
    };
    let media = media_runtime.as_ref().map(fast_path::MediaRuntime::handle);
    let cache_mesh_region = args
        .cache_mesh_region
        .clone()
        .unwrap_or_else(|| args.region.clone());
    let cache_mesh_role: CacheMeshRole = args.cache_mesh_role.into();
    let replication = effective_replication(args.cache_mesh_replication, cache_mesh_role);
    // A forwarder slot (--cache-mesh-upstream-demand) holds the playlists
    // that its children lease from it as an edge holds those its readers
    // ask for: by subscribing at its parent distributors (AM 12).
    let upstream_demand = args.cache_mesh_upstream_demand
        && replication == ReplicationMode::Demand
        && cache_mesh_role == CacheMeshRole::Distributor;
    let demand_enabled = replication == ReplicationMode::Demand
        && (cache_mesh_role == CacheMeshRole::Edge || upstream_demand);
    // C 3.1: the drain reasons, an operator's from the drain-state file;
    // the hello says draining from the mesh's start while any holds. A node
    // that replicates on demand opens at its start what must be warm.
    let lifecycle = NodeLifecycle::new(LifecycleConfig {
        edge: cache_mesh_role == CacheMeshRole::Edge,
        start_drained: args.start_drained,
        state_file: args.drain_state_file.clone(),
        warm_pass: demand_enabled,
    });
    let mut mesh_config = CacheMeshConfig::new(node_id.clone(), cache_mesh_region, args.mesh_bind)
        .with_peers(mesh_peers)
        .with_same_region_only(true)
        .with_role(args.cache_mesh_role.into())
        .with_max_parents(args.cache_mesh_max_parents)
        .with_max_children(args.cache_mesh_max_children)
        .with_announce_interval(Duration::from_millis(CACHE_MESH_ANNOUNCE_MS));
    mesh_config.sync_interval = Duration::from_millis(args.mesh_sync_interval_ms);
    mesh_config.repair_symbols = args.mesh_repair_symbols;
    mesh_config.repair_ratio = args.mesh_repair_ratio;
    mesh_config.max_repair_symbols = args.mesh_max_repair_symbols;
    mesh_config.symbol_size = args.mesh_symbol_size;
    let (mesh_applied_tx, mesh_applied_rx) = mpsc::unbounded_channel();
    let mesh_config = mesh_config
        .with_receive_loss_ppm(args.cache_mesh_test_receive_loss_ppm)
        .with_max_symbol_size(args.mesh_max_symbol_size)
        .with_replication(replication)
        .with_subscription_lease(Duration::from_millis(args.cache_mesh_lease_ms.max(100)))
        .with_backfill_bytes_per_sec(args.cache_mesh_warm_kbps.saturating_mul(125))
        .with_backfill_total_bytes_per_sec(args.cache_mesh_warm_total_kbps.saturating_mul(125))
        .with_subscribe_rank(args.cache_mesh_subscribe_rank)
        .with_release_unranked_parents(args.cache_mesh_release_unranked_parents)
        .with_avoid_draining_parents(args.cache_mesh_avoid_draining_parents)
        .with_warm_from_second_parent(args.cache_mesh_warm_second_parent)
        .with_video_backfill_parts(args.cache_mesh_video_warm_parts.0)
        .with_socket_buffer_bytes(if args.cache_mesh_socket_buffer_bytes > 0 {
            args.cache_mesh_socket_buffer_bytes
        } else {
            args.udp_socket_buffer_bytes
        })
        .with_applied_tx(mesh_applied_tx)
        // C CR2: a parent that leaves a stream's ranked set is kept until
        // its replacement feeds, at most two of this node's renewal periods
        // (`cache_mesh_parent_release_after`); the hello carries the boot id
        // that `GET /api/node` shows.
        .with_parent_release_after(cache_mesh_parent_release_after(args.cache_mesh_lease_ms))
        .with_boot_id(cache.started_unix_us)
        // C CR6: the hello gives this node's build and state.
        .with_build(av_mesh::build::GIT.to_owned())
        .with_hello_state(lifecycle.hello())
        // cr68 finding 6: a node that starts drained says so in its first
        // hello, not only once `attach_mesh` has run.
        .with_draining(lifecycle.hello_draining())
        .with_test_future_frames(args.cache_mesh_test_future_frames)
        // A PL1 (A 2.7): a part from a parent keeps the first copy of its
        // epoch (two contributors publish the same parts).
        .with_slot_epoch(mesh_slot_epoch);
    let mesh_config = with_low_latency_mesh_options(mesh_config, &hop_journal);
    // An edge with a client UDP port forwards the parts that reach it over
    // the cache mesh to its UDP clients as their datagrams arrive.
    // With a class-split mesh each class's receive task feeds a cut-through
    // of its own, and with --client-udp-cut-through-thread each runs on a
    // thread of its own rather than inline on the receive task.
    let mesh_split = args.cache_mesh_class_port_offset > 0;
    // A node whose class threads take RelaySession symbols feeds its UDP
    // clients the fast lane; cut-through is then off.
    let fast_lane = (args.client_udp_bind.is_some()
        && args.client_udp_fast_lane
        && args.relay_class_threads
        && args.relay_controlled_local
        && fast_plane::sys::supported())
    .then(|| fast_plane::edge_clients::EdgeFastLane::new(args.client_udp_edge_rank));
    if let Some(lane) = &fast_lane {
        lane.set_compact_top_up(args.client_udp_compact_top_up);
        lane.set_compact_mark(args.client_udp_compact_mark_fast_lane);
        lane.set_repair_thread(args.client_udp_repair_thread);
        lane.set_fanout_inline_shard(args.client_udp_fanout_inline_shard);
        lane.set_fanout_nice(args.client_udp_fanout_nice);
        lane.set_class_arena_warm_bytes(
            usize::try_from(args.relay_class_arena_warm_mb.saturating_mul(1 << 20))
                .unwrap_or(usize::MAX),
        );
        lane.set_fanout(
            args.client_udp_fanout_threads,
            args.client_udp_fanout_inline_sends,
        );
        lane.set_video_pacing(Some(fast_plane::edge_clients::VideoPacing {
            percent: args.client_udp_video_pace_percent,
            max_delay_us: args.client_udp_video_pace_max_ms.saturating_mul(1_000),
        }));
    }
    if fast_lane.is_some() && args.client_udp_cut_through {
        info!("edge client UDP: the fast lane runs, so cut-through is off (--client-udp-fast-lane false turns it back on)");
    }
    let edge_cut_through: Vec<Arc<edge_udp::CutThrough>> = args
        .client_udp_bind
        .filter(|_| args.client_udp_cut_through && fast_lane.is_none())
        .map(|_| {
            (0..if mesh_split { 2 } else { 1 })
                .map(|_| Arc::new(edge_udp::CutThrough::default()))
                .collect()
        })
        .unwrap_or_default();
    let cut_observer =
        |class: fast_plane::TrafficClass| -> Result<Option<Arc<dyn CacheMeshReceiveObserver>>> {
            let Some(cut) = edge_cut_through.get(class.index()) else {
                return Ok(None);
            };
            Ok(Some(if args.client_udp_cut_through_thread {
                edge_udp::CutThroughLane::start(
                    Arc::clone(cut),
                    class.as_str(),
                    tokio::runtime::Handle::current(),
                )
                .context("failed to start a cut-through thread")? as _
            } else {
                Arc::clone(cut) as _
            }))
        };
    let mesh_config = match cut_observer(fast_plane::TrafficClass::Audio)? {
        Some(observer) => mesh_config.with_receive_observer(observer),
        None => mesh_config,
    };
    // Split by class: video playlists on a socket of their own. The class of
    // a stream comes from where it arrived (see `fast_plane::StreamClasses`).
    let mesh_config = if mesh_split {
        let classes = cache.stream_classes().clone();
        let marker_classes = classes.clone();
        mesh_config
            .with_class_port_offset(args.cache_mesh_class_port_offset)
            .with_stream_classifier(Arc::new(move |stream_id| classes.mesh_class(stream_id)))
            .with_class_receive_observer(Some(Arc::new(fast_plane::ClassMarker::new(
                marker_classes,
                cut_observer(fast_plane::TrafficClass::Video)?,
            ))))
    } else {
        mesh_config
    };
    // The lease children are made from the running mesh; the mesh's live
    // push filter reads them from this slot once they run.
    let lease_push_slot: Arc<std::sync::OnceLock<Arc<fast_plane::lease::LeaseChildren>>> =
        Arc::default();
    let mesh_config = match (
        args.cache_mesh_fast_plane_push,
        args.cache_mesh_fast_plane_video_push,
    ) {
        _ if !(args.relay_lease_children && args.relay_lease_bind.is_some()) => mesh_config,
        (CacheMeshFastPlanePush::All, CacheMeshFastPlanePush::All) => mesh_config,
        (audio, video) => mesh_config.with_live_push_filter(fast_plane::lease::live_push_filter(
            Arc::clone(&lease_push_slot),
            cache.stream_classes().clone(),
            audio.live_push(),
            video.live_push(),
        )),
    };
    let mesh_chunk_cache = Arc::clone(&cache.chunk_cache);
    let mesh_handle = Arc::new(
        fast_path::on_media(media, async move {
            CacheMesh::new(mesh_chunk_cache, mesh_config).start().await
        })
        .await?
        .context("failed to start cache mesh")?,
    );
    lifecycle.attach_mesh(&mesh_handle);
    fast_path_report.tune_receive_socket_at(mesh_handle.local_addr(), "cache mesh");
    if let Some(class_addr) = mesh_handle.class_local_addr() {
        info!(bind = %class_addr, "cache mesh video class socket listening");
        fast_path_report.tune_receive_socket_at(class_addr, "cache mesh video");
    }
    let playlist_demand = PlaylistDemand::new(PlaylistDemandConfig {
        enabled: demand_enabled,
        lease: Duration::from_millis(args.cache_mesh_lease_ms.max(100)),
        idle: Duration::from_millis(args.cache_mesh_demand_idle_ms.max(1_000)),
        warm_parts: if args.cache_mesh_warm_parts > 0 {
            args.cache_mesh_warm_parts
        } else {
            args.window_parts
        },
        max_playlists: args.playlist_slots.max(2) - 1,
    });

    let control_packets = packetize_control_message(&MeshControlMessage {
        node_id: node_id.clone(),
        region: args.region.clone(),
        event: MeshControlEvent::NodeStarted {
            mesh_addr: mesh_handle.local_addr().to_string(),
        },
    })?;
    let control_echo = reassemble_unsigned_control_packets(&control_packets)?;
    info!(
        packets = control_packets.len(),
        event = ?control_echo.event,
        "mesh control message packetized"
    );

    let (ingest_shutdown_tx, ingest_shutdown_rx) = watch::channel(());
    link_telemetry.start(ingest_shutdown_rx.clone());
    // An edge finds its holes by part distance: in its fast-plane tee when
    // the class threads feed it, and otherwise as the cache mesh applies.
    let hole_trigger = (cache_mesh_role == CacheMeshRole::Edge)
        .then(|| {
            edge_holes::HoleTrigger::new(
                Arc::clone(&cache),
                Arc::clone(&mesh_handle),
                Duration::from_millis(args.edge_hole_distance_ms),
            )
        })
        .flatten();
    // The quiet catch-up of the trigger (a stream that the fast plane left
    // quiet is asked of the cache-mesh parents), off the live path.
    let hole_quiet_task = hole_trigger.clone().map(|trigger| {
        let mut shutdown = ingest_shutdown_rx.clone();
        tokio::spawn(async move {
            let mut tick = tokio::time::interval(Duration::from_millis(25));
            tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
            loop {
                tokio::select! {
                    _ = shutdown.changed() => return,
                    _ = tick.tick() => trigger.sweep_quiet(),
                }
            }
        })
    });
    let fast_ingest_planned =
        args.relay_class_threads && args.relay_controlled_local && fast_plane::sys::supported();
    let mesh_applied_task = tokio::spawn(run_mesh_applied_parts(
        Arc::clone(&cache),
        edge_load.clone(),
        mesh_applied_rx,
        // Also beside the fast plane: the trigger takes the cache mesh's
        // arrivals of a stream that the fast plane has stopped feeding.
        hole_trigger.clone(),
        ingest_shutdown_rx.clone(),
    ));
    let playlist_demand_task = tokio::spawn(run_playlist_demand(
        Arc::clone(&cache),
        Arc::clone(&mesh_handle),
        edge_load.clone(),
        playlist_demand.clone(),
        ingest_shutdown_rx.clone(),
    ));
    let playlist_standby_task = tokio::spawn(run_playlist_standby(
        Arc::clone(&mesh_handle),
        edge_load.clone(),
        playlist_demand.clone(),
        telemetry_aggregator.clone(),
        StandbyConfig {
            node_id: node_id.clone(),
            region: args.region.clone(),
            copies: args.playlist_copies,
            fresh_ms: args.telemetry_interval_ms.saturating_mul(3).max(3_000),
        },
        ingest_shutdown_rx.clone(),
    ));

    #[cfg(feature = "private-subnet-discovery")]
    let private_subnet_discovery = if args.private_subnet_discovery {
        Some(
            start_private_subnet_discovery(
                args.private_discovery_broadcast_port,
                args.private_discovery_mesh_port
                    .unwrap_or_else(|| args.mesh_bind.port()),
                Arc::clone(&mesh_handle),
                ingest_shutdown_rx.clone(),
            )
            .await?,
        )
    } else {
        None
    };

    // A relay or distributor runs its RelaySession ingest on the fast plane:
    // class threads that forward before anything decodes.
    let class_ingest = fast_ingest_planned;
    let class_sockets = if class_ingest {
        let sockets = fast_plane::relay::bind_class_sockets(
            args.fec_bind,
            args.relay_secondary_bind,
            args.relay_class_port_offset,
            args.udp_socket_buffer_bytes,
        )?;
        for socket in &sockets {
            fast_path_report.tune_receive_socket(
                &socket.socket,
                &format!("relay {} ingest", socket.class.as_str()),
            );
        }
        apply_fast_busy_poll(&sockets, args.fast_busy_poll_us);
        Some(sockets)
    } else {
        None
    };
    // One class thread for each class that has a socket.
    let class_threads_expected = class_sockets.as_ref().map_or(0, |sockets| {
        fast_plane::TrafficClass::ALL
            .iter()
            .filter(|class| sockets.iter().any(|socket| socket.class == **class))
            .count() as u64
    });
    let fec_socket = if class_ingest {
        None
    } else {
        let socket = fast_path::on_media(
            media,
            bind_buffered_udp_ingress(
                args.fec_bind,
                args.udp_socket_buffer_bytes,
                "UDP-FEC mesh byte ingest",
            ),
        )
        .await??;
        info!(bind = %socket.local_addr()?, "UDP-FEC mesh byte ingest listening");
        fast_path_report.tune_receive_socket(&socket, "relay primary ingest");
        Some(socket)
    };
    let relay_secondary_bind = args.relay_secondary_bind.filter(|_| !class_ingest);
    let relay_secondary_socket = if let Some(bind) = relay_secondary_bind {
        let socket = fast_path::on_media(
            media,
            bind_buffered_udp_ingress(
                bind,
                args.udp_socket_buffer_bytes,
                "secondary RelaySession repair ingest",
            ),
        )
        .await??;
        info!(bind = %socket.local_addr()?, "secondary RelaySession repair ingest listening");
        fast_path_report.tune_receive_socket(&socket, "relay secondary ingest");
        Some(socket)
    } else {
        None
    };
    // A relay or distributor with the single loop still reads its video
    // class ports, where a parent with class threads sends its video.
    let relay_class_twins = if class_ingest || !args.relay_controlled_local {
        Vec::new()
    } else {
        let secondary = args.relay_secondary_bind;
        let (primary, offset, buffer_bytes) = (
            args.fec_bind,
            args.relay_class_port_offset,
            args.udp_socket_buffer_bytes,
        );
        let twins = fast_path::on_media(media, async move {
            bind_single_loop_class_twins(primary, secondary, offset, buffer_bytes).await
        })
        .await?;
        for (_, socket) in &twins {
            fast_path_report.tune_receive_socket(socket, "relay video class ingest");
        }
        twins
    };
    let ranked_parents = if cache_mesh_role == CacheMeshRole::Edge {
        ranked_lease_parents(&args, &mesh_peer_ips)
    } else {
        Vec::new()
    };
    let mut relay_dispatch = configured_relay_udp_dispatch(&args, &node_id)?;
    bind_ranked_lease_parents(&mut relay_dispatch, &args, &node_id, &ranked_parents)?;
    if !ranked_parents.is_empty() {
        info!(
            parents = ?ranked_parents,
            "the fast plane admits every distributor of the region (--relay-ranked-parents)"
        );
    }
    let relay_forwards = args.relay_forwards.clone();
    let forward_class_offset =
        (class_ingest && args.relay_class_port_offset > 0).then_some(args.relay_class_port_offset);
    let relay_forwarder = fast_path::on_media(media, async move {
        RelayDownstreamForwarder::bind_split(&relay_forwards, forward_class_offset).await
    })
    .await??;
    if let Some(forwarder) = &relay_forwarder {
        forwarder.set_nonblocking(args.relay_forward_nonblocking);
        forwarder.set_batch(args.relay_forward_batch);
        forwarder.set_repair_lane_single_symbol(args.relay_repair_lane_single_symbol);
        forwarder.set_repair_lane_burst_copy(args.relay_repair_lane_burst_copy);
        forwarder.set_warm_hold_us(args.relay_media_deadline_us());
        forwarder.set_demand_groups(args.relay_demand_renditions.clone());
        fast_path_report.record_relay_forward_sockets(
            forwarder.socket_groups.len(),
            forwarder.shared_socket_count(),
        );
        if args.relay_forward_batch && forwarder.shared_socket_count() == 0 {
            info!(
                children = forwarder.paths.len(),
                "relay forward batching is on but inert: every child has a source socket of its own"
            );
        }
        forwarder.configure_buffers(args.udp_socket_buffer_bytes);
        forwarder.set_hop_journal(Arc::clone(&hop_journal));
    }
    cache.update_relay_forward(
        relay_forwarder
            .as_ref()
            .map_or_else(RelayForwardSnapshot::default, |forwarder| {
                forwarder.snapshot()
            }),
    );
    // Wave 7 item 5: the children's demand in, this node's demand out. A
    // forwarder reads its children's reports whenever it reports its own
    // demand (which includes theirs), with rendition groups or without:
    // a first forwarder without groups must still pass its long-haul
    // children's demand to a contributor that has them.
    let mut demand_tasks = Vec::new();
    let reports_demand = reports_relay_demand(&args, cache_mesh_role, upstream_demand);
    if let Some(forwarder) = &relay_forwarder {
        if forwarder.demand_groups().is_some() || reports_demand {
            demand_tasks.extend(forwarder.spawn_demand_readers());
        }
    }
    let node_demand = reports_demand.then(|| {
        let demand = Arc::new(fast_plane::demand::NodeDemand::default());
        let (mesh, forwarder, out) = (
            Arc::clone(&mesh_handle),
            relay_forwarder.clone(),
            Arc::clone(&demand),
        );
        demand_tasks.push(tokio::spawn(async move {
            let mut tick = tokio::time::interval(fast_plane::demand::DEMAND_REPORT_INTERVAL);
            tick.set_missed_tick_behavior(MissedTickBehavior::Delay);
            loop {
                tick.tick().await;
                let mut streams: Vec<u64> = mesh
                    .served_subscriptions()
                    .iter()
                    .map(|served| served.stream_id)
                    .collect();
                streams.extend(mesh.subscribed_streams());
                if let Some(forwarder) = &forwarder {
                    match forwarder.child_demand(Instant::now()) {
                        Some(children) => streams.extend(children),
                        None => {
                            out.clear();
                            continue;
                        }
                    }
                }
                out.set(streams);
            }
        }));
        demand
    });
    let relay_failover_listener_tasks = start_relay_failover_listeners(
        &args.relay_failover_listeners,
        relay_forwarder.as_ref(),
        TopologyGeneration::new(args.relay_topology_generation)?,
        SubscriptionId::new(args.relay_subscription_id)?,
        &cache,
        ingest_shutdown_rx.clone(),
    )
    .await?;
    let relay_failover_controller = RelayFailoverController::bind(&args).await?;
    cache.update_relay_failover_controller(
        relay_failover_controller
            .as_ref()
            .map_or_else(RelayFailoverControllerSnapshot::default, |controller| {
                controller.snapshot()
            }),
    );
    let (audio_epoch_tx, _) = broadcast::channel(AUDIO_EPOCH_BROADCAST_CAPACITY);
    let node_status_source = NodeStatusSource {
        threads_expected: class_threads_expected,
        warm_parts: args.cache_mesh_warm_parts as u64,
        parents: Arc::new(
            [
                (args.relay_primary_peer, &args.relay_primary_id, "primary"),
                (args.relay_secondary_peer, &args.relay_secondary_id, "secondary"),
            ]
            .into_iter()
            .filter_map(|(peer, id, path)| peer.map(|peer| (peer.ip(), id.clone(), path)))
            .collect(),
        ),
        forwarder: relay_forwarder.clone(),
        node_warm: node_warm::installed().cloned(),
        ..NodeStatusSource::default()
    };
    // C CR2's make-before-break release: a parent that left a ranked set
    // goes once the fast plane sees its replacement deliver.
    let parent_release_task = tokio::spawn(run_parent_release(
        Arc::clone(&mesh_handle),
        Arc::clone(&cache),
        ingest_shutdown_rx.clone(),
    ));
    let node_cpu_task = tokio::spawn(run_node_cpu_sampler(
        edge_admission::process_cpu_us,
        edge_admission::available_cpus(),
        Arc::clone(&node_status_source.cpu_permille),
        ingest_shutdown_rx.clone(),
    ));
    let relay_ingest_runtime = RelayIngestRuntime {
        dispatch: relay_dispatch,
        secondary_socket: relay_secondary_socket,
        class_twins: relay_class_twins,
        forwarder: relay_forwarder,
        audio_epochs: Some(audio_epoch_tx.clone()),
        failover_controller: relay_failover_controller,
        failover_heartbeat: Duration::from_millis(args.relay_failover_heartbeat_ms),
        link_telemetry: Some(link_telemetry),
    };
    // The served cache-mesh leases make fast-plane children (B5).
    let (lease_children, lease_tasks) = start_lease_children(
        &args,
        class_ingest,
        &mesh_handle,
        ingest_shutdown_rx.clone(),
    )
    .await?;
    if let Some(lease) = &lease_children {
        let _ = lease_push_slot.set(Arc::clone(lease));
    }
    fast_plane::sys::set_fallback_nice(args.relay_class_fallback_nice);
    // `..Default::default()` fills the fields that exist only in tests.
    #[allow(clippy::needless_update)]
    let relay_class_config = fast_plane::relay::RelayClassConfig {
        port_offset: args.relay_class_port_offset,
        cpus: args.relay_class_cpus.0,
        realtime: args.relay_class_realtime,
        tee_capacity: args.relay_class_tee_capacity,
        video_tee_bytes: args.relay_video_tee_mb.saturating_mul(1 << 20),
        video_gso: args.relay_video_gso,
        video_gro: args.relay_video_gro,
        burst_copy_ms: args.relay_burst_copy_ms,
        loss_report: args.relay_loss_report,
        demand: node_demand,
        ranked_parents: ranked_parents.clone(),
        lease: lease_children,
        edge_clients: fast_lane.clone(),
        holes: hole_trigger.clone(),
        lease_descriptors: args.relay_lease_descriptors,
        // A 2.5: the class threads' media clocks take the budget that the
        // receiver and the warm holds take (join J2 of the A reports).
        media_deadline_us: args.relay_media_deadline_us(),
        socket_buffer_bytes: args.udp_socket_buffer_bytes,
        video_socket_buffer_ms: args.relay_video_socket_buffer_ms,
        video_socket_buffer_max_bytes: args.relay_video_socket_buffer_max_mb.saturating_mul(1 << 20),
        ..Default::default()
    };
    let fec_ingest_task = match (fec_socket, class_sockets) {
        (Some(socket), _) => fast_path::spawn_media(
            media,
            run_udp_fec_ingest(
                socket,
                Arc::clone(&cache),
                ingest_shutdown_rx.clone(),
                relay_ingest_runtime,
            ),
        ),
        (None, Some(sockets)) => fast_path::spawn_media(
            media,
            fast_plane::relay::run_relay_class_ingest(
                sockets,
                Arc::clone(&cache),
                ingest_shutdown_rx.clone(),
                relay_ingest_runtime,
                relay_class_config,
            ),
        ),
        (None, None) => unreachable!("the relay ingest binds one kind of socket"),
    };

    let media_fec_socket = bind_buffered_udp_ingress(
        args.media_fec_bind,
        args.udp_socket_buffer_bytes,
        "media UDP-FEC access-unit ingest",
    )
    .await?;
    info!(
        bind = %media_fec_socket.local_addr()?,
        "media UDP-FEC access-unit ingest listening"
    );
    let media_fec_ingest_task = tokio::spawn(run_udp_media_fec_ingest(
        media_fec_socket,
        Arc::clone(&cache),
        audio_epoch_tx.clone(),
        ingest_shutdown_rx.clone(),
    ));

    let (cert, key) = load_tls(&args)?;
    let telemetry_runtime = if let Some(bind) = args.telemetry_bind {
        Some(
            start_telemetry_feed(
                bind,
                args.telemetry_private_ipv4,
                cert.clone(),
                key.clone(),
                control_dispatch.clone(),
            )
            .await?,
        )
    } else {
        None
    };
    mesh_transport.fast_path = fast_path_report.snapshot();
    let router = AppRouter::new(
        Arc::clone(&cache),
        usize::try_from(args.response_ms.map_or(1, |response_ms| {
            response_ms.saturating_mul(1_000) / args.part_us
        }))
        .context("LL-HLS response part count exceeds this platform")?,
        Arc::clone(&mesh_handle),
        audio_epoch_tx.clone(),
        mesh_transport,
        node_profile.clone(),
        cache_mesh_role,
        replication_policy.clone(),
        control_plane.clone(),
        control_dispatch.clone(),
        telemetry_aggregator.clone(),
        demand_tracker.clone(),
        lifecycle.clone(),
        playback_base_url.clone(),
        args.hls_failover_bandwidth_bps,
        edge_load.clone(),
        edge_lifecycle_config,
        provision_executor.clone(),
        telemetry_peer_monitor.clone(),
        telemetry_fec_monitor.clone(),
        private_discovery_status,
        args.operations_snapshot_file.clone(),
    )
    .with_hls_renditions(args.hls_renditions.clone(), args.hls_rendition_stale_ms)
    .with_failover_entries(&args.failover_entries)
    .with_parents_silent_after(
        (args.edge_parents_silent_ms > 0)
            .then(|| Duration::from_millis(args.edge_parents_silent_ms)),
    )
    .with_region_silence_holds(
        args.edge_region_silence_holds,
        args.telemetry_interval_ms
            .saturating_mul(3)
            .max(REGION_SILENCE_MIN_FRESH_MS),
    )
    .with_liveness_cache(args.edge_liveness_cache_us)
    .with_region_failover(
        Duration::from_millis(args.client_udp_region_hold_ms),
        failover_probe(&args),
    )
    .with_region_head_check(args.client_udp_region_head_check)
    .with_part_wait_due(args.edge_part_wait_due)
    .with_hole_distance(
        hole_trigger
            .is_some()
            .then(|| Duration::from_millis(args.edge_hole_distance_ms)),
    )
    .with_regional_view_ttl(REGIONAL_VIEW_TTL)
    .with_node_status(node_status_source)
    .with_playlist_demand(playlist_demand)
    .with_client_udp_port(args.client_udp_bind.map(|bind| bind.port()))
    .with_host_tag(args.host_tag.clone())
    .with_assignment(
        AssignmentPolicy {
            spread_permille: u32::from(args.assignment_spread_percent.min(100)) * 10,
            max_alternates: args.assignment_alternates,
            max_head_lag_parts: args.assignment_max_head_lag_parts,
            move_headroom: args.assignment_move_headroom,
            rebalance_target_permille: args.rebalance_target_permille,
            rebalance_margin_permille: args.client_udp_rebalance_margin_permille,
            two_path_max_bps: args.assignment_two_path_max_bps,
        },
        args.steering_ttl_seconds.max(1),
        args.telemetry_interval_ms,
    )
    .with_assignment_udp_in_region(args.assignment_udp_in_region);
    let rebalance_config = RebalanceConfig {
        target_permille: args.rebalance_target_permille,
        margin_permille: args.client_udp_rebalance_margin_permille,
        interval: Duration::from_millis(args.client_udp_rebalance_interval_ms.max(500)),
        spread: Duration::from_millis(args.client_udp_drain_spread_ms),
        to_mean: args.client_udp_rebalance_to_mean,
    };
    let router = router
        .with_region_rebalance(args.client_udp_rebalance.then_some(rebalance_config))
        .with_rebalance(
            (args.client_udp_rebalance
                && args.client_udp_bind.is_some()
                && cache_mesh_role == CacheMeshRole::Edge)
                .then_some(rebalance_config),
        );
    // C 3.1: a node that starts drained takes its place once warm.
    let start_task = if cache_mesh_role == CacheMeshRole::Edge {
        tokio::spawn(lifecycle::start_edge(
            router.clone(),
            Duration::from_millis(args.start_warm_ms),
            ingest_shutdown_rx.clone(),
        ))
    } else {
        tokio::spawn(lifecycle::start_forwarder(
            router.clone(),
            ingest_shutdown_rx.clone(),
        ))
    };
    // A slot holds what its children lease, and at its start what its
    // region's edges hold (F7).
    let upstream_demand_task = upstream_demand.then(|| {
        tokio::spawn(run_upstream_demand(
            router.clone(),
            ingest_shutdown_rx.clone(),
        ))
    });
    // The stop (C 3.2) drives the node through its router.
    let stop_router = router.clone();
    let telemetry_fec_sender = if let Some(queue) = telemetry_fec_queue.clone() {
        Some(
            start_telemetry_fec_sender(
                telemetry_fec_targets.clone(),
                args.telemetry_fec_rate_bps,
                args.telemetry_fec_repair_percent,
                queue,
                telemetry_fec_monitor.clone(),
                ingest_shutdown_rx.clone(),
            )
            .await?,
        )
    } else {
        None
    };
    let telemetry_fec_collector = if let Some(bind) = args.telemetry_fec_bind {
        Some(
            start_telemetry_fec_collector(
                bind,
                telemetry_aggregator.clone(),
                telemetry_fec_monitor.clone(),
                ingest_shutdown_rx.clone(),
            )
            .await?,
        )
    } else {
        None
    };
    let telemetry_publisher_task = start_telemetry_publisher(
        router.clone(),
        args.telemetry_interval_ms,
        args.cache_mesh_test_future_frames,
        if args.telemetry_snapshots_fec_only {
            None
        } else {
            telemetry_runtime.as_ref().map(|runtime| runtime.tx.clone())
        },
        telemetry_fec_queue
            .map(|queue| TelemetryFecPublisher::new(queue, telemetry_fec_monitor.clone())),
        ingest_shutdown_rx.clone(),
    );
    let telemetry_collector_tasks = start_telemetry_collectors(
        telemetry_peers.clone(),
        args.telemetry_dns_name.clone(),
        cert.clone(),
        router.clone(),
        telemetry_peer_monitor.clone(),
        ingest_shutdown_rx.clone(),
    );
    if args.cpu_load && cache_mesh_role == CacheMeshRole::Edge {
        // Wave 9 C2: the edge's CPU over its CPUs in its load.
        let cpus = edge_admission::available_cpus();
        router.edge_load.egress.set_cpu_counter(
            // Less the tees' decode and commit, which a playlist costs
            // whatever its listeners (a 4K edge read as full and shed its
            // audio listeners, wave 9 review).
            Arc::new(edge_admission::process_cpu_us_for_listeners),
            cpus,
            args.cpu_load_full_percent,
            args.cpu_load_window_ms,
        );
        info!(
            cpus,
            full_percent = args.cpu_load_full_percent,
            window_ms = args.cpu_load_window_ms,
            "edge load counts the process's CPU"
        );
    }
    let edge_udp_task = if let Some(bind) = args.client_udp_bind {
        if args.client_udp_egress_load {
            // Phase AM item 8: the client lanes' bytes are this node's
            // egress too (read when the load is, from their counters).
            let stats = Arc::clone(&router.edge_udp_stats);
            let per_datagram =
                datagram_load_bytes(args.egress_capacity_bps, args.client_udp_datagram_capacity);
            router.edge_load.egress.add_egress_counter(Arc::new(move || {
                stats
                    .egress_wire_bytes()
                    .max(stats.egress_datagrams().saturating_mul(per_datagram))
            }));
        }
        // The pair sends by the class of a stream, which an edge learns only
        // from the class socket of a split cache mesh: without the split
        // every stream would look like audio and its 4K would leave from the
        // audio socket, ahead of the audio in band 0. One socket then.
        let class_sockets = args.client_udp_class_sockets && fast_plane::sys::supported();
        if class_sockets && !mesh_split {
            info!(
                "edge client UDP: one socket, as --client-udp-class-sockets needs the cache mesh split by class (--cache-mesh-class-port-offset)"
            );
        }
        let sockets = if class_sockets && mesh_split {
            bind_edge_class_sockets_with(
                bind,
                args.udp_socket_buffer_bytes,
                cache.stream_classes(),
                args.client_udp_send_twins,
            )?
        } else {
            edge_udp::EdgeSockets::single(
                bind_buffered_udp_ingress(bind, args.udp_socket_buffer_bytes, "edge client UDP")
                    .await?,
            )
        };
        Some(tokio::spawn(edge_udp::run_edge_udp(
            sockets
                .with_fast_lane(fast_lane.clone())
                .with_hop_journal(Some(Arc::clone(&hop_journal))),
            router.clone(),
            edge_udp::EdgeUdpConfig {
                symbol_size: args.client_udp_symbol_size,
                max_subscribers: args.client_udp_max_subscribers,
                send_queue: Duration::from_millis(args.client_udp_send_queue_ms),
                playout: Duration::from_millis(args.client_udp_playout_ms),
                move_hold_down: Duration::from_millis(args.client_udp_move_hold_down_ms),
                move_grace: Duration::from_millis(args.client_udp_move_grace_ms),
                batch_send: args.client_udp_batch_send,
                inline_complete_bytes: args.client_udp_inline_complete_bytes,
                gso: args.client_udp_gso,
                compact: args.client_udp_compact,
                compact_short_header: args.client_udp_compact_short_header,
                admit_on_first_part: args.client_udp_admit_on_first_part,
                first_part_at_once: args.client_udp_first_part_at_once,
                fresh_head: Duration::from_millis(args.client_udp_fresh_head_ms),
                nack_send_unlocked: args.client_udp_repair_thread,
                batched_admission: args.client_udp_batched_admission,
                resume_from_request: args.client_udp_resume_from_request,
                nack_edge_rate: args.client_udp_nack_edge_rate,
                admit_by_load: args.client_udp_admit_by_load,
                drain_spread: Duration::from_millis(args.client_udp_drain_spread_ms),
                keepalive: Duration::from_millis(args.client_udp_keepalive_ms),
                prompt_sender: args.client_udp_prompt_sender,
                assign: args.client_udp_assign,
                assign_confirms_per_source: args.client_udp_assign_confirms_per_source,
            },
            Arc::clone(&router.edge_udp_stats),
            edge_cut_through.clone(),
            ingest_shutdown_rx.clone(),
        )))
    } else {
        None
    };
    let replication_planner_task = tokio::spawn(run_replication_planner(
        router.clone(),
        Duration::from_millis(args.replication_plan_interval_ms),
        ingest_shutdown_rx.clone(),
    ));
    let mut server_builder = H2H3Server::builder()
        .with_tls(cert, key)
        .with_port(args.http_port)
        .enable_h2(true)
        .enable_h3(args.edge_http3 || args.edge_webtransport)
        .enable_webtransport(args.edge_webtransport)
        .enable_websocket(args.edge_websocket);
    if let Some(raw_tcp_port) = args.raw_tcp_port {
        server_builder = server_builder
            .enable_raw_tcp(true)
            .with_raw_tcp_port(raw_tcp_port)
            .with_raw_tcp_tls(args.raw_tcp_tls)
            .with_raw_tcp_handler(Box::new(router.clone()));
    }
    let server = server_builder.with_router(Box::new(router)).build()?;
    // Readers are served on threads of their own. A crowd of readers costs
    // processor for each connection, and on the threads that carry the media
    // it held the media back: a distributor that two thousand readers asked
    // at once fell behind its relays and lost parts for the whole region.
    // On one vCPU the kernel now shares the processor between the two, and
    // the threads of the readers have the lower priority.
    let http_runtime = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(args.http_worker_threads())
        .thread_name("needletail-http")
        .on_thread_start(lower_thread_priority)
        .enable_all()
        .build()
        .context("failed to start the runtime that serves readers")?;
    let handle = http_runtime
        .spawn(async move { server.start().await })
        .await
        .context("the HTTP server task ended")??;
    let _ = handle.ready_rx.await;

    println!("node:    {} ({})", node_id, args.region);
    println!("mesh:    {}", mesh_handle.local_addr());
    println!("fec:     udp+fec://{}", args.fec_bind);
    println!("media:   udp+media-fec://{}", args.media_fec_bind);
    println!(
        "hls:     https://127.0.0.1:{}/live/{}/master.m3u8",
        args.http_port, args.stream_id
    );
    println!(
        "hls-default: https://127.0.0.1:{}/live/master.m3u8",
        args.http_port
    );
    println!(
        "needletail-operations: https://127.0.0.1:{}/mesh",
        args.http_port
    );
    if args.edge_http3 || args.edge_webtransport {
        println!("hls-http3: https://127.0.0.1:{} (HTTP/3)", args.http_port);
    }
    if args.edge_websocket {
        println!(
            "edge-ws: wss://127.0.0.1:{}{}",
            args.http_port, MESH_WEBSOCKET_PATH
        );
    }
    if args.edge_webtransport {
        println!(
            "edge-webtransport: https://127.0.0.1:{} (HTTP/3 WebTransport)",
            args.http_port
        );
    }
    if let Some(runtime) = &telemetry_runtime {
        println!("telemetry: tcp+tls://{}", runtime.local_addr);
    }
    if !telemetry_peers.is_empty() {
        println!("telemetry-peers: {}", telemetry_peers.len());
    }
    if let Some(runtime) = &telemetry_fec_sender {
        println!(
            "telemetry-fec-send: udp+fec://{} targets={}",
            runtime.local_addr,
            telemetry_fec_targets.len()
        );
    }
    if let Some(runtime) = &telemetry_fec_collector {
        println!("telemetry-fec-recv: udp+fec://{}", runtime.local_addr);
    }
    if let Some(raw_tcp_port) = args.raw_tcp_port {
        println!(
            "raw-tcp: {}://0.0.0.0:{}",
            if args.raw_tcp_tls { "tls+tcp" } else { "tcp" },
            raw_tcp_port
        );
    }
    #[cfg(feature = "private-subnet-discovery")]
    if args.private_subnet_discovery {
        println!(
            "private-discovery: udp-broadcast://0.0.0.0:{} mesh-port={}",
            args.private_discovery_broadcast_port,
            args.private_discovery_mesh_port
                .unwrap_or_else(|| args.mesh_bind.port())
        );
    }
    println!("health:  https://127.0.0.1:{}/up", args.http_port);

    // The relay ingest ends only at shutdown. If it ends before (an error,
    // or a fast-plane tee that failed), the node no longer takes or commits
    // media: it shuts down with the error, so that its supervisor restarts it.
    // SIGTERM and SIGINT are a graceful stop (C 3.2): an edge drains first, a
    // forwarder says it is leaving; a second signal skips what is left.
    let mut fec_ingest_task = fec_ingest_task;
    let ingest_failure = tokio::select! {
        signal = stop.recv() => {
            info!(signal, "stopping");
            None
        }
        ended = &mut fec_ingest_task => Some(match ended {
            Ok(Ok(())) => anyhow::anyhow!("the RelaySession ingest ended"),
            Ok(Err(error)) => error.context("the RelaySession ingest failed"),
            Err(error) => anyhow::anyhow!("the RelaySession ingest ended: {error}"),
        }),
    };
    if let Some(error) = &ingest_failure {
        error!(error = %format!("{error:#}"), "shutting down");
    } else {
        let second = async {
            let signal = stop.recv().await;
            warn!(signal, "a second signal: the stop skips what is left of its waits");
        };
        let stopped = if cache_mesh_role == CacheMeshRole::Edge {
            lifecycle::stop_edge(&stop_router, args.stop_drain(), second).await
        } else {
            lifecycle::stop_forwarder(
                &stop_router,
                Duration::from_millis(args.stop_linger_ms),
                upstream_demand,
                second,
            )
            .await
        };
        info!(
            drained = stopped.drained,
            skipped = stopped.skipped,
            waited_ms = stopped.waited.as_millis() as u64,
            released = stopped.released,
            "stopped taking part: shutting down"
        );
    }
    mesh_handle.shutdown();
    let _ = ingest_shutdown_tx.send(());
    let _ = handle.shutdown_tx.send(());
    let _ = handle.finished_rx.await;
    if ingest_failure.is_none() {
        let _ = fec_ingest_task.await;
    }
    for task in &demand_tasks {
        task.abort();
    }
    for task in relay_failover_listener_tasks.into_iter().chain(lease_tasks) {
        let _ = task.await;
    }
    let _ = media_fec_ingest_task.await;
    let _ = mesh_applied_task.await;
    if let Some(task) = hole_quiet_task {
        let _ = task.await;
    }
    let _ = playlist_demand_task.await;
    let _ = playlist_standby_task.await;
    if let Some(task) = upstream_demand_task {
        let _ = task.await;
    }
    http_runtime.shutdown_background();
    let _ = replication_planner_task.await;
    let _ = node_cpu_task.await;
    let _ = parent_release_task.await;
    let _ = start_task.await;
    if let Some(task) = edge_udp_task {
        let _ = task.await;
    }
    if let Some(task) = telemetry_publisher_task {
        let _ = task.await;
    }
    if let Some(runtime) = telemetry_fec_sender {
        let _ = runtime.task.await;
    }
    if let Some(runtime) = telemetry_fec_collector {
        let _ = runtime.task.await;
    }
    if let Some(runtime) = telemetry_runtime {
        let _ = runtime.shutdown_tx.send(());
        let _ = runtime.finished_rx.await;
    }
    #[cfg(feature = "private-subnet-discovery")]
    if let Some(runtime) = private_subnet_discovery {
        let _ = runtime.shutdown_tx.send(());
        let _ = runtime.task.await;
    }
    for task in telemetry_collector_tasks {
        let _ = task.await;
    }
    match ingest_failure {
        Some(error) => Err(error),
        None => Ok(()),
    }
}

/// Give the calling thread a lower priority than the threads that carry the
/// media. On Linux a nice value belongs to the thread.
fn lower_thread_priority() {
    #[cfg(target_os = "linux")]
    {
        // SAFETY: `nice` has no memory effects. A failure leaves the
        // priority as it was.
        let _ = unsafe { libc::nice(5) };
    }
}

impl Args {
    /// `--relay-media-deadline-ms` in µs: the budget of this node's media
    /// clocks and the hold of its warm sources.
    fn relay_media_deadline_us(&self) -> u64 {
        self.relay_media_deadline_ms.saturating_mul(1_000)
    }

    /// An edge's stop bound (C 3.2, B 3.12): `--stop-drain-ms`, or B's drain
    /// spread and move grace and 2 s.
    fn stop_drain(&self) -> Duration {
        Duration::from_millis(if self.stop_drain_ms > 0 {
            self.stop_drain_ms
        } else {
            self.client_udp_drain_spread_ms
                .saturating_add(self.client_udp_move_grace_ms)
                .saturating_add(lifecycle::STOP_DRAIN_SPARE_MS)
        })
    }

    /// Threads that serve readers: the configured number, or as many as the
    /// media has.
    fn http_worker_threads(&self) -> usize {
        if self.http_worker_threads > 0 {
            return self.http_worker_threads;
        }
        std::env::var("TOKIO_WORKER_THREADS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|workers| *workers > 0)
            .or_else(|| {
                std::thread::available_parallelism()
                    .ok()
                    .map(std::num::NonZero::get)
            })
            .unwrap_or(1)
    }

    /// Requests a second that the node answers with its processor full:
    /// the configured number, or 8,000 for each worker thread.
    fn egress_request_capacity(&self) -> u64 {
        if self.egress_request_capacity > 0 {
            return self.egress_request_capacity;
        }
        let workers = std::env::var("TOKIO_WORKER_THREADS")
            .ok()
            .and_then(|value| value.parse::<u64>().ok())
            .filter(|workers| *workers > 0)
            .or_else(|| {
                std::thread::available_parallelism()
                    .ok()
                    .map(|count| count.get() as u64)
            })
            .unwrap_or(1);
        workers.saturating_mul(DEFAULT_REQUESTS_PER_WORKER)
    }

    /// An edge with --edge-fast-ingest false: its relay flags are dropped,
    /// so that it binds no relay parent and its cache mesh alone feeds it.
    fn without_edge_fast_ingest(&mut self) {
        info!("--edge-fast-ingest false: the edge ignores its relay parents and takes the cache mesh alone");
        self.relay_controlled_local = false;
        self.relay_primary_peer = None;
        self.relay_primary_bind = None;
        self.relay_secondary_peer = None;
        self.relay_secondary_bind = None;
        self.relay_primary_promoted = false;
        self.relay_secondary_promoted = false;
        self.relay_failover_controller = None;
        self.relay_failover_listeners.clear();
    }

    fn normalized(mut self) -> Result<Self> {
        self.part_us = match (self.part_us_arg, self.part_ms) {
            (Some(part_us), _) => part_us,
            (None, Some(part_ms)) => part_ms.saturating_mul(1_000),
            (None, None) => DEFAULT_PART_US,
        };
        if self.part_us == 0 {
            bail!("--part-us (or --part-ms) must be at least 1");
        }
        if self.part_us > u64::from(u32::MAX) {
            bail!("--part-us must be at most {} µs", u32::MAX);
        }
        if let Some(response_ms) = self.response_ms {
            let response_us = response_ms.saturating_mul(1_000);
            if response_us < self.part_us || !response_us.is_multiple_of(self.part_us) {
                bail!("--response-ms must be a positive multiple of the part");
            }
            if response_us / self.part_us > MAX_LLHLS_TAIL_PARTS as u64 {
                bail!("--response-ms may contain at most {MAX_LLHLS_TAIL_PARTS} parts");
            }
        }
        // Segments and windows are lengths of time. An explicit count of
        // parts is kept as given, as before.
        self.parts_per_segment = self
            .parts_per_segment_arg
            .unwrap_or_else(|| parts_in_ms(self.segment_ms.max(1), self.part_us))
            .max(1);
        self.window_parts = self
            .window_parts_arg
            .unwrap_or_else(|| parts_in_ms(self.window_ms.max(1), self.part_us))
            .max(self.parts_per_segment * 3)
            .max(6);
        let response_parts = self.response_ms.map_or(1, |response_ms| {
            response_ms.saturating_mul(1_000) / self.part_us
        });
        self.ring_parts = cache_ring_parts(
            self.part_us,
            self.parts_per_segment,
            self.window_parts,
            self.min_part_us,
        );
        // A stream of nominal parts retains four windows of them.
        let retained_cache_parts = self.window_parts.saturating_mul(4).max(32) as u64;
        if response_parts > retained_cache_parts {
            bail!(
                "--response-ms requires {response_parts} retained parts, but --window-parts retains capacity for {retained_cache_parts}; increase --window-parts"
            );
        }
        self.slot_kb = self.slot_kb.max(64);
        self.storage_bytes = self.storage_bytes.max((self.slot_kb as u64) * 1024);
        self.egress_capacity_bps = self.egress_capacity_bps.max(1);
        self.egress_admission_percent = self.egress_admission_percent.clamp(1, 100);
        self.egress_recovery_percent = self
            .egress_recovery_percent
            .clamp(1, self.egress_admission_percent.saturating_sub(1).max(1));
        self.egress_window_seconds = self.egress_window_seconds.max(1);
        self.egress_min_sustained_seconds = self
            .egress_min_sustained_seconds
            .clamp(1, self.egress_window_seconds);
        self.hls_rendition_stale_ms = self.hls_rendition_stale_ms.max(1);
        let mut hls_rendition_streams = HashSet::with_capacity(self.hls_renditions.len());
        for rendition in &self.hls_renditions {
            if !hls_rendition_streams.insert((rendition.master_stream_id, rendition.stream_id)) {
                bail!(
                    "duplicate HLS rendition stream {} for master stream {}",
                    rendition.stream_id,
                    rendition.master_stream_id
                );
            }
        }
        self.edge_min_per_region = self.edge_min_per_region.max(1);
        self.edge_max_per_region = self.edge_max_per_region.max(self.edge_min_per_region);
        self.edge_scale_up_readers = self.edge_scale_up_readers.max(1);
        self.edge_idle_seconds = self.edge_idle_seconds.max(1);
        self.edge_provision_cooldown_seconds = self.edge_provision_cooldown_seconds.max(1);
        self.cache_mesh_region = self
            .cache_mesh_region
            .take()
            .filter(|region| !region.trim().is_empty());
        self.cache_mesh_max_parents = self.cache_mesh_max_parents.max(1);
        self.cache_mesh_max_children = self.cache_mesh_max_children.max(1);
        self.mesh_sync_interval_ms = self.mesh_sync_interval_ms.max(1);
        self.mesh_symbol_size = self.mesh_symbol_size.max(1);
        self.mesh_max_repair_symbols = self.mesh_max_repair_symbols.max(self.mesh_repair_symbols);
        validate_udp_socket_buffer_target(self.udp_socket_buffer_bytes)?;
        if !self.mesh_repair_ratio.is_finite() || self.mesh_repair_ratio < 0.0 {
            bail!("--mesh-repair-ratio must be a finite non-negative number");
        }
        if self.cache_mesh_role == CacheMeshRoleArg::Edge
            && self.relay_controlled_local
            && !self.edge_fast_ingest
        {
            self.without_edge_fast_ingest();
        }
        if (self.relay_primary_peer.is_some() || self.relay_secondary_peer.is_some())
            && !self.relay_controlled_local
        {
            bail!("--relay-primary-peer/--relay-secondary-peer require --relay-controlled-local");
        }
        if self.relay_primary_bind.is_some() && self.relay_primary_peer.is_none() {
            bail!("--relay-primary-bind requires --relay-primary-peer");
        }
        if self.relay_secondary_bind.is_some() && self.relay_secondary_peer.is_none() {
            bail!("--relay-secondary-bind requires --relay-secondary-peer");
        }
        if self.relay_primary_peer.is_some() && self.relay_primary_bind.is_none() {
            self.relay_primary_bind = Some(self.fec_bind);
        }
        if self
            .relay_primary_bind
            .is_some_and(|bind| bind != self.fec_bind)
        {
            bail!("--relay-primary-bind currently shares the --fec-bind socket");
        }
        if self.relay_secondary_peer.is_some() && self.relay_secondary_bind.is_none() {
            bail!("--relay-secondary-peer requires --relay-secondary-bind");
        }
        if self.relay_secondary_promoted && self.relay_secondary_peer.is_none() {
            bail!("--relay-secondary-promoted requires --relay-secondary-peer");
        }
        if self.relay_primary_promoted && self.relay_primary_peer.is_none() {
            bail!("--relay-primary-promoted requires --relay-primary-peer");
        }
        if self
            .relay_secondary_bind
            .is_some_and(|bind| bind == self.fec_bind)
        {
            bail!("--relay-secondary-bind must differ from --fec-bind");
        }
        if self.relay_controlled_local
            && self.relay_primary_peer.is_none()
            && self.relay_secondary_peer.is_none()
        {
            bail!("--relay-controlled-local requires at least one configured relay peer");
        }
        if self.relay_primary_peer.is_some() && self.relay_primary_peer == self.relay_secondary_peer
        {
            bail!("primary and secondary relay peer addresses must differ");
        }
        if self.relay_max_downstream_children == 0 {
            bail!("--relay-max-downstream-children must be positive");
        }
        if self.relay_max_lease_children == 0 {
            bail!("--relay-max-lease-children must be positive");
        }
        if let Some(bind) = self.relay_lease_bind {
            if bind == self.fec_bind || Some(bind) == self.relay_secondary_bind {
                bail!("--relay-lease-bind {bind} conflicts with a RelaySession receive socket");
            }
            if self
                .relay_forwards
                .iter()
                .any(|forward| forward.bind == bind)
            {
                bail!("--relay-lease-bind {bind} conflicts with a --relay-forward bind");
            }
        }
        if self.relay_forwards.len() > self.relay_max_downstream_children {
            bail!(
                "{} --relay-forward subscriptions exceed the configured child limit {}",
                self.relay_forwards.len(),
                self.relay_max_downstream_children
            );
        }
        let mut relay_forward_targets = HashSet::with_capacity(self.relay_forwards.len());
        for forward in &self.relay_forwards {
            if forward.bind == forward.target {
                bail!(
                    "RelaySession forward bind and target require distinct sockets; both resolve to {}",
                    forward.bind
                );
            }
            if forward.bind == self.fec_bind || Some(forward.bind) == self.relay_secondary_bind {
                bail!(
                    "RelaySession forward bind {} conflicts with a RelaySession receive socket",
                    forward.bind
                );
            }
            // Children given the same bind share one source socket, which
            // lets one sendmmsg reach all of them (--relay-forward-batch).
            if !relay_forward_targets.insert(forward.target) {
                bail!("duplicate RelaySession forward target {}", forward.target);
            }
        }
        if self.relay_failover_controller.is_some() {
            if !self.relay_controlled_local {
                bail!("--relay-failover-controller requires --relay-controlled-local");
            }
            if self.relay_secondary_peer.is_none() || !self.relay_secondary_promoted {
                bail!(
                    "--relay-failover-controller requires a seeded --relay-secondary-peer with --relay-secondary-promoted"
                );
            }
        }
        if !self.relay_failover_listeners.is_empty() && !self.relay_controlled_local {
            bail!("--relay-failover-listener requires --relay-controlled-local");
        }
        let mut control_binds = HashSet::with_capacity(self.relay_failover_listeners.len() + 1);
        let mut controlled_targets = HashSet::with_capacity(self.relay_failover_listeners.len());
        for listener in &self.relay_failover_listeners {
            let Some(forward) = self
                .relay_forwards
                .iter()
                .find(|forward| forward.target == listener.forward_target)
            else {
                bail!(
                    "failover listener target {} is not a compiled --relay-forward target",
                    listener.forward_target
                );
            };
            if forward.role != RelayForwardRole::Repair {
                bail!(
                    "failover listener target {} must select a repair-only warm forward",
                    listener.forward_target
                );
            }
            if listener.bind == listener.peer || listener.bind.ip().is_unspecified() {
                bail!(
                    "failover listener requires a distinct, explicit local bind and controller peer"
                );
            }
            if !control_binds.insert(listener.bind) {
                bail!("duplicate failover control bind {}", listener.bind);
            }
            if !controlled_targets.insert(listener.forward_target) {
                bail!(
                    "duplicate failover control target {}",
                    listener.forward_target
                );
            }
        }
        if let Some(controller) = self.relay_failover_controller {
            if controller.bind == controller.target || controller.bind.ip().is_unspecified() {
                bail!("failover controller requires a distinct, explicit local bind and target");
            }
            if !control_binds.insert(controller.bind) {
                bail!("duplicate failover control bind {}", controller.bind);
            }
        }
        if self.relay_primary_silence_ms == 0
            || self.relay_primary_recovery_ms < self.relay_primary_silence_ms
            || self.relay_secondary_warm_ms < self.relay_primary_silence_ms
        {
            bail!(
                "relay failover windows require positive silence and recovery/warm windows at least as large as silence"
            );
        }
        if self.relay_failover_heartbeat_ms == 0
            || self.relay_failover_lease_ms < self.relay_failover_heartbeat_ms.saturating_mul(3)
            || self.relay_failover_lease_ms > 60_000
        {
            bail!(
                "relay failover lease must be at most 60000ms and at least three heartbeat intervals"
            );
        }
        TopologyGeneration::new(self.relay_topology_generation)
            .context("--relay-topology-generation must be positive")?;
        SubscriptionId::new(self.relay_subscription_id)
            .context("--relay-subscription-id must be positive")?;
        if self.telemetry_fec_targets.len() > MAX_TELEMETRY_FEC_TARGETS {
            bail!(
                "{} --telemetry-fec-target values exceed the configured limit {}",
                self.telemetry_fec_targets.len(),
                MAX_TELEMETRY_FEC_TARGETS
            );
        }
        if self.telemetry_fec_rate_bps == 0 {
            bail!("--telemetry-fec-rate-bps must be positive");
        }
        if self.telemetry_fec_repair_percent > 100 {
            bail!("--telemetry-fec-repair-percent must be between 0 and 100");
        }
        if self.telemetry_snapshots_fec_only && self.telemetry_fec_targets.is_empty() {
            bail!("--telemetry-snapshots-fec-only requires --telemetry-fec-target");
        }
        self.telemetry_interval_ms = self.telemetry_interval_ms.max(1_000);
        self.replication_plan_interval_ms = self.replication_plan_interval_ms.max(100);
        self.provision_timeout_ms = self.provision_timeout_ms.max(100);
        #[cfg(feature = "linode-provisioner")]
        self.validate_linode_provision()?;
        Ok(self)
    }

    #[cfg(feature = "linode-provisioner")]
    fn validate_linode_provision(&self) -> Result<()> {
        if !self.linode_provision {
            return Ok(());
        }
        let mut missing = Vec::new();
        if self.linode_image_id.is_none() {
            missing.push("--linode-image-id");
        }
        if self.linode_instance_type.is_none() {
            missing.push("--linode-instance-type");
        }
        if self.linode_domain_id.is_none() {
            missing.push("--linode-domain-id");
        }
        if missing.is_empty() {
            Ok(())
        } else {
            bail!("--linode-provision requires {}", missing.join(", "))
        }
    }

    #[cfg(feature = "linode-provisioner")]
    fn linode_provision_config(&self) -> Option<LinodeProvisionConfig> {
        if !self.linode_provision {
            return None;
        }
        Some(LinodeProvisionConfig {
            token_env: self.linode_token_env.clone(),
            pub_key_env: self.linode_pub_key_env.clone(),
            image_id: self.linode_image_id.clone().unwrap_or_default(),
            instance_type: self.linode_instance_type.clone().unwrap_or_default(),
            domain_id: self.linode_domain_id.unwrap_or_default(),
            vlan_tag: self.linode_vlan_tag.clone(),
            region_map: self.linode_region_maps.iter().cloned().collect(),
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RelayForwardEndpoint {
    bind: SocketAddr,
    target: SocketAddr,
    role: RelayForwardRole,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RelayFailoverListenerEndpoint {
    bind: SocketAddr,
    peer: SocketAddr,
    forward_target: SocketAddr,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RelayFailoverControllerEndpoint {
    bind: SocketAddr,
    target: SocketAddr,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct HlsRenditionSpec {
    master_stream_id: u64,
    stream_id: u64,
    bandwidth_bps: u64,
    average_bandwidth_bps: u64,
    width: u32,
    height: u32,
    frame_rate_millihertz: u32,
}

#[derive(Debug, Clone, Default)]
struct HlsRenditionCatalog {
    by_master_stream: HashMap<u64, Vec<HlsRenditionSpec>>,
    /// The ladder that each rendition belongs to, by its stream.
    master_of: HashMap<u64, u64>,
}

impl HlsRenditionCatalog {
    fn new(renditions: Vec<HlsRenditionSpec>) -> Self {
        let mut by_master_stream: HashMap<u64, Vec<HlsRenditionSpec>> = HashMap::new();
        for rendition in renditions {
            by_master_stream
                .entry(rendition.master_stream_id)
                .or_default()
                .push(rendition);
        }
        let mut master_of = HashMap::new();
        for (master_stream_id, variants) in by_master_stream.iter_mut() {
            variants.sort_by_key(|variant| {
                (std::cmp::Reverse(variant.bandwidth_bps), variant.stream_id)
            });
            for variant in variants.iter() {
                master_of
                    .entry(variant.stream_id)
                    .or_insert(*master_stream_id);
            }
        }
        Self {
            by_master_stream,
            master_of,
        }
    }

    /// The renditions of the ladder that a stream is one rendition of.
    fn ladder_of(&self, stream_id: u64) -> Option<&[HlsRenditionSpec]> {
        self.variants(*self.master_of.get(&stream_id)?)
            .filter(|ladder| ladder.len() > 1)
    }

    fn variants(&self, master_stream_id: u64) -> Option<&[HlsRenditionSpec]> {
        self.by_master_stream
            .get(&master_stream_id)
            .map(Vec::as_slice)
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, ValueEnum)]
enum RelayForwardRole {
    #[default]
    All,
    Source,
    Repair,
}

/// `--cache-mesh-fast-plane-push`, `--cache-mesh-fast-plane-video-push`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
enum CacheMeshFastPlanePush {
    All,
    Secondary,
    #[value(name = "none")]
    Nothing,
}

impl CacheMeshFastPlanePush {
    const fn live_push(self) -> fast_plane::lease::LivePush {
        match self {
            Self::All => fast_plane::lease::LivePush::All,
            Self::Secondary => fast_plane::lease::LivePush::Secondary,
            Self::Nothing => fast_plane::lease::LivePush::Nothing,
        }
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, ValueEnum)]
enum CacheMeshReplicationArg {
    #[default]
    Demand,
    All,
}

/// The replication mode in effect for a role. The `peer` role is the
/// symmetric mesh of local fixtures and always replicates every playlist.
fn effective_replication(mode: CacheMeshReplicationArg, role: CacheMeshRole) -> ReplicationMode {
    match (mode, role) {
        (CacheMeshReplicationArg::Demand, CacheMeshRole::Edge | CacheMeshRole::Distributor) => {
            ReplicationMode::Demand
        }
        _ => ReplicationMode::All,
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, ValueEnum)]
enum CacheMeshRoleArg {
    #[default]
    Edge,
    Distributor,
    Peer,
}

impl From<CacheMeshRoleArg> for CacheMeshRole {
    fn from(value: CacheMeshRoleArg) -> Self {
        match value {
            CacheMeshRoleArg::Edge => Self::Edge,
            CacheMeshRoleArg::Distributor => Self::Distributor,
            CacheMeshRoleArg::Peer => Self::Peer,
        }
    }
}

fn cache_mesh_role_label(role: CacheMeshRole) -> &'static str {
    match role {
        CacheMeshRole::Peer => "peer",
        CacheMeshRole::Distributor => "distributor",
        CacheMeshRole::Edge => "edge",
    }
}

impl RelayForwardRole {
    const fn permits(self, role: MediaDatagramRole) -> bool {
        match self {
            Self::All => true,
            Self::Source => matches!(role, MediaDatagramRole::Source),
            Self::Repair => matches!(role, MediaDatagramRole::Repair),
        }
    }
}

/// The port offset of the video class, on the relay ports and the cache
/// mesh.
const DEFAULT_CLASS_PORT_OFFSET: u16 = 1_000;

/// CPUs of the fast-plane threads, by traffic class.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct ClassCpus([Option<usize>; 2]);

fn parse_class_cpus(value: &str) -> std::result::Result<ClassCpus, String> {
    let value = value.trim();
    if value.is_empty() || value == "none" {
        return Ok(ClassCpus::default());
    }
    let mut cpus = [None, None];
    let parts: Vec<&str> = value.split(',').map(str::trim).collect();
    if parts.len() > 2 {
        return Err("expected AUDIO,VIDEO".to_owned());
    }
    for (slot, part) in cpus.iter_mut().zip(parts) {
        if !part.is_empty() {
            *slot = Some(part.parse().map_err(|_| format!("invalid CPU {part}"))?);
        }
    }
    Ok(ClassCpus(cpus))
}

fn parse_relay_forward_endpoint(value: &str) -> std::result::Result<RelayForwardEndpoint, String> {
    let (bind, target_and_role) = value
        .split_once('=')
        .ok_or_else(|| "expected BIND=TARGET,ROLE".to_owned())?;
    let (target, role) = match target_and_role.rsplit_once(',') {
        Some((target, "all")) => (target, RelayForwardRole::All),
        Some((target, "source")) => (target, RelayForwardRole::Source),
        Some((target, "repair")) => (target, RelayForwardRole::Repair),
        Some((_target, role)) => {
            return Err(format!(
                "invalid relay forward role {role}; expected source, repair, or all"
            ));
        }
        None => (target_and_role, RelayForwardRole::All),
    };
    let bind = bind
        .parse::<SocketAddr>()
        .map_err(|error| format!("invalid relay forward bind {bind}: {error}"))?;
    let target = target
        .parse::<SocketAddr>()
        .map_err(|error| format!("invalid relay forward target {target}: {error}"))?;
    Ok(RelayForwardEndpoint { bind, target, role })
}

fn parse_hls_rendition_spec(value: &str) -> std::result::Result<HlsRenditionSpec, String> {
    let fields = value.split(':').collect::<Vec<_>>();
    if fields.len() != 6 {
        return Err(
            "expected MASTER_STREAM:STREAM:BANDWIDTH:AVERAGE_BANDWIDTH:WIDTHxHEIGHT:FRAME_RATE_MILLIHERTZ"
                .to_owned(),
        );
    }
    let parse_u64 = |field: &str, label: &str| {
        field
            .parse::<u64>()
            .map_err(|error| format!("invalid HLS rendition {label} {field}: {error}"))
            .and_then(|parsed| {
                (parsed > 0)
                    .then_some(parsed)
                    .ok_or_else(|| format!("HLS rendition {label} must be positive"))
            })
    };
    let parse_u32 = |field: &str, label: &str| {
        field
            .parse::<u32>()
            .map_err(|error| format!("invalid HLS rendition {label} {field}: {error}"))
            .and_then(|parsed| {
                (parsed > 0)
                    .then_some(parsed)
                    .ok_or_else(|| format!("HLS rendition {label} must be positive"))
            })
    };
    let master_stream_id = parse_u64(fields[0], "master stream")?;
    let stream_id = parse_u64(fields[1], "stream")?;
    let bandwidth_bps = parse_u64(fields[2], "bandwidth")?;
    let average_bandwidth_bps = parse_u64(fields[3], "average bandwidth")?;
    if average_bandwidth_bps > bandwidth_bps {
        return Err("HLS rendition average bandwidth cannot exceed peak bandwidth".to_owned());
    }
    let (width, height) = fields[4]
        .split_once('x')
        .ok_or_else(|| "HLS rendition resolution must be WIDTHxHEIGHT".to_owned())?;
    Ok(HlsRenditionSpec {
        master_stream_id,
        stream_id,
        bandwidth_bps,
        average_bandwidth_bps,
        width: parse_u32(width, "width")?,
        height: parse_u32(height, "height")?,
        frame_rate_millihertz: parse_u32(fields[5], "frame rate millihertz")?,
    })
}

fn parse_relay_failover_listener_endpoint(
    value: &str,
) -> std::result::Result<RelayFailoverListenerEndpoint, String> {
    let (bind, peer_and_target) = value
        .split_once('=')
        .ok_or_else(|| "expected BIND=CONTROLLER_PEER,FORWARD_TARGET".to_owned())?;
    let (peer, forward_target) = peer_and_target
        .split_once(',')
        .ok_or_else(|| "expected BIND=CONTROLLER_PEER,FORWARD_TARGET".to_owned())?;
    Ok(RelayFailoverListenerEndpoint {
        bind: bind
            .parse()
            .map_err(|error| format!("invalid failover listener bind {bind}: {error}"))?,
        peer: peer
            .parse()
            .map_err(|error| format!("invalid failover controller peer {peer}: {error}"))?,
        forward_target: forward_target.parse().map_err(|error| {
            format!("invalid failover forward target {forward_target}: {error}")
        })?,
    })
}

fn parse_relay_failover_controller_endpoint(
    value: &str,
) -> std::result::Result<RelayFailoverControllerEndpoint, String> {
    let (bind, target) = value
        .split_once('=')
        .ok_or_else(|| "expected BIND=TARGET".to_owned())?;
    Ok(RelayFailoverControllerEndpoint {
        bind: bind
            .parse()
            .map_err(|error| format!("invalid failover controller bind {bind}: {error}"))?,
        target: target
            .parse()
            .map_err(|error| format!("invalid failover controller target {target}: {error}"))?,
    })
}

#[cfg(feature = "linode-provisioner")]
fn parse_key_value(value: &str) -> std::result::Result<(String, String), String> {
    let (key, val) = value
        .split_once('=')
        .ok_or_else(|| "expected KEY=VALUE".to_string())?;
    let key = key.trim();
    let val = val.trim();
    if key.is_empty() || val.is_empty() {
        return Err("expected non-empty KEY=VALUE".to_string());
    }
    Ok((key.to_string(), val.to_string()))
}

async fn resolve_socket_addr_args(kind: &str, values: &[String]) -> Result<Vec<SocketAddr>> {
    let mut resolved = Vec::new();
    for value in values {
        let addrs = tokio::net::lookup_host(value)
            .await
            .with_context(|| format!("failed to resolve --{kind} {value}"))?
            .collect::<Vec<_>>();
        if addrs.is_empty() {
            bail!("--{kind} {value} resolved no socket addresses");
        }
        resolved.extend(addrs);
    }
    resolved.sort();
    resolved.dedup();
    Ok(resolved)
}

/// Phase AM item 11: asks the entry point of a failover region whether it
/// holds a fresh copy of a stream (its `/api/assignment`: a fresh cache
/// that serves readers, holds the playlist and is not draining), over
/// HTTPS/2, trusting the certificates of this node's own chain (the
/// regions of one deployment share their CA). Answers are reused for
/// FAILOVER_PROBE_CACHE; a region that does not answer within
/// FAILOVER_PROBE_TIMEOUT is not fresh.
struct FailoverProbe {
    connector: tokio_rustls::TlsConnector,
    server_name: String,
    /// Per (region, stream): until when the answer holds, and the newest
    /// part that a cache there that can take a reader holds (`None`: no
    /// such cache).
    answers: tokio::sync::Mutex<HashMap<(String, u64), (Instant, Option<u64>)>>,
}

impl FailoverProbe {
    fn from_pem(pem: &[u8], server_name: String) -> Result<Self> {
        let mut roots = rustls::RootCertStore::empty();
        for certificate in rustls_pemfile::certs(&mut &pem[..]) {
            // A leaf or an intermediate as a root is harmless here: the
            // chain's CA is among them.
            let _ = roots.add(certificate?);
        }
        if roots.is_empty() {
            bail!("no certificate to trust for the failover regions");
        }
        let mut config = rustls::ClientConfig::builder_with_provider(Arc::new(
            rustls::crypto::ring::default_provider(),
        ))
        .with_safe_default_protocol_versions()?
        .with_root_certificates(roots)
        .with_no_client_auth();
        config.alpn_protocols = vec![b"h2".to_vec()];
        Ok(Self {
            connector: tokio_rustls::TlsConnector::from(Arc::new(config)),
            server_name,
            answers: tokio::sync::Mutex::new(HashMap::new()),
        })
    }

    /// Whether the failover region at `base_url` holds a fresh copy of
    /// `stream_id`: a cache there can take a reader and, with `min_head`,
    /// holds that part or a newer one (wave 8 review: a region that gets
    /// the stream through the lost one has fresh nodes and a stale head).
    async fn fresh(&self, base_url: &str, stream_id: u64, min_head: Option<u64>) -> bool {
        let key = (base_url.to_owned(), stream_id);
        let cached = self
            .answers
            .lock()
            .await
            .get(&key)
            .filter(|(at, _)| *at > Instant::now())
            .map(|(_, head)| *head);
        let head = match cached {
            Some(head) => head,
            None => {
                let head =
                    tokio::time::timeout(FAILOVER_PROBE_TIMEOUT, self.ask(base_url, stream_id))
                        .await
                        .ok()
                        .and_then(|answer| {
                            answer
                                .map_err(|error| debug!(base_url, error = %error, "failover region did not answer"))
                                .ok()
                        })
                        .flatten();
                self.answers
                    .lock()
                    .await
                    .insert(key, (Instant::now() + FAILOVER_PROBE_CACHE, head));
                head
            }
        };
        head.is_some_and(|head| min_head.is_none_or(|min| head >= min))
    }

    async fn ask(&self, base_url: &str, stream_id: u64) -> Result<Option<u64>> {
        use http_body_util::BodyExt;
        let authority = base_url
            .strip_prefix("https://")
            .ok_or_else(|| anyhow!("a failover entry is asked over HTTPS"))?
            .split('/')
            .next()
            .unwrap_or_default()
            .to_owned();
        let tcp = tokio::net::TcpStream::connect(authority.as_str()).await?;
        tcp.set_nodelay(true)?;
        let name = rustls::pki_types::ServerName::try_from(self.server_name.clone())
            .map_err(|error| anyhow!("invalid TLS server name: {error}"))?;
        let tls = self.connector.connect(name, tcp).await?;
        let (mut sender, connection) = hyper::client::conn::http2::handshake(
            hyper_util::rt::TokioExecutor::new(),
            TokioIo::new(tls),
        )
        .await?;
        tokio::spawn(async move {
            let _ = connection.await;
        });
        let request = Request::builder()
            .method(Method::GET)
            .uri(format!(
                "https://{authority}/api/assignment?stream={stream_id}"
            ))
            .body(http_body_util::Empty::<Bytes>::new())?;
        let response = sender.send_request(request).await?;
        let body = response.into_body().collect().await?.to_bytes();
        let answer: serde_json::Value = serde_json::from_slice(&body)?;
        Ok(failover_answer_head(&answer))
    }

    /// A probe that trusts nothing: its answers are set by the test.
    #[cfg(test)]
    fn for_tests() -> Self {
        let config = rustls::ClientConfig::builder_with_provider(Arc::new(
            rustls::crypto::ring::default_provider(),
        ))
        .with_safe_default_protocol_versions()
        .unwrap()
        .with_root_certificates(rustls::RootCertStore::empty())
        .with_no_client_auth();
        Self {
            connector: tokio_rustls::TlsConnector::from(Arc::new(config)),
            server_name: "local.wavey.ai".into(),
            answers: tokio::sync::Mutex::new(HashMap::new()),
        }
    }

    /// Fix the answer for a region (tests).
    #[cfg(test)]
    async fn set_answer(&self, base_url: &str, stream_id: u64, head: Option<u64>) {
        self.answers.lock().await.insert(
            (base_url.to_owned(), stream_id),
            (Instant::now() + Duration::from_secs(3_600), head),
        );
    }
}

/// The newest part held by a cache that an `/api/assignment` answer of a
/// failover region names as able to take a reader of the stream now
/// (fresh, serving readers, not draining, holding the playlist).
fn failover_answer_head(answer: &serde_json::Value) -> Option<u64> {
    answer["caches"]
        .as_array()?
        .iter()
        .filter(|cache| {
            cache["fresh"].as_bool() == Some(true)
                && cache["serves_readers"].as_bool() == Some(true)
                && cache["draining"].as_bool() != Some(true)
        })
        .filter_map(|cache| cache["head_part"].as_u64())
        .max()
}

/// The failover probe of a node with --failover-entry and
/// --client-udp-region-hold-ms, trusting its --cert chain.
fn failover_probe(args: &Args) -> Option<Arc<FailoverProbe>> {
    if args.failover_entries.is_empty() || args.client_udp_region_hold_ms == 0 {
        return None;
    }
    let Some(path) = args.cert.as_ref() else {
        warn!("--client-udp-region-hold-ms needs --cert to trust the failover regions: UDP clients are held");
        return None;
    };
    match std::fs::read(path)
        .map_err(anyhow::Error::from)
        .and_then(|pem| FailoverProbe::from_pem(&pem, args.telemetry_dns_name.clone()))
    {
        Ok(probe) => Some(Arc::new(probe)),
        Err(error) => {
            warn!(error = %error, "no failover probe: UDP clients are held through a region-wide silence");
            None
        }
    }
}

fn load_tls(args: &Args) -> Result<(String, String)> {
    match (&args.cert, &args.key) {
        (Some(cert), Some(key)) => load_tls_base64_from_paths(cert, key).with_context(|| {
            format!(
                "failed to load TLS files {} and {}",
                cert.display(),
                key.display()
            )
        }),
        (None, None) => {
            load_default_tls_base64().context("failed to load default TLS files from av-service")
        }
        _ => bail!("--cert and --key must be provided together"),
    }
}

#[cfg(feature = "private-subnet-discovery")]
struct PrivateSubnetDiscoveryRuntime {
    shutdown_tx: watch::Sender<()>,
    task: tokio::task::JoinHandle<()>,
}

#[cfg(feature = "private-subnet-discovery")]
async fn start_private_subnet_discovery(
    broadcast_port: u16,
    mesh_port: u16,
    mesh: Arc<CacheMeshHandle>,
    mut shutdown_rx: watch::Receiver<()>,
) -> Result<PrivateSubnetDiscoveryRuntime> {
    let (up_rx, _finished_rx, discovery_shutdown_tx, nodes) =
        discovery::vlan::discover(broadcast_port)
            .await
            .map_err(|err| anyhow!("private subnet discovery failed to start: {err}"))?;
    let _ = up_rx.await;

    let mut node_rx = nodes.rx();
    let task = tokio::spawn(async move {
        loop {
            tokio::select! {
                _ = shutdown_rx.changed() => return,
                discovered = node_rx.recv() => {
                    match discovered {
                        Ok(node) if node.is_self() => {}
                        Ok(node) => {
                            let peer = node.addr(mesh_port);
                            if mesh.add_peer(peer).await {
                                info!(
                                    peer = %peer,
                                    tag = ?node.tag(),
                                    seq = ?node.seq(),
                                    "private subnet discovery added cache mesh peer"
                                );
                            }
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Lagged(skipped)) => {
                            debug!(skipped, "private subnet discovery receiver lagged");
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Closed) => return,
                    }
                }
            }
        }
    });

    Ok(PrivateSubnetDiscoveryRuntime {
        shutdown_tx: discovery_shutdown_tx,
        task,
    })
}

/// Bind the lease children of a forwarder (`--relay-lease-children`) and
/// start the tasks that rebuild them from the served leases and take their
/// failover commands. None when the node has no class threads or no
/// --relay-lease-bind.
async fn start_lease_children(
    args: &Args,
    class_ingest: bool,
    mesh: &Arc<CacheMeshHandle>,
    shutdown_rx: watch::Receiver<()>,
) -> Result<(
    Option<Arc<fast_plane::lease::LeaseChildren>>,
    Vec<tokio::task::JoinHandle<()>>,
)> {
    let Some(bind) = args.relay_lease_bind.filter(|_| args.relay_lease_children) else {
        return Ok((None, Vec::new()));
    };
    if !class_ingest {
        warn!(
            bind = %bind,
            "--relay-lease-bind is inert: lease children are fed by the class threads (--relay-class-threads with --relay-controlled-local)"
        );
        return Ok((None, Vec::new()));
    }
    let lease = fast_plane::lease::LeaseChildren::bind(
        fast_plane::lease::LeaseChildConfig {
            bind,
            child_ports: args.relay_lease_child_ports,
            class_port_offset: args.relay_class_port_offset,
            primary_children: args.relay_lease_primary_children.clone(),
            max_children: args.relay_max_lease_children,
            ranked: args.relay_lease_ranked,
            warm_hold_us: args.relay_media_deadline_us(),
        },
        args.udp_socket_buffer_bytes,
    )?;
    info!(
        bind = %lease.local_addr(),
        "lease children of the served cache-mesh leases are fed on the fast plane"
    );
    let mut tasks = vec![tokio::spawn(fast_control::run_lease_children(
        Arc::clone(&lease),
        Arc::clone(mesh),
        shutdown_rx.clone(),
    ))];
    if args.relay_lease_drain_inbound {
        tasks.extend(fast_control::spawn_lease_inbound_drain(
            &lease,
            shutdown_rx.clone(),
        ));
    }
    if let Some(failover_bind) = args.relay_lease_failover_bind {
        let socket = UdpSocket::bind(failover_bind).await.with_context(|| {
            format!("failed to bind the lease children's failover listener on {failover_bind}")
        })?;
        info!(bind = %socket.local_addr()?, "lease children's failover listener ready");
        tasks.push(tokio::spawn(fast_control::run_lease_failover_listener(
            socket,
            Arc::clone(&lease),
            TopologyGeneration::new(args.relay_topology_generation)?,
            SubscriptionId::new(args.relay_subscription_id)?,
            shutdown_rx,
        )));
    }
    Ok((Some(lease), tasks))
}

fn configured_relay_udp_dispatch(args: &Args, node_id: &str) -> Result<RelayUdpDispatch> {
    let receiver = RelayObjectReceiver::new(RelayObjectReceiverConfig {
        media_deadline_us: args.relay_media_deadline_us(),
        ..RelayObjectReceiverConfig::default()
    })
    .context("invalid RelaySession receive limits")?;
    let mut dispatch = RelayUdpDispatch::new(receiver);
    if !args.relay_controlled_local {
        return Ok(dispatch);
    }

    let local = NodeId::new(node_id).context("invalid local RelaySession node identity")?;
    let generation = TopologyGeneration::new(args.relay_topology_generation)
        .context("invalid RelaySession topology generation")?;
    let subscription_id = SubscriptionId::new(args.relay_subscription_id)
        .context("invalid RelaySession subscription id")?;
    for (session_id, peer, peer_node_id, path) in [
        (
            1,
            args.relay_primary_peer,
            args.relay_primary_id.as_str(),
            if args.relay_primary_promoted {
                ParentPath::PromotedSecondary
            } else {
                ParentPath::Primary
            },
        ),
        (
            2,
            args.relay_secondary_peer,
            args.relay_secondary_id.as_str(),
            if args.relay_secondary_promoted {
                ParentPath::PromotedSecondary
            } else {
                ParentPath::Secondary
            },
        ),
    ] {
        let Some(peer) = peer else {
            continue;
        };
        let session = ControlledRelayParentSession::new(
            session_id,
            CarrierIdentity {
                local: local.clone(),
                peer: NodeId::new(peer_node_id).with_context(|| {
                    format!("invalid relay parent node identity {peer_node_id}")
                })?,
                kind: CarrierKind::PrivateUdp,
                trust_mode: TrustMode::ControlledPrivateNetwork,
            },
            generation,
            subscription_id,
            path,
        )?;
        dispatch.bind_controlled_peer(peer, session)?;
    }
    Ok(dispatch)
}

#[cfg(test)]
fn empty_relay_udp_dispatch() -> RelayUdpDispatch {
    RelayUdpDispatch::new(
        RelayObjectReceiver::new(RelayObjectReceiverConfig::default())
            .expect("default RelaySession receive limits are valid"),
    )
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct RelayForwardSnapshot {
    downstream_children: u64,
    source_datagrams: u64,
    repair_datagrams: u64,
    bytes: u64,
    errors: u64,
    filtered_datagrams: u64,
    warm_source_buffered_datagrams: u64,
    warm_source_buffered_bytes: u64,
    warm_source_replayed_datagrams: u64,
    warm_source_replayed_bytes: u64,
    warm_source_expired_datagrams: u64,
    warm_source_retired_datagrams: u64,
    warm_source_evicted_datagrams: u64,
    warm_source_refused_datagrams: u64,
    duration_count: u64,
    duration_sum_us: u64,
    duration_max_us: u64,
    duration_buckets: [u64; EDGE_RESPONSE_DURATION_BUCKETS_US.len()],
    failover_listeners: u64,
    failover_promoted_children: u64,
    failover_commands_received: u64,
    failover_commands_rejected: u64,
    failover_lease_expirations: u64,
    failover_promotions_applied: u64,
    failover_demotions_applied: u64,
    failover_last_transition_unix_ms: u64,
}

/// The identity of a buffered object: a hash of its key's fields. Computed
/// from an `ObjectKey`, or from the RLS1 header in place on the fast plane
/// (no allocation); both give the same value.
#[allow(clippy::too_many_arguments)]
fn warm_object_id(
    tenant: &str,
    stream: &str,
    track: &str,
    epoch: u64,
    group: u64,
    object: u64,
    version: u32,
    payload_hash: &[u8; 32],
) -> u64 {
    use std::hash::Hasher;
    let mut hasher = std::hash::DefaultHasher::new();
    hasher.write(tenant.as_bytes());
    hasher.write_u8(0xff);
    hasher.write(stream.as_bytes());
    hasher.write_u8(0xff);
    hasher.write(track.as_bytes());
    hasher.write_u8(0xff);
    hasher.write_u64(epoch);
    hasher.write_u64(group);
    hasher.write_u64(object);
    hasher.write_u32(version);
    hasher.write(payload_hash);
    hasher.finish()
}

fn warm_object_id_of_key(key: &media_object::ObjectKey) -> u64 {
    warm_object_id(
        key.tenant(),
        key.stream(),
        key.track(),
        key.epoch(),
        key.group(),
        key.object(),
        key.version(),
        key.payload_hash().as_bytes(),
    )
}

/// The capacity a warm-source buffer is given when first used: a whole RLS1
/// datagram, so that a reused buffer never grows.
const WARM_SOURCE_SLOT_BYTES: usize = 1_536;
/// Buffers a warm-source buffer keeps for its next pushes, at most: one
/// more than the datagrams it holds.
const WARM_SOURCE_SPARE_BUFFERS: usize = RELAY_WARM_SOURCE_REPLAY_MAX_DATAGRAMS_PER_CHILD + 1;

#[derive(Debug)]
struct WarmSourceDatagram {
    object: u64,
    expires_at_us: u64,
    wire: Vec<u8>,
}

/// The source datagrams held back from a warm repair-only child, replayed
/// to it on promotion. A forwarder keeps one per child and class, touched
/// only by that class's thread (or the single receive loop) and a replay.
/// A datagram is kept for a hold from its receipt, on this node's clock (its
/// wire deadline is on the stream's timeline and says nothing here).
/// Datagram buffers are reused, and expiry and the bounds work from the
/// front, so a push costs O(1) amortised and, once warm, allocates nothing.
/// A buffer made [`Self::preallocated`] (the audio class's, read by the
/// real-time class thread) allocates nothing from its first push: its
/// queues have their whole room and its spare holds a buffer for every
/// datagram it may keep, each faulted in; a datagram longer than a slot is
/// refused (counted), not given a larger buffer.
#[derive(Debug, Default)]
struct WarmSourceReplayBuffer {
    datagrams: VecDeque<WarmSourceDatagram>,
    /// The objects held, oldest first, with how many datagrams each has.
    object_order: VecDeque<(u64, usize)>,
    bytes: usize,
    /// Buffers of datagrams that left, for the next pushes.
    spare: Vec<Vec<u8>>,
    /// Made with all its room: a push never allocates.
    fixed: bool,
}

#[derive(Debug, Default)]
struct WarmSourceBufferMutation {
    /// Not kept: longer than a preallocated slot, or no room left.
    refused_datagrams: usize,
    added_datagrams: usize,
    added_bytes: usize,
    expired_datagrams: usize,
    expired_bytes: usize,
    retired_datagrams: usize,
    retired_bytes: usize,
    evicted_datagrams: usize,
    evicted_bytes: usize,
}

impl WarmSourceBufferMutation {
    fn removed_datagrams(&self) -> usize {
        self.expired_datagrams
            .saturating_add(self.retired_datagrams)
            .saturating_add(self.evicted_datagrams)
    }

    fn removed_bytes(&self) -> usize {
        self.expired_bytes
            .saturating_add(self.retired_bytes)
            .saturating_add(self.evicted_bytes)
    }
}

#[derive(Debug, Default)]
struct WarmSourceReplayBatch {
    datagrams: Vec<Vec<u8>>,
    bytes: usize,
    expired_datagrams: usize,
    expired_bytes: usize,
}

impl WarmSourceReplayBuffer {
    #[cfg_attr(not(test), allow(dead_code))]
    fn push_key(
        &mut self,
        object_key: &media_object::ObjectKey,
        hold_us: u64,
        wire: &[u8],
        now_us: u64,
    ) -> WarmSourceBufferMutation {
        self.push(warm_object_id_of_key(object_key), hold_us, wire, now_us)
    }

    /// A buffer with the room of its bounds made now, and its pages
    /// faulted in: about 3 MB, made off the class thread (with the path,
    /// or before a replay swaps it in).
    fn preallocated() -> Self {
        let mut datagrams = VecDeque::with_capacity(RELAY_WARM_SOURCE_REPLAY_MAX_DATAGRAMS_PER_CHILD + 1);
        let mut object_order =
            VecDeque::with_capacity(RELAY_WARM_SOURCE_REPLAY_MAX_OBJECTS_PER_CHILD + 1);
        // Each queue's room, written once.
        for _ in 0..datagrams.capacity() {
            datagrams.push_back(WarmSourceDatagram {
                object: 0,
                expires_at_us: 0,
                wire: Vec::new(),
            });
        }
        datagrams.clear();
        for _ in 0..object_order.capacity() {
            object_order.push_back((0, 0));
        }
        object_order.clear();
        // One buffer more than it keeps: a push takes one before the bound
        // gives the oldest back.
        let spare = (0..WARM_SOURCE_SPARE_BUFFERS)
            .map(|_| {
                let mut buffer = Vec::with_capacity(WARM_SOURCE_SLOT_BYTES);
                memory::touch_spare(&mut buffer);
                buffer
            })
            .collect();
        Self {
            datagrams,
            object_order,
            bytes: 0,
            spare,
            fixed: true,
        }
    }

    /// Made with all its room ([`Self::preallocated`]): a push never
    /// allocates.
    const fn is_fixed(&self) -> bool {
        self.fixed
    }

    /// Keep `wire` for `hold_us` from `now_us`, this node's clock.
    fn push(
        &mut self,
        object: u64,
        hold_us: u64,
        wire: &[u8],
        now_us: u64,
    ) -> WarmSourceBufferMutation {
        let mut mutation = WarmSourceBufferMutation::default();
        self.remove_expired(now_us, &mut mutation);
        if hold_us == 0 || wire.len() > RELAY_WARM_SOURCE_REPLAY_MAX_BYTES_PER_CHILD {
            return mutation;
        }
        if self.fixed && (wire.len() > WARM_SOURCE_SLOT_BYTES || self.spare.is_empty()) {
            mutation.refused_datagrams = 1;
            return mutation;
        }
        let expires_at_us = now_us.saturating_add(hold_us);

        // Most pushes are of the newest object.
        match self
            .object_order
            .iter_mut()
            .rev()
            .find(|(id, _)| *id == object)
        {
            Some((_, count)) => *count += 1,
            None => self.object_order.push_back((object, 1)),
        }
        let mut buffer = self
            .spare
            .pop()
            .unwrap_or_else(|| Vec::with_capacity(wire.len().max(WARM_SOURCE_SLOT_BYTES)));
        buffer.clear();
        buffer.extend_from_slice(wire);
        self.bytes = self.bytes.saturating_add(wire.len());
        self.datagrams.push_back(WarmSourceDatagram {
            object,
            expires_at_us,
            wire: buffer,
        });
        mutation.added_datagrams = 1;
        mutation.added_bytes = wire.len();

        while self.object_order.len() > RELAY_WARM_SOURCE_REPLAY_MAX_OBJECTS_PER_CHILD {
            if let Some((oldest, count)) = self.object_order.pop_front() {
                self.remove_object(oldest, count, &mut mutation);
            }
        }
        while self.datagrams.len() > RELAY_WARM_SOURCE_REPLAY_MAX_DATAGRAMS_PER_CHILD
            || self.bytes > RELAY_WARM_SOURCE_REPLAY_MAX_BYTES_PER_CHILD
        {
            let Some(evicted) = self.datagrams.pop_front() else {
                break;
            };
            mutation.evicted_datagrams = mutation.evicted_datagrams.saturating_add(1);
            mutation.evicted_bytes = mutation.evicted_bytes.saturating_add(evicted.wire.len());
            self.release(evicted);
        }
        mutation
    }

    fn take_live(&mut self, now_us: u64) -> WarmSourceReplayBatch {
        let mut batch = WarmSourceReplayBatch::default();
        for datagram in self.datagrams.drain(..) {
            if datagram.expires_at_us <= now_us {
                batch.expired_datagrams = batch.expired_datagrams.saturating_add(1);
                batch.expired_bytes = batch.expired_bytes.saturating_add(datagram.wire.len());
            } else {
                batch.bytes = batch.bytes.saturating_add(datagram.wire.len());
                batch.datagrams.push(datagram.wire);
            }
        }
        self.object_order.clear();
        self.bytes = 0;
        batch
    }

    /// Drop the expired datagrams at the front. One that expires behind a
    /// live one waits for it to leave (or for a replay, which skips it).
    fn remove_expired(&mut self, now_us: u64, mutation: &mut WarmSourceBufferMutation) {
        while self
            .datagrams
            .front()
            .is_some_and(|datagram| datagram.expires_at_us <= now_us)
        {
            let Some(datagram) = self.datagrams.pop_front() else {
                break;
            };
            mutation.expired_datagrams = mutation.expired_datagrams.saturating_add(1);
            mutation.expired_bytes = mutation.expired_bytes.saturating_add(datagram.wire.len());
            self.release(datagram);
        }
    }

    /// Account for a datagram that left, and keep its buffer.
    fn release(&mut self, datagram: WarmSourceDatagram) {
        self.bytes = self.bytes.saturating_sub(datagram.wire.len());
        if let Some(index) = self
            .object_order
            .iter()
            .position(|(id, _)| *id == datagram.object)
        {
            let count = &mut self.object_order[index].1;
            *count = count.saturating_sub(1);
            if *count == 0 {
                self.object_order.remove(index);
            }
        }
        if self.spare.len() < WARM_SOURCE_SPARE_BUFFERS {
            self.spare.push(datagram.wire);
        }
    }

    /// Remove the `count` datagrams of an object that has left
    /// `object_order`: from the front while they lead, then by one pass.
    fn remove_object(
        &mut self,
        object: u64,
        mut count: usize,
        mutation: &mut WarmSourceBufferMutation,
    ) {
        let mut retire = |buffer: &mut Self, datagram: WarmSourceDatagram| {
            buffer.bytes = buffer.bytes.saturating_sub(datagram.wire.len());
            mutation.retired_datagrams = mutation.retired_datagrams.saturating_add(1);
            mutation.retired_bytes = mutation.retired_bytes.saturating_add(datagram.wire.len());
            if buffer.spare.len() < WARM_SOURCE_SPARE_BUFFERS {
                buffer.spare.push(datagram.wire);
            }
        };
        while count > 0
            && self
                .datagrams
                .front()
                .is_some_and(|datagram| datagram.object == object)
        {
            if let Some(datagram) = self.datagrams.pop_front() {
                retire(self, datagram);
                count -= 1;
            }
        }
        if count == 0 {
            return;
        }
        // Interleaved with other objects: one pass, in place.
        for _ in 0..self.datagrams.len() {
            let Some(datagram) = self.datagrams.pop_front() else {
                break;
            };
            if datagram.object == object {
                retire(self, datagram);
            } else {
                self.datagrams.push_back(datagram);
            }
        }
    }
}

struct RelayForwardPath {
    /// The source socket. Children given the same non-zero bind share one
    /// socket, so one `sendmmsg` reaches all of them.
    socket: Arc<UdpSocket>,
    /// Index into `RelayDownstreamForwarder::socket_groups`.
    group: usize,
    target: SocketAddr,
    /// Where the child takes video-class datagrams: `target` at the class
    /// port offset when the forwarder is split by class, else `target`.
    video_target: SocketAddr,
    role: RelayForwardRole,
    promoted: AtomicBool,
    /// Warm sources by traffic class ([`fast_plane::TrafficClass::index`]):
    /// each class's thread holds only its own lock, so a 4K symbol's
    /// buffering never holds an audio one back, and audio objects never
    /// push a 4K object out. The single receive loop uses the audio one.
    warm_sources: [StdMutex<WarmSourceReplayBuffer>; 2],
    /// The child's last demand report (`RLD1`, wave 7 item 5).
    demand: fast_plane::demand::DemandSlot,
}

struct RelayDownstreamForwarder {
    paths: Vec<RelayForwardPath>,
    /// The paths of each source socket, in path order.
    socket_groups: Vec<Vec<usize>>,
    /// The video-class twin of each source socket, on the same address
    /// (SO_REUSEPORT), so that a child's peer binding holds for both
    /// classes. Empty unless the forwarder is split by class.
    video_sockets: Vec<Arc<UdpSocket>>,
    source_datagrams: AtomicU64,
    repair_datagrams: AtomicU64,
    bytes: AtomicU64,
    errors: AtomicU64,
    filtered_datagrams: AtomicU64,
    warm_source_buffered_datagrams: AtomicU64,
    warm_source_buffered_bytes: AtomicU64,
    warm_source_replayed_datagrams: AtomicU64,
    warm_source_replayed_bytes: AtomicU64,
    warm_source_expired_datagrams: AtomicU64,
    warm_source_retired_datagrams: AtomicU64,
    warm_source_evicted_datagrams: AtomicU64,
    /// Sources not kept for a repair-only child: its buffer's lock was held
    /// by a replay, or the datagram was longer than a preallocated slot.
    warm_source_refused_datagrams: AtomicU64,
    duration_count: AtomicU64,
    duration_sum_us: AtomicU64,
    duration_max_us: AtomicU64,
    duration_buckets: [AtomicU64; EDGE_RESPONSE_DURATION_BUCKETS_US.len()],
    failover_listeners: AtomicU64,
    failover_commands_received: AtomicU64,
    failover_commands_rejected: AtomicU64,
    failover_lease_expirations: AtomicU64,
    failover_promotions_applied: AtomicU64,
    failover_demotions_applied: AtomicU64,
    failover_last_transition_unix_ms: AtomicU64,
    /// Send to every child with a non-blocking send first, and await only
    /// the children whose socket was full.
    nonblocking: AtomicBool,
    /// Hand one datagram to every child of a shared source socket, and a
    /// warm-source replay to its child, in one `sendmmsg` call.
    batch: AtomicBool,
    /// `--relay-repair-lane-single-symbol`: a repair-lane child takes the
    /// source of a one-symbol audio object (fast plane).
    repair_lane_single_symbol: AtomicBool,
    /// `--relay-repair-lane-burst-copy`: that symbol gets a burst copy.
    repair_lane_burst_copy: AtomicBool,
    /// `--relay-media-deadline-ms`, in µs: how long a source held back from
    /// a warm repair-only child is kept from its receipt.
    warm_hold_us: AtomicU64,
    /// `--relay-demand-renditions`: renditions held off a compiled lane
    /// whose child does not read them. Unset or empty: none.
    demand_groups: OnceLock<fast_plane::demand::RenditionGroups>,
    hop_journal: OnceLock<Arc<HopJournal>>,
    /// Children whose non-blocking send a test reports as full, as a bit
    /// set of path indexes.
    #[cfg(test)]
    test_would_block: AtomicU64,
    #[cfg(test)]
    test_attempts: StdMutex<Vec<(usize, RelayForwardAttempt)>>,
}

/// How the forwarder tried to hand a datagram to a child.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(not(test), allow(dead_code))]
enum RelayForwardAttempt {
    /// A non-blocking send that the kernel took.
    Immediate,
    /// Part of one `sendmmsg` to the children of a shared socket, which the
    /// kernel took.
    Batched,
    /// A non-blocking send that found the socket full.
    WouldBlock,
    /// A send that the forwarder waited for.
    Awaited,
}

impl RelayDownstreamForwarder {
    /// The compiled children, for `GET /api/node`.
    fn compiled_children(&self) -> Vec<node_status::CompiledChild> {
        self.paths
            .iter()
            .map(|path| node_status::CompiledChild {
                target: path.target.to_string(),
                lane: match path.role {
                    RelayForwardRole::All => "all",
                    RelayForwardRole::Source => "source",
                    RelayForwardRole::Repair => "repair",
                }
                .to_owned(),
                promoted: path.promoted.load(Ordering::Relaxed),
            })
            .collect()
    }

    #[cfg_attr(not(test), allow(dead_code))]
    async fn bind(endpoints: &[RelayForwardEndpoint]) -> Result<Option<Arc<Self>>> {
        Self::bind_split(endpoints, None).await
    }

    /// Bind the source sockets. With `class_port_offset`, each source socket
    /// is an audio/video pair on one address: the audio socket at
    /// SO_PRIORITY 6 sends to the child's port, the video twin to the
    /// child's port plus the offset, where the child's video thread listens.
    async fn bind_split(
        endpoints: &[RelayForwardEndpoint],
        class_port_offset: Option<u16>,
    ) -> Result<Option<Arc<Self>>> {
        if endpoints.is_empty() {
            return Ok(None);
        }
        let mut video_sockets: Vec<Arc<UdpSocket>> = Vec::new();
        let mut paths = Vec::with_capacity(endpoints.len());
        let mut socket_groups: Vec<Vec<usize>> = Vec::new();
        // Sockets by bind address. Port 0 asks for a socket of its own each
        // time; a fixed address given twice is one shared socket.
        let mut shared: HashMap<SocketAddr, (Arc<UdpSocket>, usize)> = HashMap::new();
        for (index, endpoint) in endpoints.iter().enumerate() {
            let existing = (endpoint.bind.port() != 0)
                .then(|| shared.get(&endpoint.bind).cloned())
                .flatten();
            let (socket, group) = if let Some((socket, group)) = existing {
                socket_groups[group].push(index);
                (socket, group)
            } else {
                let socket = Arc::new(
                    match class_port_offset {
                        None => UdpSocket::bind(endpoint.bind).await,
                        Some(_) => {
                            fast_plane::sys::bind_reuseport(endpoint.bind).and_then(|socket| {
                                fast_plane::sys::set_priority(
                                    &socket,
                                    fast_plane::sys::AUDIO_SO_PRIORITY,
                                )?;
                                UdpSocket::from_std(socket)
                            })
                        }
                    }
                    .with_context(|| {
                        format!(
                            "failed to bind RelaySession downstream source {} for {}",
                            endpoint.bind, endpoint.target
                        )
                    })?,
                );
                if class_port_offset.is_some() {
                    let local = socket.local_addr()?;
                    let twin = fast_plane::sys::bind_reuseport(local)
                        .and_then(UdpSocket::from_std)
                        .with_context(|| {
                            format!("failed to bind the video twin of RelaySession source {local}")
                        })?;
                    video_sockets.push(Arc::new(twin));
                }
                let group = socket_groups.len();
                socket_groups.push(vec![index]);
                if endpoint.bind.port() != 0 {
                    shared.insert(endpoint.bind, (Arc::clone(&socket), group));
                }
                (socket, group)
            };
            info!(
                bind = %socket.local_addr()?,
                target = %endpoint.target,
                role = ?endpoint.role,
                shared_with = socket_groups[group].len() - 1,
                "RelaySession subscribed downstream forwarding path ready"
            );
            let video_target = match class_port_offset {
                Some(offset) => fast_plane::class_addr(
                    endpoint.target,
                    fast_plane::TrafficClass::Video,
                    offset,
                )?,
                None => endpoint.target,
            };
            paths.push(RelayForwardPath {
                socket,
                group,
                target: endpoint.target,
                video_target,
                role: endpoint.role,
                promoted: AtomicBool::new(false),
                // A repair-only child's sources are kept by the class
                // threads (audio real-time, video too since fix4-video):
                // in buffers made whole here.
                warm_sources: [(); 2].map(|()| {
                    StdMutex::new(if endpoint.role == RelayForwardRole::Repair {
                        WarmSourceReplayBuffer::preallocated()
                    } else {
                        WarmSourceReplayBuffer::default()
                    })
                }),
                demand: Default::default(),
            });
        }
        Ok(Some(Arc::new(Self {
            paths,
            socket_groups,
            video_sockets,
            source_datagrams: AtomicU64::new(0),
            repair_datagrams: AtomicU64::new(0),
            bytes: AtomicU64::new(0),
            errors: AtomicU64::new(0),
            filtered_datagrams: AtomicU64::new(0),
            warm_source_buffered_datagrams: AtomicU64::new(0),
            warm_source_buffered_bytes: AtomicU64::new(0),
            warm_source_replayed_datagrams: AtomicU64::new(0),
            warm_source_replayed_bytes: AtomicU64::new(0),
            warm_source_expired_datagrams: AtomicU64::new(0),
            warm_source_retired_datagrams: AtomicU64::new(0),
            warm_source_evicted_datagrams: AtomicU64::new(0),
            warm_source_refused_datagrams: AtomicU64::new(0),
            duration_count: AtomicU64::new(0),
            duration_sum_us: AtomicU64::new(0),
            duration_max_us: AtomicU64::new(0),
            duration_buckets: std::array::from_fn(|_| AtomicU64::new(0)),
            failover_listeners: AtomicU64::new(0),
            failover_commands_received: AtomicU64::new(0),
            failover_commands_rejected: AtomicU64::new(0),
            failover_lease_expirations: AtomicU64::new(0),
            failover_promotions_applied: AtomicU64::new(0),
            failover_demotions_applied: AtomicU64::new(0),
            failover_last_transition_unix_ms: AtomicU64::new(0),
            nonblocking: AtomicBool::new(true),
            batch: AtomicBool::new(true),
            repair_lane_single_symbol: AtomicBool::new(true),
            repair_lane_burst_copy: AtomicBool::new(true),
            warm_hold_us: AtomicU64::new(DEFAULT_RELAY_MEDIA_DEADLINE_MS * 1_000),
            demand_groups: OnceLock::new(),
            hop_journal: OnceLock::new(),
            #[cfg(test)]
            test_would_block: AtomicU64::new(0),
            #[cfg(test)]
            test_attempts: StdMutex::new(Vec::new()),
        })))
    }

    async fn forward(
        &self,
        datagram: &[u8],
        role: MediaDatagramRole,
        object_key: Option<&media_object::ObjectKey>,
    ) {
        let nonblocking = self.nonblocking.load(Ordering::Relaxed);
        let batch = nonblocking && self.batch.load(Ordering::Relaxed);
        // Children whose socket was full for a non-blocking send. They are
        // served, in order, once every other child has the datagram. Empty
        // in the normal case, so it costs no allocation.
        let mut deferred: Vec<usize> = Vec::new();
        let mut first_child: Option<(SocketAddr, u64)> = None;
        // Shared sockets already served by one batched send, as a bit set of
        // group indexes.
        let mut batched_groups = 0_u64;
        for (index, path) in self.paths.iter().enumerate() {
            if batch && self.group_is_batched(path.group) {
                let bit = 1_u64 << path.group;
                if batched_groups & bit == 0 {
                    batched_groups |= bit;
                    self.forward_group(
                        path.group,
                        datagram,
                        role,
                        object_key,
                        &mut deferred,
                        &mut first_child,
                    );
                }
                continue;
            }
            if !self.admits(path, datagram, role, object_key) {
                continue;
            }
            let started = Instant::now();
            let result = if nonblocking {
                match self.try_send_on_path(index, path, datagram) {
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        self.record_forward_attempt(index, RelayForwardAttempt::WouldBlock);
                        deferred.push(index);
                        continue;
                    }
                    result => {
                        self.record_forward_attempt(index, RelayForwardAttempt::Immediate);
                        result
                    }
                }
            } else {
                self.record_forward_attempt(index, RelayForwardAttempt::Awaited);
                path.socket.send_to(datagram, path.target).await
            };
            if self.finish_forward(path, role, datagram.len(), result, started.elapsed())
                && first_child.is_none()
            {
                first_child = Some((path.target, now_unix_us()));
            }
        }
        for index in deferred {
            let path = &self.paths[index];
            let started = Instant::now();
            self.record_forward_attempt(index, RelayForwardAttempt::Awaited);
            let result = path.socket.send_to(datagram, path.target).await;
            if self.finish_forward(path, role, datagram.len(), result, started.elapsed())
                && first_child.is_none()
            {
                first_child = Some((path.target, now_unix_us()));
            }
        }
        if let (Some((child, sent_us)), Some(object_key)) = (first_child, object_key) {
            self.journal_forward(object_key, child, sent_us);
        }
    }

    /// Whether a path takes a datagram of this role. A source datagram held
    /// back from a warm repair-only child is kept for a later promotion.
    fn admits(
        &self,
        path: &RelayForwardPath,
        datagram: &[u8],
        role: MediaDatagramRole,
        object_key: Option<&media_object::ObjectKey>,
    ) -> bool {
        let promoted = path.promoted.load(Ordering::Relaxed);
        let failover_source = promoted
            && path.role == RelayForwardRole::Repair
            && matches!(role, MediaDatagramRole::Source);
        if path.role.permits(role) || failover_source {
            return true;
        }
        if path.role == RelayForwardRole::Repair && matches!(role, MediaDatagramRole::Source) {
            if let Some(object_key) = object_key {
                self.buffer_warm_source(path, object_key, datagram, now_unix_us());
            }
        }
        self.filtered_datagrams.fetch_add(1, Ordering::Relaxed);
        false
    }

    /// Source sockets whose children are served by one batched send.
    fn shared_socket_count(&self) -> usize {
        (0..self.socket_groups.len())
            .filter(|group| self.group_is_batched(*group))
            .count()
    }

    /// Whether the children of a source socket are served by one batched
    /// send: several of them share it, and they fit one call.
    fn group_is_batched(&self, group: usize) -> bool {
        let members = self.socket_groups[group].len();
        group < 64 && members > 1 && members <= fast_path::MAX_BATCH_MESSAGES
    }

    /// Hand a datagram to every child of one shared socket in one
    /// `sendmmsg`. Children the kernel did not take in that call get a
    /// non-blocking send of their own, and a full socket is waited for
    /// after every other child has the datagram, as in the unbatched path.
    fn forward_group(
        &self,
        group: usize,
        datagram: &[u8],
        role: MediaDatagramRole,
        object_key: Option<&media_object::ObjectKey>,
        deferred: &mut Vec<usize>,
        first_child: &mut Option<(SocketAddr, u64)>,
    ) {
        let mut eligible = [0_usize; fast_path::MAX_BATCH_MESSAGES];
        let mut count = 0;
        for &index in &self.socket_groups[group] {
            let path = &self.paths[index];
            if !self.admits(path, datagram, role, object_key) {
                continue;
            }
            #[cfg(test)]
            if self.test_would_block.load(Ordering::Relaxed) & (1_u64 << (index % 64)) != 0 {
                self.record_forward_attempt(index, RelayForwardAttempt::WouldBlock);
                deferred.push(index);
                continue;
            }
            eligible[count] = index;
            count += 1;
        }
        if count == 0 {
            return;
        }
        let eligible = &eligible[..count];
        let socket = &self.paths[eligible[0]].socket;
        let started = Instant::now();
        let sent = match fast_path::try_send_batch(socket, count, |slot| {
            (datagram, self.paths[eligible[slot]].target)
        }) {
            Ok(sent) => sent,
            // Full before the first child, or the first child failed: each
            // child gets its own attempt below, which waits or reports.
            Err(_) => 0,
        };
        let elapsed = started.elapsed();
        for &index in &eligible[..sent] {
            let path = &self.paths[index];
            self.record_forward_attempt(index, RelayForwardAttempt::Batched);
            if self.finish_forward(path, role, datagram.len(), Ok(datagram.len()), elapsed)
                && first_child.is_none()
            {
                *first_child = Some((path.target, now_unix_us()));
            }
        }
        for &index in &eligible[sent..] {
            let path = &self.paths[index];
            let started = Instant::now();
            match self.try_send_on_path(index, path, datagram) {
                Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                    self.record_forward_attempt(index, RelayForwardAttempt::WouldBlock);
                    deferred.push(index);
                }
                result => {
                    self.record_forward_attempt(index, RelayForwardAttempt::Immediate);
                    if self.finish_forward(path, role, datagram.len(), result, started.elapsed())
                        && first_child.is_none()
                    {
                        *first_child = Some((path.target, now_unix_us()));
                    }
                }
            }
        }
    }

    /// Count one send to a child and report whether the whole datagram left.
    fn finish_forward(
        &self,
        path: &RelayForwardPath,
        role: MediaDatagramRole,
        expected: usize,
        result: std::io::Result<usize>,
        duration: Duration,
    ) -> bool {
        match result {
            Ok(sent) if sent == expected => {
                self.record_forward_success(role, sent, duration);
                true
            }
            Ok(sent) => {
                self.errors.fetch_add(1, Ordering::Relaxed);
                warn!(
                    target = %path.target,
                    expected_bytes = expected,
                    sent_bytes = sent,
                    "RelaySession downstream forwarding sent a partial datagram"
                );
                false
            }
            Err(error) => {
                self.errors.fetch_add(1, Ordering::Relaxed);
                warn!(
                    target = %path.target,
                    error = %error,
                    "RelaySession downstream forwarding failed"
                );
                false
            }
        }
    }

    /// One non-blocking send on the registered socket of a child.
    fn try_send_on_path(
        &self,
        index: usize,
        path: &RelayForwardPath,
        datagram: &[u8],
    ) -> std::io::Result<usize> {
        #[cfg(test)]
        if self.test_would_block.load(Ordering::Relaxed) & (1_u64 << (index % 64)) != 0 {
            return Err(std::io::ErrorKind::WouldBlock.into());
        }
        let _ = index;
        path.socket.try_send_to(datagram, path.target)
    }

    #[cfg_attr(not(test), allow(unused_variables))]
    fn record_forward_attempt(&self, index: usize, attempt: RelayForwardAttempt) {
        #[cfg(test)]
        self.test_attempts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .push((index, attempt));
    }

    /// Journal `relay_forward` for the first symbol of an object that left
    /// for a child.
    fn journal_forward(&self, object_key: &media_object::ObjectKey, child: SocketAddr, t_us: u64) {
        let Some(journal) = self
            .hop_journal
            .get()
            .filter(|journal| journal.is_enabled())
        else {
            return;
        };
        let Ok(stream) = object_key.stream().parse::<u64>() else {
            return;
        };
        journal.record_first(
            HopEvent::new(HopStage::RelayForward, stream, object_key.object(), t_us)
                .with_peer(Some(child)),
        );
    }

    fn set_repair_lane_single_symbol(&self, enabled: bool) {
        self.repair_lane_single_symbol
            .store(enabled, Ordering::Relaxed);
    }

    fn repair_lane_single_symbol(&self) -> bool {
        self.repair_lane_single_symbol.load(Ordering::Relaxed)
    }

    fn set_repair_lane_burst_copy(&self, enabled: bool) {
        self.repair_lane_burst_copy.store(enabled, Ordering::Relaxed);
    }

    fn repair_lane_burst_copy(&self) -> bool {
        self.repair_lane_burst_copy.load(Ordering::Relaxed)
    }

    fn set_demand_groups(&self, groups: fast_plane::demand::RenditionGroups) {
        let _ = self.demand_groups.set(groups);
    }

    fn demand_groups(&self) -> Option<&fast_plane::demand::RenditionGroups> {
        self.demand_groups.get().filter(|groups| !groups.is_empty())
    }

    /// The streams that the compiled children report fresh demand for;
    /// `None` while a child has no fresh report (an older node, one with
    /// --relay-demand-report false, a lost report): this node's demand is
    /// then unknown, and it reports none, so its parents fail open.
    fn child_demand(&self, now: Instant) -> Option<Vec<u64>> {
        let mut out = Vec::new();
        for path in &self.paths {
            out.extend_from_slice(&path.demand.fresh(now)?.1);
        }
        Some(out)
    }

    /// Read the children's demand reports (`RLD1`) that arrive on the
    /// source sockets (and their video twins, which share the address):
    /// each is the report of the path whose child sent it.
    fn spawn_demand_readers(self: &Arc<Self>) -> Vec<tokio::task::JoinHandle<()>> {
        let mut sockets: Vec<Arc<UdpSocket>> = self
            .socket_groups
            .iter()
            .map(|group| Arc::clone(&self.paths[group[0]].socket))
            .collect();
        sockets.extend(self.video_sockets.iter().cloned());
        sockets
            .into_iter()
            .map(|socket| {
                let forwarder = Arc::clone(self);
                tokio::spawn(async move {
                    let mut buf = [0_u8; 2_048];
                    loop {
                        let Ok((len, from)) = socket.recv_from(&mut buf).await else {
                            tokio::time::sleep(Duration::from_millis(50)).await;
                            continue;
                        };
                        let Some(streams) = fast_plane::demand::decode_demand(&buf[..len]) else {
                            continue;
                        };
                        let now = Instant::now();
                        for path in forwarder
                            .paths
                            .iter()
                            .filter(|path| path.target == from || path.video_target == from)
                        {
                            path.demand.record(streams.clone(), now);
                        }
                    }
                })
            })
            .collect()
    }

    fn set_nonblocking(&self, nonblocking: bool) {
        self.nonblocking.store(nonblocking, Ordering::Relaxed);
    }

    /// How long a source held back from a warm child is kept, from its
    /// receipt on this node's clock.
    fn set_warm_hold_us(&self, hold_us: u64) {
        self.warm_hold_us.store(hold_us, Ordering::Relaxed);
    }

    fn set_batch(&self, batch: bool) {
        self.batch.store(batch, Ordering::Relaxed);
    }

    /// Apply the node's buffer target to every source socket. The children
    /// of a relay are fed from these sockets, so a burst for all of them has
    /// to fit.
    fn configure_buffers(&self, requested_bytes: usize) {
        for members in &self.socket_groups {
            let path = &self.paths[members[0]];
            match configure_udp_socket_buffers(
                &path.socket,
                requested_bytes,
                "RelaySession downstream forwarding",
            ) {
                Ok(state) if state.target_met() => {}
                Ok(state) => warn!(
                    target = %path.target,
                    requested_bytes,
                    actual_receive_bytes = state.receive_bytes,
                    actual_send_bytes = state.send_bytes,
                    "UDP socket buffer target was limited by the operating system"
                ),
                Err(error) => warn!(
                    target = %path.target,
                    error = %error,
                    "could not configure the RelaySession forwarding socket buffers"
                ),
            }
        }
        for twin in &self.video_sockets {
            if let Err(error) = configure_udp_socket_buffers(
                twin.as_ref(),
                requested_bytes,
                "RelaySession downstream forwarding (video)",
            ) {
                warn!(error = %error, "could not configure a video forwarding socket's buffers");
            }
        }
    }

    fn set_hop_journal(&self, journal: Arc<HopJournal>) {
        let _ = self.hop_journal.set(journal);
    }

    fn buffer_warm_source(
        &self,
        path: &RelayForwardPath,
        object_key: &media_object::ObjectKey,
        datagram: &[u8],
        now_us: u64,
    ) {
        self.buffer_warm_source_class(
            path,
            fast_plane::TrafficClass::Audio,
            warm_object_id_of_key(object_key),
            datagram,
            now_us,
        );
    }

    /// Keep a source datagram held back from a warm repair-only child, in
    /// the child's buffer of `class`, for the media budget from `now_us`.
    fn buffer_warm_source_class(
        &self,
        path: &RelayForwardPath,
        class: fast_plane::TrafficClass,
        object: u64,
        datagram: &[u8],
        now_us: u64,
    ) {
        let hold_us = self.warm_hold_us.load(Ordering::Relaxed);
        // Never waits: a replay holds the lock only to swap the buffer, and
        // a datagram that meets it then is not kept (counted).
        let mut buffer = match path.warm_sources[class.index()].try_lock() {
            Ok(buffer) => buffer,
            Err(std::sync::TryLockError::Poisoned(poisoned)) => poisoned.into_inner(),
            Err(std::sync::TryLockError::WouldBlock) => {
                self.warm_source_refused_datagrams
                    .fetch_add(1, Ordering::Relaxed);
                return;
            }
        };
        // A class thread keeps a datagram only in a buffer made whole
        // before it ran (a repair-only path's): any other would grow here.
        if !buffer.fixed {
            drop(buffer);
            self.warm_source_refused_datagrams
                .fetch_add(1, Ordering::Relaxed);
            return;
        }
        let mutation = buffer.push(object, hold_us, datagram, now_us);
        drop(buffer);
        self.record_warm_source_mutation(&mutation);
    }

    fn record_warm_source_mutation(&self, mutation: &WarmSourceBufferMutation) {
        if mutation.refused_datagrams > 0 {
            self.warm_source_refused_datagrams
                .fetch_add(mutation.refused_datagrams as u64, Ordering::Relaxed);
        }
        if mutation.added_datagrams > 0 {
            self.warm_source_buffered_datagrams
                .fetch_add(mutation.added_datagrams as u64, Ordering::Relaxed);
            self.warm_source_buffered_bytes
                .fetch_add(mutation.added_bytes as u64, Ordering::Relaxed);
        }
        if mutation.removed_datagrams() == 0 {
            return;
        }
        atomic_saturating_sub(
            &self.warm_source_buffered_datagrams,
            mutation.removed_datagrams() as u64,
        );
        atomic_saturating_sub(
            &self.warm_source_buffered_bytes,
            mutation.removed_bytes() as u64,
        );
        self.warm_source_expired_datagrams
            .fetch_add(mutation.expired_datagrams as u64, Ordering::Relaxed);
        self.warm_source_retired_datagrams
            .fetch_add(mutation.retired_datagrams as u64, Ordering::Relaxed);
        self.warm_source_evicted_datagrams
            .fetch_add(mutation.evicted_datagrams as u64, Ordering::Relaxed);
    }

    /// Replay the warm sources of a promoted child: the audio ones first,
    /// from the audio socket to the child's port, then the video ones from
    /// the video twin to the child's video port, each class in as few
    /// `sendmmsg` calls as the kernel takes.
    async fn replay_warm_sources(&self, target: SocketAddr) {
        let Some(path) = self.paths.iter().find(|path| path.target == target) else {
            return;
        };
        for class in fast_plane::TrafficClass::ALL {
            let slot = &path.warm_sources[class.index()];
            let fixed = slot
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .fixed;
            // A preallocated buffer's datagrams leave with the replay, and
            // with them its buffers: a new one, made here, takes its place in
            // one swap under the lock, so the class thread never allocates
            // (nor finds the lock held for more than the swap).
            let batch = if fixed {
                let mut fresh = WarmSourceReplayBuffer::preallocated();
                std::mem::swap(
                    &mut *slot
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner),
                    &mut fresh,
                );
                fresh.take_live(now_unix_us())
            } else {
                slot.lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .take_live(now_unix_us())
            };
            let removed_datagrams = batch
                .datagrams
                .len()
                .saturating_add(batch.expired_datagrams);
            let removed_bytes = batch.bytes.saturating_add(batch.expired_bytes);
            atomic_saturating_sub(
                &self.warm_source_buffered_datagrams,
                removed_datagrams as u64,
            );
            atomic_saturating_sub(&self.warm_source_buffered_bytes, removed_bytes as u64);
            self.warm_source_expired_datagrams
                .fetch_add(batch.expired_datagrams as u64, Ordering::Relaxed);
            if batch.datagrams.is_empty() {
                continue;
            }
            // Video sources go back the way they came: from the video twin
            // to the child's video port.
            let (socket, class_target) = match (class, self.video_sockets.get(path.group)) {
                (fast_plane::TrafficClass::Video, Some(twin)) => (twin, path.video_target),
                _ => (&path.socket, path.target),
            };
            self.replay_batch(socket, class_target, &batch.datagrams)
                .await;
        }
    }

    /// Send a replay in as few calls as the kernel takes; what it does not
    /// take is sent one by one, waiting if need be.
    async fn replay_batch(&self, socket: &UdpSocket, target: SocketAddr, datagrams: &[Vec<u8>]) {
        let mut replayed = 0;
        if self.batch.load(Ordering::Relaxed) {
            let started = Instant::now();
            replayed = fast_path::try_send_batch(socket, datagrams.len(), |index| {
                (&datagrams[index][..], target)
            })
            .unwrap_or(0);
            let elapsed = started.elapsed();
            for datagram in &datagrams[..replayed] {
                self.record_forward_success(MediaDatagramRole::Source, datagram.len(), elapsed);
                self.warm_source_replayed_datagrams
                    .fetch_add(1, Ordering::Relaxed);
                self.warm_source_replayed_bytes
                    .fetch_add(datagram.len() as u64, Ordering::Relaxed);
            }
        }
        for datagram in &datagrams[replayed..] {
            let started = Instant::now();
            match socket.send_to(datagram, target).await {
                Ok(sent) if sent == datagram.len() => {
                    self.record_forward_success(MediaDatagramRole::Source, sent, started.elapsed());
                    self.warm_source_replayed_datagrams
                        .fetch_add(1, Ordering::Relaxed);
                    self.warm_source_replayed_bytes
                        .fetch_add(sent as u64, Ordering::Relaxed);
                }
                Ok(sent) => {
                    self.errors.fetch_add(1, Ordering::Relaxed);
                    warn!(
                        %target,
                        expected_bytes = datagram.len(),
                        sent_bytes = sent,
                        "RelaySession warm-source replay sent a partial datagram"
                    );
                }
                Err(error) => {
                    self.errors.fetch_add(1, Ordering::Relaxed);
                    warn!(
                        %target,
                        error = %error,
                        "RelaySession warm-source replay failed"
                    );
                }
            }
        }
    }

    /// The sends of one `sendmmsg` call (the fast plane's): the counters as
    /// that many `record_forward_success` calls leave them, in a handful of
    /// atomic adds instead of about twenty a datagram, which the audio and
    /// video threads would otherwise contend for at 4K rates.
    fn record_forward_batch(&self, sources: u64, repairs: u64, bytes: u64, duration: Duration) {
        if sources > 0 {
            self.source_datagrams.fetch_add(sources, Ordering::Relaxed);
        }
        if repairs > 0 {
            self.repair_datagrams.fetch_add(repairs, Ordering::Relaxed);
        }
        let count = sources + repairs;
        if count > 0 {
            self.bytes.fetch_add(bytes, Ordering::Relaxed);
            self.observe_durations(duration, count);
        }
    }

    fn record_forward_success(&self, role: MediaDatagramRole, sent: usize, duration: Duration) {
        match role {
            MediaDatagramRole::Source => {
                self.source_datagrams.fetch_add(1, Ordering::Relaxed);
            }
            MediaDatagramRole::Repair => {
                self.repair_datagrams.fetch_add(1, Ordering::Relaxed);
            }
        }
        self.bytes.fetch_add(sent as u64, Ordering::Relaxed);
        self.observe_duration(duration);
    }

    fn register_failover_listener(&self) {
        self.failover_listeners.fetch_add(1, Ordering::Relaxed);
    }

    fn record_failover_command_rejected(&self) {
        self.failover_commands_rejected
            .fetch_add(1, Ordering::Relaxed);
    }

    fn apply_failover_mode(
        &self,
        target: SocketAddr,
        mode: FailoverForwardMode,
        lease_expired: bool,
    ) -> Option<bool> {
        let Some(path) = self.paths.iter().find(|path| path.target == target) else {
            self.record_failover_command_rejected();
            return None;
        };
        if path.role != RelayForwardRole::Repair {
            self.record_failover_command_rejected();
            return None;
        }
        if !lease_expired {
            self.failover_commands_received
                .fetch_add(1, Ordering::Relaxed);
        }
        let promoted = mode == FailoverForwardMode::SourceAndRepair;
        let previous = path.promoted.swap(promoted, Ordering::Relaxed);
        if previous != promoted {
            if promoted {
                self.failover_promotions_applied
                    .fetch_add(1, Ordering::Relaxed);
            } else {
                self.failover_demotions_applied
                    .fetch_add(1, Ordering::Relaxed);
            }
            if lease_expired {
                self.failover_lease_expirations
                    .fetch_add(1, Ordering::Relaxed);
            }
            self.failover_last_transition_unix_ms
                .store(now_unix_ms(), Ordering::Relaxed);
            info!(
                %target,
                ?mode,
                lease_expired,
                "RelaySession warm-secondary forwarding mode changed"
            );
        }
        Some(!previous && promoted)
    }

    fn observe_duration(&self, duration: Duration) {
        self.observe_durations(duration, 1);
    }

    /// `count` sends that each took `duration` (the sends of one call).
    fn observe_durations(&self, duration: Duration, count: u64) {
        let duration_us = duration.as_micros().min(u128::from(u64::MAX)) as u64;
        self.duration_count.fetch_add(count, Ordering::Relaxed);
        self.duration_sum_us
            .fetch_add(duration_us.saturating_mul(count), Ordering::Relaxed);
        self.duration_max_us
            .fetch_max(duration_us, Ordering::Relaxed);
        for (index, upper_bound_us) in EDGE_RESPONSE_DURATION_BUCKETS_US.iter().enumerate() {
            if duration_us <= *upper_bound_us {
                self.duration_buckets[index].fetch_add(count, Ordering::Relaxed);
            }
        }
    }

    fn snapshot(&self) -> RelayForwardSnapshot {
        RelayForwardSnapshot {
            downstream_children: self.paths.len() as u64,
            source_datagrams: self.source_datagrams.load(Ordering::Relaxed),
            repair_datagrams: self.repair_datagrams.load(Ordering::Relaxed),
            bytes: self.bytes.load(Ordering::Relaxed),
            errors: self.errors.load(Ordering::Relaxed),
            filtered_datagrams: self.filtered_datagrams.load(Ordering::Relaxed),
            warm_source_buffered_datagrams: self
                .warm_source_buffered_datagrams
                .load(Ordering::Relaxed),
            warm_source_buffered_bytes: self.warm_source_buffered_bytes.load(Ordering::Relaxed),
            warm_source_replayed_datagrams: self
                .warm_source_replayed_datagrams
                .load(Ordering::Relaxed),
            warm_source_replayed_bytes: self.warm_source_replayed_bytes.load(Ordering::Relaxed),
            warm_source_expired_datagrams: self
                .warm_source_expired_datagrams
                .load(Ordering::Relaxed),
            warm_source_retired_datagrams: self
                .warm_source_retired_datagrams
                .load(Ordering::Relaxed),
            warm_source_evicted_datagrams: self
                .warm_source_evicted_datagrams
                .load(Ordering::Relaxed),
            warm_source_refused_datagrams: self
                .warm_source_refused_datagrams
                .load(Ordering::Relaxed),
            duration_count: self.duration_count.load(Ordering::Relaxed),
            duration_sum_us: self.duration_sum_us.load(Ordering::Relaxed),
            duration_max_us: self.duration_max_us.load(Ordering::Relaxed),
            duration_buckets: std::array::from_fn(|index| {
                self.duration_buckets[index].load(Ordering::Relaxed)
            }),
            failover_listeners: self.failover_listeners.load(Ordering::Relaxed),
            failover_promoted_children: self
                .paths
                .iter()
                .filter(|path| path.promoted.load(Ordering::Relaxed))
                .count() as u64,
            failover_commands_received: self.failover_commands_received.load(Ordering::Relaxed),
            failover_commands_rejected: self.failover_commands_rejected.load(Ordering::Relaxed),
            failover_lease_expirations: self.failover_lease_expirations.load(Ordering::Relaxed),
            failover_promotions_applied: self.failover_promotions_applied.load(Ordering::Relaxed),
            failover_demotions_applied: self.failover_demotions_applied.load(Ordering::Relaxed),
            failover_last_transition_unix_ms: self
                .failover_last_transition_unix_ms
                .load(Ordering::Relaxed),
        }
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
enum RelayFailoverControllerState {
    #[default]
    Disabled,
    Arming,
    Healthy,
    Promoted,
    Recovering,
    SecondaryUnavailable,
}

impl RelayFailoverControllerState {
    const ALL: [Self; 6] = [
        Self::Disabled,
        Self::Arming,
        Self::Healthy,
        Self::Promoted,
        Self::Recovering,
        Self::SecondaryUnavailable,
    ];

    const fn as_str(self) -> &'static str {
        match self {
            Self::Disabled => "disabled",
            Self::Arming => "arming",
            Self::Healthy => "healthy",
            Self::Promoted => "promoted",
            Self::Recovering => "recovering",
            Self::SecondaryUnavailable => "secondary_unavailable",
        }
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct RelayFailoverControllerSnapshot {
    state: RelayFailoverControllerState,
    enabled: u64,
    commands_sent: u64,
    command_send_errors: u64,
    promotions: u64,
    demotions: u64,
    secondary_unavailable_events: u64,
    /// Promotions that waited for a longer silence (the backoff).
    deferred_promotions: u64,
    primary_source_age_ms: u64,
    secondary_repair_age_ms: u64,
    last_detection_us: u64,
    last_promotion_to_source_us: u64,
    last_media_gap_us: u64,
    max_media_gap_us: u64,
    last_transition_unix_ms: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RelayIngressParentPath {
    Primary,
    Secondary,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RelayDatagramObservation {
    role: MediaDatagramRole,
    decoded: bool,
}

struct RelayFailoverController {
    socket: UdpSocket,
    target: SocketAddr,
    generation: TopologyGeneration,
    subscription_id: SubscriptionId,
    silence: Duration,
    recovery: Duration,
    secondary_warm: Duration,
    lease_duration_us: u64,
    state: RelayFailoverControllerState,
    desired_mode: FailoverForwardMode,
    transition_id: u64,
    last_primary_source: Option<Instant>,
    last_secondary_repair: Option<Instant>,
    recovered_since: Option<Instant>,
    last_decoded: Option<Instant>,
    promotion_gap_base: Option<Instant>,
    promotion_sent_at: Option<Instant>,
    awaiting_secondary_source: bool,
    awaiting_post_promotion_object: bool,
    /// --relay-failover-promotion-backoff, and the promotions of the last
    /// [`FAILOVER_FLAP_WINDOW`].
    promotion_backoff: bool,
    recent_promotions: VecDeque<Instant>,
    /// A promotion waits for the backoff now (counted once).
    deferring: bool,
    snapshot: RelayFailoverControllerSnapshot,
}

/// Promotions within this window make the next one wait longer.
const FAILOVER_FLAP_WINDOW: Duration = Duration::from_secs(30);
/// The backoff's largest factor of the primary silence.
const FAILOVER_MAX_BACKOFF_SHIFT: u32 = 3;

impl RelayFailoverController {
    async fn bind(args: &Args) -> Result<Option<Self>> {
        let Some(endpoint) = args.relay_failover_controller else {
            return Ok(None);
        };
        let socket = UdpSocket::bind(endpoint.bind).await.with_context(|| {
            format!(
                "failed to bind RelaySession failover controller on {}",
                endpoint.bind
            )
        })?;
        info!(
            bind = %socket.local_addr()?,
            target = %endpoint.target,
            "RelaySession warm-secondary failover controller ready"
        );
        let transition_id = now_unix_us().max(1);
        Ok(Some(Self {
            socket,
            target: endpoint.target,
            generation: TopologyGeneration::new(args.relay_topology_generation)?,
            subscription_id: SubscriptionId::new(args.relay_subscription_id)?,
            silence: Duration::from_millis(args.relay_primary_silence_ms),
            recovery: Duration::from_millis(args.relay_primary_recovery_ms),
            secondary_warm: Duration::from_millis(args.relay_secondary_warm_ms),
            lease_duration_us: args.relay_failover_lease_ms.saturating_mul(1_000),
            state: RelayFailoverControllerState::Arming,
            desired_mode: FailoverForwardMode::RepairOnly,
            transition_id,
            last_primary_source: None,
            last_secondary_repair: None,
            recovered_since: None,
            last_decoded: None,
            promotion_gap_base: None,
            promotion_sent_at: None,
            awaiting_secondary_source: false,
            awaiting_post_promotion_object: false,
            promotion_backoff: args.relay_failover_promotion_backoff,
            recent_promotions: VecDeque::new(),
            deferring: false,
            snapshot: RelayFailoverControllerSnapshot {
                state: RelayFailoverControllerState::Arming,
                enabled: 1,
                last_transition_unix_ms: now_unix_ms(),
                ..RelayFailoverControllerSnapshot::default()
            },
        }))
    }

    fn observe(
        &mut self,
        path: RelayIngressParentPath,
        observation: RelayDatagramObservation,
        now: Instant,
    ) {
        match (path, observation.role) {
            (RelayIngressParentPath::Primary, MediaDatagramRole::Source) => {
                self.last_primary_source = Some(now);
            }
            (RelayIngressParentPath::Secondary, MediaDatagramRole::Repair) => {
                self.last_secondary_repair = Some(now);
            }
            (RelayIngressParentPath::Secondary, MediaDatagramRole::Source)
                if self.awaiting_secondary_source =>
            {
                if let Some(sent_at) = self.promotion_sent_at {
                    self.snapshot.last_promotion_to_source_us =
                        duration_us(now.saturating_duration_since(sent_at));
                }
                self.awaiting_secondary_source = false;
            }
            _ => {}
        }
        if observation.decoded {
            if self.awaiting_post_promotion_object {
                if let Some(base) = self.promotion_gap_base {
                    let gap_us = duration_us(now.saturating_duration_since(base));
                    self.snapshot.last_media_gap_us = gap_us;
                    self.snapshot.max_media_gap_us = self.snapshot.max_media_gap_us.max(gap_us);
                }
                self.awaiting_post_promotion_object = false;
            }
            self.last_decoded = Some(now);
        }
    }

    async fn tick(&mut self, now: Instant) {
        let primary_recent = self
            .last_primary_source
            .is_some_and(|seen| now.saturating_duration_since(seen) < self.silence);
        let secondary_recent = self
            .last_secondary_repair
            .is_some_and(|seen| now.saturating_duration_since(seen) < self.secondary_warm);
        if primary_recent {
            self.deferring = false;
        }

        match self.state {
            RelayFailoverControllerState::Disabled => {}
            RelayFailoverControllerState::Arming => {
                if primary_recent && secondary_recent {
                    self.set_state(RelayFailoverControllerState::Healthy);
                } else if self.last_primary_source.is_some() && !primary_recent {
                    self.primary_silent(now, secondary_recent);
                }
            }
            RelayFailoverControllerState::Healthy => {
                if !primary_recent {
                    self.primary_silent(now, secondary_recent);
                }
            }
            RelayFailoverControllerState::SecondaryUnavailable => {
                if primary_recent {
                    self.set_state(RelayFailoverControllerState::Healthy);
                } else if self.last_primary_source.is_some() {
                    self.primary_silent(now, secondary_recent);
                }
            }
            RelayFailoverControllerState::Promoted | RelayFailoverControllerState::Recovering => {
                if primary_recent {
                    let recovered_since = *self.recovered_since.get_or_insert(now);
                    self.set_state(RelayFailoverControllerState::Recovering);
                    if now.saturating_duration_since(recovered_since) >= self.recovery {
                        self.demote();
                    }
                } else {
                    self.recovered_since = None;
                    self.set_state(RelayFailoverControllerState::Promoted);
                }
            }
        }
        self.refresh_ages(now);
        self.send_desired().await;
    }

    /// The primary has been silent past `silence`: promote the secondary
    /// (once the backoff allows), whether or not it was heard lately.
    ///
    /// A secondary that sends nothing can still hold the sources: for a
    /// video stream a lease forwarder sends its secondary children repair
    /// only, and a forwarder that receives no repair itself (a regional
    /// distributor fed sources over the long haul) sends them nothing at all
    /// while it keeps every source in their warm ring (4K on Linode, 24 Nov:
    /// new-dist-a stopped for 2.7 s, its edge saw no repair from new-dist-b,
    /// never promoted it and took 41 parts 2.2 to 2.65 s late over the cache
    /// mesh, while new-dist-b had committed each 35 ms after packaging).
    /// Promoting a secondary that is gone costs one RLF1 command; not
    /// promoting one that is there costs the stream for the primary's whole
    /// stop. A silence with no recent secondary is still counted as
    /// `secondary_unavailable` and shown as that state until the promotion.
    fn primary_silent(&mut self, now: Instant, secondary_recent: bool) {
        if !secondary_recent {
            self.secondary_unavailable();
        }
        self.try_promote(now);
    }

    /// The primary silence that a promotion needs now: the configured
    /// silence, doubled for each promotion of the last
    /// [`FAILOVER_FLAP_WINDOW`] with the backoff on.
    fn promotion_silence(&mut self, now: Instant) -> Duration {
        while self
            .recent_promotions
            .front()
            .is_some_and(|at| now.saturating_duration_since(*at) >= FAILOVER_FLAP_WINDOW)
        {
            self.recent_promotions.pop_front();
        }
        if !self.promotion_backoff {
            return self.silence;
        }
        let shift = (self.recent_promotions.len() as u32).min(FAILOVER_MAX_BACKOFF_SHIFT);
        self.silence.saturating_mul(1 << shift)
    }

    /// Promote once the primary has been silent for the silence that a
    /// promotion needs now; until then count the wait (once).
    fn try_promote(&mut self, now: Instant) {
        let needed = self.promotion_silence(now);
        let silent_for = self
            .last_primary_source
            .map_or(Duration::MAX, |seen| now.saturating_duration_since(seen));
        if silent_for >= needed {
            self.deferring = false;
            self.promote(now);
        } else if !self.deferring {
            self.deferring = true;
            self.snapshot.deferred_promotions = self.snapshot.deferred_promotions.saturating_add(1);
        }
    }

    fn promote(&mut self, now: Instant) {
        self.recent_promotions.push_back(now);
        self.desired_mode = FailoverForwardMode::SourceAndRepair;
        self.advance_transition();
        self.snapshot.promotions = self.snapshot.promotions.saturating_add(1);
        self.snapshot.last_detection_us = self
            .last_primary_source
            .map_or(0, |seen| duration_us(now.saturating_duration_since(seen)));
        self.promotion_sent_at = Some(now);
        self.promotion_gap_base = self.last_decoded;
        self.awaiting_secondary_source = true;
        self.awaiting_post_promotion_object = true;
        self.recovered_since = None;
        self.set_state(RelayFailoverControllerState::Promoted);
    }

    fn demote(&mut self) {
        self.desired_mode = FailoverForwardMode::RepairOnly;
        self.advance_transition();
        self.snapshot.demotions = self.snapshot.demotions.saturating_add(1);
        self.recovered_since = None;
        self.awaiting_secondary_source = false;
        self.set_state(RelayFailoverControllerState::Healthy);
    }

    fn secondary_unavailable(&mut self) {
        if self.state != RelayFailoverControllerState::SecondaryUnavailable {
            self.snapshot.secondary_unavailable_events =
                self.snapshot.secondary_unavailable_events.saturating_add(1);
        }
        self.set_state(RelayFailoverControllerState::SecondaryUnavailable);
    }

    fn set_state(&mut self, state: RelayFailoverControllerState) {
        if self.state != state {
            self.state = state;
            self.snapshot.state = state;
            self.snapshot.last_transition_unix_ms = now_unix_ms();
        }
    }

    fn advance_transition(&mut self) {
        self.transition_id = now_unix_us().max(self.transition_id.saturating_add(1));
    }

    fn refresh_ages(&mut self, now: Instant) {
        self.snapshot.primary_source_age_ms = self
            .last_primary_source
            .map_or(0, |seen| duration_ms(now.saturating_duration_since(seen)));
        self.snapshot.secondary_repair_age_ms = self
            .last_secondary_repair
            .map_or(0, |seen| duration_ms(now.saturating_duration_since(seen)));
    }

    async fn send_desired(&mut self) {
        let issued_at = now_unix_us().max(1);
        let Ok(command) = FailoverLeaseCommand::new(
            self.generation,
            self.subscription_id,
            self.transition_id,
            issued_at,
            self.lease_duration_us,
            self.desired_mode,
        ) else {
            self.snapshot.command_send_errors = self.snapshot.command_send_errors.saturating_add(1);
            return;
        };
        match self.socket.send_to(&command.encode(), self.target).await {
            Ok(sent) if sent == FAILOVER_CONTROL_WIRE_LEN => {
                self.snapshot.commands_sent = self.snapshot.commands_sent.saturating_add(1);
            }
            Ok(_) | Err(_) => {
                self.snapshot.command_send_errors =
                    self.snapshot.command_send_errors.saturating_add(1);
            }
        }
    }

    const fn snapshot(&self) -> RelayFailoverControllerSnapshot {
        self.snapshot
    }
}

fn duration_us(duration: Duration) -> u64 {
    duration.as_micros().min(u128::from(u64::MAX)) as u64
}

fn duration_ms(duration: Duration) -> u64 {
    duration.as_millis().min(u128::from(u64::MAX)) as u64
}

fn hls_target_duration_from_millis(duration_ms: u64) -> u64 {
    ((duration_ms.saturating_add(500)) / 1_000).max(1)
}

fn format_hls_program_date_time(unix_us: u64) -> Option<String> {
    let unix_us = i64::try_from(unix_us).ok()?;
    DateTime::<Utc>::from_timestamp_micros(unix_us)
        .map(|value| value.to_rfc3339_opts(SecondsFormat::Millis, true))
}

fn atomic_saturating_sub(value: &AtomicU64, amount: u64) {
    let _ = value.fetch_update(Ordering::Relaxed, Ordering::Relaxed, |current| {
        Some(current.saturating_sub(amount))
    });
}

async fn start_relay_failover_listeners(
    endpoints: &[RelayFailoverListenerEndpoint],
    forwarder: Option<&Arc<RelayDownstreamForwarder>>,
    generation: TopologyGeneration,
    subscription_id: SubscriptionId,
    cache: &Arc<LiveTsCache>,
    shutdown_rx: watch::Receiver<()>,
) -> Result<Vec<tokio::task::JoinHandle<()>>> {
    if endpoints.is_empty() {
        return Ok(Vec::new());
    }
    let forwarder = forwarder.context("failover listeners require a downstream forwarder")?;
    let mut bound = Vec::with_capacity(endpoints.len());
    for endpoint in endpoints {
        let socket = UdpSocket::bind(endpoint.bind).await.with_context(|| {
            format!(
                "failed to bind RelaySession failover listener on {}",
                endpoint.bind
            )
        })?;
        info!(
            bind = %socket.local_addr()?,
            peer = %endpoint.peer,
            forward_target = %endpoint.forward_target,
            "RelaySession warm-secondary failover listener ready"
        );
        bound.push((*endpoint, socket));
    }
    let mut tasks = Vec::with_capacity(bound.len());
    for (endpoint, socket) in bound {
        forwarder.register_failover_listener();
        cache.update_relay_forward(forwarder.snapshot());
        tasks.push(tokio::spawn(run_relay_failover_listener(
            socket,
            endpoint,
            generation,
            subscription_id,
            Arc::clone(forwarder),
            Arc::clone(cache),
            shutdown_rx.clone(),
        )));
    }
    Ok(tasks)
}

async fn run_relay_failover_listener(
    socket: UdpSocket,
    endpoint: RelayFailoverListenerEndpoint,
    generation: TopologyGeneration,
    subscription_id: SubscriptionId,
    forwarder: Arc<RelayDownstreamForwarder>,
    cache: Arc<LiveTsCache>,
    mut shutdown_rx: watch::Receiver<()>,
) {
    let mut buffer = [0_u8; FAILOVER_CONTROL_WIRE_LEN + 1];
    let mut transition_id = 0_u64;
    let mut transition_mode = FailoverForwardMode::RepairOnly;
    let mut lease_deadline: Option<Instant> = None;
    let mut lease_tick = interval(Duration::from_millis(25));
    lease_tick.set_missed_tick_behavior(MissedTickBehavior::Skip);
    loop {
        tokio::select! {
            _ = shutdown_rx.changed() => return,
            _ = lease_tick.tick() => {
                if lease_deadline.is_some_and(|deadline| Instant::now() >= deadline) {
                    let _ = forwarder.apply_failover_mode(
                        endpoint.forward_target,
                        FailoverForwardMode::RepairOnly,
                        true,
                    );
                    cache.update_relay_forward(forwarder.snapshot());
                    lease_deadline = None;
                    transition_mode = FailoverForwardMode::RepairOnly;
                }
            }
            received = socket.recv_from(&mut buffer) => {
                let Ok((len, peer)) = received else {
                    forwarder.record_failover_command_rejected();
                    cache.update_relay_forward(forwarder.snapshot());
                    continue;
                };
                let command = if peer == endpoint.peer {
                    FailoverLeaseCommand::decode(&buffer[..len])
                } else {
                    Err(relay_session::Error::InvalidField {
                        field: "failover_controller_peer",
                        reason: "command arrived from an unassigned controller",
                    })
                };
                let Ok(command) = command else {
                    forwarder.record_failover_command_rejected();
                    cache.update_relay_forward(forwarder.snapshot());
                    continue;
                };
                let stale = command.generation != generation
                    || command.subscription_id != subscription_id
                    || command.transition_id < transition_id
                    || (command.transition_id == transition_id && command.mode != transition_mode);
                if stale {
                    forwarder.record_failover_command_rejected();
                    cache.update_relay_forward(forwarder.snapshot());
                    continue;
                }
                transition_id = command.transition_id;
                transition_mode = command.mode;
                if let Some(promoted_now) =
                    forwarder.apply_failover_mode(endpoint.forward_target, command.mode, false)
                {
                    lease_deadline = (command.mode == FailoverForwardMode::SourceAndRepair)
                        .then(|| Instant::now() + Duration::from_micros(command.lease_duration_us));
                    if promoted_now {
                        forwarder.replay_warm_sources(endpoint.forward_target).await;
                    }
                }
                cache.update_relay_forward(forwarder.snapshot());
            }
        }
    }
}

struct RelayIngestRuntime {
    dispatch: RelayUdpDispatch,
    secondary_socket: Option<UdpSocket>,
    /// The video-class ports (each relay port plus the class offset) of a
    /// node that runs the single receive loop: a parent with class threads
    /// sends video there whatever this node runs (see
    /// `bind_single_loop_class_twins`). Unused by the fast plane, which
    /// binds its own.
    class_twins: Vec<(RelayIngressParentPath, UdpSocket)>,
    forwarder: Option<Arc<RelayDownstreamForwarder>>,
    audio_epochs: Option<broadcast::Sender<AudioEpochDatagram>>,
    failover_controller: Option<RelayFailoverController>,
    failover_heartbeat: Duration,
    link_telemetry: Option<Arc<LinkTelemetry>>,
}

fn take_relay_deadline_drop_delta(reported_total: &mut u64, current_total: u64) -> Option<u64> {
    let delta = current_total.saturating_sub(*reported_total);
    *reported_total = current_total;
    (delta > 0).then_some(delta)
}

async fn run_udp_fec_ingest(
    socket: UdpSocket,
    cache: Arc<LiveTsCache>,
    mut shutdown_rx: watch::Receiver<()>,
    runtime: RelayIngestRuntime,
) -> Result<()> {
    let RelayIngestRuntime {
        dispatch: mut relay_dispatch,
        secondary_socket: relay_secondary_socket,
        class_twins,
        forwarder: relay_forwarder,
        audio_epochs,
        failover_controller: mut relay_failover_controller,
        failover_heartbeat,
        link_telemetry,
    } = runtime;
    let mut receiver = UdpFecReceiver::new();
    let mut audio_block_sessions = HashMap::<u32, (u64, Instant)>::new();
    let mut native_audio_relay = NativeAudioRelay::default();
    cache.update_relay_ingress(relay_dispatch.receiver().snapshot());
    let mut buf = vec![0u8; 65_536];
    let mut relay_secondary_buf = vec![0u8; 65_536];
    let mut relay_twin_buf = vec![0u8; 65_536];
    let mut rotate = interval(Duration::from_millis(10));
    rotate.set_missed_tick_behavior(MissedTickBehavior::Skip);
    let mut expire_fec = interval(Duration::from_secs(1));
    expire_fec.set_missed_tick_behavior(MissedTickBehavior::Skip);
    let mut reported_deadline_drops = 0_u64;
    let mut failover_tick = interval(failover_heartbeat);
    failover_tick.set_missed_tick_behavior(MissedTickBehavior::Skip);

    loop {
        tokio::select! {
            _ = shutdown_rx.changed() => {
                cache.rotate_if_due(true).await?;
                info!("UDP-FEC mesh byte ingest shutting down");
                return Ok(());
            }
            _ = rotate.tick() => {
                cache.rotate_if_due(false).await?;
                // Holes past the repair horizon that no commit released.
                cache.release_expired_repair_holes().await;
            }
            _ = expire_fec.tick() => {
                native_audio_relay.expire(Instant::now());
                let expired = receiver.expire_inactive();
                if expired.objects > 0 || expired.flows > 0 {
                    debug!(
                        expired_objects = expired.objects,
                        expired_flows = expired.flows,
                        released_object_bytes = expired.released_object_bytes,
                        released_datagrams = expired.released_datagrams,
                        "expired inactive UDP-FEC receive state"
                    );
                }
                let relay_expired = relay_dispatch.receiver_mut().expire(now_unix_us());
                let relay_snapshot = relay_dispatch.receiver().snapshot();
                cache.update_relay_ingress(relay_snapshot);
                if let Some(deadline_drops) = take_relay_deadline_drop_delta(
                    &mut reported_deadline_drops,
                    relay_snapshot.counters.deadline_drops,
                ) {
                    warn!(
                        deadline_drops,
                        deadline_drops_total = reported_deadline_drops,
                        "dropped expired RelaySession datagrams since previous ingress report"
                    );
                }
                if relay_expired.objects > 0 {
                    debug!(
                        expired_objects = relay_expired.objects,
                        released_object_bytes = relay_expired.released_object_bytes,
                        released_datagrams = relay_expired.released_datagrams,
                        "expired deadline-bound RelaySession receive state"
                    );
                }
                // A hole near the end of a stream is never followed by
                // enough commits to release it, so the idle tail is flushed
                // here once the hold has elapsed without further ingest.
                cache.flush_idle_canonical_gaps(now_unix_ms()).await;
                let retired_streams = cache
                    .retire_streams_idle_before(
                        now_unix_ms().saturating_sub(
                            CANONICAL_STREAM_IDLE_RETENTION.as_millis() as u64,
                        ),
                    )
                    .await;
                if retired_streams > 0 {
                    info!(retired_streams, "retired idle canonical stream cache state");
                }
            }
            _ = failover_tick.tick(), if relay_failover_controller.is_some() => {
                if let Some(controller) = relay_failover_controller.as_mut() {
                    controller.tick(Instant::now()).await;
                    cache.update_relay_failover_controller(controller.snapshot());
                }
            }
            received = socket.recv_from(&mut buf) => {
                let (len, peer) = received?;
                if let Some(telemetry) = &link_telemetry {
                    telemetry.record_primary_bytes(peer, len);
                }
                if native_audio_relay
                    .handle_control(&socket, peer, &buf[..len])
                    .await
                {
                    continue;
                }
                if process_relay_audio_epoch_datagram(
                    peer,
                    &buf[..len],
                    &mut audio_block_sessions,
                    audio_epochs.as_ref(),
                    relay_forwarder.as_deref(),
                    Some((&socket, &native_audio_relay)),
                ).await {
                    continue;
                }
                let observation = process_udp_fec_ingest_datagram(
                    peer,
                    &buf[..len],
                    &cache,
                    &mut receiver,
                    &mut relay_dispatch,
                    relay_forwarder.as_deref(),
                ).await?;
                if let (Some(controller), Some(observation)) =
                    (relay_failover_controller.as_mut(), observation)
                {
                    controller.observe(RelayIngressParentPath::Primary, observation, Instant::now());
                    cache.update_relay_failover_controller(controller.snapshot());
                }
            }
            received = recv_optional_udp(&relay_secondary_socket, &mut relay_secondary_buf) => {
                let (len, peer) = received?;
                if let Some(telemetry) = &link_telemetry {
                    telemetry.record_secondary_bytes(peer, len);
                }
                if process_relay_audio_epoch_datagram(
                    peer,
                    &relay_secondary_buf[..len],
                    &mut audio_block_sessions,
                    audio_epochs.as_ref(),
                    relay_forwarder.as_deref(),
                    Some((&socket, &native_audio_relay)),
                ).await {
                    continue;
                }
                let observation = process_udp_fec_ingest_datagram(
                    peer,
                    &relay_secondary_buf[..len],
                    &cache,
                    &mut receiver,
                    &mut relay_dispatch,
                    relay_forwarder.as_deref(),
                ).await?;
                if let (Some(controller), Some(observation)) =
                    (relay_failover_controller.as_mut(), observation)
                {
                    controller.observe(RelayIngressParentPath::Secondary, observation, Instant::now());
                    cache.update_relay_failover_controller(controller.snapshot());
                }
            }
            received = recv_class_twins(&class_twins, &mut relay_twin_buf) => {
                let (len, peer, path) = received?;
                let observation = process_class_twin_datagram(
                    peer,
                    path,
                    &relay_twin_buf[..len],
                    &cache,
                    &mut receiver,
                    &mut relay_dispatch,
                    relay_forwarder.as_deref(),
                    link_telemetry.as_deref(),
                ).await?;
                if let (Some(controller), Some(observation)) =
                    (relay_failover_controller.as_mut(), observation)
                {
                    controller.observe(path, observation, Instant::now());
                    cache.update_relay_failover_controller(controller.snapshot());
                }
            }
        }
    }
}

/// Bind the video-class twins of the relay ports for a node that runs the
/// single receive loop. A parent with class threads sends a child's video to
/// the child's port plus the offset without knowing what the child runs, so
/// a node with its class threads off (or without the fast plane) still
/// reads there, and turning the flag off on one node never drops its video.
/// A port that cannot be bound is reported and skipped.
async fn bind_single_loop_class_twins(
    primary: SocketAddr,
    secondary: Option<SocketAddr>,
    offset: u16,
    buffer_bytes: usize,
) -> Vec<(RelayIngressParentPath, UdpSocket)> {
    let mut twins = Vec::new();
    if offset == 0 {
        return twins;
    }
    for (path, bind) in [
        (RelayIngressParentPath::Primary, Some(primary)),
        (RelayIngressParentPath::Secondary, secondary),
    ] {
        let Some(bind) = bind.filter(|bind| bind.port() != 0) else {
            continue;
        };
        let twin = match fast_plane::class_addr(bind, fast_plane::TrafficClass::Video, offset) {
            Ok(twin) => twin,
            Err(error) => {
                warn!(%bind, error = %error, "no video class port for the single receive loop");
                continue;
            }
        };
        match bind_buffered_udp_ingress(twin, buffer_bytes, "RelaySession video class ingest").await
        {
            Ok(socket) => {
                info!(bind = %twin, ?path, "RelaySession video class port read by the single receive loop");
                twins.push((path, socket));
            }
            Err(error) => warn!(
                bind = %twin,
                error = %format!("{error:#}"),
                "could not bind the video class port: video that a parent sends there is lost"
            ),
        }
    }
    twins
}

/// Receive from whichever video-class twin is ready.
async fn recv_class_twins(
    twins: &[(RelayIngressParentPath, UdpSocket)],
    buffer: &mut [u8],
) -> std::io::Result<(usize, SocketAddr, RelayIngressParentPath)> {
    if twins.is_empty() {
        return std::future::pending().await;
    }
    std::future::poll_fn(|cx| {
        for (path, socket) in twins {
            let mut read = tokio::io::ReadBuf::new(buffer);
            match socket.poll_recv_from(cx, &mut read) {
                std::task::Poll::Ready(Ok(peer)) => {
                    return std::task::Poll::Ready(Ok((read.filled().len(), peer, *path)));
                }
                std::task::Poll::Ready(Err(error)) => return std::task::Poll::Ready(Err(error)),
                std::task::Poll::Pending => {}
            }
        }
        std::task::Poll::Pending
    })
    .await
}

/// One datagram of a video-class twin in the single receive loop: what the
/// relay port of its path does with a RelaySession or RQD2 datagram.
#[allow(clippy::too_many_arguments)]
async fn process_class_twin_datagram(
    peer: SocketAddr,
    path: RelayIngressParentPath,
    datagram: &[u8],
    cache: &Arc<LiveTsCache>,
    receiver: &mut UdpFecReceiver,
    relay_dispatch: &mut RelayUdpDispatch,
    relay_forwarder: Option<&RelayDownstreamForwarder>,
    link_telemetry: Option<&LinkTelemetry>,
) -> Result<Option<RelayDatagramObservation>> {
    if let Some(telemetry) = link_telemetry {
        match path {
            RelayIngressParentPath::Primary => telemetry.record_primary_bytes(peer, datagram.len()),
            RelayIngressParentPath::Secondary => {
                telemetry.record_secondary_bytes(peer, datagram.len());
            }
        }
    }
    process_udp_fec_ingest_datagram(
        peer,
        datagram,
        cache,
        receiver,
        relay_dispatch,
        relay_forwarder,
    )
    .await
}

async fn process_relay_audio_epoch_datagram(
    peer: SocketAddr,
    datagram: &[u8],
    block_sessions: &mut HashMap<u32, (u64, Instant)>,
    audio_epochs: Option<&broadcast::Sender<AudioEpochDatagram>>,
    relay_forwarder: Option<&RelayDownstreamForwarder>,
    native_audio_relay: Option<(&UdpSocket, &NativeAudioRelay)>,
) -> bool {
    if !is_multichannel_audio_transport_datagram(datagram) {
        return false;
    }

    let audio_epoch_receivers = audio_epochs.map_or(0, broadcast::Sender::receiver_count);
    let has_native_audio_subscriptions = native_audio_relay
        .as_ref()
        .is_some_and(|(_, relay)| relay.has_subscriptions());
    if relay_forwarder.is_none() && audio_epoch_receivers == 0 && !has_native_audio_subscriptions {
        // A leaf with no live audio consumer cannot use this datagram. Consume
        // the AEP1 lane without parsing, allocating, or retaining session state;
        // relays and active subscribers still take the validated path below.
        return true;
    }

    let now = Instant::now();
    block_sessions.retain(|_, (_, expires_at)| *expires_at > now);
    let identity = match inspect_multichannel_audio_datagram(
        &datagram[MULTICHANNEL_AUDIO_TRANSPORT_MAGIC.len()..],
    ) {
        Ok(identity) => identity,
        Err(error) => {
            warn!(peer = %peer, error = %error, "invalid AEP1 datagram rejected at relay ingress");
            return true;
        }
    };
    let session_id = if let Some(session_id) = identity.session_id {
        block_sessions.insert(
            identity.block_id,
            (session_id, now + Duration::from_secs(15)),
        );
        Some(session_id)
    } else {
        block_sessions
            .get(&identity.block_id)
            .map(|(session_id, _)| *session_id)
    };
    let role = if identity.source_index.is_some() {
        MediaDatagramRole::Source
    } else {
        MediaDatagramRole::Repair
    };

    if let Some((socket, native_audio_relay)) = native_audio_relay {
        native_audio_relay.forward(socket, datagram, session_id);
    }

    if let Some(forwarder) = relay_forwarder {
        forwarder.forward(datagram, role, None).await;
    }
    if let Some(audio_epochs) = audio_epochs {
        let _ = audio_epochs.send(AudioEpochDatagram {
            session_id,
            bytes: Bytes::copy_from_slice(datagram),
        });
        debug!(
            peer = %peer,
            ?session_id,
            ?role,
            receivers = audio_epoch_receivers,
            datagram_bytes = datagram.len(),
            "relayed AEP1 datagram to playback-edge subscribers"
        );
    }
    true
}

async fn recv_optional_udp(
    socket: &Option<UdpSocket>,
    buffer: &mut [u8],
) -> std::io::Result<(usize, SocketAddr)> {
    match socket {
        Some(socket) => socket.recv_from(buffer).await,
        None => std::future::pending().await,
    }
}

async fn process_udp_fec_ingest_datagram(
    peer: SocketAddr,
    datagram: &[u8],
    cache: &LiveTsCache,
    receiver: &mut UdpFecReceiver,
    relay_dispatch: &mut RelayUdpDispatch,
    relay_forwarder: Option<&RelayDownstreamForwarder>,
) -> Result<Option<RelayDatagramObservation>> {
    let started = Instant::now();
    let result = process_udp_fec_ingest_datagram_inner(
        peer,
        datagram,
        cache,
        receiver,
        relay_dispatch,
        relay_forwarder,
    )
    .await;
    cache.update_relay_runtime(
        relay_dispatch.receiver().snapshot(),
        relay_forwarder.map(RelayDownstreamForwarder::snapshot),
    );
    cache.record_relay_processing(started.elapsed());
    result
}

async fn process_udp_fec_ingest_datagram_inner(
    peer: SocketAddr,
    datagram: &[u8],
    cache: &LiveTsCache,
    receiver: &mut UdpFecReceiver,
    relay_dispatch: &mut RelayUdpDispatch,
    relay_forwarder: Option<&RelayDownstreamForwarder>,
) -> Result<Option<RelayDatagramObservation>> {
    debug!(
        peer = %peer,
        datagram_bytes = datagram.len(),
        "UDP-FEC mesh datagram received"
    );
    let received_us = now_unix_us();
    let relay_result = relay_dispatch.push(peer, datagram, received_us);
    match relay_result {
        Ok(RelayUdpDispatchOutcome::Legacy) => {}
        Ok(RelayUdpDispatchOutcome::Relay(RelayIngressOutcome::Buffered { key, role, .. })) => {
            journal_relay_symbol(cache, &key, peer, received_us);
            if let Some(forwarder) = relay_forwarder {
                forwarder.forward(datagram, role, Some(&key)).await;
            }
            debug!(
                peer = %peer,
                stream = key.stream(),
                object = key.object(),
                ?role,
                "RelaySession RaptorQ symbol buffered"
            );
            return Ok(Some(RelayDatagramObservation {
                role,
                decoded: false,
            }));
        }
        Ok(RelayUdpDispatchOutcome::Relay(RelayIngressOutcome::Decoded {
            object,
            envelope,
            role,
            parent_count,
            accepted_datagrams,
            ..
        })) => {
            let decoded_us = now_unix_us();
            journal_relay_symbol(cache, object.key(), peer, received_us);
            if let Some(forwarder) = relay_forwarder {
                forwarder.forward(datagram, role, Some(object.key())).await;
            }
            let stream = object.key().stream().to_owned();
            let sequence = object.key().object();
            let publication_clock = relay_publication_clock(&object);
            let decoded = match commit_relay_object(cache, *object, envelope).await {
                // Another copy, or one refused and counted: nothing new.
                Ok(Committed::AlreadyPresent(_)) => true,
                Ok(Committed::Refused(_)) => false,
                Ok(Committed::Stored(_)) => {
                    journal_relay_decoded(cache, &stream, sequence, peer, decoded_us);
                    if let Some(clock) = publication_clock {
                        cache.record_relay_availability(clock.observe(now_unix_us()));
                    }
                    debug!(
                        peer = %peer,
                        stream,
                        sequence,
                        parent_count,
                        accepted_datagrams,
                        "committed canonical RelaySession RaptorQ object"
                    );
                    true
                }
                Err(error) => {
                    warn!(
                        peer = %peer,
                        stream,
                        sequence,
                        error = %error,
                        "failed to cache canonical RelaySession object"
                    );
                    false
                }
            };
            return Ok(Some(RelayDatagramObservation { role, decoded }));
        }
        Ok(RelayUdpDispatchOutcome::Relay(RelayIngressOutcome::Duplicate { key, role, .. })) => {
            if let Some(forwarder) = relay_forwarder {
                forwarder.forward(datagram, role, Some(&key)).await;
            }
            debug!(
                peer = %peer,
                stream = key.stream(),
                object = key.object(),
                ?role,
                "authenticated duplicate RelaySession symbol admitted for downstream forwarding"
            );
            return Ok(Some(RelayDatagramObservation {
                role,
                decoded: false,
            }));
        }
        Err(RelayIngressError::DeadlineExpired | RelayIngressError::StaleEpoch) => {
            // This is an expected outcome (a sender that was frozen, the tail
            // of a session that has ended) and is already counted in
            // RelayIngressCounters (deadline_drops, rejected_by_kind). Logging every
            // expired symbol here would add synchronous work to the UDP receive
            // loop precisely when ingress is behind; the receive loop reports
            // one aggregate warning per expiry tick instead.
            return Ok(None);
        }
        Err(error) => {
            warn_relay_rejection(relay_dispatch, peer, None, datagram.len(), &error);
            return Ok(None);
        }
    }

    match receiver.try_push_payload(peer, datagram) {
        Ok(UdpFecPushOutcome::Decoded {
            block_id,
            payload: decoded,
        }) => {
            let payload_bytes = decoded.payload.len();
            if let Some(stream_id) = decoded.stream_id {
                match cache
                    .commit_stream_payload(stream_id, decoded.payload)
                    .await
                {
                    Ok(outcome) => {
                        debug!(
                            peer = %peer,
                            stream_id,
                            block_id,
                            ?outcome,
                            payload_bytes,
                            "cached stream-prefixed UDP-FEC mesh byte payload"
                        );
                    }
                    Err(error) => {
                        warn!(peer = %peer, stream_id, block_id, error = %error, "failed to cache stream-prefixed UDP-FEC mesh byte payload");
                    }
                }
            } else if let Err(error) = cache.push_payload(&decoded.payload).await {
                warn!(peer = %peer, block_id, error = %error, "failed to cache UDP-FEC mesh byte payload");
            } else {
                debug!(
                    peer = %peer,
                    block_id,
                    payload_bytes,
                    "cached UDP-FEC mesh byte payload"
                );
            }
        }
        Ok(UdpFecPushOutcome::Buffered {
            stream_id,
            block_id,
        }) => {
            debug!(
                peer = %peer,
                ?stream_id,
                block_id,
                "UDP-FEC symbols buffered awaiting repair/source symbols"
            );
        }
        Ok(UdpFecPushOutcome::Duplicate {
            stream_id,
            block_id,
        }) => {
            debug!(
                peer = %peer,
                ?stream_id,
                block_id,
                "duplicate completed UDP-FEC object ignored"
            );
        }
        Err(error) => {
            warn!(
                peer = %peer,
                datagram_bytes = datagram.len(),
                error = %error,
                "UDP-FEC datagram rejected"
            );
        }
    }
    Ok(None)
}

/// `--fast-busy-poll-us` on the audio class receive sockets; a refusal is
/// said once and leaves them without it.
fn apply_fast_busy_poll(sockets: &[fast_plane::relay::ClassSocket], micros: u32) {
    if micros == 0 {
        return;
    }
    let audio = sockets
        .iter()
        .filter(|socket| socket.class == fast_plane::TrafficClass::Audio);
    let mut set = 0;
    for socket in audio {
        match fast_plane::sys::set_busy_poll(&socket.socket, micros) {
            Ok(()) => set += 1,
            Err(error) => {
                info!(
                    micros,
                    error = %error,
                    "--fast-busy-poll-us refused: the audio fast-plane sockets run without busy polling"
                );
                return;
            }
        }
    }
    info!(
        micros,
        sockets = set,
        "audio fast-plane sockets busy-poll (needs net.core.busy_poll above zero for poll())"
    );
}

/// A RelaySession datagram was rejected. The receiver counts it by kind
/// (`relay_session.rejected_by_kind`); one line is logged a kind, at counts
/// 1, 2, 4, 8... with the total, so that a parent that sends what this node
/// refuses cannot flood the log. `class` is the fast-plane class whose tee
/// rejected it; the single loop has none.
fn warn_relay_rejection(
    dispatch: &RelayUdpDispatch,
    peer: SocketAddr,
    class: Option<&str>,
    datagram_bytes: usize,
    error: &RelayIngressError,
) {
    let kind = error.kind();
    let total = dispatch.receiver().counters().rejected_by_kind.get(kind);
    if total.is_power_of_two() {
        warn!(
            %peer,
            class,
            kind = kind.as_str(),
            total,
            datagram_bytes,
            error = %error,
            "RelaySession datagram rejected at configured dispatch seam"
        );
    }
}

/// Journal the arrival of a RelaySession symbol: `relay_first` for the
/// first symbol of an object (`relay_decoded` is `journal_relay_decoded`'s).
fn journal_relay_symbol(
    cache: &LiveTsCache,
    key: &media_object::ObjectKey,
    peer: SocketAddr,
    received_us: u64,
) {
    let Some(journal) = cache.hops() else {
        return;
    };
    let Ok(stream) = key.stream().parse::<u64>() else {
        return;
    };
    journal.record_first(
        HopEvent::new(HopStage::RelayFirst, stream, key.object(), received_us)
            .with_peer(Some(peer)),
    );
}

/// `relay_decoded`: the object decoded at `decoded_us` and its commit stored
/// it (another copy, or a refused one, journals nothing).
fn journal_relay_decoded(
    cache: &LiveTsCache,
    stream: &str,
    sequence: u64,
    peer: SocketAddr,
    decoded_us: u64,
) {
    let (Some(journal), Ok(stream)) = (cache.hops(), stream.parse::<u64>()) else {
        return;
    };
    journal.record(
        HopEvent::new(HopStage::RelayDecoded, stream, sequence, decoded_us).with_peer(Some(peer)),
    );
}

/// What `LiveTsCache::walk_holes` found.
struct HoleWalk {
    /// The newest slot the watermark may move to.
    ceiling: Option<usize>,
    /// How long the first hole released held the watermark.
    held_us: Option<u64>,
    /// No slot of the walk was stored (and it did not reach the part being
    /// committed).
    empty: bool,
}

/// What a commit did with a canonical object.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Committed {
    /// Written (a metadata object or a stream-prefixed payload: taken), at
    /// this sequence.
    Stored(u64),
    /// The cache holds these bytes under the identity already (another copy,
    /// or the cache mesh, wrote them first): nothing is new.
    AlreadyPresent(u64),
    /// Nothing written; counted. Whatever the cache holds stays.
    Refused(CommitRefusal),
}

/// Why a commit wrote nothing. Neither is an error, and neither resets a
/// stream: only a higher epoch does.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CommitRefusal {
    /// Other bytes under a slot's identity (`canonical_conflicts`).
    IdentityConflict,
    /// An epoch below the one the stream has taken up
    /// (`canonical_stale_epoch`).
    StaleEpoch,
}

impl CommitRefusal {
    const fn as_str(self) -> &'static str {
        match self {
            Self::IdentityConflict => "identity_conflict",
            Self::StaleEpoch => "stale_epoch",
        }
    }
}

async fn commit_relay_object(
    cache: &LiveTsCache,
    object: MediaObject,
    envelope: Vec<u8>,
) -> Result<Committed> {
    let stream_id = object
        .key()
        .stream()
        .parse::<u64>()
        .context("RelaySession object stream identity must map to a local numeric stream")?;
    cache
        .commit_validated_stream_payload(stream_id, Bytes::from(envelope), object)
        .await
}

async fn run_udp_media_fec_ingest(
    socket: UdpSocket,
    cache: Arc<LiveTsCache>,
    audio_epochs: broadcast::Sender<AudioEpochDatagram>,
    mut shutdown_rx: watch::Receiver<()>,
) -> Result<()> {
    let mut decoder = MediaFecDecoder::new();
    let mut audio_block_sessions = HashMap::<(SocketAddr, u32), (u64, Instant)>::new();
    let mut native_audio_relay = NativeAudioRelay::default();
    let mut buf = vec![0u8; 65_536];
    let audio_block_ttl = Duration::from_secs(15);

    loop {
        tokio::select! {
            _ = shutdown_rx.changed() => {
                info!("media UDP-FEC access-unit ingest shutting down");
                return Ok(());
            }
            received = socket.recv_from(&mut buf) => {
                let (len, peer) = received?;
                native_audio_relay.expire(Instant::now());
                if native_audio_relay
                    .handle_control(&socket, peer, &buf[..len])
                    .await
                {
                    continue;
                }
                debug!(
                    peer = %peer,
                    datagram_bytes = len,
                    "media UDP-FEC datagram received"
                );
                if is_multichannel_audio_transport_datagram(&buf[..len]) {
                    let now = Instant::now();
                    audio_block_sessions.retain(|_, (_, expires_at)| *expires_at > now);
                    let identity = inspect_multichannel_audio_datagram(
                        &buf[MULTICHANNEL_AUDIO_TRANSPORT_MAGIC.len()..len],
                    );
                    let session_id = identity.ok().and_then(|identity| {
                        if let Some(session_id) = identity.session_id {
                            audio_block_sessions.insert(
                                (peer, identity.block_id),
                                (session_id, now + audio_block_ttl),
                            );
                            Some(session_id)
                        } else {
                            audio_block_sessions
                                .get(&(peer, identity.block_id))
                                .map(|(session_id, _)| *session_id)
                        }
                    });
                    native_audio_relay.forward(&socket, &buf[..len], session_id);
                    let receivers = audio_epochs.receiver_count();
                    let _ = audio_epochs.send(AudioEpochDatagram {
                        session_id,
                        bytes: Bytes::copy_from_slice(&buf[..len]),
                    });
                    debug!(
                        peer = %peer,
                        ?session_id,
                        datagram_bytes = len,
                        receivers,
                        "broadcast media UDP-FEC multichannel audio epoch datagram"
                    );
                    continue;
                }
                match decoder.push_datagram(&buf[..len]) {
                    Ok(Some(frame)) => {
                        let stream_id = frame.metadata.stream_id;
                        let sequence = frame.metadata.sequence;
                        let payload_bytes = frame.payload.len();
                        if let Err(error) = cache
                            .add_media_access_unit(frame.metadata, Bytes::from(frame.payload))
                            .await
                        {
                            warn!(
                                peer = %peer,
                                stream_id,
                                sequence,
                                error = %error,
                                "failed to cache media UDP-FEC access unit"
                            );
                        } else {
                            debug!(
                                peer = %peer,
                                stream_id,
                                sequence,
                                payload_bytes,
                                "cached media UDP-FEC access unit"
                            );
                        }
                    }
                    Ok(None) => {
                        debug!(
                            peer = %peer,
                            datagram_bytes = len,
                            "media UDP-FEC datagram buffered awaiting complete access unit"
                        );
                    }
                    Err(error) => {
                        warn!(
                            peer = %peer,
                            error = %error,
                            "failed to decode media UDP-FEC access unit"
                        );
                    }
                }
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RelayAvailabilityObservation {
    Measured {
        duration_us: u64,
        clock_error_us: u64,
    },
    UnusableClock,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RelayPublicationClock {
    Measured {
        published_us: u64,
        clock_error_us: u64,
    },
    Unusable,
}

impl RelayPublicationClock {
    fn observe(self, available_at_us: u64) -> RelayAvailabilityObservation {
        match self {
            Self::Measured {
                published_us,
                clock_error_us,
            } => available_at_us
                .checked_sub(published_us)
                .map(|duration_us| RelayAvailabilityObservation::Measured {
                    duration_us,
                    clock_error_us,
                })
                .unwrap_or(RelayAvailabilityObservation::UnusableClock),
            Self::Unusable => RelayAvailabilityObservation::UnusableClock,
        }
    }
}

fn relay_publication_clock(object: &MediaObject) -> Option<RelayPublicationClock> {
    if object.kind() != ObjectKind::Media {
        return None;
    }
    let Some(published) = object
        .stage_timestamps()
        .iter()
        .find(|timestamp| timestamp.stage() == Stage::Published)
        .map(|timestamp| timestamp.timestamp())
    else {
        return Some(RelayPublicationClock::Unusable);
    };
    let Ok(published_ns) = u64::try_from(published.unix_time_ns()) else {
        return Some(RelayPublicationClock::Unusable);
    };
    let Some(clock_error_ns) = published.confidence().maximum_error_ns() else {
        return Some(RelayPublicationClock::Unusable);
    };
    Some(RelayPublicationClock::Measured {
        published_us: published_ns.div_ceil(1_000),
        clock_error_us: clock_error_ns.div_ceil(1_000),
    })
}

#[cfg(test)]
fn relay_availability_observation(
    object: &MediaObject,
    available_at_us: u64,
) -> Option<RelayAvailabilityObservation> {
    relay_publication_clock(object).map(|clock| clock.observe(available_at_us))
}

#[derive(Debug, Clone)]
struct CachedMediaAccessUnit {
    metadata: MediaFrameMetadata,
    payload_bytes: usize,
    serialized: Bytes,
    hash: u64,
}

fn codec_name(codec: MediaCodec) -> &'static str {
    match codec {
        MediaCodec::Unknown => "unknown",
        MediaCodec::H264 => "h264",
        MediaCodec::Opus => "opus",
        MediaCodec::Aac => "aac",
        MediaCodec::Data => "data",
    }
}

struct WebTransportMediaDecoder {
    unprefixed: MediaFecDecoder,
    prefixed_by_stream: HashMap<u64, MediaFecDecoder>,
}

impl WebTransportMediaDecoder {
    fn new() -> Self {
        Self {
            unprefixed: MediaFecDecoder::new(),
            prefixed_by_stream: HashMap::new(),
        }
    }

    fn push_datagram(
        &mut self,
        datagram: &[u8],
    ) -> std::result::Result<Option<DecodedMediaFrame>, String> {
        if datagram.len() == STREAM_ID_PREFIX_LEN && split_stream_id_prefix(datagram).is_some() {
            return Ok(None);
        }

        if let Some((stream_id, payload)) = split_stream_id_prefix(datagram) {
            if payload.starts_with(&DATAGRAM_MAGIC) {
                let decoder = self.prefixed_by_stream.entry(stream_id).or_default();
                let transport = FecDatagramDecoder::webtransport_with_stream_prefix(stream_id);
                let decoded = transport
                    .push_media_datagram(decoder, datagram)
                    .map_err(|error| error.to_string())?;
                if let Some(frame) = decoded.as_ref() {
                    let metadata_stream_id = frame.metadata.stream_id;
                    if metadata_stream_id != stream_id {
                        return Err(format!(
                            "WebTransport stream prefix {stream_id} does not match media stream id {metadata_stream_id}"
                        ));
                    }
                }
                return Ok(decoded);
            }
        }

        self.unprefixed
            .push_datagram(datagram)
            .map_err(|error| error.to_string())
    }
}

#[derive(Debug, Clone, Serialize)]
struct MediaAccessUnitResponse {
    stream_id: u64,
    stream_id_text: String,
    sequence: u64,
    pts_ms: u64,
    dts_ms: Option<u64>,
    duration_ms: u32,
    codec: &'static str,
    flags: u16,
    payload_bytes: usize,
    stored_bytes: usize,
}

impl MediaAccessUnitResponse {
    fn from_cached(unit: &CachedMediaAccessUnit) -> Self {
        Self {
            stream_id: unit.metadata.stream_id,
            stream_id_text: stream_id_text(unit.metadata.stream_id),
            sequence: unit.metadata.sequence,
            pts_ms: unit.metadata.pts_ms,
            dts_ms: unit.metadata.dts_ms,
            duration_ms: unit.metadata.duration_ms,
            codec: codec_name(unit.metadata.codec),
            flags: unit.metadata.flags.bits(),
            payload_bytes: unit.payload_bytes,
            stored_bytes: unit.serialized.len(),
        }
    }
}

#[derive(Debug, Clone)]
struct CachedPlaylist {
    /// The stream lifetime the playlist was rendered from: a stream that
    /// takes the index again starts a new playlist.
    handle: StreamHandle,
    version: u64,
    body: String,
}

/// What a playlist render learned of each slot of a stream's window
/// (--playlist-scan-memo): when the slot was written, and the media kind of
/// the part in it, or `None` for a slot with no media. A slot written since
/// is read again. A part that carries an initialization section is never
/// kept: the render takes the section from it each time. A memo belongs to
/// one lifetime of a stream: a stream that takes the index again, or the
/// same stream restarted, starts a new one.
#[derive(Debug)]
struct PlaylistScanMemo {
    handle: StreamHandle,
    /// The sequence of `slots[0]`.
    first: u64,
    slots: VecDeque<Option<(u64, Option<LiveMediaKind>)>>,
}

/// The most slots a scan memo holds: far more than any window.
const PLAYLIST_SCAN_MEMO_MAX_SLOTS: usize = 1 << 20;

impl PlaylistScanMemo {
    fn for_handle(handle: StreamHandle) -> Self {
        Self {
            handle,
            first: 0,
            slots: VecDeque::new(),
        }
    }

    fn get(&self, sequence: u64) -> Option<(u64, Option<LiveMediaKind>)> {
        let index = usize::try_from(sequence.checked_sub(self.first)?).ok()?;
        self.slots.get(index).copied().flatten()
    }

    fn set(&mut self, sequence: u64, entry: Option<(u64, Option<LiveMediaKind>)>) {
        if self.slots.is_empty() || sequence < self.first {
            // The first slot, or a stream that started again below it.
            if entry.is_none() {
                return;
            }
            self.slots.clear();
            self.first = sequence;
        }
        let Ok(index) = usize::try_from(sequence - self.first) else {
            return;
        };
        if index >= PLAYLIST_SCAN_MEMO_MAX_SLOTS {
            self.slots.clear();
            self.first = sequence;
            self.slots.push_back(entry);
            return;
        }
        if index >= self.slots.len() {
            self.slots.resize(index + 1, None);
        }
        self.slots[index] = entry;
    }

    /// Forget the slots before `first`.
    fn trim_below(&mut self, first: u64) {
        while self.first < first && self.slots.pop_front().is_some() {
            self.first += 1;
        }
        if self.slots.is_empty() {
            self.first = first;
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct HlsReloadPosition {
    msn: u64,
    part: Option<usize>,
}

/// Convert the canonical gap hold into parts at the configured part cadence.
/// A zero hold disables gap skipping; any other hold is at least one part.
fn canonical_gap_hold_parts(hold_ms: u64, part_target: Duration) -> u64 {
    // A node with no part target counts the hold in milliseconds.
    let part_us = match duration_us(part_target) {
        0 => 1_000,
        part_us => part_us,
    };
    hold_ms.saturating_mul(1_000).div_ceil(part_us)
}

struct LiveTsCache {
    chunk_cache: Arc<ChunkCache>,
    stream_id: u64,
    part_target: Duration,
    parts_per_segment: usize,
    window_parts: usize,
    max_part_bytes: usize,
    state: RwLock<LiveState>,
    canonical_commit_locks: StdMutex<HashMap<u64, Arc<AsyncMutex<()>>>>,
    canonical_gap_hold_ms: AtomicU64,
    canonical_gap_hold_parts: AtomicU64,
    /// A floor for PART-HOLD-BACK in microseconds; zero keeps three part
    /// targets.
    part_hold_back_floor_us: AtomicU64,
    canonical_gap_skips: AtomicU64,
    canonical_gap_idle_flushes: AtomicU64,
    canonical_gap_skipped_parts: AtomicU64,
    canonical_gap_last_log_unix_ms: AtomicU64,
    /// `--canonical-repair-horizon`, as [`RepairHorizon::code`].
    repair_horizon: AtomicU64,
    repair_delays: StdMutex<RepairDelays>,
    /// The measured horizon, kept current as repairs are measured: the
    /// commit path reads it without a lock.
    repair_horizon_auto_us: AtomicU64,
    /// The least that the measured (auto) horizon may be: the burst copy
    /// delay plus a margin, or [`REPAIR_HORIZON_MIN_MS`].
    repair_horizon_floor_us: AtomicU64,
    /// Told each source epoch that a stream takes up (the edge's compact
    /// lane forgets the parts of the old one).
    source_epoch_observers: StdMutex<Vec<SourceEpochObserver>>,
    /// Releases of a hole by the repair horizon, and the parts they listed
    /// as gaps.
    repair_horizon_releases: AtomicU64,
    /// The longest a hole held a stream's contiguous watermark (µs), and the
    /// holes that held it longer than WATERMARK_STALL_US (AM 13).
    watermark_stall_max_us: AtomicU64,
    watermark_stalls_over: AtomicU64,
    /// Parts that came after they were listed as gaps: the cache has them
    /// for later readers.
    late_gap_fills: AtomicU64,
    /// Commits refused for other bytes under a slot's identity, and for an
    /// epoch below the stream's (`CommitRefusal`).
    canonical_conflicts: AtomicU64,
    canonical_stale_epoch: AtomicU64,
    /// The parts of each stream that the watermark passed as holes: the
    /// playlist lists them as gaps while they are missing.
    gap_parts: StdMutex<HashMap<u64, BTreeSet<u64>>>,
    /// Per stream, the parts the watermark passed without them, by Unix
    /// second (the newest MISSED_SECONDS): `/api/node`'s `missed_10s`.
    missed_parts: StdMutex<HashMap<u64, VecDeque<(u64, u64)>>>,
    /// Per stream, parts stored more than CANONICAL_GAP_SCAN_LIMIT above
    /// the watermark, no two within the scan of each other (at most
    /// WIDE_HOLE_RECORDS): where the walk of a hole wider than its scan
    /// resumes (both contributors lost, a source that jumped), the lowest
    /// above the watermark first. Dropped once the watermark has passed
    /// them.
    wide_hole_resume: StdMutex<HashMap<u64, BTreeSet<u64>>>,
    /// Holes wider than the scan that the repair horizon released.
    wide_hole_releases: AtomicU64,
    part_updates: watch::Sender<u64>,
    playlist_cache: Vec<StdRwLock<Option<CachedPlaylist>>>,
    /// The scan memo of the playlist in each playlist slot.
    playlist_scan_memos: Vec<StdMutex<Option<PlaylistScanMemo>>>,
    /// One render at a time of the playlist in each playlist slot, with the
    /// scan memo: readers that reload together (a crowd that started
    /// together does) wait for one render and take it, or render from the
    /// memo that it left, instead of each scanning the window.
    playlist_render_locks: Vec<AsyncMutex<()>>,
    /// A playlist render reads a slot of its window only when it was
    /// written since the last render (--playlist-scan-memo).
    playlist_scan_memo: AtomicBool,
    /// Slots that playlist renders read and decoded.
    playlist_scan_reads: AtomicU64,
    /// Parts of streams that found every playlist slot in use by a live
    /// stream.
    stream_slot_refusals: AtomicU64,
    relay_ingress: StdRwLock<RelaySessionIngressSnapshot>,
    relay_failover_controller: StdRwLock<RelayFailoverControllerSnapshot>,
    relay_processing: AtomicDurationHistogram,
    relay_availability: RelayAvailabilityTelemetry,
    link_telemetry: StdRwLock<Option<Arc<LinkTelemetry>>>,
    /// Set once at start. Unset, nothing is journaled.
    hop_journal: OnceLock<Arc<HopJournal>>,
    /// The streams this node knows to be video (see `fast_plane`).
    stream_classes: fast_plane::StreamClasses,
    /// The counters of the fast plane, when the relay ingest runs on it.
    fast_plane: OnceLock<Arc<fast_plane::relay::FastPlaneStats>>,
    /// What each parent delivers on the fast plane (`GET /api/node`).
    parent_feeds: OnceLock<Arc<fast_plane::parent_feeds::ParentFeeds>>,
    /// When this node started, in Unix µs: its boot id.
    started_unix_us: u64,
}

impl LiveTsCache {
    #[cfg(test)]
    async fn new(
        stream_id: u64,
        part_target: Duration,
        parts_per_segment: usize,
        window_parts: usize,
        slot_kb: usize,
    ) -> Arc<Self> {
        Self::with_slots(
            stream_id,
            part_target,
            parts_per_segment,
            window_parts,
            slot_kb,
            DEFAULT_PLAYLIST_SLOTS,
        )
        .await
    }

    /// A live cache that holds at most `playlist_slots` streams, with a ring
    /// of four windows of nominal parts.
    #[cfg(test)]
    async fn with_slots(
        stream_id: u64,
        part_target: Duration,
        parts_per_segment: usize,
        window_parts: usize,
        slot_kb: usize,
        playlist_slots: usize,
    ) -> Arc<Self> {
        Self::with_ring(
            stream_id,
            part_target,
            parts_per_segment,
            window_parts,
            slot_kb,
            playlist_slots,
            window_parts.saturating_mul(4).max(32),
        )
        .await
    }

    /// A live cache that holds at most `playlist_slots` streams in rings of
    /// `ring_parts` slots, at least four windows of nominal parts.
    async fn with_ring(
        stream_id: u64,
        part_target: Duration,
        parts_per_segment: usize,
        window_parts: usize,
        slot_kb: usize,
        playlist_slots: usize,
        ring_parts: usize,
    ) -> Arc<Self> {
        let ring_parts = ring_parts.max(window_parts.saturating_mul(4).max(32));
        let options = CacheOptions {
            num_playlists: playlist_slots.max(1),
            max_segments: 1,
            max_parts_per_segment: ring_parts,
            // The cache refuses a part larger than a slot and an
            // initialization larger than `init_size_kb`. An initialization
            // also travels inside a part slot, so a slot bounds both; the
            // mesh's largest frame follows the larger of the two.
            buffer_size_kb: slot_kb,
            init_size_kb: slot_kb,
            ..CacheOptions::default()
        };
        let playlist_cache = (0..options.num_playlists)
            .map(|_| StdRwLock::new(None))
            .collect();
        let playlist_scan_memos = (0..options.num_playlists)
            .map(|_| StdMutex::new(None))
            .collect();
        let playlist_render_locks = (0..options.num_playlists)
            .map(|_| AsyncMutex::new(()))
            .collect();
        let chunk_cache = Arc::new(ChunkCache::new(options));
        chunk_cache.resolve_or_create_stream(stream_id).await;
        let (part_updates, _) = watch::channel(0);
        let mut state = LiveState::new();
        let started_unix_us = state.process_started_unix_us;
        state.segment_seed_parts = parts_per_segment.max(1) as u64;
        state.nominal_part_us = duration_us(part_target).max(1);
        state.ring_parts = ring_parts;
        Arc::new(Self {
            chunk_cache,
            stream_id,
            part_target,
            parts_per_segment,
            window_parts,
            max_part_bytes: slot_kb * 1024,
            state: RwLock::new(state),
            canonical_commit_locks: StdMutex::new(HashMap::new()),
            canonical_gap_hold_ms: AtomicU64::new(DEFAULT_CANONICAL_GAP_HOLD_MS),
            canonical_gap_hold_parts: AtomicU64::new(canonical_gap_hold_parts(
                DEFAULT_CANONICAL_GAP_HOLD_MS,
                part_target,
            )),
            part_hold_back_floor_us: AtomicU64::new(0),
            canonical_gap_skips: AtomicU64::new(0),
            canonical_gap_idle_flushes: AtomicU64::new(0),
            canonical_gap_skipped_parts: AtomicU64::new(0),
            canonical_gap_last_log_unix_ms: AtomicU64::new(0),
            // A node is configured from its flags; a cache made otherwise
            // (tests) keeps the gap hold alone.
            repair_horizon: AtomicU64::new(RepairHorizon::Off.code()),
            repair_delays: StdMutex::new(RepairDelays::default()),
            repair_horizon_auto_us: AtomicU64::new(REPAIR_HORIZON_INITIAL_MS * 1_000),
            repair_horizon_floor_us: AtomicU64::new(REPAIR_HORIZON_MIN_MS * 1_000),
            source_epoch_observers: StdMutex::new(Vec::new()),
            repair_horizon_releases: AtomicU64::new(0),
            watermark_stall_max_us: AtomicU64::new(0),
            watermark_stalls_over: AtomicU64::new(0),
            late_gap_fills: AtomicU64::new(0),
            canonical_conflicts: AtomicU64::new(0),
            canonical_stale_epoch: AtomicU64::new(0),
            gap_parts: StdMutex::new(HashMap::new()),
            missed_parts: StdMutex::new(HashMap::new()),
            wide_hole_resume: StdMutex::new(HashMap::new()),
            wide_hole_releases: AtomicU64::new(0),
            part_updates,
            playlist_cache,
            playlist_scan_memos,
            playlist_render_locks,
            playlist_scan_memo: AtomicBool::new(true),
            playlist_scan_reads: AtomicU64::new(0),
            stream_slot_refusals: AtomicU64::new(0),
            relay_ingress: StdRwLock::new(RelaySessionIngressSnapshot::default()),
            relay_failover_controller: StdRwLock::new(RelayFailoverControllerSnapshot::default()),
            relay_processing: AtomicDurationHistogram::default(),
            relay_availability: RelayAvailabilityTelemetry::default(),
            link_telemetry: StdRwLock::new(None),
            hop_journal: OnceLock::new(),
            stream_classes: fast_plane::StreamClasses::default(),
            fast_plane: OnceLock::new(),
            parent_feeds: OnceLock::new(),
            started_unix_us,
        })
    }

    fn stream_classes(&self) -> &fast_plane::StreamClasses {
        &self.stream_classes
    }

    fn set_fast_plane_stats(&self, stats: Arc<fast_plane::relay::FastPlaneStats>) {
        let _ = self.fast_plane.set(stats);
    }

    fn set_parent_feeds(&self, feeds: Arc<fast_plane::parent_feeds::ParentFeeds>) {
        let _ = self.parent_feeds.set(feeds);
    }

    /// The feed records of the fast plane, when the relay ingest runs on it.
    fn parent_feeds(&self) -> Option<&Arc<fast_plane::parent_feeds::ParentFeeds>> {
        self.parent_feeds.get()
    }

    /// A playlist render reads only the slots written since the last one
    /// (`true`), or every slot of the window (`false`, as before).
    fn set_playlist_scan_memo(&self, memo: bool) {
        self.playlist_scan_memo.store(memo, Ordering::Relaxed);
    }

    /// Take the scan memo of a stream's lifetime out of its playlist slot (a
    /// new one if the slot held another lifetime's), to put back after the
    /// scan.
    fn take_playlist_scan_memo(&self, handle: StreamHandle) -> PlaylistScanMemo {
        self.playlist_scan_memos
            .get(handle.index())
            .and_then(|memo| {
                memo.lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .take()
            })
            .filter(|memo| memo.handle == handle)
            .unwrap_or_else(|| PlaylistScanMemo::for_handle(handle))
    }

    fn put_playlist_scan_memo(&self, memo: PlaylistScanMemo) {
        if let Some(slot) = self.playlist_scan_memos.get(memo.handle.index()) {
            *slot
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(memo);
        }
    }

    /// The parts of a stream's window that have media, oldest first, with
    /// the media kind of the newest and the last initialization section
    /// found in them.
    async fn scan_playlist_window(
        &self,
        handle: StreamHandle,
        first: usize,
        last: usize,
    ) -> (Vec<u64>, Option<LiveMediaKind>, Option<Bytes>) {
        let stream_id = handle.stream_id();
        let mut available = Vec::new();
        let mut latest_media_kind = None;
        let mut discovered_init = None;
        if !self.playlist_scan_memo.load(Ordering::Relaxed) {
            for seq in first..=last {
                if let Some((bytes, _hash)) = self.chunk_cache.get_for_handle(handle, seq).await {
                    let slot = LiveSlotPayload::decode_for_stream(bytes, stream_id);
                    if slot.has_media() {
                        latest_media_kind = Some(slot.media_kind());
                        if let Some(init) = slot.init() {
                            discovered_init = Some(init);
                        }
                        available.push(seq as u64);
                    }
                }
            }
            return (available, latest_media_kind, discovered_init);
        }
        let mut memo = self.take_playlist_scan_memo(handle);
        for seq in first..=last {
            let sequence = seq as u64;
            // When the slot was written, without a lock: a slot that holds
            // no part of the stream has no time.
            let Some(written_us) = self.chunk_cache.written_unix_us_for_handle(handle, seq) else {
                memo.set(sequence, None);
                continue;
            };
            if let Some((memo_written_us, kind)) = memo.get(sequence) {
                if memo_written_us == written_us {
                    if let Some(kind) = kind {
                        latest_media_kind = Some(kind);
                        available.push(sequence);
                    }
                    continue;
                }
            }
            self.playlist_scan_reads.fetch_add(1, Ordering::Relaxed);
            let Some((bytes, _hash)) = self.chunk_cache.get_for_handle(handle, seq).await else {
                memo.set(sequence, None);
                continue;
            };
            let slot = LiveSlotPayload::decode_for_stream(bytes, stream_id);
            if !slot.has_media() {
                memo.set(sequence, Some((written_us, None)));
                continue;
            }
            let kind = slot.media_kind();
            latest_media_kind = Some(kind);
            available.push(sequence);
            match slot.init() {
                Some(init) => {
                    discovered_init = Some(init);
                    memo.set(sequence, None);
                }
                None => memo.set(sequence, Some((written_us, Some(kind)))),
            }
        }
        memo.trim_below(first as u64);
        self.put_playlist_scan_memo(memo);
        (available, latest_media_kind, discovered_init)
    }

    fn set_hop_journal(&self, journal: Arc<HopJournal>) {
        let _ = self.hop_journal.set(journal);
    }

    /// The hop journal of the node, if it records.
    fn hops(&self) -> Option<&HopJournal> {
        self.hop_journal
            .get()
            .map(Arc::as_ref)
            .filter(|journal| journal.is_enabled())
    }

    /// The contiguous watermark of a stream, for the hop journal: `None`
    /// when the journal is off, so that a node without it does no lookup.
    fn journal_watermark(&self, handle: Option<StreamHandle>) -> Option<Option<usize>> {
        self.hops()?;
        Some(handle.and_then(|handle| self.chunk_cache.last_for_handle(handle)))
    }

    /// Journal the watermark stage for every part from the part after
    /// `previous` up to `current`, the parts that an advance of the
    /// contiguous watermark has just made visible.
    fn journal_watermark_advance(
        &self,
        stream_id: u64,
        previous: Option<usize>,
        current: Option<usize>,
        committed_seq: u64,
        t_us: u64,
    ) {
        let Some(journal) = self.hops() else {
            return;
        };
        let Some(current) = current else {
            return;
        };
        let first = match previous {
            Some(previous) if previous >= current => return,
            Some(previous) => previous + 1,
            // The first publication of a stream starts at the part that
            // made it.
            None => (committed_seq as usize).min(current),
        };
        let first = first.max(current.saturating_sub(HOP_JOURNAL_MAX_WATERMARK_PARTS - 1));
        for seq in first..=current {
            journal.record_part(HopStage::Watermark, stream_id, seq as u64, t_us);
        }
    }

    fn set_link_telemetry(&self, telemetry: Arc<LinkTelemetry>) {
        *self
            .link_telemetry
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(telemetry);
    }

    fn link_observations(&self) -> Vec<LinkObservation> {
        self.link_telemetry
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .as_ref()
            .map_or_else(Vec::new, |telemetry| telemetry.snapshot())
    }

    fn update_relay_ingress(&self, snapshot: RelayIngressSnapshot) {
        self.update_relay_runtime(snapshot, None);
    }

    fn update_relay_runtime(
        &self,
        snapshot: RelayIngressSnapshot,
        forward: Option<RelayForwardSnapshot>,
    ) {
        let mut current = self
            .relay_ingress
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let forward = forward.unwrap_or_else(|| current.forward_snapshot());
        *current = snapshot.into();
        current.apply_forward_snapshot(forward);
    }

    fn update_relay_forward(&self, snapshot: RelayForwardSnapshot) {
        let mut current = self
            .relay_ingress
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        current.apply_forward_snapshot(snapshot);
    }

    fn update_relay_failover_controller(&self, snapshot: RelayFailoverControllerSnapshot) {
        *self
            .relay_failover_controller
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = snapshot;
    }

    fn relay_ingress_snapshot(&self) -> RelaySessionIngressSnapshot {
        let mut snapshot = *self
            .relay_ingress
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        snapshot.apply_failover_controller_snapshot(
            *self
                .relay_failover_controller
                .read()
                .unwrap_or_else(std::sync::PoisonError::into_inner),
        );
        snapshot.processing_duration_count = self.relay_processing.count.load(Ordering::Relaxed);
        snapshot.processing_duration_sum_us = self.relay_processing.sum_us.load(Ordering::Relaxed);
        snapshot.processing_duration_max_us = self.relay_processing.max_us.load(Ordering::Relaxed);
        snapshot.processing_duration_buckets = std::array::from_fn(|index| {
            self.relay_processing.buckets[index].load(Ordering::Relaxed)
        });
        self.relay_availability.apply_to(&mut snapshot);
        snapshot.canonical_conflicts = self.canonical_conflicts.load(Ordering::Relaxed);
        snapshot.canonical_stale_epoch = self.canonical_stale_epoch.load(Ordering::Relaxed);
        snapshot.wide_hole_releases = self.wide_hole_releases.load(Ordering::Relaxed);
        if let Some(stats) = self.fast_plane.get() {
            snapshot.fast_plane = stats.snapshot();
        }
        snapshot
    }

    fn record_relay_processing(&self, duration: Duration) {
        self.relay_processing.record(duration);
    }

    fn record_relay_availability(&self, observation: RelayAvailabilityObservation) {
        self.relay_availability.record(observation);
    }

    fn canonical_commit_lock(&self, stream_id: u64) -> Arc<AsyncMutex<()>> {
        let mut locks = self
            .canonical_commit_locks
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        Arc::clone(
            locks
                .entry(stream_id)
                .or_insert_with(|| Arc::new(AsyncMutex::new(()))),
        )
    }

    /// Configure how long an unrecovered canonical object may hold back the
    /// mesh-visible contiguous watermark. A zero hold disables gap skipping.
    fn set_canonical_gap_hold(&self, hold: Duration) {
        let hold_ms = u64::try_from(hold.as_millis()).unwrap_or(u64::MAX);
        self.canonical_gap_hold_ms.store(hold_ms, Ordering::Relaxed);
        self.canonical_gap_hold_parts.store(
            canonical_gap_hold_parts(hold_ms, self.part_target),
            Ordering::Relaxed,
        );
    }

    /// Configure the repair horizon of the live path (`--canonical-repair-horizon`).
    fn set_repair_horizon(&self, horizon: RepairHorizon) {
        self.repair_horizon.store(horizon.code(), Ordering::Relaxed);
    }

    /// Tell `observer` (stream, epoch) of every source epoch that a stream
    /// takes up from now on, and of each stream's epoch now.
    async fn on_source_epoch(&self, observer: SourceEpochObserver) {
        let current: Vec<(u64, u64)> = self
            .state
            .read()
            .await
            .stream_canonical_epoch
            .iter()
            .map(|(stream_id, epoch)| (*stream_id, *epoch))
            .collect();
        for (stream_id, epoch) in current {
            observer(stream_id, epoch);
        }
        self.source_epoch_observers
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .push(observer);
    }

    fn note_source_epoch(&self, stream_id: u64, epoch: u64) {
        let observers = self
            .source_epoch_observers
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        for observer in observers.iter() {
            observer(stream_id, epoch);
        }
    }

    /// The floor of the measured horizon for long-haul lanes that send
    /// burst copies `burst_copy` after the source (`--relay-burst-copy-ms`):
    /// the copy delay plus a margin, never below [`REPAIR_HORIZON_MIN_MS`].
    /// A fixed horizon is not raised.
    fn set_repair_horizon_floor_for_burst_copy(&self, burst_copy: Duration) {
        let floor_us = if burst_copy.is_zero() {
            REPAIR_HORIZON_MIN_MS * 1_000
        } else {
            duration_us(burst_copy)
                .saturating_add(REPAIR_HORIZON_BURST_COPY_MARGIN_MS * 1_000)
                .max(REPAIR_HORIZON_MIN_MS * 1_000)
        };
        self.repair_horizon_floor_us
            .store(floor_us, Ordering::Relaxed);
    }

    fn repair_horizon_mode(&self) -> RepairHorizon {
        RepairHorizon::from_code(self.repair_horizon.load(Ordering::Relaxed))
    }

    /// The repair horizon in microseconds now, never above the gap hold;
    /// `None` when it is off or the gap hold is 0 (nothing is skipped).
    fn repair_horizon_us(&self) -> Option<u64> {
        let hold_us = self
            .canonical_gap_hold_ms
            .load(Ordering::Relaxed)
            .saturating_mul(1_000);
        if hold_us == 0 {
            return None;
        }
        let horizon_us = match self.repair_horizon_mode() {
            RepairHorizon::Off => return None,
            RepairHorizon::Fixed(ms) => ms.saturating_mul(1_000),
            RepairHorizon::Auto => self
                .repair_horizon_auto_us
                .load(Ordering::Relaxed)
                .max(self.repair_horizon_floor_us.load(Ordering::Relaxed)),
        };
        Some(horizon_us.min(hold_us))
    }

    /// How long the cache-fed UDP lane may still wait for the hole at
    /// `part`, `age` behind the head: zero for a part listed as a gap, the
    /// rest of the repair horizon otherwise; `None` with the horizon off.
    fn live_hole_wait(&self, stream_id: u64, part: u64, age: Duration) -> Option<Duration> {
        let horizon_us = self.repair_horizon_us()?;
        if self.is_gap_part(stream_id, part) {
            return Some(Duration::ZERO);
        }
        Some(Duration::from_micros(horizon_us).saturating_sub(age))
    }

    fn is_gap_part(&self, stream_id: u64, part: u64) -> bool {
        self.gap_parts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(&stream_id)
            .is_some_and(|gaps| gaps.contains(&part))
    }

    /// The gaps of a stream in `first..=last`.
    fn gap_parts_in(&self, stream_id: u64, first: u64, last: u64) -> Vec<u64> {
        if first > last {
            return Vec::new();
        }
        self.gap_parts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(&stream_id)
            .map(|gaps| gaps.range(first..=last).copied().collect())
            .unwrap_or_default()
    }

    fn record_gap_parts(&self, stream_id: u64, parts: &[u64]) {
        if parts.is_empty() {
            return;
        }
        let mut gaps = self
            .gap_parts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let stream = gaps.entry(stream_id).or_default();
        stream.extend(parts.iter().copied());
        while stream.len() > MAX_GAP_PARTS_PER_STREAM {
            stream.pop_first();
        }
    }

    /// Book parts of a stream that the watermark passed without them (once
    /// a hole, never per datagram).
    fn note_missed_parts(&self, stream_id: u64, parts: u64, now_us: u64) {
        let second = now_us / 1_000_000;
        let mut missed = self
            .missed_parts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let seconds = missed.entry(stream_id).or_default();
        match seconds.back_mut() {
            Some((at, count)) if *at == second => *count = count.saturating_add(parts),
            _ => seconds.push_back((second, parts)),
        }
        while seconds.len() > MISSED_SECONDS {
            seconds.pop_front();
        }
    }

    /// The parts of each stream that the watermark passed without them in
    /// the last [`MISSED_WINDOW_S`] seconds (the whole Unix seconds that
    /// hold them, so 10 to 11 s); streams with none are left out.
    fn missed_parts_10s(&self, now_us: u64) -> HashMap<u64, u64> {
        let since = (now_us / 1_000_000).saturating_sub(MISSED_WINDOW_S);
        let mut missed = self
            .missed_parts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        missed.retain(|_, seconds| seconds.back().is_some_and(|(at, _)| *at >= since));
        missed
            .iter()
            .map(|(stream_id, seconds)| {
                let parts = seconds
                    .iter()
                    .filter(|(at, _)| *at >= since)
                    .map(|(_, count)| *count)
                    .sum();
                (*stream_id, parts)
            })
            .collect()
    }

    /// A part has come: it is no longer a gap. Returns whether it was one.
    fn fill_gap_part(&self, stream_id: u64, part: u64) -> bool {
        let mut gaps = self
            .gap_parts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let Some(stream) = gaps.get_mut(&stream_id) else {
            return false;
        };
        let filled = stream.remove(&part);
        if stream.is_empty() {
            gaps.remove(&stream_id);
        }
        filled
    }

    fn forget_gap_parts(&self, stream_id: u64) {
        self.gap_parts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&stream_id);
        self.wide_hole_resume
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&stream_id);
    }

    /// Part `slot` was stored: when it is more than the scan limit above
    /// the watermark, the walk of a hole below it may have to resume there.
    /// It is recorded unless a record within the scan below it reaches it
    /// already, so that each of several wide holes (a contributor pair that
    /// flaps, a straggler between two outages) has the part after it on
    /// record. A part near the watermark costs one load and one comparison.
    fn note_wide_hole(&self, handle: StreamHandle, slot: usize) {
        let Some(last) = self.chunk_cache.last_for_handle(handle) else {
            return;
        };
        if slot <= last.saturating_add(CANONICAL_GAP_SCAN_LIMIT) {
            return;
        }
        let (last, slot) = (last as u64, slot as u64);
        let mut records = self
            .wide_hole_resume
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let starts = records.entry(handle.stream_id()).or_default();
        starts.retain(|start| *start > last);
        let reach = slot.saturating_sub(CANONICAL_GAP_SCAN_LIMIT as u64);
        if starts.range(reach..=slot).next().is_some() {
            return;
        }
        starts.insert(slot);
        // The lowest are released first; a part beyond the kept records is
        // recorded again by a later commit once they are passed.
        if starts.len() > WIDE_HOLE_RECORDS {
            starts.pop_last();
        }
    }

    /// Where the walk of a stream's wide hole resumes: its lowest record
    /// above `last`.
    fn wide_hole_resume_above(&self, stream_id: u64, last: usize) -> Option<usize> {
        self.wide_hole_resume
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(&stream_id)?
            .range(last as u64 + 1..)
            .next()
            .and_then(|resume| usize::try_from(*resume).ok())
    }

    /// A part `part` of a stream was stored after a later part: a repair
    /// (or a reordering), `delay_us` after the first part beyond it came.
    fn record_repair_delay(&self, delay_us: u64) {
        let mut delays = self
            .repair_delays
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        delays.record(delay_us);
        self.repair_horizon_auto_us
            .store(delays.horizon_us(), Ordering::Relaxed);
    }

    /// A hole held a stream's contiguous watermark for `held_us` (it was
    /// filled, or the repair horizon released it).
    fn record_watermark_stall(&self, held_us: u64) {
        self.watermark_stall_max_us
            .fetch_max(held_us, Ordering::Relaxed);
        if held_us > WATERMARK_STALL_US {
            self.watermark_stalls_over.fetch_add(1, Ordering::Relaxed);
        }
    }

    fn watermark_stall_max_us(&self) -> u64 {
        self.watermark_stall_max_us.load(Ordering::Relaxed)
    }

    fn watermark_stalls_over(&self) -> u64 {
        self.watermark_stalls_over.load(Ordering::Relaxed)
    }

    /// How long after the first stored part beyond it `part` came, if one
    /// is stored within the next 16: the time that its hole was open. Lock
    /// free: the registry's check and the slot tag, a slot.
    fn hole_open_us(&self, handle: StreamHandle, part: usize, committed_us: u64) -> Option<u64> {
        (1..=16).find_map(|step| {
            let later = part.checked_add(step)?;
            self.chunk_cache
                .written_unix_us_for_handle(handle, later)
                .map(|written_us| committed_us.saturating_sub(written_us))
        })
    }

    /// A canonical part was just stored, by the commit that resolved
    /// `handle`: when a later part of its stream was stored before it, it
    /// filled a hole. How long the hole was open is a repair delay, which
    /// the measured repair horizon is made of; a part already listed as a
    /// gap is a late fill, kept for later readers.
    fn observe_late_part(&self, handle: StreamHandle, seq: u64, committed_us: u64) {
        let was_gap = self.fill_gap_part(handle.stream_id(), seq);
        if was_gap {
            self.late_gap_fills.fetch_add(1, Ordering::Relaxed);
        }
        let Ok(part) = usize::try_from(seq) else {
            return;
        };
        // In order (no later part stored): nothing to measure. A part a
        // moment behind a later one was reordered, or came from the other
        // parent: not a repair.
        if let Some(delay_us) = self
            .hole_open_us(handle, part, committed_us)
            .filter(|delay_us| *delay_us >= REPAIR_REORDER_GRACE_US)
        {
            self.record_repair_delay(delay_us);
            // A hole filled before the horizon released it held the
            // watermark that long; a gap's late fill held nothing.
            if !was_gap {
                self.record_watermark_stall(delay_us);
            }
        }
    }

    /// Configure a floor for PART-HOLD-BACK. Zero keeps three part targets.
    fn set_part_hold_back_floor(&self, floor: Duration) {
        self.part_hold_back_floor_us
            .store(duration_us(floor), Ordering::Relaxed);
    }

    /// PART-HOLD-BACK for a part target: three part targets, or the
    /// configured floor when it is larger. RFC 8216bis asks for at least
    /// two part targets and recommends three.
    fn part_hold_back_us(&self, part_target_us: u64) -> u64 {
        part_target_us
            .saturating_mul(3)
            .max(self.part_hold_back_floor_us.load(Ordering::Relaxed))
    }

    fn canonical_gap_skip_snapshot(&self) -> CanonicalGapSkipSnapshot {
        let (repair_delay_p90_us, repair_delays) = {
            let delays = self
                .repair_delays
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            (delays.p90_us(), delays.total)
        };
        CanonicalGapSkipSnapshot {
            hold_ms: self.canonical_gap_hold_ms.load(Ordering::Relaxed),
            hold_parts: self.canonical_gap_hold_parts.load(Ordering::Relaxed),
            skips: self.canonical_gap_skips.load(Ordering::Relaxed),
            idle_flushes: self.canonical_gap_idle_flushes.load(Ordering::Relaxed),
            skipped_parts: self.canonical_gap_skipped_parts.load(Ordering::Relaxed),
            repair_horizon: self.repair_horizon_mode().as_str(),
            repair_horizon_us: self.repair_horizon_us(),
            repair_delay_p90_us,
            repair_delays,
            repair_horizon_releases: self.repair_horizon_releases.load(Ordering::Relaxed),
            late_gap_fills: self.late_gap_fills.load(Ordering::Relaxed),
        }
    }

    /// Release a hole that has blocked the contiguous watermark for longer
    /// than the configured hold, measured in parts committed beyond it.
    ///
    /// `ChunkCache::last` gates cache-mesh replication and stops at the first
    /// missing slot until that slot leaves the retained ring. An object the
    /// relay never recovers would therefore freeze replication of the stream
    /// for the whole ring and then release it as one burst. Once
    /// `committing_slot` is more than the hold ahead of the watermark, the
    /// watermark moves to the newest stored slot that is itself older than the
    /// hold; the write that follows resumes contiguous publication from there.
    ///
    /// The caller must hold the stream's canonical commit lock, and passes
    /// the handle that it resolved for the commit. A stream with no hole
    /// costs one watermark load and one comparison.
    async fn release_held_canonical_gap(&self, handle: StreamHandle, committing_slot: usize) {
        // The hold is a length of time. Count it in the parts of this stream,
        // not in the nominal parts of the node.
        let hold_ms = self.canonical_gap_hold_ms.load(Ordering::Relaxed);
        if hold_ms == 0 {
            return;
        }
        if let Some(horizon_us) = self.repair_horizon_us() {
            self.release_holes_past_horizon(handle, Some(committing_slot), horizon_us)
                .await;
            return;
        }
        let hold_parts = hold_ms
            .saturating_mul(1_000)
            .div_ceil(self.state.read().await.stream_part_us(handle.stream_id()));
        if hold_parts == 0 {
            return;
        }
        let Some(ceiling) = usize::try_from(hold_parts)
            .ok()
            .and_then(|hold_parts| committing_slot.checked_sub(hold_parts))
        else {
            return;
        };
        // Nothing is published before the first canonical media object, so
        // an empty watermark has no hole to release.
        let Some(last) = self.chunk_cache.last_for_handle(handle) else {
            return;
        };
        if last >= ceiling {
            return;
        }
        self.advance_canonical_watermark(handle, last, ceiling, false)
            .await;
    }

    /// The repair horizon (wave 5, W2): move the contiguous watermark of a
    /// stream past every hole that has been open for `horizon_us`, counted
    /// from when the first stored part after the hole was written. The
    /// parts passed are recorded as gaps. `committing` is a part about to be
    /// written: the walk stops there, since its write continues the
    /// contiguous publication. Returns the new watermark.
    ///
    /// The caller must hold the stream's canonical commit lock. The walk
    /// reads each slot through `handle`, resolved once by the caller.
    async fn release_holes_past_horizon(
        &self,
        handle: StreamHandle,
        committing: Option<usize>,
        horizon_us: u64,
    ) -> Option<usize> {
        let stream_id = handle.stream_id();
        // Nothing is published before the first canonical media object.
        let last = self.chunk_cache.last_for_handle(handle)?;
        let first = last.checked_add(1)?;
        // The part right after the watermark: no hole (the common case
        // costs no lock).
        if committing == Some(first) {
            return None;
        }
        let head = {
            let state = self.state.read().await;
            state
                .stream_latest_canonical_object
                .get(&stream_id)
                .and_then(|head| usize::try_from(*head).ok())
        };
        let head = match (head, committing) {
            (Some(head), Some(committing)) => head.max(committing),
            (head, committing) => head.or(committing)?,
        };
        if head < first {
            return None;
        }
        let now_us = now_unix_us();
        let end = head.min(last.saturating_add(CANONICAL_GAP_SCAN_LIMIT));
        let mut walk = self.walk_holes(handle, first..=end, false, committing, now_us, horizon_us);
        // Nothing stored within the scan: a hole wider than the scan. Its
        // walk resumes at the lowest part stored above it, as after a
        // narrow hole.
        let wide = walk.empty
            && match self.wide_hole_resume_above(stream_id, last) {
                Some(resume) if resume <= head => {
                    let end = head.min(resume.saturating_add(CANONICAL_GAP_SCAN_LIMIT));
                    walk =
                        self.walk_holes(handle, resume..=end, true, committing, now_us, horizon_us);
                    true
                }
                _ => false,
            };
        let ceiling = walk.ceiling.filter(|ceiling| *ceiling > last)?;
        let watermark = self
            .advance_canonical_watermark(handle, last, ceiling, false)
            .await?;
        self.repair_horizon_releases.fetch_add(1, Ordering::Relaxed);
        if wide {
            self.wide_hole_releases.fetch_add(1, Ordering::Relaxed);
        }
        if let Some(held_us) = walk.held_us {
            self.record_watermark_stall(held_us);
        }
        Some(watermark)
    }

    /// The walk of `release_holes_past_horizon` over `slots`, in order,
    /// stopping at `committing`: the newest stored slot behind which every
    /// hole is `horizon_us` old (a hole is as old as the first part stored
    /// after it). `in_hole`: the first slot follows a hole.
    fn walk_holes(
        &self,
        handle: StreamHandle,
        slots: std::ops::RangeInclusive<usize>,
        mut in_hole: bool,
        committing: Option<usize>,
        now_us: u64,
        horizon_us: u64,
    ) -> HoleWalk {
        let mut walk = HoleWalk {
            ceiling: None,
            held_us: None,
            empty: true,
        };
        for slot in slots {
            if committing == Some(slot) {
                walk.empty = false;
                break;
            }
            match self.chunk_cache.written_unix_us_for_handle(handle, slot) {
                None => in_hole = true,
                Some(written_us) => {
                    walk.empty = false;
                    if in_hole && now_us.saturating_sub(written_us) < horizon_us {
                        break;
                    }
                    if in_hole && walk.held_us.is_none() {
                        walk.held_us = Some(now_us.saturating_sub(written_us));
                    }
                    in_hole = false;
                    walk.ceiling = Some(slot);
                }
            }
        }
        walk
    }

    /// Release every hole of every stream that the repair horizon has
    /// passed, for streams that no commit has come to since (a stalled or
    /// ended stream, or parts longer than the horizon). Returns the streams
    /// whose watermark moved.
    async fn release_expired_repair_holes(&self) -> usize {
        let Some(horizon_us) = self.repair_horizon_us() else {
            return 0;
        };
        let candidates: Vec<(u64, u64)> = {
            let state = self.state.read().await;
            state
                .stream_latest_canonical_object
                .iter()
                .map(|(stream_id, head)| (*stream_id, *head))
                .collect()
        };
        let mut released = 0;
        for (stream_id, head) in candidates {
            // Most streams have no hole: one lookup and one comparison.
            let Some(handle) = self.chunk_cache.resolve_stream(stream_id) else {
                continue;
            };
            let Some(last) = self.chunk_cache.last_for_handle(handle) else {
                continue;
            };
            if last as u64 >= head {
                continue;
            }
            let Some(commit_lock) = self
                .canonical_commit_locks
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .get(&stream_id)
                .cloned()
            else {
                continue;
            };
            let _commit_guard = commit_lock.lock().await;
            // The stream may have been retired or restarted while the lock
            // was awaited: resolve it again under the lock.
            let Some(handle) = self.chunk_cache.resolve_stream(stream_id) else {
                continue;
            };
            if let Some(watermark) = self
                .release_holes_past_horizon(handle, None, horizon_us)
                .await
            {
                released += 1;
                self.part_updates.send_replace(watermark as u64);
            }
        }
        released
    }

    /// Advance the watermark of idle canonical streams whose tail is stranded
    /// behind a hole.
    ///
    /// The commit path releases a hole only when later objects arrive. A
    /// stream that stops, or stalls, shortly after a lost object would keep
    /// its last parts unpublished, so a stream with no ingest for longer than
    /// the hold has its watermark moved to its newest stored object.
    async fn flush_idle_canonical_gaps(&self, now_unix_ms: u64) -> usize {
        let hold_ms = self.canonical_gap_hold_ms.load(Ordering::Relaxed);
        if hold_ms == 0 {
            return 0;
        }
        let candidates: Vec<u64> = {
            let state = self.state.read().await;
            state
                .stream_latest_canonical_object
                .keys()
                .filter(|stream_id| {
                    state.canonical_stream_idle_for(**stream_id, now_unix_ms, hold_ms)
                })
                .copied()
                .collect()
        };

        let mut flushed = 0;
        for stream_id in candidates {
            // Never create a lock here: a stream retired since the candidate
            // scan must not regain a commit-lock entry.
            let Some(commit_lock) = self
                .canonical_commit_locks
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .get(&stream_id)
                .cloned()
            else {
                continue;
            };
            let _commit_guard = commit_lock.lock().await;
            let head = {
                let state = self.state.read().await;
                if !state.canonical_stream_idle_for(stream_id, now_unix_ms, hold_ms) {
                    continue;
                }
                state
                    .stream_latest_canonical_object
                    .get(&stream_id)
                    .copied()
            };
            let Some(head) = head.and_then(|head| usize::try_from(head).ok()) else {
                continue;
            };
            let Some(handle) = self.chunk_cache.resolve_stream(stream_id) else {
                continue;
            };
            let Some(last) = self.chunk_cache.last_for_handle(handle) else {
                continue;
            };
            if last >= head {
                continue;
            }
            if let Some(watermark) = self
                .advance_canonical_watermark(handle, last, head, true)
                .await
            {
                flushed += 1;
                // Wake blocked playlist and tail readers so they observe the
                // newly published tail without waiting for another commit.
                self.part_updates.send_replace(watermark as u64);
            }
        }
        flushed
    }

    /// Move the contiguous watermark to the newest stored slot in
    /// `(last, ceiling]`, returning the new watermark.
    ///
    /// `ChunkCache` exposes no direct watermark control, so the stored bytes
    /// of that slot are republished unchanged through `add_for_handle`,
    /// which publishes the slot identity as the new watermark. The caller must
    /// hold the stream's canonical commit lock so the slot cannot be replaced
    /// between the read and the republication. A handle that has gone stale
    /// (the stream was retired, or its index given to another stream)
    /// republishes nothing.
    async fn advance_canonical_watermark(
        &self,
        handle: StreamHandle,
        last: usize,
        ceiling: usize,
        idle_flush: bool,
    ) -> Option<usize> {
        let stream_id = handle.stream_id();
        let first_unpublished = last.checked_add(1)?;
        let scan_floor =
            first_unpublished.max(ceiling.saturating_sub(CANONICAL_GAP_SCAN_LIMIT - 1));
        for candidate in (scan_floor..=ceiling).rev() {
            let Some((bytes, _hash)) = self.chunk_cache.get_for_handle(handle, candidate).await
            else {
                continue;
            };
            if bytes.is_empty() {
                continue;
            }

            // Slots that are no longer retained, or were never stored, are
            // the parts replication will not carry.
            let retained_start = self
                .chunk_cache
                .retained_start(candidate)
                .max(first_unpublished);
            // At most the gaps a stream keeps are read, below the new
            // watermark; the rest of a wider hole is counted unread (a hole
            // of thousands of parts is one gap to a reader).
            let read_from = retained_start.max(candidate.saturating_sub(MAX_GAP_PARTS_PER_STREAM));
            let mut skipped_parts = (read_from - first_unpublished) as u64;
            let mut gaps = Vec::new();
            for slot in read_from..candidate {
                if self
                    .chunk_cache
                    .get_for_handle(handle, slot)
                    .await
                    .is_none()
                {
                    skipped_parts = skipped_parts.saturating_add(1);
                    gaps.push(slot as u64);
                }
            }

            if let Err(error) = self
                .chunk_cache
                .add_for_handle(handle, candidate, bytes)
                .await
            {
                // A stale handle ("Stale stream handle") means the stream
                // was retired or its index given to another stream since the
                // caller resolved it.
                warn!(
                    stream_id,
                    watermark = last,
                    candidate,
                    error,
                    "canonical gap release could not republish a stored slot"
                );
                return None;
            }
            if let Some(journal) = self.hops() {
                // The stored parts behind the released hole are visible now.
                let t_us = now_unix_us();
                for slot in read_from..=candidate {
                    if slot == candidate
                        || self
                            .chunk_cache
                            .get_for_handle(handle, slot)
                            .await
                            .is_some()
                    {
                        journal.record_part(HopStage::Watermark, stream_id, slot as u64, t_us);
                    }
                }
            }

            // With the repair horizon, the playlist lists them as gaps while
            // they are missing. With it off (the gap hold alone, as before
            // the horizon) they are left out of the playlist, as they were.
            if self.repair_horizon_us().is_some() {
                self.record_gap_parts(stream_id, &gaps);
            }
            if skipped_parts > 0 {
                self.canonical_gap_skips.fetch_add(1, Ordering::Relaxed);
                self.canonical_gap_skipped_parts
                    .fetch_add(skipped_parts, Ordering::Relaxed);
                self.note_missed_parts(stream_id, skipped_parts, now_unix_us());
            }
            if idle_flush {
                self.canonical_gap_idle_flushes
                    .fetch_add(1, Ordering::Relaxed);
            }
            let now_ms = now_unix_ms();
            let last_log_ms = self.canonical_gap_last_log_unix_ms.load(Ordering::Relaxed);
            if now_ms.saturating_sub(last_log_ms) >= CANONICAL_GAP_LOG_INTERVAL_MS
                && self
                    .canonical_gap_last_log_unix_ms
                    .compare_exchange(last_log_ms, now_ms, Ordering::Relaxed, Ordering::Relaxed)
                    .is_ok()
            {
                info!(
                    stream_id,
                    old_watermark = last,
                    new_watermark = candidate,
                    skipped_parts,
                    idle_flush,
                    gap_skips_total = self.canonical_gap_skips.load(Ordering::Relaxed),
                    skipped_parts_total = self.canonical_gap_skipped_parts.load(Ordering::Relaxed),
                    "advanced canonical contiguous watermark past an unrecovered gap"
                );
            } else {
                debug!(
                    stream_id,
                    old_watermark = last,
                    new_watermark = candidate,
                    skipped_parts,
                    idle_flush,
                    "advanced canonical contiguous watermark past an unrecovered gap"
                );
            }
            return Some(candidate);
        }
        None
    }

    async fn push_payload(&self, payload: &[u8]) -> Result<()> {
        let now = Instant::now();
        let now_ms = now_unix_ms();
        let finalized = {
            let mut state = self.state.write().await;
            state.datagrams_received += 1;
            state.last_ingest_unix_ms = Some(now_ms);
            state.bytes_received += payload.len() as u64;

            if state.current.is_empty() {
                state.current_started = now;
                state.current_started_unix_ms = now_ms;
            }
            state.current.extend_from_slice(payload);

            if now.duration_since(state.current_started) >= self.part_target
                || state.current.len() >= self.max_part_bytes
            {
                state.take_current(now, now_ms)
            } else {
                None
            }
        };

        if let Some(part) = finalized {
            self.commit_part(part).await?;
        }
        Ok(())
    }

    async fn rotate_if_due(&self, force: bool) -> Result<()> {
        let now = Instant::now();
        let now_ms = now_unix_ms();
        let finalized = {
            let mut state = self.state.write().await;
            if force || now.duration_since(state.current_started) >= self.part_target {
                state.take_current(now, now_ms)
            } else {
                None
            }
        };

        if let Some(part) = finalized {
            self.commit_part(part).await?;
        }
        Ok(())
    }

    async fn commit_part(&self, part: PendingPart) -> Result<()> {
        self.chunk_cache
            .add_for_stream_id(self.stream_id, part.seq as usize, Bytes::from(part.data))
            .await
            .map_err(|err| anyhow!("chunk cache write failed: {err}"))?;

        let mut state = self.state.write().await;
        state.last_committed_seq = Some(part.seq);
        state.last_committed_unix_ms = Some(part.committed_unix_ms);
        state.last_committed_bytes = Some(part.bytes);
        state.last_committed_duration_us = Some(part.duration_us);
        state.record_part_available(
            self.stream_id,
            part.seq,
            part.bytes,
            now_unix_us(),
            u32::try_from(part.duration_us).ok(),
            false,
            false,
            None,
            self.window_parts,
        );
        debug!(
            stream_id = self.stream_id,
            sequence = part.seq,
            bytes = part.bytes,
            duration_us = part.duration_us,
            "committed mesh byte part"
        );
        drop(state);
        self.part_updates.send_replace(part.seq);
        Ok(())
    }

    async fn commit_stream_payload(&self, stream_id: u64, payload: Bytes) -> Result<Committed> {
        self.commit_stream_payload_inner(stream_id, payload, None)
            .await
    }

    async fn commit_validated_stream_payload(
        &self,
        stream_id: u64,
        payload: Bytes,
        object: MediaObject,
    ) -> Result<Committed> {
        self.commit_stream_payload_inner(stream_id, payload, Some(object))
            .await
    }

    /// Count a refused commit; one log line at counts 1, 2, 4, 8... of each
    /// refusal, so that two contributors that differ cannot flood the log.
    fn refuse_commit(&self, refusal: CommitRefusal, stream_id: u64, sequence: u64) -> Committed {
        let counter = match refusal {
            CommitRefusal::IdentityConflict => &self.canonical_conflicts,
            CommitRefusal::StaleEpoch => &self.canonical_stale_epoch,
        };
        let total = counter.fetch_add(1, Ordering::Relaxed) + 1;
        if total.is_power_of_two() {
            warn!(
                stream_id,
                sequence,
                refusal = refusal.as_str(),
                total,
                "canonical commit refused; the first copy stays"
            );
        }
        Committed::Refused(refusal)
    }

    /// Commit a part or a metadata object. Other bytes under a slot's
    /// identity and an epoch the stream has left are refused, counted and
    /// never an error: nothing is written and nothing is reset.
    async fn commit_stream_payload_inner(
        &self,
        stream_id: u64,
        payload: Bytes,
        validated_object: Option<MediaObject>,
    ) -> Result<Committed> {
        let bytes = payload.len();
        self.make_room_for(stream_id).await?;
        // Stream commits and retirement share this lock so a newly arriving
        // object cannot race cache/state removal for the same stream.
        let commit_lock = self.canonical_commit_lock(stream_id);
        let _commit_guard = commit_lock.lock().await;
        let canonical_object = match validated_object {
            Some(object) => Some(object),
            None => decode_canonical_stream_object(&payload)?,
        };
        if let Some(object) = canonical_object {
            let expected_stream = stream_id.to_string();
            if object.key().stream() != expected_stream {
                bail!(
                    "canonical media-object stream {} does not match carrier stream {stream_id}",
                    object.key().stream()
                );
            }

            let source_epoch = object.key().epoch();
            let (previous_epoch, process_started_unix_us) = {
                let state = self.state.read().await;
                (
                    state.stream_canonical_epoch.get(&stream_id).copied(),
                    state.process_started_unix_us,
                )
            };
            if previous_epoch.is_some_and(|previous| source_epoch < previous) {
                return Ok(self.refuse_commit(
                    CommitRefusal::StaleEpoch,
                    stream_id,
                    object.key().object(),
                ));
            }
            // An edge fed on the fast plane beside the cache mesh: the mesh
            // can have written parts of this epoch (a lease's warm-up window)
            // that nothing has recorded yet. They are the same parts, so the
            // epoch is taken up without dropping them.
            let adopt_mesh_copy = previous_epoch.is_none()
                && self.mesh_copy_epoch(stream_id).await == Some(source_epoch);
            if adopt_mesh_copy {
                self.state
                    .write()
                    .await
                    .stream_canonical_epoch
                    .entry(stream_id)
                    .or_insert(source_epoch);
                self.note_source_epoch(stream_id, source_epoch);
                info!(
                    stream_id,
                    source_epoch, "took up the canonical source epoch of the cache-mesh copy"
                );
            } else if previous_epoch != Some(source_epoch) {
                self.chunk_cache.zero_stream_id(stream_id);
                self.forget_gap_parts(stream_id);
                // A relay may restart and inherit an epoch that has already
                // been active for minutes or hours. Its source age is not an
                // epoch-activation delay. Measure only epochs observed after
                // this process began, or genuine transitions from a previous
                // epoch already active in this process.
                let activation_delay_us = (previous_epoch.is_some()
                    || source_epoch >= process_started_unix_us)
                    .then(|| now_unix_us().checked_sub(source_epoch))
                    .flatten();
                self.note_source_epoch(stream_id, source_epoch);
                let mut state = self.state.write().await;
                state.stream_canonical_epoch.insert(stream_id, source_epoch);
                state
                    .stream_canonical_epoch_activation_delay_us
                    .remove(&stream_id);
                if let Some(activation_delay_us) = activation_delay_us {
                    state
                        .stream_canonical_epoch_activation_delay_us
                        .insert(stream_id, activation_delay_us);
                }
                state.stream_subscription_base_object.remove(&stream_id);
                state.stream_latest_canonical_object.remove(&stream_id);
                state.stream_next_seq.remove(&stream_id);
                state.stream_parts.remove(&stream_id);
                state.stream_keyframe_segments.remove(&stream_id);
                state.stream_retained_bytes.remove(&stream_id);
                state.stream_max_part_duration_us.remove(&stream_id);
                state.stream_max_segment_duration_us.remove(&stream_id);
                state.stream_declared_us.remove(&stream_id);
                state.stream_playlist_floor.remove(&stream_id);
                state.stream_init_scanned.remove(&stream_id);
                state.stream_inits.remove(&stream_id);
                state.stream_media_kinds.remove(&stream_id);
                if stream_id == self.stream_id {
                    state.last_committed_seq = None;
                    state.last_committed_unix_ms = None;
                    state.last_committed_bytes = None;
                    state.last_committed_duration_us = None;
                }
                info!(
                    stream_id,
                    source_epoch,
                    ?activation_delay_us,
                    ?previous_epoch,
                    "activated canonical media source epoch"
                );
            }

            let seq = object.key().object();
            let kind = object.kind();
            let is_soundkit_v2_bundle = object
                .metadata()
                .get("payload-format")
                .is_some_and(|format| format.as_slice() == b"soundkit-v2-bundle");
            let reboxed_audio = (kind == ObjectKind::Media && is_soundkit_v2_bundle)
                .then(|| rebox_soundkit_v2_bundle(object.payload(), seq))
                .transpose()?;
            let media_bytes = reboxed_audio
                .as_ref()
                .map_or_else(|| object.payload().len(), |reboxed| reboxed.media.len());
            let media_duration_us = reboxed_audio
                .as_ref()
                .map(|reboxed| reboxed.duration_us)
                .or_else(|| object_duration_us(&object));
            // The kind that the fast-lane client derives from the envelope
            // with the same function (a reboxed bundle is fMP4).
            let media_kind = if reboxed_audio.is_some() {
                LiveMediaKind::Fmp4
            } else {
                av_mesh::canonical_slot::live_media_kind(&object)
            };
            let now_ms = now_unix_ms();

            {
                let mut state = self.state.write().await;
                state.datagrams_received = state.datagrams_received.saturating_add(1);
                state.bytes_received = state.bytes_received.saturating_add(bytes as u64);
                state.last_ingest_unix_ms = Some(now_ms);
                state.stream_last_ingest_unix_ms.insert(stream_id, now_ms);
                state.observe_stream_seq(stream_id, seq);
                state.stream_media_kinds.insert(stream_id, media_kind);
                if matches!(
                    kind,
                    ObjectKind::Initialization | ObjectKind::CodecConfiguration
                ) {
                    state
                        .stream_inits
                        .insert(stream_id, Bytes::copy_from_slice(object.payload()));
                }
            }

            if matches!(
                kind,
                ObjectKind::Initialization | ObjectKind::CodecConfiguration
            ) {
                self.chunk_cache
                    .set_stream_initialization(stream_id, Bytes::copy_from_slice(object.payload()))
                    .await
                    .map_err(|err| anyhow!("stream initialization cache write failed: {err}"))?;
            }

            if kind != ObjectKind::Media {
                debug!(
                    stream_id,
                    source_epoch,
                    sequence = seq,
                    object_kind = ?kind,
                    bytes = media_bytes,
                    "accepted canonical stream metadata object"
                );
                return Ok(Committed::Stored(seq));
            }

            let slot_id = usize::try_from(seq).context("stream slot sequence too large")?;
            let subscription_base_object = self
                .state
                .read()
                .await
                .stream_subscription_base_object
                .get(&stream_id)
                .copied()
                .unwrap_or(seq);
            let subscription_base_object = usize::try_from(subscription_base_object)
                .context("stream subscription base object is too large")?;
            let cached_payload = if let Some(reboxed) = &reboxed_audio {
                encode_fmp4_slot(&reboxed.init, &reboxed.media)?
            } else {
                encode_canonical_live_slot(stream_id, &object, payload, media_kind)?
            };
            let cached_bytes = cached_payload.len();
            // One handle serves the whole commit: the gap release, the write,
            // its time and the late-part check. The commit lock keeps the
            // stream from being retired or restarted under it. A stream's
            // first part is written by stream ID, which checks the write
            // before it creates the stream, so a refused part takes no slot.
            let existing = self.chunk_cache.resolve_stream(stream_id);
            if let Some(handle) = existing {
                // Runs before the write so the contiguous publication
                // performed by this commit resumes directly behind a
                // released hole.
                self.release_held_canonical_gap(handle, slot_id).await;
            }
            let watermark_before = self.journal_watermark(existing);
            let write_result = match existing {
                Some(handle) => {
                    self.chunk_cache
                        .put_if_absent_contiguous_for_handle(
                            handle,
                            slot_id,
                            subscription_base_object,
                            cached_payload,
                        )
                        .await
                }
                None => {
                    self.chunk_cache
                        .put_if_absent_contiguous_for_stream_id(
                            stream_id,
                            slot_id,
                            subscription_base_object,
                            cached_payload,
                        )
                        .await
                }
            }
            .map_err(|err| anyhow!("canonical stream cache write failed: {err}"))?;
            let handle = existing.or_else(|| self.chunk_cache.resolve_stream(stream_id));
            // The time the cache stored with the slot, which a reader woken
            // by the write already reports.
            let committed_us = handle
                .and_then(|handle| self.chunk_cache.written_unix_us_for_handle(handle, slot_id))
                .unwrap_or_else(now_unix_us);
            if write_result == PutIfAbsentResult::HashConflict {
                return Ok(self.refuse_commit(CommitRefusal::IdentityConflict, stream_id, seq));
            }
            if write_result == PutIfAbsentResult::Inserted {
                // A reboxed bundle's initialization is the stored part's: a
                // copy that is present already or refused leaves the
                // stream's alone. A reader that comes before it is set finds
                // it in the part's slot.
                if let Some(reboxed) = &reboxed_audio {
                    self.remember_stream_init(stream_id, reboxed.init.clone())
                        .await;
                }
                if let Some(handle) = handle {
                    self.observe_late_part(handle, seq, committed_us);
                    self.note_wide_hole(handle, slot_id);
                }
                if let Some(journal) = self.hops() {
                    journal.record_part(HopStage::Committed, stream_id, seq, committed_us);
                    if let Some(before) = watermark_before {
                        let after = self.journal_watermark(handle).flatten();
                        self.journal_watermark_advance(stream_id, before, after, seq, committed_us);
                    }
                }
            }

            let mut state = self.state.write().await;
            state
                .stream_subscription_base_object
                .entry(stream_id)
                .or_insert(seq);
            state
                .stream_latest_canonical_object
                .entry(stream_id)
                .and_modify(|head| *head = (*head).max(seq))
                .or_insert(seq);
            state.last_committed_seq =
                Some(state.last_committed_seq.map_or(seq, |last| last.max(seq)));
            state.last_committed_unix_ms = Some(now_ms);
            state.last_committed_bytes = Some(media_bytes);
            state.last_committed_duration_us = media_duration_us.map(u64::from);
            state.record_part_available(
                stream_id,
                seq,
                cached_bytes,
                now_unix_us(),
                media_duration_us,
                object.is_keyframe(),
                media_kind == LiveMediaKind::Fmp4,
                object_part_stamp(&object),
                self.window_parts,
            );
            state.record_part_published(stream_id, seq, object_published_unix_us(&object));
            state.record_part_committed(stream_id, seq, Some(committed_us));
            debug!(
                stream_id,
                source_epoch,
                sequence = seq,
                slot_id,
                bytes,
                media_bytes,
                media_kind = ?media_kind,
                cache_write = ?write_result,
                keyframe = object.is_keyframe(),
                "committed canonical RaptorQ media object"
            );
            drop(state);
            self.trim_stream_ring(stream_id, slot_id).await;
            self.part_updates.send_replace(seq);
            return Ok(if write_result == PutIfAbsentResult::AlreadyPresent {
                Committed::AlreadyPresent(seq)
            } else {
                Committed::Stored(seq)
            });
        }

        let decoded = LiveSlotPayload::decode(payload.clone());
        let media_bytes = decoded.media().len();
        let media_kind = decoded.media_kind();
        let init = decoded.init();
        let now_ms = now_unix_ms();
        let seq = {
            let mut state = self.state.write().await;
            state.datagrams_received = state.datagrams_received.saturating_add(1);
            state.bytes_received = state.bytes_received.saturating_add(bytes as u64);
            state.last_ingest_unix_ms = Some(now_ms);
            state.stream_last_ingest_unix_ms.insert(stream_id, now_ms);
            state.stream_media_kinds.insert(stream_id, media_kind);
            if let Some(init) = init.clone() {
                state.stream_inits.insert(stream_id, init);
            }
            state.next_stream_seq(stream_id)
        };
        if let Some(init) = init {
            self.chunk_cache
                .set_stream_initialization(stream_id, init)
                .await
                .map_err(|err| anyhow!("stream initialization cache write failed: {err}"))?;
        }
        let slot_id = usize::try_from(seq).context("stream slot sequence too large")?;
        self.chunk_cache
            .add_for_stream_id(stream_id, slot_id, payload)
            .await
            .map_err(|err| anyhow!("stream-prefixed chunk cache write failed: {err}"))?;

        let mut state = self.state.write().await;
        state.last_committed_seq = Some(state.last_committed_seq.map_or(seq, |last| last.max(seq)));
        state.last_committed_unix_ms = Some(now_ms);
        state.last_committed_bytes = Some(media_bytes);
        state.last_committed_duration_us = None;
        state.record_part_available(
            stream_id,
            seq,
            bytes,
            now_unix_us(),
            None,
            false,
            false,
            None,
            self.window_parts,
        );
        debug!(
            stream_id,
            sequence = seq,
            slot_id,
            bytes,
            media_bytes,
            media_kind = ?media_kind,
            "committed stream-prefixed mesh payload"
        );
        drop(state);
        self.part_updates.send_replace(seq);
        Ok(Committed::Stored(seq))
    }

    /// The source epoch of the newest part of a stream that the cache mesh
    /// wrote into the cache, if it carries one.
    async fn mesh_copy_epoch(&self, stream_id: u64) -> Option<u64> {
        let handle = self.chunk_cache.resolve_stream(stream_id)?;
        let last = self.chunk_cache.last_for_handle(handle)?;
        let (bytes, _) = self.chunk_cache.get_for_handle(handle, last).await?;
        MeshPartRecord::from_slot(&bytes, stream_id)?.epoch
    }

    /// Record the playlist entry of a part that the cache mesh delivered.
    ///
    /// A part carries its own playlist entry: its duration, whether it starts
    /// with a key frame, and when the contributor published it. An edge reads
    /// the entry from the part, so its playlist is the playlist of its
    /// distributor and not a second, poorer one.
    ///
    /// `committed_unix_us` is when the mesh wrote the part into the cache.
    async fn observe_mesh_part(
        &self,
        stream_id: u64,
        slot_id: usize,
        committed_unix_us: Option<u64>,
    ) -> Option<MeshPartRecord> {
        let (bytes, _) = self
            .chunk_cache
            .get_for_stream_id(stream_id, slot_id)
            .await?;
        let record = MeshPartRecord::from_slot(&bytes, stream_id)?;
        let sequence = slot_id as u64;
        let now_ms = now_unix_ms();

        let previous_epoch = self
            .state
            .read()
            .await
            .stream_canonical_epoch
            .get(&stream_id)
            .copied();
        match (record.epoch, previous_epoch) {
            // A late part of a publication that has been replaced.
            (Some(epoch), Some(previous)) if epoch < previous => return None,
            (Some(epoch), Some(previous)) if epoch > previous => {
                // The source started a new publication, and its sequence
                // starts again. Drop the copy of the old publication and keep
                // the part that announced the new one.
                let initialization = self.chunk_cache.stream_initialization(stream_id);
                self.forget_mesh_stream(stream_id).await;
                if let Some(initialization) = initialization {
                    let _ = self
                        .chunk_cache
                        .set_stream_initialization(stream_id, initialization)
                        .await;
                }
                if self
                    .chunk_cache
                    .add_for_stream_id(stream_id, slot_id, bytes.clone())
                    .await
                    .is_err()
                {
                    return None;
                }
                info!(
                    stream_id,
                    epoch, previous, "cache-mesh copy restarted for a new source publication"
                );
            }
            _ => {}
        }

        if let Some(epoch) = record.epoch.filter(|epoch| previous_epoch != Some(*epoch)) {
            self.note_source_epoch(stream_id, epoch);
        }
        let mut state = self.state.write().await;
        if let Some(epoch) = record.epoch {
            state.stream_canonical_epoch.insert(stream_id, epoch);
        }
        state.stream_last_ingest_unix_ms.insert(stream_id, now_ms);
        state
            .stream_media_kinds
            .insert(stream_id, record.media_kind);
        if let Some(init) = record.init.clone() {
            state.stream_inits.insert(stream_id, init);
        }
        state.observe_stream_seq(stream_id, sequence);
        state.record_part_available(
            stream_id,
            sequence,
            bytes.len(),
            now_unix_us(),
            record.duration_us,
            record.keyframe,
            record.keyframe_segments,
            record.stamp,
            self.window_parts,
        );
        state.record_part_published(stream_id, sequence, record.published_unix_us);
        state.record_part_committed(stream_id, sequence, committed_unix_us);
        drop(state);
        self.trim_stream_ring(stream_id, slot_id).await;
        // A reader can render the playlist between the cache write and this
        // record. That rendering lacks the entry, so it must not be reused.
        self.invalidate_cached_playlist(stream_id);
        self.part_updates.send_replace(sequence);
        Some(record)
    }

    fn invalidate_cached_playlist(&self, stream_id: u64) {
        for cached_playlist in &self.playlist_cache {
            let mut cached_playlist = cached_playlist
                .write()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if cached_playlist
                .as_ref()
                .is_some_and(|cached| cached.handle.stream_id() == stream_id)
            {
                *cached_playlist = None;
            }
        }
    }

    /// Drop the local copy of a playlist that the cache mesh supplied.
    async fn forget_mesh_stream(&self, stream_id: u64) {
        let commit_lock = self.canonical_commit_lock(stream_id);
        let _commit_guard = commit_lock.lock().await;
        // Release the bytes too. A copy that is only hidden stays in memory
        // until another stream overwrites it, and a small node that holds 4K
        // copies in turn would fill with copies that nobody reads.
        self.chunk_cache.release_stream_id(stream_id).await;
        self.state.write().await.forget_stream(stream_id);
        self.invalidate_cached_playlist(stream_id);
    }

    /// Parts in the playlist window of one stream. See
    /// [`LiveState::stream_window_parts`].
    /// What `GET /api/node` reports of each stream the cache holds or has
    /// ingested, by stream: its retained parts and its window.
    async fn stream_holdings(&self) -> Vec<StreamHolding> {
        let state = self.state.read().await;
        let mut streams: BTreeSet<u64> = state.stream_parts.keys().copied().collect();
        streams.extend(state.stream_last_ingest_unix_ms.keys().copied());
        streams
            .into_iter()
            .map(|stream_id| {
                let parts = state.stream_parts.get(&stream_id);
                let head = parts.and_then(|parts| parts.iter().next_back());
                StreamHolding {
                    stream_id,
                    ingest_unix_ms: state.stream_last_ingest_unix_ms.get(&stream_id).copied(),
                    head_part: head.map(|(sequence, _)| *sequence),
                    head_written_unix_us: head.map(|(_, part)| {
                        part.committed_unix_us.unwrap_or(part.available_unix_us)
                    }),
                    first_part: parts
                        .and_then(|parts| parts.keys().next())
                        .copied(),
                    window_parts: parts.map_or(0, |parts| parts.len() as u64),
                    window_limit: state.stream_window_parts(stream_id, self.window_parts) as u64,
                }
            })
            .collect()
    }

    async fn window_parts_for(&self, stream_id: u64) -> usize {
        self.state
            .read()
            .await
            .stream_window_parts(stream_id, self.window_parts)
    }

    /// Release the part that has just left the retained window of a stream
    /// with a shorter window than the cache ring.
    ///
    /// The ring keeps four windows of nominal parts for every stream. A 4K
    /// part is hundreds of kilobytes, so a ring of them does not fit a small
    /// node. A stream keeps four of its own windows instead.
    async fn trim_stream_ring(&self, stream_id: u64, newest: usize) {
        let window_parts = self.window_parts_for(stream_id).await;
        if window_parts >= self.window_parts {
            return;
        }
        let retained = self
            .state
            .read()
            .await
            .stream_retained_parts(stream_id, self.window_parts);
        if let Some(expired) = newest.checked_sub(retained) {
            self.chunk_cache
                .clear_for_stream_id(stream_id, expired)
                .await;
        }
    }

    /// Measured bit rate of a playlist over its retained parts.
    async fn playlist_bitrate_bps(&self, stream_id: u64) -> Option<u64> {
        let state = self.state.read().await;
        state.playlist_bitrate_bps(
            stream_id,
            self.nominal_part_us(),
            self.min_bitrate_window_ms(),
        )
    }

    /// The nominal part of the node in microseconds, at least one.
    fn nominal_part_us(&self) -> u64 {
        duration_us(self.part_target).max(1)
    }

    /// The bit rate of a playlist is measured over at least four seconds, or
    /// over half of the window of a node with a shorter window.
    fn min_bitrate_window_ms(&self) -> u64 {
        let window_ms = (self.window_parts as u64).saturating_mul(self.nominal_part_us()) / 1_000;
        MIN_BITRATE_WINDOW_MS.min(window_ms / 2)
    }

    /// Wait until a playlist that this node has just subscribed to has parts
    /// to serve, or the wait ends. Returns whether parts are present.
    /// Wait until a new copy of a playlist can be played: it lists a whole
    /// segment, which a player needs before it starts. A cache that answers
    /// with the first part alone gives a player an empty playlist: hls.js
    /// counts that as a failure of the cache, and ffmpeg ends.
    async fn wait_for_playlist_copy(&self, stream_id: u64, wait: Duration) -> bool {
        let deadline = Instant::now() + wait;
        let mut updates = self.part_updates.subscribe();
        loop {
            if self.state.read().await.playlist_is_playable(stream_id) {
                return true;
            }
            let now = Instant::now();
            if now >= deadline {
                return false;
            }
            let _ = tokio::time::timeout(
                (deadline - now).min(Duration::from_millis(50)),
                updates.changed(),
            )
            .await;
        }
    }

    /// Refuse a stream that has no playlist slot while every slot holds a
    /// live stream.
    ///
    /// The chunk cache gives a new stream the slot of another stream when
    /// none is free. With one stream more than slots, each part of the
    /// stream without a slot took the slot of a live stream, whose next part
    /// took the slot of another: every stream of the node lost its window
    /// again and again. A full node now keeps what it has. A stream that
    /// has had no part for `STREAM_SLOT_IDLE_MS` gives up its slot.
    async fn make_room_for(&self, stream_id: u64) -> Result<()> {
        if self.chunk_cache.resolve_stream(stream_id).is_some() {
            return Ok(());
        }
        let slots = self.chunk_cache.options.num_playlists;
        if self.chunk_cache.stream_handles().len() < slots {
            return Ok(());
        }
        self.retire_streams_idle_before(now_unix_ms().saturating_sub(STREAM_SLOT_IDLE_MS))
            .await;
        if self.chunk_cache.stream_handles().len() < slots {
            return Ok(());
        }
        let refused = self.stream_slot_refusals.fetch_add(1, Ordering::Relaxed) + 1;
        if refused <= 4 || refused.is_power_of_two() {
            warn!(
                stream_id,
                slots,
                refused,
                "every playlist slot holds a live stream: the parts of this stream are refused (see --playlist-slots)"
            );
        }
        bail!("no playlist slot is free for stream {stream_id}: all {slots} hold a live stream")
    }

    async fn retire_streams_idle_before(&self, cutoff_unix_ms: u64) -> usize {
        let candidates: Vec<u64> = {
            let state = self.state.read().await;
            state
                .stream_last_ingest_unix_ms
                .iter()
                .filter_map(|(stream_id, last_ingest_unix_ms)| {
                    (*stream_id != self.stream_id && *last_ingest_unix_ms <= cutoff_unix_ms)
                        .then_some(*stream_id)
                })
                .collect()
        };

        let mut retired = 0;
        for stream_id in candidates {
            let commit_lock = self.canonical_commit_lock(stream_id);
            let commit_guard = commit_lock.lock().await;
            let still_idle = self
                .state
                .read()
                .await
                .stream_last_ingest_unix_ms
                .get(&stream_id)
                .is_some_and(|last_ingest_unix_ms| *last_ingest_unix_ms <= cutoff_unix_ms);
            if !still_idle {
                continue;
            }

            self.chunk_cache.zero_stream_id(stream_id);
            self.state.write().await.forget_stream(stream_id);
            self.forget_gap_parts(stream_id);
            for cached_playlist in &self.playlist_cache {
                let mut cached_playlist = cached_playlist
                    .write()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                if cached_playlist
                    .as_ref()
                    .is_some_and(|cached| cached.handle.stream_id() == stream_id)
                {
                    *cached_playlist = None;
                }
            }
            retired += 1;
            drop(commit_guard);

            let mut commit_locks = self
                .canonical_commit_locks
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if commit_locks
                .get(&stream_id)
                .is_some_and(|stored| Arc::ptr_eq(stored, &commit_lock))
                && Arc::strong_count(&commit_lock) == 2
            {
                commit_locks.remove(&stream_id);
            }
        }
        retired
    }

    async fn add_media_access_unit(
        &self,
        metadata: MediaFrameMetadata,
        payload: Bytes,
    ) -> Result<CachedMediaAccessUnit> {
        let stream_id = metadata.stream_id;
        let slot_id =
            usize::try_from(metadata.sequence).context("media access-unit sequence too large")?;
        if payload.len() > u32::MAX as usize {
            bail!(
                "media access-unit too large: {} bytes exceeds u32::MAX",
                payload.len()
            );
        }

        let header = MediaFragmentHeader {
            metadata,
            fragment_index: 0,
            fragment_count: 1,
            access_unit_len: payload.len() as u32,
            fragment_offset: 0,
        };
        let mut serialized = Vec::with_capacity(MEDIA_FRAME_HEADER_LEN + payload.len());
        serialized.resize(MEDIA_FRAME_HEADER_LEN, 0);
        header
            .encode(&mut serialized[..MEDIA_FRAME_HEADER_LEN])
            .map_err(|err| anyhow!("media access-unit header encode failed: {err}"))?;
        serialized.extend_from_slice(&payload);
        let serialized = Bytes::from(serialized);

        self.chunk_cache
            .add_for_stream_id(stream_id, slot_id, serialized.clone())
            .await
            .map_err(|err| anyhow!("media access-unit cache write failed: {err}"))?;

        {
            let mut state = self.state.write().await;
            state.datagrams_received = state.datagrams_received.saturating_add(1);
            state.last_ingest_unix_ms = Some(now_unix_ms());
            state.bytes_received = state.bytes_received.saturating_add(payload.len() as u64);
        }

        debug!(
            stream_id,
            sequence = metadata.sequence,
            slot_id,
            payload_bytes = payload.len(),
            serialized_bytes = serialized.len(),
            codec = ?metadata.codec,
            keyframe = metadata.flags.is_keyframe(),
            "committed media access unit"
        );

        Ok(CachedMediaAccessUnit {
            metadata,
            payload_bytes: payload.len(),
            serialized,
            hash: 0,
        })
    }

    async fn get_media_access_unit(
        &self,
        stream_id: u64,
        sequence: u64,
    ) -> Option<CachedMediaAccessUnit> {
        let slot_id = usize::try_from(sequence).ok()?;
        let (serialized, hash) = self
            .chunk_cache
            .get_for_stream_id(stream_id, slot_id)
            .await?;
        if serialized.len() < MEDIA_FRAME_HEADER_LEN {
            return None;
        }
        let header = MediaFragmentHeader::decode(&serialized[..MEDIA_FRAME_HEADER_LEN]).ok()?;
        if header.metadata.stream_id != stream_id
            || header.metadata.sequence != sequence
            || header.fragment_index != 0
            || header.fragment_count != 1
            || header.fragment_offset != 0
        {
            return None;
        }
        let payload_bytes = serialized.len().checked_sub(MEDIA_FRAME_HEADER_LEN)?;
        if header.access_unit_len as usize != payload_bytes {
            return None;
        }
        Some(CachedMediaAccessUnit {
            metadata: header.metadata,
            payload_bytes,
            serialized,
            hash,
        })
    }

    async fn playlist(&self) -> String {
        self.playlist_for_stream_id(self.stream_id).await
    }

    async fn playlist_for_stream_id(&self, stream_id: u64) -> String {
        let mut attempts = 0;
        loop {
            let Some((handle, last)) = self.stream_position_for_id(stream_id).await else {
                let media_kind = self
                    .media_kind_hint(stream_id)
                    .await
                    .unwrap_or(LiveMediaKind::Fmp4);
                let include_map = media_kind == LiveMediaKind::Fmp4
                    && self.get_init_for_stream_id(stream_id).await.is_some();
                return self.empty_playlist(0, media_kind, include_map);
            };
            let playlist = self.playlist_for_handle(handle, last).await;
            attempts += 1;
            // The stream was retired or restarted while its playlist was
            // rendered, so the rendering may hold parts of the lifetime that
            // ended. Render the current one, once.
            if attempts >= 2 || self.chunk_cache.version_for_handle(handle).is_some() {
                return playlist;
            }
        }
    }

    /// The playlist of one lifetime of a stream, whose contiguous watermark
    /// was `last`.
    async fn playlist_for_handle(&self, handle: StreamHandle, last: usize) -> String {
        let stream_id = handle.stream_id();
        let mut version = self
            .chunk_cache
            .version_for_handle(handle)
            .unwrap_or_default();
        if let Some(playlist) = self.cached_playlist(handle, version) {
            return playlist;
        }
        let _rendering = match self.playlist_render_locks.get(handle.index()) {
            Some(lock) if self.playlist_scan_memo.load(Ordering::Relaxed) => {
                let guard = lock.lock().await;
                // The render that this one waited for may be the one it
                // wants.
                version = self
                    .chunk_cache
                    .version_for_handle(handle)
                    .unwrap_or_default();
                if let Some(playlist) = self.cached_playlist(handle, version) {
                    return playlist;
                }
                Some(guard)
            }
            _ => None,
        };
        // The newest part now: the render waited for may have made room.
        let last = self.chunk_cache.last_for_handle(handle).unwrap_or(last);
        let first = last.saturating_sub(self.window_parts_for(stream_id).await.saturating_sub(1));
        let (available, latest_media_kind, discovered_init) =
            self.scan_playlist_window(handle, first, last).await;
        if available.is_empty() {
            let media_kind = self
                .media_kind_hint(stream_id)
                .await
                .unwrap_or(LiveMediaKind::Fmp4);
            let include_map = media_kind == LiveMediaKind::Fmp4
                && self.get_init_for_stream_id(stream_id).await.is_some();
            let playlist = self.empty_playlist(last, media_kind, include_map);
            return self.cache_playlist(handle, version, playlist);
        }
        if let Some(init) = discovered_init {
            self.remember_stream_init(stream_id, init).await;
        }
        let media_kind = if let Some(media_kind) = latest_media_kind {
            media_kind
        } else {
            self.media_kind_hint(stream_id)
                .await
                .unwrap_or(LiveMediaKind::Fmp4)
        };
        self.remember_media_kind(stream_id, media_kind).await;
        let init = if media_kind == LiveMediaKind::Fmp4 {
            self.get_init_for_stream_id(stream_id).await
        } else {
            None
        };
        if media_kind == LiveMediaKind::Fmp4 && init.is_none() {
            warn!(
                stream_id,
                "suppressing fMP4 live playlist until init segment is available"
            );
            let playlist = self.waiting_playlist(false);
            return self.cache_playlist(handle, version, playlist);
        }

        let next_part = available.last().copied().unwrap_or(0) + 1;
        let nominal_part_duration_us = u32::try_from(self.nominal_part_us()).unwrap_or(u32::MAX);
        let (part_target_us, declared_target_us, available) = {
            let state = self.state.read().await;
            let observations = state.stream_parts.get(&stream_id);
            let declared = state.stream_declared_us.get(&stream_id).copied();
            // A part that the cache mesh has just written has no playlist
            // entry for a moment. Listing it now would give it the nominal
            // duration of the node and no independent flag. It is listed
            // when its entry is recorded, which invalidates this playlist.
            // A stamped stream has the part target that its contributor
            // declares. Another stream has its longest part, and no less
            // than the nominal part of the node.
            let part_target_us = match declared {
                Some((part_us, _)) if part_us > 0 => part_us,
                _ => state
                    .stream_max_part_duration_us
                    .get(&stream_id)
                    .copied()
                    .unwrap_or(nominal_part_duration_us)
                    .max(nominal_part_duration_us),
            };
            let entry = |sequence: u64, part: Option<&RetainedPartObservation>| {
                (
                    sequence,
                    part.and_then(|part| part.duration_us)
                        .unwrap_or(nominal_part_duration_us),
                    part.is_some_and(|part| part.keyframe),
                    part.and_then(|part| part.fmp4_segment_id),
                    // The publication time is written by the contributor, so
                    // every cache derives the same program date and time. The
                    // local arrival time is the fallback for a part without
                    // it.
                    part.map(|part| part.published_unix_us.unwrap_or(part.available_unix_us))
                        .unwrap_or_default(),
                    part.and_then(|part| part.stamped_part),
                )
            };
            let available = match observations {
                Some(parts) if !parts.is_empty() => {
                    // One ordered walk of the window's observations beside
                    // the parts, not a lookup of each part for each field.
                    let mut observed = parts
                        .range(available.first().copied().unwrap_or(0)..)
                        .peekable();
                    available
                        .into_iter()
                        .filter_map(|sequence| {
                            while observed.next_if(|(seen, _)| **seen < sequence).is_some() {}
                            observed
                                .next_if(|(seen, _)| **seen == sequence)
                                .map(|(_, part)| entry(sequence, Some(part)))
                        })
                        .collect::<Vec<_>>()
                }
                _ => available
                    .into_iter()
                    .map(|sequence| entry(sequence, None))
                    .collect::<Vec<_>>(),
            };
            (
                part_target_us,
                declared.map(|(_, target_us)| u64::from(target_us)),
                available,
            )
        };
        // The hint names the part after the last part that is listed.
        let next_part = available
            .last()
            .map_or(next_part, |(sequence, ..)| sequence + 1);

        // The contributor stamps the segment number and the part index on
        // every part. A stream with stamps has the same playlist on every
        // cache. The rules below it are for a stream without stamps.
        let stamped = available
            .iter()
            .any(|(_, _, _, _, _, stamped_part)| stamped_part.is_some());
        let keyframe_aligned_segments = (stamped || media_kind == LiveMediaKind::Fmp4)
            && available
                .iter()
                .any(|(_, _, _, segment_id, _, _)| segment_id.is_some());
        // Parts that the watermark passed as holes and that are still
        // missing (the repair horizon, wave 5 W2) are listed where they
        // belong, as gaps, so that a player knows that they will not come.
        let gaps = available
            .first()
            .map(|(first_listed, ..)| self.gap_parts_in(stream_id, *first_listed, last as u64))
            .unwrap_or_default();
        // The first listed part of each segment and its stamped index.
        let mut first_stamped_parts: BTreeMap<u64, (u64, u32)> = BTreeMap::new();
        // Each segment's parts: (sequence, duration, key frame, time, gap).
        let mut groups: BTreeMap<u64, Vec<PlaylistEntry>> = BTreeMap::new();
        // The listed parts in order: (sequence, segment, key frame, stamped
        // index), for placing the gaps between them.
        let mut listed: Vec<(u64, u64, bool, Option<u32>)> = Vec::new();
        for (seq, duration_us, keyframe, fmp4_segment_id, available_unix_us, stamped_part) in
            available
        {
            if let (Some(segment_id), Some(stamped_part)) = (fmp4_segment_id, stamped_part) {
                first_stamped_parts
                    .entry(segment_id)
                    .or_insert((seq, stamped_part));
            }
            let segment_id = if keyframe_aligned_segments {
                let Some(segment_id) = fmp4_segment_id else {
                    continue;
                };
                segment_id
            } else {
                seq / self.parts_per_segment as u64
            };
            listed.push((seq, segment_id, keyframe, stamped_part));
            groups.entry(segment_id).or_default().push((
                seq,
                duration_us,
                keyframe,
                available_unix_us,
                false,
            ));
        }
        if !gaps.is_empty() {
            for gap in &gaps {
                let segment_id = if keyframe_aligned_segments {
                    gap_segment(&listed, *gap)
                } else {
                    Some(gap / self.parts_per_segment as u64)
                };
                if let Some(segment_id) = segment_id {
                    groups.entry(segment_id).or_default().push((
                        *gap,
                        part_target_us,
                        false,
                        0,
                        true,
                    ));
                }
            }
            for group in groups.values_mut() {
                group.sort_unstable_by_key(|entry| entry.0);
            }
        }
        if stamped {
            // A retained window can begin halfway through a segment. The
            // segment is listed only when its first part is here, or when
            // the gaps in front of its first listed part stand for the
            // parts before it (a segment in the middle of the window whose
            // first part never came stays, so that the segments after it
            // keep their numbers).
            groups.retain(|segment_id, group| {
                let Some((first_listed, index)) = first_stamped_parts.get(segment_id) else {
                    return false;
                };
                let first = group.first().map_or(*first_listed, |entry| entry.0);
                u64::from(*index) == first_listed.saturating_sub(first)
                    && (*index == 0 || group.first().is_some_and(|entry| entry.4))
            });
            // A playlist never grows at its front. The first segment that a
            // reader was shown stays the first until it leaves the window.
            if groups.len() >= 2 {
                let mut state = self.state.write().await;
                let first = *groups.keys().next().expect("a group");
                let floor = *state
                    .stream_playlist_floor
                    .entry(stream_id)
                    .or_insert(first);
                drop(state);
                groups.retain(|segment_id, _group| *segment_id >= floor);
            }
        } else if keyframe_aligned_segments {
            // A retained window can begin halfway through a GOP. Do not
            // advertise that truncated parent as a playable HLS segment. A
            // segment that starts with a gap is one in the middle of the
            // window whose key frame never came: it stays.
            groups.retain(|_segment_id, group| {
                group.first().is_some_and(
                    |(_sequence, _duration_us, keyframe, _available_unix_us, gap)| {
                        *keyframe || *gap
                    },
                )
            });
        } else if groups.len() > 1 {
            // A retained window can also begin halfway through a fixed-size
            // audio parent segment. Omit that incomplete old parent.
            let first_segment = groups.first_key_value().map(|(segment, _)| *segment);
            if let Some(first_segment) = first_segment {
                let expected_first_sequence =
                    first_segment.saturating_mul(self.parts_per_segment as u64);
                if groups
                    .get(&first_segment)
                    .and_then(|group| group.first())
                    .is_some_and(
                        |(sequence, _duration_us, _keyframe, _available_unix_us, _)| {
                            *sequence != expected_first_sequence
                        },
                    )
                {
                    groups.remove(&first_segment);
                }
            }
        }
        let open_segment_id = keyframe_aligned_segments
            .then(|| {
                groups
                    .last_key_value()
                    .map(|(segment_id, _group)| *segment_id)
            })
            .flatten();
        // A contributor cuts a part short only for the key frame that starts
        // the next segment. The segment of a short part is whole as soon as
        // the part is here: the playlist does not show a short part at the
        // end of an open segment, which only the last part of a segment may
        // be, and a player that reads segments has it one part sooner.
        let open_segment_ended_short = stamped
            && groups
                .last_key_value()
                .and_then(|(_segment_id, group)| group.last())
                .is_some_and(
                    |(_sequence, duration_us, _keyframe, _available_unix_us, gap)| {
                        !*gap && part_ends_segment_short(*duration_us, part_target_us)
                    },
                );
        let segment_is_complete = |segment_id: u64, group_len: usize| {
            if keyframe_aligned_segments {
                Some(segment_id) != open_segment_id || open_segment_ended_short
            } else {
                group_len == self.parts_per_segment
            }
        };
        let observed_segment_duration_us = groups
            .iter()
            .filter(|(segment_id, group)| segment_is_complete(**segment_id, group.len()))
            .map(|(_segment_id, group)| {
                group
                    .iter()
                    .map(
                        |(_sequence, duration_us, _keyframe, _available_unix_us, _)| {
                            u64::from(*duration_us)
                        },
                    )
                    .sum::<u64>()
            })
            .max();
        let fallback_segment_duration_us =
            u64::from(nominal_part_duration_us) * self.parts_per_segment as u64;
        let segment_target_us = {
            let mut state = self.state.write().await;
            if let Some(observed_duration_us) = observed_segment_duration_us {
                state
                    .stream_max_segment_duration_us
                    .entry(stream_id)
                    .and_modify(|duration_us| {
                        *duration_us = (*duration_us).max(observed_duration_us);
                    })
                    .or_insert(observed_duration_us);
            }
            let observed = state
                .stream_max_segment_duration_us
                .get(&stream_id)
                .copied();
            match declared_target_us {
                // The target duration of a stamped stream is the one that
                // its contributor declares, and nothing else. One long
                // segment, after a fault upstream, is longer than the target
                // while it is in the playlist. It does not raise the target
                // of the stream for good, and with it the hold-back of every
                // player.
                Some(declared_us) if declared_us > 0 => {
                    let _ = observed;
                    declared_us
                }
                _ => observed
                    .unwrap_or(fallback_segment_duration_us)
                    .max(fallback_segment_duration_us),
            }
        };
        let target_duration = hls_target_duration_from_micros(segment_target_us);

        let mut out = String::new();
        out.push_str("#EXTM3U\n");
        out.push_str("#EXT-X-VERSION:10\n");
        out.push_str(&format!("#EXT-X-TARGETDURATION:{target_duration}\n"));
        let media_sequence = groups.keys().next().copied().unwrap_or(0);
        out.push_str(&format!("#EXT-X-MEDIA-SEQUENCE:{media_sequence}\n"));
        let audio_only_fmp4 = media_kind == LiveMediaKind::Fmp4
            && init.as_deref().is_some_and(fmp4_init_is_audio_only);
        if (keyframe_aligned_segments && media_kind == LiveMediaKind::Fmp4) || audio_only_fmp4 {
            out.push_str("#EXT-X-INDEPENDENT-SEGMENTS\n");
        }
        if media_kind == LiveMediaKind::Fmp4 {
            if init.is_some() {
                out.push_str("#EXT-X-MAP:URI=\"init.mp4\"\n");
            } else {
                warn!(
                    stream_id,
                    "fMP4 live playlist has media fragments but no init segment"
                );
            }
        }
        push_part_inf_and_server_control(
            &mut out,
            u64::from(part_target_us),
            self.part_hold_back_us(u64::from(part_target_us)),
            target_duration,
        );
        let program_date_time = groups
            .values()
            .next()
            .and_then(|group| group.first())
            .filter(
                |(_sequence, _duration_us, _keyframe, available_unix_us, _)| *available_unix_us > 0,
            )
            .and_then(
                |(_sequence, duration_us, _keyframe, available_unix_us, _)| {
                    let start_unix_us = available_unix_us.saturating_sub(u64::from(*duration_us));
                    format_hls_program_date_time(start_unix_us)
                },
            );
        if let Some(program_date_time) = program_date_time {
            out.push_str(&format!("#EXT-X-PROGRAM-DATE-TIME:{program_date_time}\n"));
        }

        let extension = media_kind.extension();
        let last_segment = groups
            .last_key_value()
            .map(|(segment, _group)| *segment)
            .unwrap_or(0);
        let parted_window_segments = (target_duration.saturating_mul(3_000_000))
            .div_ceil(segment_target_us.max(1))
            .max(1);
        let first_parted_segment =
            last_segment.saturating_sub(parted_window_segments.saturating_sub(1));
        use std::fmt::Write as _;
        // Nearly every part of a stream has the same duration: its text is
        // written once and copied.
        let mut part_duration_text = (u32::MAX, String::new());
        let mut gap_duration_text = String::new();
        push_seconds(&mut gap_duration_text, u64::from(part_target_us));
        for (segment, group) in groups {
            let mut segment_duration_us = 0_u64;
            for (seq, duration_us, keyframe, _available_unix_us, gap) in &group {
                segment_duration_us = segment_duration_us.saturating_add(u64::from(*duration_us));
                if segment < first_parted_segment {
                    continue;
                }
                if *gap {
                    out.push_str("#EXT-X-PART:DURATION=");
                    out.push_str(&gap_duration_text);
                    let _ = writeln!(out, ",URI=\"part{seq}.{extension}\",GAP=YES");
                    continue;
                }
                let independent =
                    if (*keyframe || audio_only_fmp4) && media_kind == LiveMediaKind::Fmp4 {
                        ",INDEPENDENT=YES"
                    } else {
                        ""
                    };
                if part_duration_text.0 != *duration_us {
                    part_duration_text.1.clear();
                    push_seconds(&mut part_duration_text.1, u64::from(*duration_us));
                    part_duration_text.0 = *duration_us;
                }
                out.push_str("#EXT-X-PART:DURATION=");
                out.push_str(&part_duration_text.1);
                let _ = writeln!(out, ",URI=\"part{seq}.{extension}\"{independent}");
            }
            if segment_is_complete(segment, group.len()) {
                // A segment none of whose parts came is a gap as a whole.
                if group.iter().all(|entry| entry.4) {
                    out.push_str("#EXT-X-GAP\n");
                }
                out.push_str("#EXTINF:");
                push_seconds(&mut out, segment_duration_us);
                out.push_str(",\n");
                let _ = writeln!(out, "seg{segment}.{extension}");
            }
        }

        out.push_str(&format!(
            "#EXT-X-PRELOAD-HINT:TYPE=PART,URI=\"part{next_part}.{extension}\"\n"
        ));
        self.cache_playlist(handle, version, out)
    }

    fn cached_playlist(&self, handle: StreamHandle, version: u64) -> Option<String> {
        let cached = self.playlist_cache.get(handle.index())?.read().ok()?;
        cached
            .as_ref()
            .filter(|cached| cached.handle == handle && cached.version == version)
            .map(|cached| cached.body.clone())
    }

    fn cache_playlist(&self, handle: StreamHandle, version: u64, body: String) -> String {
        if self.chunk_cache.version_for_handle(handle) != Some(version) {
            return body;
        }
        if let Some(cache) = self.playlist_cache.get(handle.index()) {
            if let Ok(mut cached) = cache.write() {
                *cached = Some(CachedPlaylist {
                    handle,
                    version,
                    body: body.clone(),
                });
            }
        }
        body
    }

    fn empty_playlist(
        &self,
        next_part: usize,
        media_kind: LiveMediaKind,
        include_map: bool,
    ) -> String {
        let extension = media_kind.extension();
        let preload_hint = if media_kind == LiveMediaKind::Fmp4 && !include_map {
            String::new()
        } else {
            format!("#EXT-X-PRELOAD-HINT:TYPE=PART,URI=\"part{next_part}.{extension}\"\n")
        };
        let mut out = self.waiting_playlist(include_map);
        out.push_str(&preload_hint);
        out
    }

    fn waiting_playlist(&self, include_map: bool) -> String {
        let part_target_us = self.nominal_part_us();
        let target_duration = hls_target_duration_from_micros(
            part_target_us.saturating_mul(self.parts_per_segment as u64),
        );
        let map = if include_map {
            "#EXT-X-MAP:URI=\"init.mp4\"\n"
        } else {
            ""
        };
        let mut out = format!(
            "#EXTM3U\n#EXT-X-VERSION:10\n#EXT-X-TARGETDURATION:{target_duration}\n#EXT-X-MEDIA-SEQUENCE:0\n{map}"
        );
        push_part_inf_and_server_control(
            &mut out,
            part_target_us,
            self.part_hold_back_us(part_target_us),
            target_duration,
        );
        out
    }

    async fn remember_media_kind(&self, stream_id: u64, media_kind: LiveMediaKind) {
        // Every part read remembers the kind of its stream, which is nearly
        // always known already: a shared lock to look, the exclusive one
        // only to change it.
        if self.state.read().await.stream_media_kinds.get(&stream_id) == Some(&media_kind) {
            return;
        }
        let mut state = self.state.write().await;
        state.stream_media_kinds.insert(stream_id, media_kind);
    }

    /// The newest stored part of a stream, without waiting for a lock.
    fn stream_head(&self, stream_id: u64) -> Option<u64> {
        let handle = self.chunk_cache.resolve_stream(stream_id)?;
        self.chunk_cache
            .last_for_handle(handle)
            .map(|last| last as u64)
    }

    async fn media_kind_hint(&self, stream_id: u64) -> Option<LiveMediaKind> {
        let state = self.state.read().await;
        state.stream_media_kinds.get(&stream_id).copied()
    }

    async fn remember_stream_init(&self, stream_id: u64, init: Bytes) {
        {
            let mut state = self.state.write().await;
            state.stream_inits.insert(stream_id, init.clone());
        }
        if let Err(error) = self
            .chunk_cache
            .set_stream_initialization(stream_id, init)
            .await
        {
            warn!(stream_id, error, "failed to retain stream initialization");
        }
    }

    async fn get_init_for_stream_id(&self, stream_id: u64) -> Option<Bytes> {
        {
            let state = self.state.read().await;
            if let Some(init) = state.stream_inits.get(&stream_id) {
                return Some(init.clone());
            }
        }
        if let Some(init) = self.chunk_cache.stream_initialization(stream_id) {
            self.remember_stream_init(stream_id, init.clone()).await;
            return Some(init);
        }

        let (handle, last) = self.stream_position_for_id(stream_id).await?;
        // A stream without an initialization section, such as opaque audio,
        // has none in any part. Each part is looked at once: without this
        // mark every request for the Multivariant Playlist of such a stream
        // decoded its whole window, which was most of the processor of an
        // entry point that two thousand readers asked at once.
        let scanned = self
            .state
            .read()
            .await
            .stream_init_scanned
            .get(&stream_id)
            .copied();
        let first = self
            .chunk_cache
            .retained_start(last)
            .max(scanned.map_or(0, |slot| slot.saturating_add(1)));
        for seq in (first..=last).rev() {
            let Some((bytes, _hash)) = self.chunk_cache.get_for_handle(handle, seq).await else {
                continue;
            };
            let slot = LiveSlotPayload::decode_for_stream(bytes, stream_id);
            if let Some(init) = slot.init() {
                self.remember_stream_init(stream_id, init.clone()).await;
                return Some(init);
            }
        }
        self.state
            .write()
            .await
            .stream_init_scanned
            .insert(stream_id, last);
        None
    }

    async fn stream_position(&self) -> Option<(StreamHandle, usize)> {
        self.stream_position_for_id(self.stream_id).await
    }

    /// The current lifetime of a stream and its contiguous watermark.
    async fn stream_position_for_id(&self, stream_id: u64) -> Option<(StreamHandle, usize)> {
        let handle = self.chunk_cache.resolve_stream(stream_id)?;
        let last = self.chunk_cache.last_for_handle(handle)?;
        Some((handle, last))
    }

    async fn get_part_for_stream_id(&self, stream_id: u64, seq: u64) -> Option<(Bytes, u64)> {
        let (media, hash, media_kind, init) = self.read_part_for_stream_id(stream_id, seq).await?;
        if let Some(init) = init {
            self.remember_stream_init(stream_id, init).await;
        }
        self.remember_media_kind(stream_id, media_kind).await;
        Some((media, hash))
    }

    /// Read one immutable cache slot without updating stream metadata. A
    /// response that combines many consecutive slots establishes metadata
    /// from its first slot once, rather than taking the global state write lock
    /// for every constituent 5 ms unit.
    async fn read_part_for_stream_id(
        &self,
        stream_id: u64,
        seq: u64,
    ) -> Option<(Bytes, u64, LiveMediaKind, Option<Bytes>)> {
        let (bytes, hash) = self
            .chunk_cache
            .get_for_stream_id(stream_id, seq as usize)
            .await?;
        decode_part_slot(stream_id, bytes, hash)
    }

    /// [`Self::get_part_for_stream_id`] for a stream that the caller
    /// resolved once to read many of its parts.
    async fn get_part_for_handle(&self, handle: StreamHandle, seq: u64) -> Option<(Bytes, u64)> {
        let stream_id = handle.stream_id();
        let (bytes, hash) = self
            .chunk_cache
            .get_for_handle(handle, usize::try_from(seq).ok()?)
            .await?;
        let (media, hash, media_kind, init) = decode_part_slot(stream_id, bytes, hash)?;
        if let Some(init) = init {
            self.remember_stream_init(stream_id, init).await;
        }
        self.remember_media_kind(stream_id, media_kind).await;
        Some((media, hash))
    }

    /// The source epoch that part `seq`'s slot carries (a canonical slot's
    /// key epoch), if its media is still `media`, the bytes the caller read
    /// from it (a slot replaced in between says nothing of them).
    async fn part_epoch_for_stream_id(&self, stream_id: u64, seq: u64, media: &Bytes) -> Option<u64> {
        let (bytes, _) = self
            .chunk_cache
            .get_for_stream_id(stream_id, usize::try_from(seq).ok()?)
            .await?;
        let epoch = mesh_slot_epoch(&bytes)?;
        let slot = LiveSlotPayload::decode_for_stream(bytes, stream_id);
        (slot.has_media() && slot.media() == *media).then_some(epoch)
    }

    async fn part_available_unix_us(&self, stream_id: u64, seq: u64) -> Option<u64> {
        self.part_times_unix_us(stream_id, seq)
            .await
            .map(|times| times.available_unix_us)
    }

    /// When the ChunkCache wrote the retained part. The cache stores the
    /// time before the part becomes readable, so it is there for a reader
    /// that the write woke, before this node has recorded the part.
    fn part_written_unix_us(&self, stream_id: u64, seq: u64) -> Option<u64> {
        self.chunk_cache
            .written_unix_us_for_stream_id(stream_id, usize::try_from(seq).ok()?)
    }

    /// When this cache had the part, when it wrote it, and when the
    /// contributor published it.
    ///
    /// A reader blocked on a part is woken by the cache write, which comes
    /// before this node records the part (on an edge, before the applied
    /// part reaches `observe_mesh_part`). The commit time then comes from the
    /// cache, and stands in for the time the cache had the part.
    async fn part_times_unix_us(&self, stream_id: u64, seq: u64) -> Option<PartTimes> {
        let written_unix_us = self.part_written_unix_us(stream_id, seq);
        self.part_times_written_at(stream_id, seq, written_unix_us)
            .await
    }

    /// [`Self::part_times_unix_us`] for a stream that the caller resolved
    /// once to read many of its parts.
    async fn part_times_for_handle(&self, handle: StreamHandle, seq: u64) -> Option<PartTimes> {
        let written_unix_us = usize::try_from(seq)
            .ok()
            .and_then(|slot| self.chunk_cache.written_unix_us_for_handle(handle, slot));
        self.part_times_written_at(handle.stream_id(), seq, written_unix_us)
            .await
    }

    async fn part_times_written_at(
        &self,
        stream_id: u64,
        seq: u64,
        written_unix_us: Option<u64>,
    ) -> Option<PartTimes> {
        let recorded = self
            .state
            .read()
            .await
            .stream_parts
            .get(&stream_id)
            .and_then(|parts| parts.get(&seq))
            .map(|part| PartTimes {
                available_unix_us: part.available_unix_us,
                published_unix_us: part.published_unix_us,
                committed_unix_us: part.committed_unix_us,
            });
        match recorded {
            Some(times) => Some(PartTimes {
                committed_unix_us: written_unix_us.or(times.committed_unix_us),
                ..times
            }),
            None => written_unix_us.map(|written_unix_us| PartTimes {
                available_unix_us: written_unix_us,
                published_unix_us: None,
                committed_unix_us: Some(written_unix_us),
            }),
        }
    }

    /// Stamp a part response with the time it is handed to the server, and
    /// journal the reply for the first few readers of the part.
    fn finish_part_response(
        &self,
        response: HandlerResponse,
        stream_id: u64,
        seq: u64,
        times: Option<PartTimes>,
    ) -> HandlerResponse {
        let reply_unix_us = now_unix_us();
        if let Some(journal) = self.hops() {
            journal.record_counted(
                HopEvent::new(HopStage::Reply, stream_id, seq, reply_unix_us),
                HOP_JOURNAL_REPLIES_PER_PART,
            );
        }
        response
            .with_part_available_unix_us(times.map(|times| times.available_unix_us))
            .with_part_published_unix_us(times.and_then(|times| times.published_unix_us))
            .with_part_committed_unix_us(times.and_then(|times| times.committed_unix_us))
            .with_part_reply_unix_us(reply_unix_us)
    }

    async fn next_part_after_for_stream_id(
        &self,
        stream_id: u64,
        after: Option<u64>,
        start_at_oldest: bool,
    ) -> Option<(u64, Bytes, u64)> {
        let (handle, last) = self.stream_position_for_id(stream_id).await?;
        if let Some(after) = after {
            let start = after.checked_add(1)?;
            if start as usize > last {
                return None;
            }
            for seq in start as usize..=last {
                if let Some((bytes, hash)) = self.chunk_cache.get_for_handle(handle, seq).await {
                    let slot = LiveSlotPayload::decode_for_stream(bytes, stream_id);
                    if slot.has_media() {
                        if let Some(init) = slot.init() {
                            self.remember_stream_init(stream_id, init).await;
                        }
                        self.remember_media_kind(stream_id, slot.media_kind()).await;
                        return Some((seq as u64, slot.media(), hash));
                    }
                }
            }
            return None;
        }

        let first = last.saturating_sub(self.window_parts.saturating_sub(1));
        let sequences: Vec<usize> = if start_at_oldest {
            (first..=last).collect()
        } else {
            (first..=last).rev().collect()
        };
        for seq in sequences {
            if let Some((bytes, hash)) = self.chunk_cache.get_for_handle(handle, seq).await {
                let slot = LiveSlotPayload::decode_for_stream(bytes, stream_id);
                if slot.has_media() {
                    if let Some(init) = slot.init() {
                        self.remember_stream_init(stream_id, init).await;
                    }
                    self.remember_media_kind(stream_id, slot.media_kind()).await;
                    return Some((seq as u64, slot.media(), hash));
                }
            }
        }
        None
    }

    async fn next_part_after_blocking_for_stream_id(
        &self,
        stream_id: u64,
        after: Option<u64>,
        start_at_oldest: bool,
    ) -> Option<(u64, Bytes, u64)> {
        let deadline = Instant::now() + Duration::from_millis(LLHLS_TAIL_WAIT_MS);
        let mut updates = self.part_updates.subscribe();
        loop {
            if let Some(part) = self
                .next_part_after_for_stream_id(stream_id, after, start_at_oldest)
                .await
            {
                return Some(part);
            }
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero()
                || tokio::time::timeout(remaining, updates.changed())
                    .await
                    .is_err()
            {
                return None;
            }
        }
    }

    /// Hold a playlist reload until the playlist holds the position that the
    /// reader asks for (`_HLS_msn`, `_HLS_part`).
    ///
    /// A position too far ahead of the playlist is refused at once, and a
    /// position that does not arrive within three target durations ends the
    /// wait: draft-pantos-hls-rfc8216bis section 6.2.5.2 asks for 400 and 503.
    async fn wait_for_hls_reload_position(
        &self,
        stream_id: u64,
        position: HlsReloadPosition,
    ) -> HlsReloadOutcome {
        let target_ms = self.target_duration_ms(stream_id).await;
        let deadline = Instant::now()
            + Duration::from_millis(target_ms.saturating_mul(3).max(HLS_PLAYLIST_WAIT_MS));
        let mut updates = self.part_updates.subscribe();
        loop {
            match self.hls_reload_position_state(stream_id, position).await {
                HlsReloadOutcome::TimedOut => {}
                outcome => return outcome,
            }
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero()
                || tokio::time::timeout(remaining, updates.changed())
                    .await
                    .is_err()
            {
                return HlsReloadOutcome::TimedOut;
            }
        }
    }

    /// Target duration of a stream in milliseconds: what its contributor
    /// declares, or the nominal segment of the node.
    async fn target_duration_ms(&self, stream_id: u64) -> u64 {
        let state = self.state.read().await;
        let nominal_us = self
            .nominal_part_us()
            .saturating_mul(self.parts_per_segment as u64);
        let target_us = state
            .stream_declared_us
            .get(&stream_id)
            .map(|(_, target_us)| u64::from(*target_us))
            .or_else(|| {
                state
                    .stream_max_segment_duration_us
                    .get(&stream_id)
                    .copied()
            })
            .unwrap_or(nominal_us);
        (target_us / 1_000).max(1_000)
    }

    #[cfg(test)]
    async fn hls_reload_position_available(
        &self,
        stream_id: u64,
        position: HlsReloadPosition,
    ) -> bool {
        self.hls_reload_position_state(stream_id, position).await == HlsReloadOutcome::Ready
    }

    /// Whether the playlist holds a position: `Ready`, not yet (`TimedOut`
    /// stands for "wait"), or `TooFarAhead`.
    async fn hls_reload_position_state(
        &self,
        stream_id: u64,
        position: HlsReloadPosition,
    ) -> HlsReloadOutcome {
        let ready = |ready: bool| {
            if ready {
                HlsReloadOutcome::Ready
            } else {
                HlsReloadOutcome::TimedOut
            }
        };
        let state = self.state.read().await;
        let Some(parts) = state.stream_parts.get(&stream_id) else {
            return HlsReloadOutcome::TimedOut;
        };
        let part_target_us = state.stream_part_target_us(stream_id);
        let keyframe_segments = parts.values().any(|part| part.fmp4_segment_id.is_some());
        let mut segment_parts = BTreeMap::<u64, usize>::new();
        for (sequence, observation) in parts {
            let segment = if keyframe_segments {
                let Some(segment) = observation.fmp4_segment_id else {
                    continue;
                };
                segment
            } else {
                sequence / self.parts_per_segment as u64
            };
            *segment_parts.entry(segment).or_default() += 1;
        }
        let Some((&first_segment, _)) = segment_parts.first_key_value() else {
            return HlsReloadOutcome::TimedOut;
        };
        let (&last_segment, &last_parts) = segment_parts.last_key_value().unwrap();
        if position.msn < first_segment || position.msn < last_segment {
            return HlsReloadOutcome::Ready;
        }
        // The last group is the segment that is still open, so the last whole
        // segment is the one before it. A reader may ask for the segment
        // after the open one, and no further.
        if position.msn > last_segment.saturating_add(1) {
            return HlsReloadOutcome::TooFarAhead;
        }
        // The advance part limit: three seconds of parts, or three parts.
        let advance_parts = if part_target_us < 1_000_000 {
            3_000_000_u64.div_ceil(part_target_us)
        } else {
            3
        };
        if let Some(part) = position.part {
            let ahead = if position.msn == last_segment {
                (part as u64).saturating_sub(last_parts as u64)
            } else {
                part as u64
            };
            if ahead >= advance_parts {
                return HlsReloadOutcome::TooFarAhead;
            }
        }
        let Some(part_count) = segment_parts.get(&position.msn).copied() else {
            return HlsReloadOutcome::TimedOut;
        };
        if let Some(part) = position.part {
            ready(part < part_count)
        } else if keyframe_segments {
            ready(position.msn < last_segment)
        } else {
            ready(part_count >= self.parts_per_segment)
        }
    }

    /// Whether a request for a part should wait for it. A part within three
    /// seconds of the newest part is on its way: a reader asks for the part
    /// that the playlist hints, and a reader on a far path asks several
    /// parts ahead. Any other part that the cache does not hold is unknown.
    async fn part_request_may_wait(&self, stream_id: u64, sequence: u64) -> bool {
        let Some((_, last)) = self.stream_position_for_id(stream_id).await else {
            // No part of the stream yet: a copy is on its way to this cache.
            return true;
        };
        let part_us = self.state.read().await.stream_part_target_us(stream_id);
        let ahead = PART_WAIT_MS
            .saturating_mul(1_000)
            .div_ceil(part_us)
            .saturating_add(4);
        let last = last as u64;
        if sequence > last {
            return sequence - last <= ahead;
        }
        // A part behind the newest one is a hole that a parent can fill while
        // it is inside the retained window.
        let window = self.window_parts_for(stream_id).await as u64;
        last - sequence <= window
    }

    async fn next_part_batch_after_blocking_for_stream_id(
        &self,
        stream_id: u64,
        after: Option<u64>,
        start_at_oldest: bool,
        part_count: usize,
    ) -> Option<(u64, u64, Bytes, Option<u64>)> {
        if part_count == 0 || part_count > MAX_LLHLS_TAIL_PARTS {
            return None;
        }
        let (start_sequence, first, first_hash) = self
            .next_part_after_blocking_for_stream_id(stream_id, after, start_at_oldest)
            .await?;
        if part_count == 1 {
            return Some((start_sequence, start_sequence, first, Some(first_hash)));
        }

        let end_sequence = start_sequence.checked_add(part_count as u64 - 1)?;
        // Waiting on the exact final sequence avoids a timer or polling loop. Once
        // it is committed, every earlier sequence in this small bounded range
        // must already be available in the cache.
        self.read_part_blocking_for_stream_id(stream_id, end_sequence)
            .await?;
        let cached_parts = self
            .chunk_cache
            .get_range_for_stream_id(stream_id, usize::try_from(start_sequence).ok()?, part_count)
            .await?;
        let mut body = BytesMut::with_capacity(first.len().saturating_mul(part_count));
        for (bytes, _hash) in cached_parts {
            let slot = LiveSlotPayload::decode_for_stream(bytes, stream_id);
            if !slot.has_media() {
                return None;
            }
            body.extend_from_slice(&slot.media());
        }
        Some((start_sequence, end_sequence, body.freeze(), None))
    }

    async fn next_part_bundle_after_blocking_for_stream_ids(
        &self,
        stream_ids: &[u64],
        start_sequence: u64,
        part_count: usize,
    ) -> Option<Bytes> {
        if stream_ids.is_empty() || stream_ids.len() > MAX_TAIL_BUNDLE_ENTRIES {
            return None;
        }
        let deadline = Instant::now() + Duration::from_millis(LLHLS_TAIL_WAIT_MS);
        let mut parts = Vec::with_capacity(stream_ids.len());
        // Exact wait registration always rechecks the cache, so tracks may
        // arrive in any order without requiring one heap-backed joined future
        // per track. One absolute deadline keeps the bundle all-or-nothing and
        // prevents sequential waits from extending the request budget.
        for &stream_id in stream_ids {
            let (start_sequence, end_sequence, payload, _etag) = self
                .exact_part_batch_until_for_stream_id(
                    stream_id,
                    start_sequence,
                    part_count,
                    deadline,
                )
                .await?;
            parts.push((stream_id, start_sequence, end_sequence, payload));
        }
        // Availability belongs to the immutable cache commit, so collect it
        // under one shared state lock after all media reads complete. Taking
        // one lock per track made an eight-track 5 ms response contend with
        // the ingress writer eight times at the H3 capacity boundary.
        let state = self.state.read().await;
        let entries = parts
            .into_iter()
            .map(
                |(stream_id, start_sequence, end_sequence, payload)| TailBundleEntry {
                    stream_id,
                    start_sequence,
                    end_sequence,
                    available_unix_us: state
                        .stream_parts
                        .get(&stream_id)
                        .and_then(|parts| parts.get(&end_sequence))
                        .map(|part| part.available_unix_us),
                    payload,
                },
            )
            .collect::<Vec<_>>();
        drop(state);
        encode_tail_bundle(&entries).ok()
    }

    async fn exact_part_batch_until_for_stream_id(
        &self,
        stream_id: u64,
        start_sequence: u64,
        part_count: usize,
        deadline: Instant,
    ) -> Option<(u64, u64, Bytes, Option<u64>)> {
        if part_count == 0 || part_count > MAX_LLHLS_TAIL_PARTS {
            return None;
        }
        let end_sequence = start_sequence.checked_add(part_count as u64 - 1)?;
        let final_part = self
            .read_part_until_for_stream_id(stream_id, end_sequence, deadline)
            .await?;
        if part_count == 1 {
            let (media, hash, _media_kind, _init) = final_part;
            return Some((start_sequence, end_sequence, media, Some(hash)));
        }

        let cached_parts = self
            .chunk_cache
            .get_range_for_stream_id(stream_id, usize::try_from(start_sequence).ok()?, part_count)
            .await?;
        let mut body = BytesMut::new();
        for (bytes, _hash) in cached_parts {
            let slot = LiveSlotPayload::decode_for_stream(bytes, stream_id);
            if !slot.has_media() {
                return None;
            }
            body.extend_from_slice(&slot.media());
        }
        Some((start_sequence, end_sequence, body.freeze(), None))
    }

    async fn get_part_blocking(&self, seq: u64) -> Option<(Bytes, u64)> {
        self.get_part_blocking_for_stream_id(self.stream_id, seq)
            .await
    }

    async fn get_part_blocking_for_stream_id(
        &self,
        stream_id: u64,
        seq: u64,
    ) -> Option<(Bytes, u64)> {
        let deadline = Instant::now() + Duration::from_millis(PART_WAIT_MS);
        self.get_part_until_for_stream_id(stream_id, seq, deadline)
            .await
    }

    async fn get_part_until_for_stream_id(
        &self,
        stream_id: u64,
        seq: u64,
        deadline: Instant,
    ) -> Option<(Bytes, u64)> {
        loop {
            if let Some((bytes, hash)) = self.get_part_for_stream_id(stream_id, seq).await {
                return Some((bytes, hash));
            }
            let waiter = self
                .chunk_cache
                .exact_part_waiter(stream_id, usize::try_from(seq).ok()?)?;
            let notified = waiter.notified();
            tokio::pin!(notified);
            notified.as_mut().enable();
            // Register before rechecking the cache so a commit between the
            // first lookup and this waiter cannot be missed.
            if let Some((bytes, hash)) = self.get_part_for_stream_id(stream_id, seq).await {
                return Some((bytes, hash));
            }
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero()
                || tokio::time::timeout(remaining, &mut notified)
                    .await
                    .is_err()
            {
                return None;
            }
        }
    }

    async fn read_part_blocking_for_stream_id(
        &self,
        stream_id: u64,
        seq: u64,
    ) -> Option<(Bytes, u64, LiveMediaKind, Option<Bytes>)> {
        let deadline = Instant::now() + Duration::from_millis(PART_WAIT_MS);
        self.read_part_until_for_stream_id(stream_id, seq, deadline)
            .await
    }

    async fn read_part_until_for_stream_id(
        &self,
        stream_id: u64,
        seq: u64,
        deadline: Instant,
    ) -> Option<(Bytes, u64, LiveMediaKind, Option<Bytes>)> {
        loop {
            if let Some(part) = self.read_part_for_stream_id(stream_id, seq).await {
                return Some(part);
            }
            let waiter = self
                .chunk_cache
                .exact_part_waiter(stream_id, usize::try_from(seq).ok()?)?;
            let notified = waiter.notified();
            tokio::pin!(notified);
            notified.as_mut().enable();
            // Register before rechecking the cache so a commit between the
            // first lookup and this waiter cannot be missed.
            if let Some(part) = self.read_part_for_stream_id(stream_id, seq).await {
                return Some(part);
            }
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero()
                || tokio::time::timeout(remaining, &mut notified)
                    .await
                    .is_err()
            {
                return None;
            }
        }
    }

    async fn get_segment(&self, segment: u64) -> Option<Bytes> {
        self.get_segment_for_stream_id(self.stream_id, segment)
            .await
    }

    async fn get_segment_for_stream_id(&self, stream_id: u64, segment: u64) -> Option<Bytes> {
        let keyframe_aligned_sequences = {
            let state = self.state.read().await;
            match state.stream_parts.get(&stream_id) {
                Some(parts) if parts.values().any(|part| part.fmp4_segment_id.is_some()) => {
                    let declared_part_us = state
                        .stream_declared_us
                        .get(&stream_id)
                        .map_or(0, |(part_us, _)| *part_us);
                    let ended_short = parts
                        .iter()
                        .filter(|(_sequence, part)| part.fmp4_segment_id == Some(segment))
                        .max_by_key(|(sequence, _part)| **sequence)
                        .is_some_and(|(_sequence, part)| {
                            part.stamped_part.is_some()
                                && part.duration_us.is_some_and(|duration_us| {
                                    part_ends_segment_short(duration_us, declared_part_us)
                                })
                        });
                    let segment_is_closed = ended_short
                        || parts.values().any(|part| {
                            part.fmp4_segment_id
                                .is_some_and(|segment_id| segment_id > segment)
                        });
                    // A segment is whole when its first part is here: the key
                    // frame of a stream without stamps, or the part that the
                    // contributor stamped with index 0.
                    let sequences = parts
                        .iter()
                        .filter_map(|(sequence, part)| {
                            (part.fmp4_segment_id == Some(segment)).then_some((
                                *sequence,
                                part.stamped_part.map_or(part.keyframe, |index| index == 0),
                            ))
                        })
                        .collect::<Vec<_>>();
                    if !segment_is_closed
                        || !sequences
                            .first()
                            .is_some_and(|(_sequence, keyframe)| *keyframe)
                    {
                        return None;
                    }
                    Some(
                        sequences
                            .into_iter()
                            .map(|(sequence, _keyframe)| sequence)
                            .collect::<Vec<_>>(),
                    )
                }
                _ => None,
            }
        };
        if let Some(sequences) = keyframe_aligned_sequences {
            let mut out = Vec::new();
            for sequence in sequences {
                let (bytes, _) = self
                    .get_part_blocking_for_stream_id(stream_id, sequence)
                    .await?;
                out.extend_from_slice(&bytes);
            }
            return Some(Bytes::from(out));
        }

        let first_part = segment.checked_mul(self.parts_per_segment as u64)?;
        let mut out = Vec::new();
        for offset in 0..self.parts_per_segment {
            let seq = first_part + offset as u64;
            let (bytes, _) = self.get_part_blocking_for_stream_id(stream_id, seq).await?;
            out.extend_from_slice(&bytes);
        }
        Some(Bytes::from(out))
    }

    async fn stats(&self, mesh: &CacheMeshHandle) -> StatsSnapshot {
        let now_ms = now_unix_ms();
        let state = self.state.read().await;
        let datagrams_received = state.datagrams_received;
        let bytes_received = state.bytes_received;
        let current_part_bytes = state.current.len();
        let latest_local_part = state.last_committed_seq;
        let latest_local_part_bytes = state.last_committed_bytes;
        let latest_local_part_duration_us = state.last_committed_duration_us;
        let latest_local_part_duration_ms = latest_local_part_duration_us
            .map(|duration_us| duration_us.saturating_add(500) / 1_000);
        let subscription_base_object = state
            .stream_subscription_base_object
            .get(&self.stream_id)
            .copied();
        let canonical_epoch = state.stream_canonical_epoch.get(&self.stream_id).copied();
        let canonical_epoch_activation_delay_us = state
            .stream_canonical_epoch_activation_delay_us
            .get(&self.stream_id)
            .copied();
        let head_object = state
            .stream_latest_canonical_object
            .get(&self.stream_id)
            .copied();
        let latest_local_part_age_ms = state
            .last_committed_unix_ms
            .map(|last| now_ms.saturating_sub(last));
        let last_ingest_age_ms = state
            .last_ingest_unix_ms
            .map(|last| now_ms.saturating_sub(last));
        drop(state);

        // `ChunkCache::last` is the published contiguous watermark and always
        // names a readable slot. Telemetry must not rescan the retained media
        // window on the latency-sensitive runtime merely to rediscover it.
        let latest_mesh_part = self.stream_position().await.map(|(_, last)| last as u64);
        let contiguous_object = latest_mesh_part;
        let gap_count = self
            .canonical_gap_count(self.stream_id, subscription_base_object, head_object)
            .await;

        StatsSnapshot {
            stream_id: self.stream_id,
            stream_id_text: stream_id_text(self.stream_id),
            part_target_ms: self.nominal_part_us().saturating_add(500) / 1_000,
            part_target_us: self.nominal_part_us(),
            parts_per_segment: self.parts_per_segment,
            window_parts: self.window_parts,
            datagrams_received,
            bytes_received,
            current_part_bytes,
            latest_local_part,
            latest_local_part_bytes,
            latest_local_part_duration_ms,
            latest_local_part_duration_us,
            latest_mesh_part,
            canonical_epoch,
            canonical_epoch_activation_delay_us,
            contiguous_object,
            head_object,
            gap_count,
            mesh_peers: mesh
                .peers()
                .await
                .into_iter()
                .map(|addr| addr.to_string())
                .collect(),
            latest_local_part_age_ms,
            last_ingest_age_ms,
        }
    }

    async fn canonical_gap_count(
        &self,
        stream_id: u64,
        subscription_base_object: Option<u64>,
        head_object: Option<u64>,
    ) -> Option<u64> {
        let base = subscription_base_object?;
        let head = head_object?;
        if self
            .stream_position_for_id(stream_id)
            .await
            .is_some_and(|(_, contiguous)| contiguous as u64 >= head)
        {
            return Some(0);
        }
        let retained_start = head
            .saturating_sub(self.window_parts.saturating_sub(1) as u64)
            .max(base);
        let handle = self.chunk_cache.resolve_stream(stream_id);
        let mut gaps = 0_u64;
        for object in retained_start..=head {
            let slot = usize::try_from(object).ok()?;
            let present = match handle {
                Some(handle) => self
                    .chunk_cache
                    .get_for_handle(handle, slot)
                    .await
                    .is_some(),
                None => false,
            };
            if !present {
                gaps = gaps.saturating_add(1);
            }
        }
        Some(gaps)
    }

    async fn estimated_storage_bytes(&self) -> u64 {
        self.state
            .read()
            .await
            .stream_retained_bytes
            .values()
            .copied()
            .fold(0_u64, u64::saturating_add)
    }

    async fn estimated_storage_bytes_for_stream(&self, stream_id: u64) -> u64 {
        self.state
            .read()
            .await
            .stream_retained_bytes
            .get(&stream_id)
            .copied()
            .unwrap_or_default()
    }

    async fn active_stream_ids(&self) -> Vec<u64> {
        let mut stream_ids = self
            .state
            .read()
            .await
            .stream_parts
            .iter()
            .filter_map(|(stream_id, parts)| (!parts.is_empty()).then_some(*stream_id))
            .collect::<Vec<_>>();
        stream_ids.sort_unstable();
        stream_ids
    }

    async fn stream_is_locally_fresh(&self, stream_id: u64) -> bool {
        let stale_after_ms = stream_stale_threshold_ms(self.nominal_part_us(), self.window_parts);
        let canonical_head = {
            let state = self.state.read().await;
            let Some(last_ingest_unix_ms) = state.stream_last_ingest_unix_ms.get(&stream_id) else {
                return false;
            };
            if now_unix_ms().saturating_sub(*last_ingest_unix_ms) > stale_after_ms {
                return false;
            }
            state
                .stream_latest_canonical_object
                .get(&stream_id)
                .copied()
        };
        match canonical_head {
            None => true,
            Some(head) => self
                .stream_position_for_id(stream_id)
                .await
                .is_some_and(|(_, contiguous)| contiguous as u64 >= head),
        }
    }

    async fn streams_are_locally_fresh(&self, stream_ids: &[u64]) -> bool {
        if stream_ids.is_empty() {
            return false;
        }
        let stale_after_ms = stream_stale_threshold_ms(self.nominal_part_us(), self.window_parts);
        let now_ms = now_unix_ms();
        let state = self.state.read().await;
        stream_ids.iter().all(|stream_id| {
            state
                .stream_last_ingest_unix_ms
                .get(stream_id)
                .is_some_and(|last_ingest_unix_ms| {
                    now_ms.saturating_sub(*last_ingest_unix_ms) <= stale_after_ms
                })
                && state
                    .stream_latest_canonical_object
                    .get(stream_id)
                    .is_none_or(|head| {
                        state
                            .stream_parts
                            .get(stream_id)
                            .and_then(BTreeMap::last_key_value)
                            .is_some_and(|(contiguous, _)| contiguous >= head)
                    })
        })
    }

    async fn stream_telemetry(
        &self,
        node_id: &str,
        default_stats: &StatsSnapshot,
    ) -> Vec<StreamTelemetry> {
        let mut streams = Vec::new();
        let now_ms = now_unix_ms();
        let nominal_part_us = self.nominal_part_us();
        let (
            canonical_epochs,
            canonical_epoch_activation_delays_us,
            subscription_bases,
            canonical_heads,
            last_ingests,
            retained_streams,
        ) = {
            let state = self.state.read().await;
            (
                state.stream_canonical_epoch.clone(),
                state.stream_canonical_epoch_activation_delay_us.clone(),
                state.stream_subscription_base_object.clone(),
                state.stream_latest_canonical_object.clone(),
                state.stream_last_ingest_unix_ms.clone(),
                state.retained_stream_summaries(nominal_part_us, self.min_bitrate_window_ms()),
            )
        };
        for (stream_id, retained) in retained_streams {
            let Some(handle) = self.chunk_cache.resolve_stream(stream_id) else {
                continue;
            };
            let Some(last) = self.chunk_cache.last_for_handle(handle) else {
                continue;
            };
            let latest_part = last as u64;
            let latest_part_bytes = if retained.latest_sequence == Some(latest_part) {
                retained.latest_bytes
            } else {
                self.chunk_cache
                    .get_for_handle(handle, last)
                    .await
                    .map(|(payload, _)| payload.len())
            };
            let bytes_received = retained.retained_bytes;
            let datagrams_received = retained.retained_parts;
            let is_default_stream = stream_id == self.stream_id;
            let contiguous_object = if is_default_stream {
                default_stats.contiguous_object
            } else {
                Some(latest_part)
            };
            let canonical_epoch = if is_default_stream {
                default_stats.canonical_epoch
            } else {
                canonical_epochs.get(&stream_id).copied()
            };
            let canonical_epoch_activation_delay_us = if is_default_stream {
                default_stats.canonical_epoch_activation_delay_us
            } else {
                canonical_epoch_activation_delays_us
                    .get(&stream_id)
                    .copied()
            };
            let head_object = if is_default_stream {
                default_stats.head_object
            } else {
                canonical_heads.get(&stream_id).copied()
            };
            let gap_count = if is_default_stream {
                default_stats.gap_count
            } else {
                self.canonical_gap_count(
                    stream_id,
                    subscription_bases.get(&stream_id).copied(),
                    head_object,
                )
                .await
            };
            streams.push(StreamTelemetry {
                node_id: node_id.to_string(),
                stream_id,
                stream_id_text: stream_id_text(stream_id),
                latest_local_part: if is_default_stream {
                    default_stats.latest_local_part
                } else {
                    None
                },
                latest_local_part_bytes: if is_default_stream {
                    default_stats.latest_local_part_bytes.or(latest_part_bytes)
                } else {
                    latest_part_bytes
                },
                latest_local_part_duration_ms: if is_default_stream {
                    default_stats.latest_local_part_duration_ms
                } else {
                    None
                },
                latest_local_part_age_ms: if is_default_stream {
                    default_stats.latest_local_part_age_ms
                } else {
                    None
                },
                latest_mesh_part: Some(latest_part),
                canonical_epoch,
                canonical_epoch_activation_delay_us,
                contiguous_object,
                head_object,
                gap_count,
                bytes_received: if is_default_stream {
                    default_stats.bytes_received.max(bytes_received)
                } else {
                    bytes_received
                },
                datagrams_received: if is_default_stream {
                    default_stats.datagrams_received.max(datagrams_received)
                } else {
                    datagrams_received
                },
                last_ingest_age_ms: if is_default_stream {
                    default_stats.last_ingest_age_ms
                } else {
                    last_ingests
                        .get(&stream_id)
                        .map(|last| now_ms.saturating_sub(*last))
                },
                stale_threshold_ms: Some(stream_stale_threshold_ms(
                    default_stats.nominal_part_us(),
                    default_stats.window_parts,
                )),
                mesh_lag_parts: None,
                part_target_us: retained.part_us.or(Some(default_stats.nominal_part_us())),
                bitrate_bps: retained.bitrate_bps,
            });
        }
        streams.sort_by_key(|stream| stream.stream_id);
        streams
    }

    /// The first missing slot among the newest `window_parts` slots of a
    /// stream, or `None` when those slots are all stored.
    ///
    /// A cache-mesh edge uses this for its replica request. A distributor
    /// that never recovers an object skips it after the canonical gap hold, so
    /// an edge can hold a slot that no parent will ever supply. The parent
    /// answers a replica request with every slot from the requested one to its
    /// newest, so a request that starts at such an old hole makes each parent
    /// send the retained window again, once a second, until the hole leaves
    /// the window. That flood overflows the edge and makes new holes.
    async fn recent_replica_request_from_slot(
        &self,
        stream_id: u64,
        window_parts: usize,
    ) -> Option<usize> {
        let handle = self.chunk_cache.resolve_stream(stream_id)?;
        let last = self.chunk_cache.last_for_handle(handle)?;
        let start = last
            .saturating_sub(window_parts.saturating_sub(1))
            .max(self.chunk_cache.retained_start(last));
        for seq in start..=last {
            let present = self
                .chunk_cache
                .get_for_handle(handle, seq)
                .await
                .map(|(bytes, hash)| hash != 0 || !bytes.is_empty())
                .unwrap_or(false);
            if !present {
                return Some(seq);
            }
        }
        None
    }

    /// Whether this node stores any slot of the stream.
    async fn has_stream_slots(&self, stream_id: u64) -> bool {
        match self.chunk_cache.resolve_stream(stream_id) {
            Some(handle) => self.chunk_cache.last_for_handle(handle).is_some(),
            None => false,
        }
    }

    async fn replica_request_from_slot(&self, stream_id: u64) -> usize {
        let Some(handle) = self.chunk_cache.resolve_stream(stream_id) else {
            return 0;
        };
        let Some(last) = self.chunk_cache.last_for_handle(handle) else {
            return 0;
        };

        let retained_start = self.chunk_cache.retained_start(last);
        let mut latest_present = None;
        for seq in retained_start..=last {
            let present = self
                .chunk_cache
                .get_for_handle(handle, seq)
                .await
                .map(|(bytes, hash)| hash != 0 || !bytes.is_empty())
                .unwrap_or(false);
            if present {
                latest_present = Some(seq);
            } else {
                return seq;
            }
        }
        latest_present
            .map(|seq| seq.saturating_add(1))
            .unwrap_or(retained_start)
    }

    async fn mesh_snapshot(
        &self,
        mesh: &CacheMeshHandle,
        mut node: MeshNode,
        policy: ReplicationPolicy,
        control: &ControlPlane,
    ) -> MeshSnapshot {
        let stats = self.stats(mesh).await;
        let streams = self.stream_telemetry(&node.node_id, &stats).await;
        node.used_storage_bytes = self
            .estimated_storage_bytes()
            .await
            .min(node.total_storage_bytes);
        node.active_streams = streams.len() as u64;
        node.contributor_streams = streams
            .iter()
            .filter(|stream| stream.latest_local_part.is_some())
            .count() as u64;

        MeshSnapshot {
            updated_unix_ms: now_unix_ms(),
            node,
            mesh_addr: Some(mesh.local_addr().to_string()),
            edge_service: None,
            relay_session: self.relay_ingress_snapshot(),
            link_observations: self.link_observations(),
            peers: stats
                .mesh_peers
                .iter()
                .map(|addr| PeerSnapshot {
                    addr: addr.clone(),
                    state: "discovered".into(),
                })
                .collect(),
            stream: stats,
            streams,
            replication_policy: policy,
            recent_commands: control.recent().await,
        }
    }
}

#[derive(Clone, Copy, Debug)]
struct RetainedPartObservation {
    bytes: usize,
    available_unix_us: u64,
    /// When the contributor published the part, from the part itself.
    published_unix_us: Option<u64>,
    /// When this node wrote the part into its ChunkCache.
    committed_unix_us: Option<u64>,
    /// Duration of the part in microseconds.
    duration_us: Option<u32>,
    keyframe: bool,
    /// Media Sequence Number of the segment of the part: the stamp of the
    /// contributor, or a number that this cache derived for a stream
    /// without stamps.
    fmp4_segment_id: Option<u64>,
    /// Index of the part in its segment, from the stamp of the contributor.
    stamped_part: Option<u32>,
}

#[derive(Clone, Copy, Debug, Default)]
struct RetainedStreamSummary {
    latest_sequence: Option<u64>,
    latest_bytes: Option<usize>,
    retained_bytes: u64,
    retained_parts: u64,
    bitrate_bps: Option<u64>,
    /// The part of the stream in microseconds.
    part_us: Option<u64>,
}

/// The playlist entry that one cached part describes for itself.
#[derive(Clone, Debug)]
struct MeshPartRecord {
    media_kind: LiveMediaKind,
    init: Option<Bytes>,
    /// Duration of the part in microseconds.
    duration_us: Option<u32>,
    keyframe: bool,
    /// The part belongs to a stream whose segments start at key frames.
    keyframe_segments: bool,
    published_unix_us: Option<u64>,
    epoch: Option<u64>,
    stamp: Option<PartStamp>,
}

/// A PL1 (A 2.7): the epoch of the origin that made a cached part, for the
/// cache mesh's first-copy rule (`CacheMeshConfig::with_slot_epoch`). It is
/// the key epoch of a canonical slot's media object, as
/// [`MeshPartRecord::from_slot`] reads it, taken from the envelope's header
/// without decoding the object: the mesh asks on every write over an
/// occupied slot, under the slot's lock, and a 4K part is hundreds of kB.
/// `None` for any other slot, which a parent's part then replaces as before.
fn mesh_slot_epoch(bytes: &[u8]) -> Option<u64> {
    if !bytes.starts_with(&CANONICAL_LIVE_SLOT_MAGIC[..]) {
        return None;
    }
    let envelope = bytes.get(CANONICAL_LIVE_SLOT_HEADER_LEN..)?;
    if envelope.get(..4)? != media_object::WIRE_MAGIC
        || envelope.get(4..6)? != media_object::WIRE_VERSION.to_be_bytes()
    {
        return None;
    }
    // The 12-byte header; kind, key frame and a reserved u16; then the key:
    // tenant, stream and track (each a u16 length and its bytes), then the
    // epoch, all big-endian.
    let mut at = 16;
    for _ in 0..3 {
        let len = u16::from_be_bytes(envelope.get(at..at + 2)?.try_into().ok()?);
        at += 2 + usize::from(len);
    }
    Some(u64::from_be_bytes(envelope.get(at..at + 8)?.try_into().ok()?))
}

impl MeshPartRecord {
    fn from_slot(bytes: &Bytes, stream_id: u64) -> Option<Self> {
        let slot = LiveSlotPayload::decode_for_stream(bytes.clone(), stream_id);
        if !slot.has_media() {
            return None;
        }
        let media_kind = slot.media_kind();
        let init = slot.init();
        if !bytes.starts_with(CANONICAL_LIVE_SLOT_MAGIC) {
            return Some(Self {
                media_kind,
                init,
                duration_us: None,
                keyframe: false,
                keyframe_segments: false,
                published_unix_us: None,
                epoch: None,
                stamp: None,
            });
        }
        // A canonical slot holds the complete media object behind a fixed
        // index. The object names its own duration, key frame and times.
        let object = media_object::decode(bytes.get(CANONICAL_LIVE_SLOT_HEADER_LEN..)?).ok()?;
        Some(Self {
            media_kind,
            init,
            duration_us: object_duration_us(&object),
            keyframe: object.is_keyframe(),
            keyframe_segments: media_kind == LiveMediaKind::Fmp4,
            published_unix_us: object_published_unix_us(&object),
            epoch: Some(object.key().epoch()),
            stamp: object_part_stamp(&object),
        })
    }
}

/// The place of a part in the Media Playlist of its stream, as the
/// contributor stamped it on the media object.
///
/// A cache that numbers segments from the parts it happens to hold numbers
/// them differently from a cache that joined the stream at another moment.
/// With the stamp every cache writes the same Media Sequence Numbers, the
/// same part target and the same target duration.
/// How a blocking playlist reload ended.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HlsReloadOutcome {
    /// The playlist holds the position.
    Ready,
    /// The position did not arrive in time.
    TimedOut,
    /// The position is further ahead than a reader may ask for.
    TooFarAhead,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PartStamp {
    /// Media Sequence Number of the segment of the part.
    msn: u64,
    /// Index of the part in its segment.
    part: u32,
    /// Longest part of the stream, in microseconds.
    part_target_us: u32,
    /// Longest segment of the stream so far, in microseconds.
    target_duration_us: u32,
}

fn object_metadata_number<T: std::str::FromStr>(object: &MediaObject, key: &str) -> Option<T> {
    std::str::from_utf8(object.metadata().get(key)?)
        .ok()?
        .parse()
        .ok()
}

/// A time of the object metadata in microseconds: the exact `<name>-us` key
/// that a current contributor writes, else the whole-millisecond
/// `<name>-ms` key of an older one. Zero is no value.
fn object_metadata_us(object: &MediaObject, us_key: &str, ms_key: &str) -> Option<u32> {
    object_metadata_number::<u32>(object, us_key)
        .filter(|us| *us > 0)
        .or_else(|| {
            object_metadata_number::<u32>(object, ms_key)
                .filter(|ms| *ms > 0)
                .map(|ms| ms.saturating_mul(1_000))
        })
}

/// Duration of a media object in microseconds: `duration-us`, else
/// `duration-samples` at `sample-rate` (rounded to the microsecond), else
/// `duration-ms`.
fn object_duration_us(object: &MediaObject) -> Option<u32> {
    object_metadata_number::<u32>(object, "duration-us")
        .filter(|us| *us > 0)
        .or_else(|| {
            let samples = object_metadata_number::<u64>(object, "duration-samples")?;
            let rate =
                object_metadata_number::<u64>(object, "sample-rate").filter(|rate| *rate > 0)?;
            let us = samples.saturating_mul(1_000_000).saturating_add(rate / 2) / rate;
            u32::try_from(us).ok().filter(|us| *us > 0)
        })
        .or_else(|| {
            object_metadata_number::<u32>(object, "duration-ms")
                .filter(|ms| *ms > 0)
                .map(|ms| ms.saturating_mul(1_000))
        })
}

fn object_part_stamp(object: &MediaObject) -> Option<PartStamp> {
    Some(PartStamp {
        msn: object_metadata_number(object, "hls-msn")?,
        part: object_metadata_number(object, "hls-part")?,
        part_target_us: object_metadata_us(object, "hls-part-target-us", "hls-part-target-ms")?,
        target_duration_us: object_metadata_us(
            object,
            "hls-target-duration-us",
            "hls-target-duration-ms",
        )?,
    })
}

/// When the contributor published a media object, in Unix microseconds.
fn object_published_unix_us(object: &MediaObject) -> Option<u64> {
    object
        .stage_timestamps()
        .iter()
        .find(|timestamp| timestamp.stage() == Stage::Published)
        .and_then(|timestamp| u64::try_from(timestamp.timestamp().unix_time_ns()).ok())
        .map(|published_ns| published_ns / 1_000)
        .filter(|published_us| *published_us > 0)
}

/// One stream as the cache holds it, for `GET /api/node`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct StreamHolding {
    stream_id: u64,
    ingest_unix_ms: Option<u64>,
    head_part: Option<u64>,
    /// When the newest part was written here (Unix µs).
    head_written_unix_us: Option<u64>,
    first_part: Option<u64>,
    window_parts: u64,
    /// The parts the stream's window holds at most.
    window_limit: u64,
}

struct LiveState {
    process_started_unix_us: u64,
    current: Vec<u8>,
    current_started: Instant,
    current_started_unix_ms: u64,
    next_seq: u64,
    datagrams_received: u64,
    bytes_received: u64,
    last_ingest_unix_ms: Option<u64>,
    last_committed_seq: Option<u64>,
    last_committed_unix_ms: Option<u64>,
    last_committed_bytes: Option<usize>,
    last_committed_duration_us: Option<u64>,
    stream_next_seq: HashMap<u64, u64>,
    stream_canonical_epoch: HashMap<u64, u64>,
    stream_canonical_epoch_activation_delay_us: HashMap<u64, u64>,
    stream_subscription_base_object: HashMap<u64, u64>,
    stream_latest_canonical_object: HashMap<u64, u64>,
    stream_last_ingest_unix_ms: HashMap<u64, u64>,
    stream_parts: HashMap<u64, BTreeMap<u64, RetainedPartObservation>>,
    /// Segment number of each key-frame part of a stream, by part sequence.
    stream_keyframe_segments: HashMap<u64, BTreeMap<u64, u64>>,
    /// Parts in a nominal segment. It seeds the segment number of the first
    /// key frame that a cache sees, so caches that join a stream at different
    /// times number its segments alike when the key-frame interval is nominal.
    /// Zero starts at segment zero.
    segment_seed_parts: u64,
    /// Nominal part duration of the node in microseconds, which sizes the
    /// cache ring. Zero gives every stream the configured window in parts.
    nominal_part_us: u64,
    /// Slots of the cache ring of one playlist. Zero is four configured
    /// windows, the ring of a node that does not size it for short parts.
    ring_parts: usize,
    stream_retained_bytes: HashMap<u64, u64>,
    /// Longest part of each stream in microseconds.
    stream_max_part_duration_us: HashMap<u64, u32>,
    /// Longest whole segment of each stream in microseconds.
    stream_max_segment_duration_us: HashMap<u64, u64>,
    /// Part target and target duration that the contributor declares for a
    /// stream, in microseconds, from the stamps of its parts.
    stream_declared_us: HashMap<u64, (u32, u32)>,
    /// First segment that this cache has listed in the playlist of a stream.
    /// A new copy is filled newest part first, and the playlist must not
    /// grow at its front: a Media Sequence Number never goes down.
    stream_playlist_floor: HashMap<u64, u64>,
    /// Newest slot of a stream that was searched for an initialization
    /// section and held none.
    stream_init_scanned: HashMap<u64, usize>,
    stream_inits: HashMap<u64, Bytes>,
    stream_media_kinds: HashMap<u64, LiveMediaKind>,
}

impl LiveState {
    fn new() -> Self {
        let now = Instant::now();
        Self {
            process_started_unix_us: now_unix_us(),
            current: Vec::new(),
            current_started: now,
            current_started_unix_ms: now_unix_ms(),
            next_seq: 0,
            datagrams_received: 0,
            bytes_received: 0,
            last_ingest_unix_ms: None,
            last_committed_seq: None,
            last_committed_unix_ms: None,
            last_committed_bytes: None,
            last_committed_duration_us: None,
            stream_next_seq: HashMap::new(),
            stream_canonical_epoch: HashMap::new(),
            stream_canonical_epoch_activation_delay_us: HashMap::new(),
            stream_subscription_base_object: HashMap::new(),
            stream_latest_canonical_object: HashMap::new(),
            stream_last_ingest_unix_ms: HashMap::new(),
            stream_parts: HashMap::new(),
            stream_keyframe_segments: HashMap::new(),
            segment_seed_parts: 0,
            nominal_part_us: 0,
            ring_parts: 0,
            stream_retained_bytes: HashMap::new(),
            stream_max_part_duration_us: HashMap::new(),
            stream_max_segment_duration_us: HashMap::new(),
            stream_declared_us: HashMap::new(),
            stream_playlist_floor: HashMap::new(),
            stream_init_scanned: HashMap::new(),
            stream_inits: HashMap::new(),
            stream_media_kinds: HashMap::new(),
        }
    }

    fn next_stream_seq(&mut self, stream_id: u64) -> u64 {
        let next = self.stream_next_seq.entry(stream_id).or_insert(0);
        let seq = *next;
        *next = next.saturating_add(1);
        seq
    }

    fn observe_stream_seq(&mut self, stream_id: u64, sequence: u64) {
        let next = self.stream_next_seq.entry(stream_id).or_insert(0);
        *next = (*next).max(sequence.saturating_add(1));
    }

    #[allow(clippy::too_many_arguments)]
    fn record_part_available(
        &mut self,
        stream_id: u64,
        sequence: u64,
        bytes: usize,
        available_unix_us: u64,
        duration_us: Option<u32>,
        keyframe: bool,
        keyframe_segments: bool,
        stamp: Option<PartStamp>,
        window_parts: usize,
    ) {
        if let Some(stamp) = stamp {
            // The contributor only raises what it declares.
            let declared = self.stream_declared_us.entry(stream_id).or_insert((0, 0));
            declared.0 = declared.0.max(stamp.part_target_us);
            declared.1 = declared.1.max(stamp.target_duration_us);
        }
        if let Some(duration_us) = duration_us {
            self.stream_max_part_duration_us
                .entry(stream_id)
                .and_modify(|maximum| *maximum = (*maximum).max(duration_us))
                .or_insert(duration_us);
        }
        // The record of a part outlives its place in the playlist, so that a
        // segment that has just left the playlist can still be put together.
        let window_parts = if stamp.is_some() || self.stream_declared_us.contains_key(&stream_id) {
            self.stream_retained_parts(stream_id, window_parts)
        } else {
            self.stream_window_parts(stream_id, window_parts)
        };
        let existing = self
            .stream_parts
            .get(&stream_id)
            .and_then(|parts| parts.get(&sequence))
            .copied();
        let fmp4_segment_id = if let Some(stamp) = stamp {
            Some(stamp.msn)
        } else if let Some(existing) = existing {
            existing.fmp4_segment_id
        } else if keyframe_segments {
            self.assign_fmp4_segment(stream_id, sequence, keyframe)
        } else {
            None
        };
        let derive_segments = keyframe_segments && stamp.is_none();
        let next_keyframe = (derive_segments && keyframe && existing.is_none()).then(|| {
            self.stream_keyframe_segments
                .get(&stream_id)
                .and_then(|keyframes| {
                    keyframes
                        .range((
                            std::ops::Bound::Excluded(sequence),
                            std::ops::Bound::Unbounded,
                        ))
                        .next()
                        .map(|(next, _)| *next)
                })
                .unwrap_or(u64::MAX)
        });
        let (inserted_bytes, removed_bytes) = {
            let parts = self.stream_parts.entry(stream_id).or_default();
            let inserted_bytes =
                if let std::collections::btree_map::Entry::Vacant(entry) = parts.entry(sequence) {
                    entry.insert(RetainedPartObservation {
                        bytes,
                        available_unix_us,
                        published_unix_us: None,
                        committed_unix_us: None,
                        duration_us,
                        keyframe,
                        fmp4_segment_id,
                        stamped_part: stamp.map(|stamp| stamp.part),
                    });
                    bytes as u64
                } else {
                    0
                };
            if let Some(next_keyframe) = next_keyframe {
                // Parts can arrive before their key frame, for example when a
                // new copy is warmed newest part first. They belong to the
                // segment of this key frame.
                for (_, part) in parts.range_mut((
                    std::ops::Bound::Excluded(sequence),
                    std::ops::Bound::Excluded(next_keyframe),
                )) {
                    if !part.keyframe {
                        part.fmp4_segment_id = fmp4_segment_id;
                    }
                }
            }
            let retention_head = parts
                .last_key_value()
                .map(|(retained_sequence, _)| *retained_sequence)
                .unwrap_or(sequence);
            let oldest_retained =
                retention_head.saturating_sub(window_parts.max(1).saturating_sub(1) as u64);
            let mut removed_bytes = 0_u64;
            while parts
                .first_key_value()
                .is_some_and(|(retained_sequence, _)| *retained_sequence < oldest_retained)
            {
                if let Some((_, removed)) = parts.pop_first() {
                    removed_bytes = removed_bytes.saturating_add(removed.bytes as u64);
                }
            }
            if let Some(keyframes) = self.stream_keyframe_segments.get_mut(&stream_id) {
                // Keep the key frame that the oldest retained part belongs to.
                if let Some(floor) = keyframes
                    .range(..=oldest_retained)
                    .next_back()
                    .map(|(keyframe_sequence, _)| *keyframe_sequence)
                {
                    *keyframes = keyframes.split_off(&floor);
                }
            }
            (inserted_bytes, removed_bytes)
        };
        let retained_bytes = self.stream_retained_bytes.entry(stream_id).or_default();
        *retained_bytes = retained_bytes
            .saturating_add(inserted_bytes)
            .saturating_sub(removed_bytes);
    }

    /// Segment number of a part of a stream whose segments start at key
    /// frames, or `None` while the key frame of the part is not known.
    ///
    /// Segment numbers must be consecutive, and they must not depend on the
    /// order in which parts arrive: a live copy receives parts oldest first, a
    /// warming copy newest first, and a repaired hole in any order.
    ///
    /// A key frame that is joined to a numbered key frame by stored parts is
    /// its direct neighbour and takes the next or the previous number. A key
    /// frame behind a hole takes its number from the distance in parts, at
    /// the nominal segment length. The first key frame that a cache sees is
    /// numbered from its part sequence in the same way, so caches that join a
    /// stream at different times agree when the key-frame interval is nominal.
    fn assign_fmp4_segment(
        &mut self,
        stream_id: u64,
        sequence: u64,
        keyframe: bool,
    ) -> Option<u64> {
        let seed_parts = self.segment_seed_parts;
        let nominal_parts = seed_parts.max(1);
        let keyframes = self.stream_keyframe_segments.entry(stream_id).or_default();
        if !keyframe {
            return keyframes
                .range(..=sequence)
                .next_back()
                .map(|(_, segment)| *segment);
        }
        if let Some(segment) = keyframes.get(&sequence) {
            return Some(*segment);
        }
        let previous = keyframes
            .range(..sequence)
            .next_back()
            .map(|(keyframe_sequence, segment)| (*keyframe_sequence, *segment));
        let next = keyframes
            .range(sequence..)
            .next()
            .map(|(keyframe_sequence, segment)| (*keyframe_sequence, *segment));
        let parts = self.stream_parts.get(&stream_id);
        // Whether every part strictly between two sequences is stored.
        let joined = |low: u64, high: u64| {
            let between = high.saturating_sub(low).saturating_sub(1);
            between == 0
                || parts.is_some_and(|parts| {
                    parts
                        .range((
                            std::ops::Bound::Excluded(low),
                            std::ops::Bound::Excluded(high),
                        ))
                        .count() as u64
                        == between
                })
        };
        let segments_in =
            |distance: u64| (distance.saturating_add(nominal_parts / 2) / nominal_parts).max(1);
        let candidate = match (previous, next) {
            (Some((previous_sequence, previous_segment)), _)
                if joined(previous_sequence, sequence) =>
            {
                Some(previous_segment.saturating_add(1))
            }
            (_, Some((next_sequence, next_segment))) if joined(sequence, next_sequence) => {
                next_segment.checked_sub(1)
            }
            (Some((previous_sequence, previous_segment)), _) => {
                Some(previous_segment.saturating_add(segments_in(sequence - previous_sequence)))
            }
            (None, Some((next_sequence, next_segment))) => {
                next_segment.checked_sub(segments_in(next_sequence - sequence))
            }
            (None, None) => Some(sequence.checked_div(seed_parts).unwrap_or(0)),
        };
        // The number must lie strictly between its neighbours. When no number
        // is free the part extends the earlier segment.
        let lower = previous.map(|(_, segment)| segment);
        let upper = next.map(|(_, segment)| segment);
        let segment = match (candidate, lower, upper) {
            (Some(candidate), Some(lower), Some(upper)) => {
                if upper <= lower.saturating_add(1) {
                    return Some(lower);
                }
                candidate.clamp(lower + 1, upper - 1)
            }
            (Some(candidate), Some(lower), None) => candidate.max(lower.saturating_add(1)),
            (Some(candidate), None, Some(upper)) => {
                if upper == 0 {
                    return None;
                }
                candidate.min(upper - 1)
            }
            (Some(candidate), None, None) => candidate,
            (None, Some(lower), _) => return Some(lower),
            (None, None, _) => return None,
        };
        keyframes.insert(sequence, segment);
        Some(segment)
    }

    /// Parts in the playlist window of one stream.
    ///
    /// The configured window counts nominal parts, and the window is a
    /// length of time. A stream whose parts are longer than the nominal part,
    /// such as 4K video beside 2.5 ms audio, covers that time with fewer
    /// parts, so it retains fewer of them. A stream whose parts are shorter,
    /// such as 0.25 ms PCM, covers it with more, up to what the cache ring
    /// holds beside the parts kept after the window.
    fn stream_window_parts(&self, stream_id: u64, configured: usize) -> usize {
        let nominal_us = self.nominal_part_us;
        let ring = self.ring_parts_for(configured);
        if let Some((part_us, target_us)) = self
            .stream_declared_us
            .get(&stream_id)
            .copied()
            .filter(|(part_us, _)| *part_us > 0 && nominal_us > 0)
        {
            let part_us = u64::from(part_us);
            let target_us = u64::from(target_us);
            // The contributor declares the part and segment durations of the
            // stream. The playlist holds the configured length of time, and
            // at least six whole segments beside the one that is open.
            let window_us = (configured as u64)
                .saturating_mul(nominal_us)
                .max(target_us.saturating_mul(PLAYLIST_WINDOW_SEGMENTS));
            // The parts of a stream are no shorter than three quarters of
            // the part that it declares, on average.
            let parts = window_us
                .saturating_mul(4)
                .div_ceil(part_us.saturating_mul(3));
            // At most the configured count of parts. A stream of parts
            // shorter than the nominal one needs more for the same time: the
            // window in parts of the declared length. Never more than the
            // ring holds beside the parts kept after the window.
            let most = if part_us < nominal_us {
                window_us.div_ceil(part_us).max(configured as u64)
            } else {
                configured as u64
            }
            .min(ring.saturating_sub(parts_after_window(part_us, target_us)) as u64);
            // At least three target durations, which the playlist of a live
            // stream must cover (RFC 8216bis), when the ring holds them.
            let least = (MIN_STREAM_WINDOW_PARTS.min(configured) as u64)
                .max(target_us.saturating_mul(3).div_ceil(part_us))
                .min(ring as u64);
            return usize::try_from(parts.clamp(least, most.max(least))).unwrap_or(configured);
        }
        let Some(part_us) = self
            .stream_max_part_duration_us
            .get(&stream_id)
            .map(|part_us| u64::from(*part_us))
        else {
            return configured;
        };
        if nominal_us == 0 || part_us == nominal_us {
            return configured;
        }
        let window_us = (configured as u64).saturating_mul(nominal_us);
        let parts = usize::try_from(window_us.div_ceil(part_us)).unwrap_or(usize::MAX);
        if part_us < nominal_us {
            // A stream without stamps keeps four of its windows in the
            // ring, as a stream of nominal parts does.
            return parts.min(ring / 4).max(configured);
        }
        parts.clamp(MIN_STREAM_WINDOW_PARTS.min(configured), configured)
    }

    /// Slots of the cache ring of one playlist.
    fn ring_parts_for(&self, configured: usize) -> usize {
        if self.ring_parts > 0 {
            self.ring_parts
        } else {
            configured.saturating_mul(4).max(32)
        }
    }

    /// Whether the parts of a stream make a playlist that a player accepts.
    /// A stamped stream needs one whole segment: its first part, and a part
    /// of a later segment. A stream without stamps needs one part.
    fn playlist_is_playable(&self, stream_id: u64) -> bool {
        let Some(parts) = self.stream_parts.get(&stream_id) else {
            return false;
        };
        let mut whole_segment = None;
        let mut stamped = false;
        for part in parts.values() {
            let (Some(msn), Some(index)) = (part.fmp4_segment_id, part.stamped_part) else {
                continue;
            };
            stamped = true;
            if index == 0 && whole_segment.is_none() {
                whole_segment = Some(msn);
            }
            if whole_segment.is_some_and(|first| msn > first) {
                return true;
            }
        }
        !stamped && !parts.is_empty()
    }

    /// Parts of a stream that a cache keeps in all: the playlist window, and
    /// three target durations after it, for which a part or a segment that
    /// has left the playlist must still be there for a reader that is slow.
    fn stream_retained_parts(&self, stream_id: u64, configured: usize) -> usize {
        let window = self.stream_window_parts(stream_id, configured);
        let retained = match self.stream_declared_us.get(&stream_id) {
            Some((part_us, target_us)) if *part_us > 0 => {
                let after = parts_after_window(u64::from(*part_us), u64::from(*target_us));
                window.saturating_add(after)
            }
            // A stream without stamps keeps four windows, as the ring does.
            _ => window.saturating_mul(4),
        };
        // A part that the ring has overwritten is not retained.
        retained.min(self.ring_parts_for(configured))
    }

    /// Longest part of a stream seen so far, or the nominal part of the
    /// node, in microseconds.
    fn stream_part_us(&self, stream_id: u64) -> u64 {
        self.stream_max_part_duration_us
            .get(&stream_id)
            .map_or(self.nominal_part_us, |part_us| u64::from(*part_us))
            .max(1)
    }

    /// Whether `part` of a stream arrived at this node within `within_us`
    /// of `now_us`, or of four of the stream's parts if that is longer. A
    /// part without a record counts as fresh.
    fn part_arrived_within(&self, stream_id: u64, part: u64, now_us: u64, within_us: u64) -> bool {
        let Some(record) = self
            .stream_parts
            .get(&stream_id)
            .and_then(|parts| parts.get(&part))
        else {
            return true;
        };
        let limit = within_us.max(self.stream_part_target_us(stream_id).saturating_mul(4));
        now_us.saturating_sub(record.available_unix_us) <= limit
    }

    /// How far a part of a stream lies behind `head`, in microseconds of
    /// media: the durations of the parts after it up to the head. A part
    /// that this node has no record of (a hole) is taken to be as long as
    /// the recorded part after it. `None` without a record of the head.
    fn part_age_us(&self, stream_id: u64, part: u64, head: u64) -> Option<u64> {
        let mut age = None;
        self.walk_part_ages(stream_id, head, |seq, age_us| {
            if seq <= part {
                age = Some(age_us);
                return false;
            }
            true
        })?;
        age.or(Some(0).filter(|_| part >= head))
    }

    /// The oldest part of a stream within `playout_us` of `head`: parts
    /// before it are past their playout deadline. `oldest` is the oldest
    /// part that anyone wants: when it is within the deadline, `oldest` is
    /// returned.
    ///
    /// The deadline is a length of media, the durations of the parts, not
    /// a count of parts of the stream's longest part, which one long part
    /// would shrink for the rest of the stream. Without a record of the
    /// head it falls back to that count. A hole in the records counts as
    /// within the deadline when the part after it is.
    fn playout_floor(&self, stream_id: u64, head: u64, playout_us: u64, oldest: u64) -> u64 {
        // Every part is at most the longest part long: at least this many
        // parts behind the head are within the deadline.
        let surely_within =
            head.saturating_sub((playout_us / self.stream_part_us(stream_id)).max(1));
        if oldest >= surely_within {
            return oldest.min(surely_within);
        }
        let mut floor = None;
        let walked = self.walk_part_ages(stream_id, head, |seq, age_us| {
            if age_us > playout_us {
                floor = Some(seq.saturating_add(1));
                return false;
            }
            if seq <= oldest {
                floor = Some(oldest);
                return false;
            }
            true
        });
        match (walked, floor) {
            (None, _) => surely_within,
            (Some(_), Some(floor)) => floor.min(surely_within),
            // The records end within the deadline: the oldest retained part.
            (Some(oldest_recorded), None) => oldest_recorded.min(surely_within),
        }
    }

    /// Walk the parts of a stream from `head` back, with the media time
    /// from the end of each to the end of the head, until `visit` returns
    /// false. A part not recorded between two that are is visited too, as
    /// long as the recorded part after it. Returns the last part visited,
    /// or `None` without a record of the head.
    fn walk_part_ages(
        &self,
        stream_id: u64,
        head: u64,
        mut visit: impl FnMut(u64, u64) -> bool,
    ) -> Option<u64> {
        let parts = self.stream_parts.get(&stream_id)?;
        let head_record = parts.get(&head)?;
        let fallback_us = self.stream_part_target_us(stream_id);
        let duration_of = |record: &RetainedPartObservation| {
            record
                .duration_us
                .map(u64::from)
                .filter(|duration_us| *duration_us > 0)
                .unwrap_or(fallback_us)
        };
        let (mut newer, mut newer_us, mut age_us) = (head, duration_of(head_record), 0_u64);
        if !visit(head, 0) {
            return Some(head);
        }
        for (seq, record) in parts.range(..head).rev() {
            // The holes between this part and the newer one, then this one.
            for hole in (seq + 1..newer).rev() {
                age_us = age_us.saturating_add(newer_us);
                if !visit(hole, age_us) {
                    return Some(hole);
                }
            }
            age_us = age_us.saturating_add(newer_us);
            if !visit(*seq, age_us) {
                return Some(*seq);
            }
            newer = *seq;
            newer_us = duration_of(record);
        }
        Some(newer)
    }

    /// The part target of a stream in microseconds: what its contributor
    /// declares, else its longest part, else the nominal part of the node.
    fn stream_part_target_us(&self, stream_id: u64) -> u64 {
        self.stream_declared_us
            .get(&stream_id)
            .map(|(part_us, _)| u64::from(*part_us))
            .filter(|part_us| *part_us > 0)
            .unwrap_or_else(|| self.stream_part_us(stream_id))
            .max(1)
    }

    /// When this node wrote the part into its ChunkCache. The first write
    /// counts.
    fn record_part_committed(
        &mut self,
        stream_id: u64,
        sequence: u64,
        committed_unix_us: Option<u64>,
    ) {
        let Some(committed_unix_us) = committed_unix_us else {
            return;
        };
        if let Some(part) = self
            .stream_parts
            .get_mut(&stream_id)
            .and_then(|parts| parts.get_mut(&sequence))
        {
            part.committed_unix_us.get_or_insert(committed_unix_us);
        }
    }

    fn record_part_published(
        &mut self,
        stream_id: u64,
        sequence: u64,
        published_unix_us: Option<u64>,
    ) {
        let Some(published_unix_us) = published_unix_us else {
            return;
        };
        if let Some(part) = self
            .stream_parts
            .get_mut(&stream_id)
            .and_then(|parts| parts.get_mut(&sequence))
        {
            part.published_unix_us.get_or_insert(published_unix_us);
        }
    }

    /// Bit rate of a stream over its retained parts, or `None` while the
    /// retained parts cover less than `min_window_ms`.
    fn playlist_bitrate_bps(
        &self,
        stream_id: u64,
        nominal_part_us: u64,
        min_window_ms: u64,
    ) -> Option<u64> {
        let parts = self.stream_parts.get(&stream_id)?;
        let (bytes, duration_us) = parts.values().fold((0_u64, 0_u64), |(bytes, us), part| {
            (
                bytes.saturating_add(part.bytes as u64),
                us.saturating_add(part.duration_us.map_or(nominal_part_us, u64::from)),
            )
        });
        (duration_us > 0 && duration_us >= min_window_ms.saturating_mul(1_000) && bytes > 0)
            .then(|| bytes.saturating_mul(8_000_000).saturating_div(duration_us))
    }

    fn retained_stream_summaries(
        &self,
        nominal_part_us: u64,
        min_bitrate_window_ms: u64,
    ) -> HashMap<u64, RetainedStreamSummary> {
        self.stream_parts
            .iter()
            .filter_map(|(stream_id, parts)| {
                let (latest_sequence, latest) = parts.last_key_value()?;
                Some((
                    *stream_id,
                    RetainedStreamSummary {
                        latest_sequence: Some(*latest_sequence),
                        latest_bytes: Some(latest.bytes),
                        retained_bytes: self
                            .stream_retained_bytes
                            .get(stream_id)
                            .copied()
                            .unwrap_or_default(),
                        retained_parts: parts.len() as u64,
                        bitrate_bps: self.playlist_bitrate_bps(
                            *stream_id,
                            nominal_part_us,
                            min_bitrate_window_ms,
                        ),
                        part_us: Some(self.stream_part_target_us(*stream_id)),
                    },
                ))
            })
            .collect()
    }

    fn canonical_stream_idle_for(&self, stream_id: u64, now_unix_ms: u64, idle_ms: u64) -> bool {
        self.stream_last_ingest_unix_ms
            .get(&stream_id)
            .is_some_and(|last_ingest_unix_ms| {
                now_unix_ms.saturating_sub(*last_ingest_unix_ms) > idle_ms
            })
    }

    fn forget_stream(&mut self, stream_id: u64) {
        self.stream_next_seq.remove(&stream_id);
        self.stream_canonical_epoch.remove(&stream_id);
        self.stream_canonical_epoch_activation_delay_us
            .remove(&stream_id);
        self.stream_subscription_base_object.remove(&stream_id);
        self.stream_latest_canonical_object.remove(&stream_id);
        self.stream_last_ingest_unix_ms.remove(&stream_id);
        self.stream_parts.remove(&stream_id);
        self.stream_keyframe_segments.remove(&stream_id);
        self.stream_retained_bytes.remove(&stream_id);
        self.stream_max_part_duration_us.remove(&stream_id);
        self.stream_max_segment_duration_us.remove(&stream_id);
        self.stream_declared_us.remove(&stream_id);
        self.stream_playlist_floor.remove(&stream_id);
        self.stream_init_scanned.remove(&stream_id);
        self.stream_inits.remove(&stream_id);
        self.stream_media_kinds.remove(&stream_id);
    }

    fn take_current(&mut self, now: Instant, now_ms: u64) -> Option<PendingPart> {
        if self.current.is_empty() {
            self.current_started = now;
            self.current_started_unix_ms = now_ms;
            return None;
        }

        let seq = self.next_seq;
        self.next_seq += 1;
        let data = std::mem::take(&mut self.current);
        let duration_us = duration_us(now.duration_since(self.current_started)).max(1);
        let part = PendingPart {
            seq,
            bytes: data.len(),
            duration_us,
            committed_unix_ms: now_ms,
            data,
        };
        self.current_started = now;
        self.current_started_unix_ms = now_ms;
        Some(part)
    }
}

struct PendingPart {
    seq: u64,
    bytes: usize,
    duration_us: u64,
    committed_unix_ms: u64,
    data: Vec<u8>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct StatsSnapshot {
    stream_id: u64,
    #[serde(default)]
    stream_id_text: String,
    /// The nominal part of the node in whole milliseconds, rounded. Kept
    /// for readers of the old telemetry; `part_target_us` is exact.
    part_target_ms: u64,
    /// The nominal part of the node in microseconds. Zero from a node that
    /// predates it: use `part_target_ms`.
    #[serde(default)]
    part_target_us: u64,
    parts_per_segment: usize,
    window_parts: usize,
    datagrams_received: u64,
    bytes_received: u64,
    current_part_bytes: usize,
    latest_local_part: Option<u64>,
    latest_local_part_bytes: Option<usize>,
    latest_local_part_duration_ms: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    latest_local_part_duration_us: Option<u64>,
    latest_mesh_part: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    canonical_epoch: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    canonical_epoch_activation_delay_us: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    contiguous_object: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    head_object: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    gap_count: Option<u64>,
    mesh_peers: Vec<String>,
    latest_local_part_age_ms: Option<u64>,
    last_ingest_age_ms: Option<u64>,
}

impl StatsSnapshot {
    /// The nominal part in microseconds, from the exact field or from the
    /// whole milliseconds of a node that predates it.
    fn nominal_part_us(&self) -> u64 {
        if self.part_target_us > 0 {
            self.part_target_us
        } else {
            self.part_target_ms.saturating_mul(1_000)
        }
    }
}

