    for (outcome, value) in [
        ("decoded", snapshot.relay_session.compact_decoded_objects),
        (
            "unknown_descriptor",
            snapshot.relay_session.compact_unknown_descriptor,
        ),
        (
            "descriptor",
            snapshot.relay_session.compact_descriptors_learned,
        ),
    ] {
        output.push_str(&format!(
            "av_mesh_relay_session_compact_total{{outcome=\"{outcome}\"}} {value}\n"
        ));
    }
    push_prometheus_metric_header(
        &mut output,
        "av_mesh_relay_session_drops_total",
        "RelaySession datagrams dropped by bounded low-cardinality reason.",
        "counter",
    );
    for (reason, value) in [
        ("conflict", snapshot.relay_session.conflict_drops),
        (
            "authentication",
            snapshot.relay_session.authentication_drops,
        ),
        ("deadline", snapshot.relay_session.deadline_drops),
    ] {
        output.push_str(&format!(
            "av_mesh_relay_session_drops_total{{reason=\"{reason}\"}} {value}\n"
        ));
    }
    push_prometheus_metric_header(
        &mut output,
        "av_mesh_relay_session_rejected_total",
        "RelaySession datagrams and announcements rejected, by the kind of error.",
        "counter",
    );
    for (kind, value) in snapshot.relay_session.rejected_by_kind.named() {
        output.push_str(&format!(
            "av_mesh_relay_session_rejected_total{{kind=\"{kind}\"}} {value}\n"
        ));
    }
    // A 2.7: the audio class's parent lanes (one a contributor each at a
    // first forwarder) and the class threads' media clocks (A 2.5).
