        assert_eq!(take_relay_deadline_drop_delta(&mut reported, 12), Some(12));
        assert_eq!(take_relay_deadline_drop_delta(&mut reported, 12), None);
        assert_eq!(take_relay_deadline_drop_delta(&mut reported, 17), Some(5));
