    #[tokio::test]
    async fn adaptive_master_advertises_only_fresh_configured_renditions() {
        let cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 32, 64).await;
        for stream_id in [77, 78, 79] {
            cache
                .commit_stream_payload(
                    stream_id,
                    encode_test_canonical_fmp4_bundle_with_duration(
                        stream_id,
                        0,
                        Some(&test_h264_aac_init()),
                        b"moof-mdat-av",
                        Some(250),
                        true,
                    ),
                )
                .await
                .unwrap();
        }
        cache
            .state
            .write()
            .await
            .stream_last_ingest_unix_ms
            .insert(79, now_unix_ms().saturating_sub(2_000));

        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh))
            .with_hls_renditions(
                vec![
                    parse_hls_rendition_spec("77:77:18000000:16000000:3840x2160:59940").unwrap(),
                    parse_hls_rendition_spec("77:78:8000000:7000000:1920x1080:59940").unwrap(),
                    parse_hls_rendition_spec("77:79:4000000:3500000:1280x720:59940").unwrap(),
                ],
                1_000,
            );

        let response = router
            .route(
                Request::builder()
                    .method(Method::GET)
                    .uri("/live/77/master.m3u8")
                    .body(())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status, StatusCode::OK);
        let playlist = String::from_utf8(response.body.unwrap().to_vec()).unwrap();
        assert!(playlist.contains(
            "#EXT-X-STREAM-INF:BANDWIDTH=18000000,AVERAGE-BANDWIDTH=16000000,CODECS=\"avc1.640033,mp4a.40.2\",RESOLUTION=3840x2160,FRAME-RATE=59.940\n/live/77/stream.m3u8"
        ));
        assert!(playlist.contains(
            "#EXT-X-STREAM-INF:BANDWIDTH=8000000,AVERAGE-BANDWIDTH=7000000,CODECS=\"avc1.640033,mp4a.40.2\",RESOLUTION=1920x1080,FRAME-RATE=59.940\n/live/78/stream.m3u8"
        ));
        assert!(!playlist.contains("/live/79/stream.m3u8"));

        // Each rendition reports the position of the other live renditions.
        for (read, other) in [(77, 78), (78, 77)] {
            let response = router
                .route(
                    Request::builder()
                        .method(Method::GET)
                        .uri(format!("/live/{read}/stream.m3u8"))
                        .body(())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status, StatusCode::OK);
            let playlist = String::from_utf8(response.body.unwrap().to_vec()).unwrap();
            assert!(
                playlist.contains(&format!(
                    "#EXT-X-RENDITION-REPORT:URI=\"../{other}/stream.m3u8\",LAST-MSN=0,LAST-PART=0\n"
                )),
                "{playlist}"
            );
            assert!(!playlist.contains(&format!("URI=\"../{read}/stream.m3u8\"")));
        }

        mesh.shutdown();
    }

    #[test]
    fn the_last_position_of_a_playlist_is_its_last_listed_part() {
        let open = "#EXTM3U\n#EXT-X-MEDIA-SEQUENCE:40\n#EXTINF:2.000,\nseg40.mp4\n\
            #EXT-X-PART:DURATION=0.2,URI=\"part10.mp4\"\n\
            #EXT-X-PART:DURATION=0.2,URI=\"part11.mp4\"\n#EXTINF:0.4,\nseg41.mp4\n\
            #EXT-X-PART:DURATION=0.2,URI=\"part12.mp4\"\n\
            #EXT-X-PRELOAD-HINT:TYPE=PART,URI=\"part13.mp4\"\n";
        assert_eq!(playlist_last_position(open), Some((42, 0)));
        // The last segment is complete: its last part is the position.
        let closed = open.replace("#EXT-X-PART:DURATION=0.2,URI=\"part12.mp4\"\n", "");
        assert_eq!(playlist_last_position(&closed), Some((41, 1)));
        assert_eq!(
            playlist_last_position("#EXTM3U\n#EXT-X-MEDIA-SEQUENCE:40\n"),
            None
        );
    }

    #[tokio::test]
    async fn a_node_holds_as_many_streams_as_it_has_playlist_slots() {
        let commit = |cache: Arc<LiveTsCache>, stream_id: u64| async move {
            cache
                .commit_stream_payload(
                    stream_id,
                    encode_test_canonical_fmp4_bundle_with_duration(
                        stream_id,
                        0,
                        Some(&test_h264_aac_init()),
                        b"moof-mdat-av",
                        Some(250),
                        true,
                    ),
                )
                .await
                .is_ok()
        };
        // The default: sixteen slots, and one is the stream of the node.
        let cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 32, 64).await;
        let mut held = 0;
        for stream_id in 100..140 {
            if commit(Arc::clone(&cache), stream_id).await {
                held += 1;
            }
        }
        assert_eq!(held, 15);
        // The streams that were there first are the ones that it holds, and
        // each still has its part. Twenty-five were refused.
        for stream_id in 100..115 {
            assert!(cache.stream_position_for_id(stream_id).await.is_some());
        }
        assert!(cache.stream_position_for_id(115).await.is_none());
        assert_eq!(cache.stream_slot_refusals.load(Ordering::Relaxed), 25);
        // A stream that has gone idle gives its slot to a new stream.
        cache.state.write().await.stream_last_ingest_unix_ms.insert(
            107,
            now_unix_ms().saturating_sub(STREAM_SLOT_IDLE_MS + 1_000),
        );
        assert!(commit(Arc::clone(&cache), 200).await);
        assert!(cache.stream_position_for_id(200).await.is_some());
        assert!(cache.stream_position_for_id(107).await.is_none());
        assert!(cache.stream_position_for_id(100).await.is_some());
        // Forty slots hold all forty streams.
        let cache = LiveTsCache::with_slots(1, Duration::from_millis(250), 4, 32, 64, 41).await;
        let mut held = 0;
        for stream_id in 100..140 {
            if commit(Arc::clone(&cache), stream_id).await {
                held += 1;
            }
        }
        assert_eq!(held, 40);
        assert_eq!(standby_playlist_limit(15), 10);
        assert_eq!(standby_playlist_limit(63), 42);
    }

    #[tokio::test]
    async fn the_age_of_an_advertisement_does_not_depend_on_the_clock_of_its_sender() {
        let telemetry = TelemetryAggregator::new(30_000);
        let advertisement = |node: &str, written_ms: u64| {
            let mut snapshot =
                telemetry_snapshot_for_tests(node, "uk-lon", "eu", 51.5, -0.1, Vec::new(), 7);
            snapshot.updated_unix_ms = written_ms;
            snapshot
        };
        let now_ms = now_unix_ms();
        // The clock of one edge is 4 s behind, and that of another 4 s ahead.
        let behind = advertisement("edge-behind", now_ms - 4_000);
        let ahead = advertisement("edge-ahead", now_ms + 4_000);
        telemetry.ingest_snapshot(behind.clone()).await;
        telemetry.ingest_snapshot(ahead.clone()).await;
        assert!(telemetry.advertisement_age_ms(&behind, now_unix_ms()) < 200);
        assert!(telemetry.advertisement_age_ms(&ahead, now_unix_ms()) < 200);

        // The same advertisement again is not news: its age goes on.
        tokio::time::sleep(Duration::from_millis(120)).await;
        telemetry.ingest_snapshot(behind.clone()).await;
        assert!(telemetry.advertisement_age_ms(&behind, now_unix_ms()) >= 120);
        // A new one is.
        let newer = advertisement("edge-behind", now_ms - 3_500);
        telemetry.ingest_snapshot(newer.clone()).await;
        assert!(telemetry.advertisement_age_ms(&newer, now_unix_ms()) < 100);

        // A first advertisement that is two minutes old is old, and a node
        // that was never heard is judged by what its advertisement says.
        let old = advertisement("edge-old", now_ms - 120_000);
        telemetry.ingest_snapshot(old.clone()).await;
        assert!(telemetry.advertisement_age_ms(&old, now_unix_ms()) >= 120_000);
        let unheard = advertisement("edge-unheard", now_ms - 5_000);
        assert!(telemetry.advertisement_age_ms(&unheard, now_unix_ms()) >= 5_000);
    }

    #[test]
    fn the_renditions_of_a_ladder_have_the_date_of_their_segment_number() {
        let rendition = |published: &str| {
            format!(
                "#EXTM3U\n#EXT-X-TARGETDURATION:2\n#EXT-X-MEDIA-SEQUENCE:897622180\n\
                 #EXT-X-PROGRAM-DATE-TIME:{published}\n#EXTINF:2.000,\nseg897622180.mp4\n"
            )
        };
        // Two renditions whose first parts were published 262 ms apart.
        let high = with_ladder_program_date_time(rendition("2026-11-21T07:03:20.412Z"), 2_000);
        let low = with_ladder_program_date_time(rendition("2026-11-21T07:03:20.150Z"), 2_000);
        assert_eq!(high, low);
        assert!(
            high.contains("#EXT-X-PROGRAM-DATE-TIME:2026-11-21T06:59:20.000Z\n#EXTINF"),
            "{high}"
        );
        // A playlist without a date, or a stream without a declared segment
        // duration, is left as it is.
        let plain = "#EXTM3U\n#EXT-X-MEDIA-SEQUENCE:5\n".to_owned();
        assert_eq!(with_ladder_program_date_time(plain.clone(), 2_000), plain);
        let dated = rendition("2026-11-21T07:03:20.412Z");
        assert_eq!(with_ladder_program_date_time(dated.clone(), 0), dated);
    }

    #[test]
    fn a_stream_knows_the_ladder_that_it_is_a_rendition_of() {
        let catalog = HlsRenditionCatalog::new(vec![
            parse_hls_rendition_spec("77:77:18000000:16000000:3840x2160:59940").unwrap(),
            parse_hls_rendition_spec("77:78:8000000:7000000:1920x1080:59940").unwrap(),
            parse_hls_rendition_spec("90:90:8000000:7000000:1920x1080:59940").unwrap(),
        ]);
        let ladder = catalog.ladder_of(78).unwrap();
        assert_eq!(
            ladder.iter().map(|item| item.stream_id).collect::<Vec<_>>(),
            vec![77, 78]
        );
        assert!(catalog.ladder_of(77).is_some());
        // One rendition is not a ladder, and neither is an unknown stream.
        assert!(catalog.ladder_of(90).is_none());
        assert!(catalog.ladder_of(5).is_none());
    }

