    #[tokio::test]
    async fn capacity_alarm_preserves_existing_session_and_rejects_new_session() {
        let cache = LiveTsCache::new(801, Duration::from_millis(50), 2, 6, 64).await;
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let telemetry = TelemetryAggregator::default();
        let mut remote = telemetry_snapshot_for_tests(
            "edge-b",
            "test-region",
            "test-continent",
            51.6,
            -0.2,
            Vec::new(),
            801,
        );
        remote.edge_service = Some(EdgeServiceSnapshot::from_node(
            &remote.node,
            Some("https://edge-b.example/live".into()),
            "edge",
            EdgeLoadSnapshot::default(),
        ));
        telemetry.ingest_snapshot(remote).await;
        let mut router =
            app_router_for_tests_with_telemetry(Arc::clone(&cache), Arc::clone(&mesh), telemetry);
        router.edge_load = EdgeLoad::new(EdgeAdmissionConfig {
            capacity_bps: 8,
            admission_percent: 100,
            recovery_percent: 50,
            window_seconds: 1,
            min_sustained_seconds: 1,
            session_idle_seconds: 60,
            max_sessions: 100,
            session_limit: 0,
            request_capacity_per_sec: 0,
        });

        let existing = || {
            Request::builder()
                .method(Method::GET)
                .uri("/live/801/stream.m3u8")
                .header("CMCD-Session", "sid=\"existing-session\"")
                .body(())
                .unwrap()
        };
        assert_eq!(
            router.route(existing()).await.unwrap().status,
            StatusCode::OK
        );
        assert!(router.edge_load.admission_snapshot().overloaded);
        assert_eq!(
            router.route(existing()).await.unwrap().status,
            StatusCode::OK
        );

        let rejected = router
            .route(
                Request::builder()
                    .method(Method::GET)
                    .uri("/live/801/stream.m3u8")
                    .header("CMCD-Session", "sid=\"new-session\"")
                    .body(())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(rejected.status, StatusCode::TOO_MANY_REQUESTS);
        assert!(rejected.headers.iter().any(|(name, value)| {
            name == "link" && value.contains("https://edge-b.example/live/801/stream.m3u8")
        }));
        assert_eq!(router.edge_load.admission_snapshot().active_sessions, 1);

        let failover = router
            .route(
                Request::builder()
                    .method(Method::GET)
                    .uri("/live/801/master.m3u8")
                    .body(())
                    .unwrap(),
            )
            .await
            .unwrap();
        let failover_body = String::from_utf8(failover.body.unwrap().to_vec()).unwrap();
        assert_eq!(failover.status, StatusCode::OK);
        assert!(!failover_body.lines().any(|line| line == "stream.m3u8"));
        assert!(failover_body.contains("https://edge-b.example/live/801/stream.m3u8"));
        mesh.shutdown();
    }

    #[tokio::test]
    async fn multivariant_playlist_uses_healthy_same_region_dag_edges() {
        let cache = LiveTsCache::new(801, Duration::from_millis(50), 2, 6, 64).await;
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let telemetry = TelemetryAggregator::default();
        let mut remote = telemetry_snapshot_for_tests(
            "edge-b",
            "test-region",
            "test-continent",
            51.6,
            -0.2,
            Vec::new(),
            801,
        );
        remote.edge_service = Some(EdgeServiceSnapshot::from_node(
            &remote.node,
            Some("https://edge-b.example/live".into()),
            "edge",
            EdgeLoadSnapshot::default(),
        ));
        telemetry.ingest_snapshot(remote).await;
        let router =
            app_router_for_tests_with_telemetry(Arc::clone(&cache), Arc::clone(&mesh), telemetry);

        let response = router
            .route(
                Request::builder()
                    .method(Method::GET)
                    .uri("/live/801/master.m3u8")
                    .body(())
                    .unwrap(),
            )
            .await
            .unwrap();
        let body = String::from_utf8(response.body.unwrap().to_vec()).unwrap();
        assert_eq!(response.status, StatusCode::OK);
        // Each cache is one Content Steering pathway. This node names itself
        // with a relative URI.
        assert!(body
            .contains("#EXT-X-STREAM-INF:BANDWIDTH=4000000,PATHWAY-ID=\"test-node\"\nstream.m3u8"));
        assert!(body.contains(
            "#EXT-X-STREAM-INF:BANDWIDTH=4000000,PATHWAY-ID=\"edge-b\"\n\
             https://edge-b.example/live/801/stream.m3u8"
        ));
        assert!(body.contains("#EXT-X-CONTENT-STEERING:SERVER-URI=\"steering.json?p="));
        mesh.shutdown();
    }

    #[test]
    fn mission_control_asset_response_serves_leptos_assets_when_present() {
        let temp_dir = std::env::temp_dir().join(format!(
            "needletail-mission-control-dist-test-{}",
            now_unix_ms()
        ));
        std::fs::create_dir_all(&temp_dir).unwrap();
        std::fs::write(
            temp_dir.join("index.html"),
            r#"<html><body><script type="module" src="/app.js"></script></body></html>"#,
        )
        .unwrap();
        std::fs::write(temp_dir.join("app.js"), "export default {};").unwrap();
        std::fs::write(temp_dir.join("app_bg.wasm"), b"\0asm").unwrap();
        std::fs::write(temp_dir.join("world-map.png"), b"\x89PNG\r\n\x1a\n").unwrap();

        let index = mission_control_asset_response_from_dir(&temp_dir, "/mesh").unwrap();
        assert_eq!(index.status, StatusCode::OK);
        assert_eq!(
            index.content_type.as_deref(),
            Some("text/html; charset=utf-8")
        );
        assert!(String::from_utf8(index.body.unwrap().to_vec())
            .unwrap()
            .contains("type=\"module\""));
        assert!(index
            .headers
            .iter()
            .any(|(name, value)| name == "cache-control" && value.contains("no-store")));

        let js = mission_control_asset_response_from_dir(&temp_dir, "/app.js").unwrap();
        assert_eq!(
            js.content_type.as_deref(),
            Some("text/javascript; charset=utf-8")
        );
        let wasm = mission_control_asset_response_from_dir(&temp_dir, "/app_bg.wasm").unwrap();
        assert_eq!(wasm.content_type.as_deref(), Some("application/wasm"));
        let map = mission_control_asset_response_from_dir(&temp_dir, "/world-map.png").unwrap();
        assert_eq!(map.content_type.as_deref(), Some("image/png"));
        assert!(mission_control_asset_response_from_dir(&temp_dir, "/live/stream.m3u8").is_none());

        let _ = std::fs::remove_dir_all(temp_dir);
    }

    #[test]
    fn global_operations_snapshot_requires_a_fresh_committed_lease() {
        let temp_dir = std::env::temp_dir().join(format!(
            "needletail-operations-snapshot-test-{}",
            now_unix_ms()
        ));
        std::fs::create_dir_all(&temp_dir).unwrap();
        let path = temp_dir.join("snapshot.json");
        let now = now_unix_ms();
        std::fs::write(
            &path,
            serde_json::to_vec(&serde_json::json!({
                "schema": OPERATIONS_SNAPSHOT_SCHEMA,
                "updated_unix_ms": now - 500,
                "orchestration": {
                    "collector": {
                        "authority": OPERATIONS_CONTROLLER_AUTHORITY,
                        "quorum_healthy": true,
                        "term": 7,
                        "fencing_generation": 9,
                        "lease_remaining_ms": 8_000,
                        "public_endpoint": "https://ops-london.example.com/mesh"
                    }
                }
            }))
            .unwrap(),
        )
        .unwrap();
        assert!(read_current_operations_snapshot(&path, now).is_ok());
        let discovery = operations_discovery_response(&path);
        assert_eq!(discovery.status, StatusCode::TEMPORARY_REDIRECT);
        assert!(discovery.headers.iter().any(|(name, value)| {
            name == "location" && value == "https://ops-london.example.com/mesh"
        }));

        let mut stale: serde_json::Value =
            serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
        stale["orchestration"]["collector"]["lease_remaining_ms"] = serde_json::json!(1_000);
        std::fs::write(&path, serde_json::to_vec(&stale).unwrap()).unwrap();
        assert_eq!(
            read_current_operations_snapshot(&path, now).unwrap_err(),
            "snapshot collector lease expired"
        );
        let _ = std::fs::remove_dir_all(temp_dir);
    }

