    /// A free loopback port in 24000-24999. A test's class-split mesh binds
    /// the port plus 1000 as well, so those (25000-25999) are never handed
    /// out here, and must be free too.
    fn unused_loopback_addr() -> SocketAddr {
        static NEXT_PORT: std::sync::atomic::AtomicU16 = std::sync::atomic::AtomicU16::new(0);

        loop {
            let port =
                24_000 + NEXT_PORT.fetch_add(1, std::sync::atomic::Ordering::Relaxed) % 1_000;
            let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
            let class = SocketAddr::from((Ipv4Addr::LOCALHOST, port + 1_000));
            if std::net::UdpSocket::bind(addr).is_ok() && std::net::UdpSocket::bind(class).is_ok() {
                return addr;
            }
        }
    }

    fn unused_tcp_loopback_addr() -> SocketAddr {
        let listener = std::net::TcpListener::bind((Ipv4Addr::LOCALHOST, 0)).unwrap();
        listener.local_addr().unwrap()
    }

    async fn unused_udp_loopback_addr() -> SocketAddr {
        let socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        socket.local_addr().unwrap()
    }

    fn tls_pair_for_tests() -> (String, String) {
        use base64::engine::general_purpose::STANDARD as base64_engine;
        use base64::Engine;

        let rcgen::CertifiedKey { cert, key_pair } =
            rcgen::generate_simple_self_signed(vec!["local.wavey.ai".into()]).unwrap();
        (
            base64_engine.encode(cert.pem()),
            base64_engine.encode(key_pair.serialize_pem()),
        )
    }

    // ---- Regional LL-HLS cache features: playlist replication on demand,
    // ---- reader assignment, load balance, drain and pinning.

    /// A canonical fMP4 part as the contributor publishes it: the part names
    /// its duration, whether it starts with a key frame, and when it was
    /// published.
    fn encode_test_published_fmp4_part(
        stream_id: u64,
        epoch: u64,
        sequence: u64,
        keyframe: bool,
        duration_ms: u32,
    ) -> Bytes {
        encode_test_stamped_fmp4_part(stream_id, epoch, sequence, keyframe, duration_ms, None)
    }

    /// A published part with the playlist stamp of a contributor.
    fn encode_test_stamped_fmp4_part(
        stream_id: u64,
        epoch: u64,
        sequence: u64,
        keyframe: bool,
        duration_ms: u32,
        stamp: Option<PartStamp>,
    ) -> Bytes {
        let init = test_h264_aac_init();
        let media = format!("moof-mdat-{stream_id}-{epoch}-{sequence}");
        let payload = encode_test_fmp4_slot(keyframe.then_some(init.as_slice()), media.as_bytes());
        let key = media_object::ObjectKey::for_payload(
            "default",
            stream_id.to_string(),
            "muxed-fmp4",
            epoch,
            0,
            sequence,
            1,
            &payload,
        )
        .unwrap();
        let published_ns = 1_795_000_000_000_000_000_i64
            + i64::try_from(sequence + 1).unwrap() * i64::from(duration_ms) * 1_000_000;
        let published = media_object::ClockTimestamp::new(
            published_ns,
            "source-clock",
            media_object::ClockConfidence::estimated(1_000_000),
        )
        .unwrap();
        let mut builder = MediaObject::builder(key, ObjectKind::Media, payload.to_vec())
            .with_keyframe(keyframe)
            .with_stage_timestamp(media_object::StageTimestamp::new(
                Stage::Published,
                published,
            ))
            .with_metadata("container", b"fmp4".to_vec())
            .with_metadata("payload-format", b"fmp4-slot-v1".to_vec())
            .with_metadata("duration-ms", duration_ms.to_string().into_bytes());
        if let Some(stamp) = stamp {
            builder = builder
                .with_metadata("hls-msn", stamp.msn.to_string().into_bytes())
                .with_metadata("hls-part", stamp.part.to_string().into_bytes())
                // The whole-millisecond keys of a contributor that predates
                // the microsecond ones.
                .with_metadata(
                    "hls-part-target-ms",
                    (stamp.part_target_us / 1_000).to_string().into_bytes(),
                )
                .with_metadata(
                    "hls-target-duration-ms",
                    (stamp.target_duration_us / 1_000).to_string().into_bytes(),
                );
        }
        let object = builder.build().unwrap();
        Bytes::from(media_object::encode(&object).unwrap())
    }

    /// Forty parts of 200 ms in segments of ten, stamped as a contributor
    /// stamps them: the first segment is number 1000.
    async fn commit_stamped_video(cache: &LiveTsCache, parts: u64) {
        for sequence in 0..parts {
            let stamp = PartStamp {
                msn: 1_000 + sequence / 10,
                part: (sequence % 10) as u32,
                part_target_us: 208_000,
                target_duration_us: 2_000_000,
            };
            cache
                .commit_stream_payload(
                    77,
                    encode_test_stamped_fmp4_part(
                        77,
                        5,
                        sequence,
                        sequence % 10 == 0,
                        200,
                        Some(stamp),
                    ),
                )
                .await
                .unwrap();
        }
    }

    #[tokio::test]
    async fn stamped_parts_give_every_cache_the_same_playlist() {
        // The nodes are sized for 5 ms audio parts.
        let distributor = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        let early = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        let late = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        commit_stamped_video(&distributor, 36).await;
        // One edge holds the stream from its first part. The other joined in
        // the middle of the second segment.
        for slot in 0..36 {
            deliver_mesh_part(&distributor, &early, 77, slot).await;
        }
        for slot in 14..36 {
            deliver_mesh_part(&distributor, &late, 77, slot).await;
        }

        let reference = distributor.playlist_for_stream_id(77).await;
        assert!(reference.contains("#EXT-X-MEDIA-SEQUENCE:1000\n"));
        // The contributor declares both durations. They do not follow the
        // nominal part of the node or the longest part that a cache saw.
        assert!(reference.contains("#EXT-X-PART-INF:PART-TARGET=0.208\n"));
        assert!(reference.contains("#EXT-X-TARGETDURATION:2\n"));
        assert!(reference.contains("PART-HOLD-BACK=0.624,HOLD-BACK=6.000"));
        assert!(reference.contains("#EXTINF:2.000,\nseg1000.mp4\n"));
        assert!(reference.contains("#EXTINF:2.000,\nseg1002.mp4\n"));
        // Segment 1003 is open: it has parts and no EXTINF yet.
        assert!(reference.contains("URI=\"part35.mp4\""));
        assert!(!reference.contains("seg1003.mp4"));
        assert_eq!(early.playlist_for_stream_id(77).await, reference);

        // The late cache lists the same segments under the same numbers. It
        // leaves out the segment whose first part it does not hold.
        let joined = late.playlist_for_stream_id(77).await;
        assert!(joined.contains("#EXT-X-MEDIA-SEQUENCE:1002\n"));
        assert!(!joined.contains("seg1001.mp4"));
        let from_1002 = |playlist: &str| {
            let start = playlist.find("#EXT-X-PART:DURATION=0.200,URI=\"part20.mp4\"");
            playlist[start.expect("part 20 is listed")..].to_owned()
        };
        assert_eq!(from_1002(&joined), from_1002(&reference));

        // A whole segment can be fetched. A segment without its first part
        // and the open segment cannot.
        assert!(late.get_segment_for_stream_id(77, 1_002).await.is_some());
        assert!(late.get_segment_for_stream_id(77, 1_001).await.is_none());
        assert!(late.get_segment_for_stream_id(77, 1_003).await.is_none());
    }

    #[tokio::test]
    async fn one_long_segment_does_not_raise_the_target_duration_of_a_stamped_stream() {
        let cache = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        // Segments of 2 s, 6 s (a fault upstream) and 2 s, and an open one.
        // The contributor declares 2 s on every part.
        let mut sequence = 0;
        for (segment, parts) in [(700_u64, 10_u32), (701, 30), (702, 10), (703, 3)] {
            for part in 0..parts {
                let stamp = PartStamp {
                    msn: segment,
                    part,
                    part_target_us: 200_000,
                    target_duration_us: 2_000_000,
                };
                cache
                    .commit_stream_payload(
                        77,
                        encode_test_stamped_fmp4_part(77, 5, sequence, part == 0, 200, Some(stamp)),
                    )
                    .await
                    .unwrap();
                sequence += 1;
            }
        }
        let playlist = cache.playlist_for_stream_id(77).await;
        assert!(
            playlist.contains("#EXTINF:6.000,\nseg701.mp4\n"),
            "{playlist}"
        );
        assert!(playlist.contains("#EXT-X-TARGETDURATION:2\n"), "{playlist}");
        assert!(playlist.contains("HOLD-BACK=6.000"), "{playlist}");
    }

    #[tokio::test]
    async fn a_short_part_completes_its_segment_at_once() {
        let cache = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        // Two segments of nine parts of 208 ms and one of 125 ms, as a
        // contributor cuts a group of 48 frames. Then the short part of a
        // third segment, before any part of a fourth has arrived.
        let mut sequence = 0;
        for segment in 0..3_u64 {
            for part in 0..10_u32 {
                let stamp = PartStamp {
                    msn: 500 + segment,
                    part,
                    part_target_us: 208_000,
                    target_duration_us: 2_000_000,
                };
                cache
                    .commit_stream_payload(
                        77,
                        encode_test_stamped_fmp4_part(
                            77,
                            5,
                            sequence,
                            part == 0,
                            if part == 9 { 125 } else { 208 },
                            Some(stamp),
                        ),
                    )
                    .await
                    .unwrap();
                sequence += 1;
                if segment == 2 && part == 8 {
                    // Nine whole parts: the third segment is still open.
                    let open = cache.playlist_for_stream_id(77).await;
                    assert!(!open.contains("seg502.mp4"), "{open}");
                    assert!(cache.get_segment_for_stream_id(77, 502).await.is_none());
                }
            }
        }
        let playlist = cache.playlist_for_stream_id(77).await;
        // The short part is listed, and its segment with it.
        assert!(
            playlist.ends_with(
                "#EXT-X-PART:DURATION=0.125,URI=\"part29.mp4\"\n#EXTINF:1.997,\nseg502.mp4\n\
                 #EXT-X-PRELOAD-HINT:TYPE=PART,URI=\"part30.mp4\"\n"
            ),
            "{playlist}"
        );
        assert!(cache.get_segment_for_stream_id(77, 502).await.is_some());
        assert!(part_ends_segment_short(125, 208));
        assert!(!part_ends_segment_short(200, 208));
        assert!(!part_ends_segment_short(5, 0));
    }

    #[test]
    fn one_edge_without_readers_takes_the_standby_copy() {
        let edges = ["edge-1", "edge-2", "edge-3", "edge-4"]
            .map(str::to_owned)
            .to_vec();
        let holder = |node: &str, sessions| StandbyHolder {
            node_id: node.to_owned(),
            sessions,
        };
        // edge-1 has readers of playlist 7. Exactly one other edge wants the
        // second copy, and every edge agrees which.
        let holders = vec![holder("edge-1", 3)];
        let wanting = edges
            .iter()
            .filter(|edge| wants_standby_copy(edge, 7, 2, &holders, &edges))
            .cloned()
            .collect::<Vec<_>>();
        assert_eq!(wanting.len(), 1, "{wanting:?}");
        assert_ne!(wanting[0], "edge-1");
        // Another playlist can have its standby copy on another edge.
        let spread = (1..40_u64)
            .map(|stream| {
                edges
                    .iter()
                    .find(|edge| wants_standby_copy(edge, stream, 2, &holders, &edges))
                    .cloned()
                    .unwrap()
            })
            .collect::<HashSet<_>>();
        assert_eq!(spread.len(), 3, "{spread:?}");

        // The standby edge holds its copy: it still wants it.
        let standby = wanting[0].clone();
        let holders = vec![holder("edge-1", 3), holder(&standby, 0)];
        assert!(wants_standby_copy(&standby, 7, 2, &holders, &edges));
        // Two edges have readers: no standby copy is needed.
        let other = edges
            .iter()
            .find(|edge| **edge != "edge-1" && **edge != standby)
            .unwrap();
        let holders = vec![holder("edge-1", 3), holder(other, 1), holder(&standby, 0)];
        assert!(!wants_standby_copy(&standby, 7, 2, &holders, &edges));
        // Nobody reads the playlist: no copy is kept for it.
        let holders = vec![holder("edge-1", 0), holder(&standby, 0)];
        assert!(!wants_standby_copy(&standby, 7, 2, &holders, &edges));
        // One copy: no standby.
        let holders = vec![holder("edge-1", 3)];
        assert!(edges
            .iter()
            .all(|edge| !wants_standby_copy(edge, 7, 1, &holders, &edges)));
    }

    #[tokio::test]
    async fn the_search_for_an_initialization_section_looks_at_each_part_once() {
        let cache = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        // An opaque audio stream: no part carries an initialization section.
        for sequence in 0..300_u64 {
            cache
                .commit_stream_payload(2_001, Bytes::from(vec![sequence as u8; 64]))
                .await
                .unwrap();
        }
        assert!(cache.get_init_for_stream_id(2_001).await.is_none());
        assert_eq!(
            cache.state.read().await.stream_init_scanned.get(&2_001),
            Some(&299)
        );
        // New parts arrive. Only they are looked at.
        for sequence in 300..310_u64 {
            cache
                .commit_stream_payload(2_001, Bytes::from(vec![sequence as u8; 64]))
                .await
                .unwrap();
        }
        assert!(cache.get_init_for_stream_id(2_001).await.is_none());
        assert_eq!(
            cache.state.read().await.stream_init_scanned.get(&2_001),
            Some(&309)
        );
        // A stream that starts again is searched again.
        cache.forget_mesh_stream(2_001).await;
        assert!(!cache
            .state
            .read()
            .await
            .stream_init_scanned
            .contains_key(&2_001));
    }

    #[tokio::test]
    async fn a_copy_that_fills_newest_first_never_grows_at_its_front() {
        let distributor = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        let edge = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        commit_stamped_video(&distributor, 36).await;

        // The warm-up of a new copy sends the newest parts first: the open
        // segment 1003 arrives before anything else.
        for slot in (30..36).rev() {
            deliver_mesh_part(&distributor, &edge, 77, slot).await;
        }
        // Parts of an open segment are not a playlist that a player accepts.
        assert!(!edge.state.read().await.playlist_is_playable(77));
        assert!(
            !edge
                .wait_for_playlist_copy(77, Duration::from_millis(30))
                .await
        );

        // Segment 1002 arrives. The playlist has a whole segment now.
        for slot in (20..30).rev() {
            deliver_mesh_part(&distributor, &edge, 77, slot).await;
        }
        assert!(
            edge.wait_for_playlist_copy(77, Duration::from_millis(30))
                .await
        );
        let first = edge.playlist_for_stream_id(77).await;
        assert!(first.contains("#EXT-X-MEDIA-SEQUENCE:1002\n"));
        assert!(first.contains("seg1002.mp4"));

        // Older segments still arrive. The playlist that a reader has seen
        // does not grow at its front: the Media Sequence Number stays.
        for slot in (0..20).rev() {
            deliver_mesh_part(&distributor, &edge, 77, slot).await;
        }
        let later = edge.playlist_for_stream_id(77).await;
        assert!(later.contains("#EXT-X-MEDIA-SEQUENCE:1002\n"));
        assert!(!later.contains("seg1001.mp4"));
        // The older parts are in the cache for a reader that asks for them.
        assert!(edge.get_segment_for_stream_id(77, 1_001).await.is_some());
    }

    #[tokio::test]
    async fn a_segment_that_left_the_playlist_can_still_be_fetched() {
        let cache = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        // Seven target durations are the playlist. Three more are kept.
        commit_stamped_video(&cache, 200).await;
        let playlist = cache.playlist_for_stream_id(77).await;
        let first_listed = playlist
            .lines()
            .find_map(|line| line.strip_prefix("#EXT-X-MEDIA-SEQUENCE:"))
            .and_then(|value| value.parse::<u64>().ok())
            .unwrap();
        assert!(first_listed > 1_002, "{first_listed}");
        assert!(!playlist.contains(&format!("seg{}.mp4", first_listed - 1)));
        assert!(cache
            .get_segment_for_stream_id(77, first_listed - 1)
            .await
            .is_some());
        assert!(cache
            .get_segment_for_stream_id(77, first_listed - 2)
            .await
            .is_some());
        // Much older media has gone.
        assert!(cache.get_segment_for_stream_id(77, 1_000).await.is_none());
    }

    #[tokio::test]
    async fn a_neighbouring_region_is_the_last_pathway_and_sends_the_reader_to_its_cache() {
        let (router, mesh) = entry_point_for_tests(vec![
            reader_cache_snapshot_for_tests("edge-b", 200, Some(500)),
            reader_cache_snapshot_for_tests("edge-c", 0, None),
        ])
        .await;
        let router = router.with_failover_entries(&[
            "us-east=https://entry.us-east.example:19444/".to_owned(),
            "not a name=https://ignored.example".to_owned(),
        ]);
        let master = body_text(get_for_tests(&router, "/live/801/master.m3u8?sid=reader-1").await);
        let variants = master
            .lines()
            .filter(|line| !line.starts_with('#'))
            .collect::<Vec<_>>();
        // The caches of this region first, the neighbour last.
        assert_eq!(variants[0], "https://edge-b.example/live/801/stream.m3u8");
        assert_eq!(
            variants.last().copied(),
            Some("https://entry.us-east.example:19444/live/801/stream.m3u8?assign=1&sid=reader-1")
        );
        assert!(master.contains("PATHWAY-ID=\"us-east\""));
        assert!(!master.contains("ignored.example"));
        let steering = master
            .lines()
            .find(|line| line.starts_with("#EXT-X-CONTENT-STEERING:"))
            .unwrap();
        assert!(steering.contains(",us-east\""), "{steering}");

        // The steering manifest keeps the neighbour as the last pathway.
        let uri = "/live/801/steering.json?sid=reader-1&p=edge-b,edge-c,test-node,us-east";
        let manifest: serde_json::Value =
            serde_json::from_slice(&get_for_tests(&router, uri).await.body.unwrap()).unwrap();
        let priority = manifest["PATHWAY-PRIORITY"].as_array().unwrap();
        assert_eq!(priority.last().unwrap(), "us-east");
        assert_eq!(priority[0], "edge-b");

        // The entry point of the neighbour is asked for the playlist itself
        // and sends the reader to the cache that it assigns.
        let request = "/live/801/stream.m3u8?assign=1&sid=far-reader&_HLS_msn=4";
        let redirect = get_for_tests(&router, request).await;
        assert_eq!(redirect.status, StatusCode::TEMPORARY_REDIRECT);
        assert!(redirect.headers.iter().any(|(name, value)| {
            name == "location"
                && value == "https://edge-b.example/live/801/stream.m3u8?sid=far-reader&_HLS_msn=4"
        }));
        mesh.shutdown();
    }

    #[tokio::test]
    async fn a_regional_cache_answers_404_for_a_stream_that_its_region_does_not_have() {
        let (mut router, mesh) = entry_point_for_tests(vec![reader_cache_snapshot_for_tests(
            "edge-b",
            100,
            Some(500),
        )])
        .await;
        router.cache_mesh_role = CacheMeshRole::Distributor;
        // Stream 801 is advertised by a cache of the region.
        let known = get_for_tests(&router, "/live/801/master.m3u8?sid=reader").await;
        assert_eq!(known.status, StatusCode::OK);
        for path in ["/live/999/master.m3u8?sid=reader", "/live/999/stream.m3u8"] {
            let started = Instant::now();
            let unknown = get_for_tests(&router, path).await;
            assert_eq!(unknown.status, StatusCode::NOT_FOUND, "{path}");
            assert!(started.elapsed() < Duration::from_millis(500), "{path}");
        }
        mesh.shutdown();
    }

    #[tokio::test]
    async fn a_stamped_stream_keeps_six_whole_segments_whatever_one_part_lasts() {
        let cache = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        commit_stamped_video(&cache, 10).await;
        // One part of two seconds, as a source that stalls produces. Without
        // the stamp it shrank the window of the stream to six parts for good.
        cache
            .commit_stream_payload(
                77,
                encode_test_stamped_fmp4_part(
                    77,
                    5,
                    10,
                    true,
                    2_000,
                    Some(PartStamp {
                        msn: 1_001,
                        part: 0,
                        part_target_us: 208_000,
                        target_duration_us: 2_000_000,
                    }),
                ),
            )
            .await
            .unwrap();
        let state = cache.state.read().await;
        // Seven segments of 2 s in parts of 208 ms, with room for the short
        // part that ends each segment.
        let window = state.stream_window_parts(77, 2_400);
        assert!((80..=100).contains(&window), "{window}");
        // An audio stream with 5 ms parts keeps the configured window.
        assert_eq!(state.stream_window_parts(2_001, 2_400), 2_400);
    }

    #[tokio::test]
    async fn a_reload_too_far_ahead_is_refused_and_one_that_never_arrives_ends() {
        let cache = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));
        // Segments 1000 to 1002 are whole. Segment 1003 has six parts.
        commit_stamped_video(&cache, 36).await;
        let position = |msn: u64, part: Option<usize>| HlsReloadPosition { msn, part };
        let state = |msn, part| {
            let cache = Arc::clone(&cache);
            async move {
                cache
                    .hls_reload_position_state(77, position(msn, part))
                    .await
            }
        };
        assert_eq!(state(1_003, Some(5)).await, HlsReloadOutcome::Ready);
        // The next part and the next segment are waited for.
        assert_eq!(state(1_003, Some(6)).await, HlsReloadOutcome::TimedOut);
        assert_eq!(state(1_004, None).await, HlsReloadOutcome::TimedOut);
        // An old position returns at once.
        assert_eq!(state(999, Some(0)).await, HlsReloadOutcome::Ready);
        // Two segments past the open one, or more than three seconds of
        // parts ahead, is refused.
        assert_eq!(state(1_005, None).await, HlsReloadOutcome::TooFarAhead);
        assert_eq!(state(1_003, Some(40)).await, HlsReloadOutcome::TooFarAhead);

        let get = |uri: &'static str| {
            let router = router.clone();
            async move {
                let started = Instant::now();
                let request = Request::builder()
                    .method(Method::GET)
                    .uri(uri)
                    .body(())
                    .unwrap();
                (
                    router.route(request).await.unwrap().status,
                    started.elapsed(),
                )
            }
        };
        let (status, took) = get("/live/77/stream.m3u8?_HLS_msn=1005").await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert!(took < Duration::from_millis(500));
        // `_HLS_part` needs `_HLS_msn`.
        let (status, _) = get("/live/77/stream.m3u8?_HLS_part=2").await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        let (status, _) = get("/live/77/stream.m3u8?_HLS_msn=1003&_HLS_part=5").await;
        assert_eq!(status, StatusCode::OK);

        // A part that the playlist does not name, and will not name soon, is
        // not waited for. The part that the playlist hints is.
        assert!(cache.part_request_may_wait(77, 36).await);
        assert!(cache.part_request_may_wait(77, 40).await);
        assert!(!cache.part_request_may_wait(77, 999_999).await);
        let (status, took) = get("/live/77/part999999.mp4").await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert!(took < Duration::from_millis(500), "{took:?}");
        mesh.shutdown();
    }

    #[tokio::test]
    async fn a_reload_that_never_arrives_is_answered_503() {
        let cache = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        commit_stamped_video(&cache, 36).await;
        // The stream has stopped. The wait ends after three target durations.
        let started = Instant::now();
        let outcome = cache
            .wait_for_hls_reload_position(
                77,
                HlsReloadPosition {
                    msn: 1_003,
                    part: Some(6),
                },
            )
            .await;
        assert_eq!(outcome, HlsReloadOutcome::TimedOut);
        let waited = started.elapsed();
        assert!(
            (Duration::from_millis(5_900)..Duration::from_millis(7_500)).contains(&waited),
            "{waited:?}"
        );
    }

    /// Copy one stored part from a distributor cache to an edge cache, as the
    /// cache mesh does, and record its playlist entry.
    async fn deliver_mesh_part(from: &LiveTsCache, to: &LiveTsCache, stream_id: u64, slot: usize) {
        let (bytes, _) = from
            .chunk_cache
            .get_for_stream_id(stream_id, slot)
            .await
            .unwrap();
        to.chunk_cache
            .add_for_stream_id(stream_id, slot, bytes)
            .await
            .unwrap();
        to.observe_mesh_part(stream_id, slot, None).await.unwrap();
    }

    #[tokio::test]
    async fn mesh_fed_edge_renders_the_playlist_of_its_distributor() {
        let distributor = LiveTsCache::new(1, Duration::from_millis(250), 4, 16, 64).await;
        let edge = LiveTsCache::new(1, Duration::from_millis(250), 4, 16, 64).await;
        for sequence in 0..14_u64 {
            distributor
                .commit_stream_payload(
                    77,
                    encode_test_published_fmp4_part(77, 5, sequence, sequence % 4 == 0, 250),
                )
                .await
                .unwrap();
        }
        // A new copy is warmed newest part first. The parts of a segment
        // arrive before the key frame that starts it.
        for slot in (0..14).rev() {
            deliver_mesh_part(&distributor, &edge, 77, slot).await;
        }

        let at_distributor = distributor.playlist_for_stream_id(77).await;
        let at_edge = edge.playlist_for_stream_id(77).await;
        assert_eq!(at_edge, at_distributor);
        assert!(at_edge.contains("#EXT-X-INDEPENDENT-SEGMENTS"));
        assert!(at_edge.contains("#EXT-X-PART:DURATION=0.250,URI=\"part12.mp4\",INDEPENDENT=YES"));
        assert!(at_edge.contains("#EXT-X-PART:DURATION=0.250,URI=\"part13.mp4\"\n"));
        // The program date and time comes from the publication time that the
        // parts carry, not from the arrival time at each cache.
        assert!(at_edge.contains("#EXT-X-PROGRAM-DATE-TIME:2026-11-"));
        assert!(at_edge.contains("#EXTINF:1.000,\nseg1.mp4"));
        assert_eq!(
            edge.get_segment_for_stream_id(77, 1).await,
            distributor.get_segment_for_stream_id(77, 1).await
        );
        assert!(edge.get_segment_for_stream_id(77, 1).await.is_some());
        // A blocking playlist reload on the edge sees the parts.
        assert!(
            edge.hls_reload_position_available(
                77,
                HlsReloadPosition {
                    msn: 3,
                    part: Some(1)
                }
            )
            .await
        );
    }

    #[tokio::test]
    async fn a_part_is_listed_only_when_its_playlist_entry_is_known() {
        // The node is sized for 5 ms parts. The stream has 250 ms parts.
        let distributor = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        let edge = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        for sequence in 0..6_u64 {
            distributor
                .commit_stream_payload(
                    77,
                    encode_test_published_fmp4_part(77, 5, sequence, sequence % 4 == 0, 250),
                )
                .await
                .unwrap();
        }
        for slot in 0..5 {
            deliver_mesh_part(&distributor, &edge, 77, slot).await;
        }
        // Part 5 is in the cache, and its entry is not recorded yet.
        let (bytes, _) = distributor
            .chunk_cache
            .get_for_stream_id(77, 5)
            .await
            .unwrap();
        edge.chunk_cache
            .add_for_stream_id(77, 5, bytes)
            .await
            .unwrap();
        let playlist = edge.playlist_for_stream_id(77).await;
        assert!(playlist.contains("#EXT-X-PART:DURATION=0.250,URI=\"part4.mp4\",INDEPENDENT=YES"));
        assert!(
            !playlist.contains("URI=\"part5.mp4\"\n#EXT") && !playlist.contains("part5.mp4\","),
            "{playlist}"
        );
        assert!(!playlist.contains("DURATION=0.005"), "{playlist}");
        // The hint names the part that is not listed yet. It named part 6,
        // and a player then saw part 5 appear after a hint that skipped it.
        assert!(
            playlist.ends_with("#EXT-X-PRELOAD-HINT:TYPE=PART,URI=\"part5.mp4\"\n"),
            "{playlist}"
        );

        edge.observe_mesh_part(77, 5, None).await.unwrap();
        let playlist = edge.playlist_for_stream_id(77).await;
        assert!(playlist.contains("#EXT-X-PART:DURATION=0.250,URI=\"part5.mp4\"\n"));
        assert_eq!(playlist, distributor.playlist_for_stream_id(77).await);
    }

    #[tokio::test]
    async fn caches_that_join_a_stream_late_number_its_segments_alike() {
        let early = LiveTsCache::new(1, Duration::from_millis(250), 4, 8, 64).await;
        let late = LiveTsCache::new(1, Duration::from_millis(250), 4, 8, 64).await;
        for sequence in 0..40_u64 {
            let part = encode_test_published_fmp4_part(77, 5, sequence, sequence % 4 == 0, 250);
            early.commit_stream_payload(77, part).await.unwrap();
        }
        // The late cache receives only the last eight parts.
        for slot in (32..40).rev() {
            deliver_mesh_part(&early, &late, 77, slot).await;
        }
        let early_playlist = early.playlist_for_stream_id(77).await;
        assert!(early_playlist.contains("#EXT-X-MEDIA-SEQUENCE:8\n"));
        assert_eq!(late.playlist_for_stream_id(77).await, early_playlist);
    }

    #[test]
    fn segment_numbers_do_not_depend_on_arrival_order() {
        let record = |state: &mut LiveState, sequence: u64| {
            state.record_part_available(
                7,
                sequence,
                100,
                1_000 + sequence,
                Some(250),
                sequence % 4 == 0,
                true,
                None,
                64,
            );
        };
        let segments = |state: &LiveState| {
            state.stream_parts[&7]
                .iter()
                .map(|(sequence, part)| (*sequence, part.fmp4_segment_id))
                .collect::<Vec<_>>()
        };
        let mut in_order = LiveState::new();
        in_order.segment_seed_parts = 4;
        for sequence in 8..24 {
            record(&mut in_order, sequence);
        }
        let mut newest_first = LiveState::new();
        newest_first.segment_seed_parts = 4;
        for sequence in (8..24).rev() {
            record(&mut newest_first, sequence);
        }
        let mut shuffled = LiveState::new();
        shuffled.segment_seed_parts = 4;
        for sequence in [20, 21, 9, 8, 23, 12, 13, 22, 10, 16, 11, 17, 15, 14, 19, 18] {
            record(&mut shuffled, sequence);
        }
        let expected = (8..24_u64)
            .map(|sequence| (sequence, Some(sequence / 4)))
            .collect::<Vec<_>>();
        assert_eq!(segments(&in_order), expected);
        assert_eq!(segments(&newest_first), expected);
        assert_eq!(segments(&shuffled), expected);

        // Parts before the first key frame that a cache knows have no segment.
        let mut truncated = LiveState::new();
        truncated.segment_seed_parts = 4;
        for sequence in [10, 11, 12, 13] {
            record(&mut truncated, sequence);
        }
        assert_eq!(
            segments(&truncated),
            vec![(10, None), (11, None), (12, Some(3)), (13, Some(3))]
        );
    }

    /// The playout deadline is a length of time: one long part (20 ms in a
    /// stream of 1 ms parts) does not shrink 500 ms to 25 parts for the
    /// rest of the stream, and a hole is aged by the parts' durations.
    #[test]
    fn the_playout_floor_is_measured_in_time_not_in_longest_parts() {
        let mut state = LiveState::new();
        state.nominal_part_us = 1_000;
        let base_us = 1_000_000_000_u64;
        let mut at_us = base_us;
        for sequence in 0..2_000_u64 {
            // Part 100 is 20 ms long; the others 1 ms. Part 1_990 is a hole.
            let duration_us = if sequence == 100 { 20_000 } else { 1_000 };
            at_us += duration_us;
            if sequence == 1_990 {
                continue;
            }
            state.record_part_available(
                7,
                sequence,
                100,
                at_us,
                Some(duration_us as u32),
                false,
                false,
                None,
                1_000_000,
            );
            state.record_part_published(7, sequence, Some(at_us));
        }
        assert_eq!(state.stream_part_us(7), 20_000);
        let head = 1_999;
        // Everyone at the head: nothing to look for.
        assert_eq!(state.playout_floor(7, head, 500_000, head), head - 25);
        // A subscriber 300 parts (300 ms) behind is within the deadline:
        // the count of longest parts would have moved it to head - 25.
        assert_eq!(
            state.playout_floor(7, head, 500_000, head - 300),
            head - 300
        );
        // One 800 ms behind is moved to the part 500 ms behind the head.
        assert_eq!(
            state.playout_floor(7, head, 500_000, head - 800),
            head - 500
        );
        // A hole is aged by the part after it.
        assert_eq!(state.part_age_us(7, 1_990, head), Some(9_000));
        assert_eq!(state.part_age_us(7, head, head), Some(0));
        assert_eq!(state.part_age_us(7, 1_500, head), Some(499_000));
        assert_eq!(state.part_age_us(7, 1_500, 5_000), None);
        // Without records: the count of longest parts, as before.
        assert_eq!(state.playout_floor(8, 1_000, 500_000, 0), 500);
    }

    #[tokio::test]
    async fn edge_copy_restarts_when_the_source_starts_a_new_publication() {
        let distributor = LiveTsCache::new(1, Duration::from_millis(250), 4, 16, 64).await;
        let edge = LiveTsCache::new(1, Duration::from_millis(250), 4, 16, 64).await;
        for sequence in 0..12_u64 {
            distributor
                .commit_stream_payload(
                    77,
                    encode_test_published_fmp4_part(77, 5, sequence, sequence % 4 == 0, 250),
                )
                .await
                .unwrap();
            deliver_mesh_part(&distributor, &edge, 77, sequence as usize).await;
        }
        assert_eq!(edge.stream_position_for_id(77).await.unwrap().1, 11);

        // The contributor restarts. Its new publication counts from zero.
        for sequence in 0..2_u64 {
            distributor
                .commit_stream_payload(
                    77,
                    encode_test_published_fmp4_part(77, 6, sequence, sequence % 4 == 0, 250),
                )
                .await
                .unwrap();
            deliver_mesh_part(&distributor, &edge, 77, sequence as usize).await;
        }
        assert_eq!(edge.stream_position_for_id(77).await.unwrap().1, 1);
        assert_eq!(
            edge.playlist_for_stream_id(77).await,
            distributor.playlist_for_stream_id(77).await
        );
    }

    #[tokio::test]
    async fn a_node_sized_for_audio_parts_keeps_a_time_window_of_video_parts() {
        // The node is configured for 5 ms audio parts and a 12 s window.
        let cache = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        for sequence in 0..400_u64 {
            cache
                .commit_stream_payload(
                    77,
                    encode_test_published_fmp4_part(77, 5, sequence, sequence % 8 == 0, 250),
                )
                .await
                .unwrap();
        }
        // 12 s of 250 ms parts is 48 parts, not 2,400.
        assert_eq!(cache.window_parts_for(77).await, 48);
        assert_eq!(cache.window_parts_for(2001).await, 2_400);
        let playlist = cache.playlist_for_stream_id(77).await;
        assert!(playlist.contains("part399.mp4"));
        assert!(playlist.contains("seg45.mp4"));
        assert!(!playlist.contains("seg43.mp4"), "{playlist}");
        assert_eq!(
            cache.state.read().await.stream_parts[&77].len(),
            48,
            "playlist entries are kept for one window"
        );
        // The ring keeps four windows of the stream and releases older parts.
        assert!(cache.chunk_cache.get_for_stream_id(77, 399).await.is_some());
        assert!(cache.chunk_cache.get_for_stream_id(77, 208).await.is_some());
        assert!(cache.chunk_cache.get_for_stream_id(77, 207).await.is_none());
        assert!(cache.chunk_cache.get_for_stream_id(77, 0).await.is_none());
        // The bit rate is measured over the window: four 250 ms parts of about
        // this size each second. A key-frame part also carries the init.
        let part_bytes = cache.state.read().await.stream_parts[&77][&399].bytes as u64;
        let rate = cache.playlist_bitrate_bps(77).await.unwrap();
        assert!(
            (part_bytes * 32..part_bytes * 40).contains(&rate),
            "{rate} bit/s for parts of {part_bytes} bytes"
        );
        // A copy that holds less than four seconds has no measured rate yet.
        let warming = LiveTsCache::new(1, Duration::from_millis(5), 200, 2_400, 64).await;
        for sequence in 0..15_u64 {
            warming
                .commit_stream_payload(
                    77,
                    encode_test_published_fmp4_part(77, 5, sequence, sequence % 8 == 0, 250),
                )
                .await
                .unwrap();
        }
        assert_eq!(warming.playlist_bitrate_bps(77).await, None);
        warming
            .commit_stream_payload(77, encode_test_published_fmp4_part(77, 5, 15, false, 250))
            .await
            .unwrap();
        assert!(warming.playlist_bitrate_bps(77).await.is_some());
        // The gap hold of one second is four video parts, not 200.
        assert_eq!(cache.state.read().await.stream_part_us(77), 250_000);
        assert_eq!(cache.state.read().await.stream_part_us(2001), 5_000);
    }

    #[test]
    fn playlist_demand_opens_renews_and_releases() {
        let demand = PlaylistDemand::new(PlaylistDemandConfig {
            enabled: true,
            lease: Duration::from_millis(3_000),
            idle: Duration::from_millis(10_000),
            warm_parts: 8,
            max_playlists: 2,
        });
        assert!(demand.touch(7, 1_000).new);
        assert!(!demand.touch(7, 1_200).new);
        assert_eq!(demand.touch(7, 1_200).opened_unix_ms, 1_000);
        // A third of the lease after the subscribe, the renewal is due once.
        assert!(demand.take_renewals(1_900).is_empty());
        assert_eq!(demand.take_renewals(2_000), vec![7]);
        assert!(demand.take_renewals(2_100).is_empty());
        // Requests keep the playlist. Ten seconds without one release it.
        demand.touch(7, 9_000);
        assert!(demand.take_idle(18_999).is_empty());
        assert_eq!(demand.snapshot(18_999)[0].idle_ms, 9_999);
        assert_eq!(demand.take_idle(19_000), vec![7]);
        assert!(demand.snapshot(19_000).is_empty());
        assert!(demand.touch(7, 20_000).new);
        assert_eq!(demand.subscriptions_opened.load(Ordering::Relaxed), 2);
        assert_eq!(demand.subscriptions_released.load(Ordering::Relaxed), 1);

        // The edge holds two playlists at most. A request for a third is
        // refused and does not replace a playlist that has readers.
        assert!(demand.touch(8, 20_000).new);
        let third = demand.touch(9, 20_000);
        assert!(third.refused && !third.new);
        assert!(!demand.touch(7, 20_100).refused);
        assert_eq!(demand.snapshot(20_100).len(), 2);
        assert_eq!(demand.subscriptions_refused.load(Ordering::Relaxed), 1);
        // When one is released the third can be held.
        demand.touch(7, 25_000);
        assert_eq!(demand.take_idle(30_100), vec![8]);
        assert!(demand.touch(9, 30_100).new);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn edge_holds_a_playlist_only_while_it_has_readers() {
        use tokio::time::timeout;

        let distributor_addr = unused_loopback_addr();
        let edge_addr = unused_loopback_addr();
        let distributor_cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 16, 64).await;
        let edge_cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 16, 64).await;

        let mut distributor_config = CacheMeshConfig::new("dist-a", "uk", distributor_addr)
            .with_peer(edge_addr)
            .with_same_region_only(true)
            .with_role(CacheMeshRole::Distributor)
            .with_replication(ReplicationMode::Demand)
            .with_subscription_lease(Duration::from_millis(900));
        distributor_config.sync_interval = Duration::from_millis(10);
        distributor_config.announce_interval = Duration::from_millis(100);
        let distributor_mesh = CacheMesh::new(
            Arc::clone(&distributor_cache.chunk_cache),
            distributor_config,
        )
        .start()
        .await
        .unwrap();

        let (applied_tx, applied_rx) = mpsc::unbounded_channel();
        let mut edge_config = CacheMeshConfig::new("edge-1", "uk", edge_addr)
            .with_peer(distributor_addr)
            .with_same_region_only(true)
            .with_role(CacheMeshRole::Edge)
            .with_replication(ReplicationMode::Demand)
            .with_subscription_lease(Duration::from_millis(900))
            .with_applied_tx(applied_tx);
        edge_config.sync_interval = Duration::from_millis(10);
        edge_config.announce_interval = Duration::from_millis(100);
        let edge_mesh = Arc::new(
            CacheMesh::new(Arc::clone(&edge_cache.chunk_cache), edge_config)
                .start()
                .await
                .unwrap(),
        );
        let demand = PlaylistDemand::new(PlaylistDemandConfig {
            enabled: true,
            lease: Duration::from_millis(900),
            idle: Duration::from_millis(1_200),
            warm_parts: 16,
            max_playlists: MAX_EDGE_PLAYLISTS,
        });
        let (shutdown_tx, shutdown_rx) = watch::channel(());
        let router = app_router_for_tests(Arc::clone(&edge_cache), Arc::clone(&edge_mesh))
            .with_playlist_demand(demand.clone());
        tokio::spawn(run_mesh_applied_parts(
            Arc::clone(&edge_cache),
            router.edge_load.clone(),
            applied_rx,
            None,
            shutdown_rx.clone(),
        ));
        tokio::spawn(run_playlist_demand(
            Arc::clone(&edge_cache),
            Arc::clone(&edge_mesh),
            router.edge_load.clone(),
            demand.clone(),
            shutdown_rx,
        ));

        // Two playlists are live at the distributor.
        for sequence in 0..8_u64 {
            for stream_id in [77_u64, 78] {
                distributor_cache
                    .commit_stream_payload(
                        stream_id,
                        encode_test_published_fmp4_part(
                            stream_id,
                            5,
                            sequence,
                            sequence % 4 == 0,
                            250,
                        ),
                    )
                    .await
                    .unwrap();
            }
        }
        // The edge must know its parent before a reader arrives.
        timeout(Duration::from_secs(3), async {
            while edge_mesh.parents_for(77).await.is_empty()
                || distributor_mesh.peers().await.is_empty()
            {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .unwrap();
        tokio::time::sleep(Duration::from_millis(300)).await;
        assert!(edge_cache.stream_position_for_id(77).await.is_none());
        assert!(edge_cache.stream_position_for_id(78).await.is_none());

        // A reader asks the edge for playlist 77. The edge subscribes, the
        // copy is warmed, and the answer is the playlist of the distributor.
        let playlist_request = || {
            Request::builder()
                .method(Method::GET)
                .uri("/live/77/stream.m3u8")
                .header("CMCD-Session", "sid=\"reader-1\"")
                .body(())
                .unwrap()
        };
        let response = router.route(playlist_request()).await.unwrap();
        assert_eq!(response.status, StatusCode::OK);
        // The reader keeps reloading while the copy warms.
        let mut warmed = false;
        for _ in 0..100 {
            let response = router.route(playlist_request()).await.unwrap();
            assert_eq!(response.status, StatusCode::OK);
            if String::from_utf8(response.body.unwrap().to_vec()).unwrap()
                == distributor_cache.playlist_for_stream_id(77).await
            {
                warmed = true;
                break;
            }
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
        assert!(
            warmed,
            "the edge copy did not reach the playlist of the distributor\n--- edge\n{}\n--- distributor\n{}",
            edge_cache.playlist_for_stream_id(77).await,
            distributor_cache.playlist_for_stream_id(77).await
        );
        // The playlist without readers stays at the distributor.
        assert!(edge_cache.stream_position_for_id(78).await.is_none());
        assert_eq!(edge_mesh.subscribed_streams(), vec![77]);
        let replication = router.cache_replication_snapshot();
        assert_eq!(replication.mode, "demand");
        assert_eq!(replication.subscribed_playlists, vec![77]);

        // The reader keeps reading for longer than the lease. Renewals keep
        // the live parts coming.
        for sequence in 8..14_u64 {
            distributor_cache
                .commit_stream_payload(
                    77,
                    encode_test_published_fmp4_part(77, 5, sequence, sequence % 4 == 0, 250),
                )
                .await
                .unwrap();
            let part = router
                .route(
                    Request::builder()
                        .method(Method::GET)
                        .uri(format!("/live/77/part{sequence}.mp4"))
                        .header("CMCD-Session", "sid=\"reader-1\"")
                        .body(())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(part.status, StatusCode::OK, "part {sequence}");
            tokio::time::sleep(Duration::from_millis(250)).await;
        }
        assert_eq!(distributor_mesh.served_subscriptions().len(), 1);

        // The reader leaves. After the idle period the edge releases the
        // playlist, the distributor stops pushing it, and the copy is gone.
        timeout(Duration::from_secs(5), async {
            while edge_cache.stream_position_for_id(77).await.is_some()
                || !distributor_mesh.served_subscriptions().is_empty()
            {
                tokio::time::sleep(Duration::from_millis(50)).await;
            }
        })
        .await
        .expect("the idle playlist was not released");
        distributor_cache
            .commit_stream_payload(77, encode_test_published_fmp4_part(77, 5, 14, false, 250))
            .await
            .unwrap();
        tokio::time::sleep(Duration::from_millis(300)).await;
        assert!(edge_cache.stream_position_for_id(77).await.is_none());
        assert!(edge_mesh.subscribed_streams().is_empty());
        assert_eq!(demand.subscriptions_released.load(Ordering::Relaxed), 1);

        let _ = shutdown_tx.send(());
        distributor_mesh.shutdown();
        edge_mesh.shutdown();
    }

    /// A telemetry snapshot of another reader cache of the test region.
    fn reader_cache_snapshot_for_tests(
        node_id: &str,
        load_permille: u32,
        head_part: Option<u64>,
    ) -> MeshSnapshot {
        let mut snapshot = telemetry_snapshot_for_tests(
            node_id,
            "test-region",
            "test-continent",
            51.6,
            -0.2,
            Vec::new(),
            1,
        );
        let mut edge = EdgeServiceSnapshot::from_node(
            &snapshot.node,
            Some(format!("https://{node_id}.example/live")),
            "edge",
            EdgeLoadSnapshot::default(),
        );
        edge.load_permille = load_permille;
        edge.playlists = head_part
            .map(|head_part| PlaylistHolding {
                request_rate: None,
                stream_id: 801,
                head_part,
                bitrate_bps: Some(16_000_000),
                sessions: 3,
                video: false,
            })
            .into_iter()
            .collect();
        snapshot.edge_service = Some(edge);
        snapshot
    }

    async fn entry_point_for_tests(
        remotes: Vec<MeshSnapshot>,
    ) -> (AppRouter, Arc<CacheMeshHandle>) {
        let cache = LiveTsCache::new(801, Duration::from_millis(50), 2, 6, 64).await;
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let telemetry = TelemetryAggregator::default();
        for remote in remotes {
            telemetry.ingest_snapshot(remote).await;
        }
        let router = app_router_for_tests_with_telemetry(cache, Arc::clone(&mesh), telemetry);
        (router, mesh)
    }

    async fn get_for_tests(router: &AppRouter, uri: &str) -> HandlerResponse {
        router
            .route(
                Request::builder()
                    .method(Method::GET)
                    .uri(uri)
                    .body(())
                    .unwrap(),
            )
            .await
            .unwrap()
    }

    fn body_text(response: HandlerResponse) -> String {
        String::from_utf8(response.body.unwrap().to_vec()).unwrap()
    }

    #[tokio::test]
    async fn entry_point_assigns_the_cache_that_holds_the_playlist() {
        let (router, mesh) = entry_point_for_tests(vec![
            reader_cache_snapshot_for_tests("edge-b", 200, Some(500)),
            reader_cache_snapshot_for_tests("edge-c", 0, None),
        ])
        .await;

        let master = get_for_tests(&router, "/live/801/master.m3u8?sid=reader-1").await;
        assert_eq!(master.status, StatusCode::OK);
        let master = body_text(master);
        let variants = master
            .lines()
            .filter(|line| !line.starts_with('#'))
            .collect::<Vec<_>>();
        // The holder is assigned. The other two caches are the failover order.
        assert_eq!(variants[0], "https://edge-b.example/live/801/stream.m3u8");
        assert_eq!(variants.len(), 3);
        // The steering request names the pathways that the reader was given.
        let steering = master
            .lines()
            .find(|line| line.starts_with("#EXT-X-CONTENT-STEERING:"))
            .unwrap();
        assert!(steering.contains("SERVER-URI=\"steering.json?sid=reader-1&p=edge-b,"));
        assert!(steering.ends_with(",PATHWAY-ID=\"edge-b\""));
        assert!(master.contains("PATHWAY-ID=\"edge-c\""));
        assert!(master.contains("PATHWAY-ID=\"test-node\""));

        // A cache that the reader was not given is defined as a clone of a
        // pathway that it has, with the host of the cache.
        let manifest = get_for_tests(
            &router,
            "/live/801/steering.json?sid=reader-1&p=edge-b&_HLS_pathway=edge-b",
        )
        .await;
        assert!(manifest
            .content_type
            .as_deref()
            .is_some_and(|kind| kind == "application/vnd.apple.steering-list"));
        let manifest: serde_json::Value = serde_json::from_slice(&manifest.body.unwrap()).unwrap();
        assert_eq!(manifest["PATHWAY-PRIORITY"][0], "edge-b");
        let clones = manifest["PATHWAY-CLONES"].as_array().unwrap();
        let clone = clones
            .iter()
            .find(|clone| clone["ID"] == "edge-c")
            .expect("edge-c is a clone");
        assert_eq!(clone["BASE-ID"], "edge-b");
        assert_eq!(clone["URI-REPLACEMENT"]["HOST"], "edge-c.example");
        assert!(manifest["PATHWAY-PRIORITY"]
            .as_array()
            .unwrap()
            .iter()
            .any(|pathway| pathway == "edge-c"));
        assert_eq!(
            manifest["RELOAD-URI"],
            "steering.json?sid=reader-1&p=edge-b"
        );

        let steering = get_for_tests(&router, "/live/801/steering.json?sid=reader-1").await;
        assert_eq!(steering.status, StatusCode::OK);
        assert_eq!(
            steering.content_type.as_deref(),
            Some("application/vnd.apple.steering-list")
        );
        let steering: serde_json::Value = serde_json::from_str(&body_text(steering)).unwrap();
        assert_eq!(steering["VERSION"], 1);
        assert_eq!(steering["TTL"], 5);
        assert_eq!(steering["RELOAD-URI"], "steering.json?sid=reader-1");
        assert_eq!(steering["PATHWAY-PRIORITY"][0], "edge-b");
        assert_eq!(steering["PATHWAY-PRIORITY"].as_array().unwrap().len(), 3);

        // The session keeps its cache when it asks again, even after another
        // cache has become the better first choice for a new session.
        let mut edge_b = reader_cache_snapshot_for_tests("edge-b", 700, Some(500));
        edge_b.updated_unix_ms = now_unix_ms();
        router.telemetry.ingest_snapshot(edge_b).await;
        router
            .telemetry
            .ingest_snapshot(reader_cache_snapshot_for_tests("edge-c", 0, Some(500)))
            .await;
        let again = body_text(get_for_tests(&router, "/live/801/master.m3u8?sid=reader-1").await);
        let first = again.lines().find(|line| !line.starts_with('#')).unwrap();
        assert_eq!(first, "https://edge-b.example/live/801/stream.m3u8");
        let other = body_text(get_for_tests(&router, "/live/801/master.m3u8?sid=reader-9").await);
        let first = other.lines().find(|line| !line.starts_with('#')).unwrap();
        assert_eq!(first, "https://edge-c.example/live/801/stream.m3u8");

        let api = get_for_tests(&router, "/api/assignment?stream=801&sid=reader-1").await;
        assert_eq!(api.status, StatusCode::OK);
        let api: serde_json::Value = serde_json::from_str(&body_text(api)).unwrap();
        assert_eq!(api["assigned"][0]["node_id"], "edge-b");
        assert_eq!(api["assigned"][0]["reason"], "sticky");
        assert_eq!(api["assigned"][1]["reason"], "alternate");
        let api = get_for_tests(&router, "/api/assignment?stream=801&sid=reader-7").await;
        let api: serde_json::Value = serde_json::from_str(&body_text(api)).unwrap();
        assert_eq!(api["assigned"][0]["node_id"], "edge-c");
        assert_eq!(api["assigned"][0]["reason"], "holds_playlist");
        assert_eq!(api["caches"].as_array().unwrap().len(), 3);
        // Phase AM item 10: a moving client's skip set is not assigned,
        // first or alternate.
        let api = get_for_tests(&router, "/api/assignment?stream=801&sid=reader-7&skip=edge-c").await;
        let api: serde_json::Value = serde_json::from_str(&body_text(api)).unwrap();
        let assigned: Vec<&str> = api["assigned"]
            .as_array()
            .unwrap()
            .iter()
            .map(|cache| cache["node_id"].as_str().unwrap())
            .collect();
        assert!(!assigned.is_empty() && !assigned.contains(&"edge-c"), "{api:#}");
        // Wave 8 review: a client that has left every cache of the region is
        // assigned in it again (the skip set is ignored), not refused.
        let all: Vec<String> = api["caches"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|cache| cache["node_id"].as_str().map(str::to_owned))
            .chain(["edge-b".to_owned(), "edge-c".to_owned()])
            .collect();
        let api = get_for_tests(
            &router,
            &format!("/api/assignment?stream=801&sid=reader-7&skip={}", all.join(",")),
        )
        .await;
        assert_eq!(api.status, StatusCode::OK);
        let api: serde_json::Value = serde_json::from_str(&body_text(api)).unwrap();
        assert!(
            !api["assigned"].as_array().unwrap().is_empty(),
            "{api:#}"
        );
        mesh.shutdown();
    }

    /// Wave 9 B: a node's client UDP port answers `ASSIGN` with the
    /// assignment of `/api/assignment` (the same caches in the same order),
    /// never with more bytes than the request, and not a short request.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_udp_assign_is_answered_with_the_assignment_of_the_https_api() {
        use av_mesh::client_udp::{Control, ASSIGN_REQUEST_BYTES};
        let (router, mesh) = entry_point_for_tests(vec![
            reader_cache_snapshot_for_tests("edge-b", 200, Some(500)),
            reader_cache_snapshot_for_tests("edge-c", 0, None),
        ])
        .await;
        let router = router.with_client_udp_port(Some(19_446));
        let start = |assign: bool| {
            let router = router.clone();
            async move {
                let socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
                let port = socket.local_addr().unwrap();
                let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
                config.assign = assign;
                let (shutdown_tx, shutdown_rx) = watch::channel(());
                let stats = Arc::clone(&router.edge_udp_stats);
                tokio::spawn(edge_udp::run_edge_udp(
                    edge_udp::EdgeSockets::single(socket),
                    router,
                    config,
                    stats,
                    Vec::new(),
                    shutdown_rx,
                ));
                (port, shutdown_tx)
            }
        };
        let (port, _shutdown) = start(true).await;
        let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let ask = |session: &str, skip: Vec<String>| {
            Control::Assign {
                stream_id: 801,
                nonce: 0x5eed,
                session: session.into(),
                skip,
                current: Vec::new(),
                paths: 1,
                spare: false,
                hold: Vec::new(),
                spare_held: None,
                place_at: None,
                token: None,
            }
            .encode()
        };
        let mut buf = vec![0_u8; 2_048];
        let request = ask("reader-u", Vec::new());
        assert_eq!(request.len(), ASSIGN_REQUEST_BYTES);
        client.send_to(&request, port).await.unwrap();
        // The token for the client's address, then the answer: no more
        // bytes in all than the request.
        let (len, _) = tokio::time::timeout(Duration::from_secs(5), client.recv_from(&mut buf))
            .await
            .expect("a token")
            .unwrap();
        let Some(Control::Token { token, .. }) = Control::decode(&buf[..len]) else {
            panic!("{:?}", String::from_utf8_lossy(&buf[..len]));
        };
        let token_len = len;
        let (len, _) = tokio::time::timeout(Duration::from_secs(5), client.recv_from(&mut buf))
            .await
            .expect("an answer")
            .unwrap();
        assert!(token_len + len <= request.len());
        let Some(Control::Assigned {
            stream_id,
            nonce,
            port: udp_port,
            caches,
            ..
        }) = Control::decode(&buf[..len])
        else {
            panic!("{:?}", String::from_utf8_lossy(&buf[..len]));
        };
        assert_eq!((stream_id, nonce, udp_port), (801, 0x5eed, Some(19_446)));
        // Wave 9 review: an unproven request charged nothing and is not
        // remembered; the client's confirmation with the token does both,
        // once; a confirmation with another token does neither.
        assert!(router.pending_load.lock().unwrap().is_empty());
        assert!(router.remembered_assignments.get("801/reader-u").is_none());
        let confirm = |token: u64, cache: &str| {
            Control::Assign {
                stream_id: 801,
                nonce: 0x5eed,
                session: "reader-u".into(),
                skip: Vec::new(),
                current: vec![cache.into()],
                paths: 1,
                spare: false,
                hold: Vec::new(),
                spare_held: None,
                place_at: None,
                token: Some(token),
            }
            .encode()
        };
        let taken = caches[0].node_id.clone();
        client
            .send_to(&confirm(token ^ 1, &taken), port)
            .await
            .unwrap();
        client.send_to(&confirm(token, &taken), port).await.unwrap();
        client.send_to(&confirm(token, &taken), port).await.unwrap();
        let stats = Arc::clone(&router.edge_udp_stats);
        let settled = async {
            while stats.assignment_confirms.load(Ordering::Relaxed)
                + stats.assignment_confirms_refused.load(Ordering::Relaxed)
                < 3
            {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        };
        tokio::time::timeout(Duration::from_secs(5), settled)
            .await
            .expect("the confirmations settle");
        assert_eq!(stats.assignment_confirms.load(Ordering::Relaxed), 1);
        assert_eq!(stats.assignment_confirms_refused.load(Ordering::Relaxed), 2);
        assert_eq!(
            router
                .remembered_assignments
                .get("801/reader-u")
                .map(|entry| entry.0.clone()),
            Some(vec![taken.clone()])
        );
        // Confirmations are not answered.
        assert!(
            tokio::time::timeout(Duration::from_millis(100), client.recv_from(&mut buf))
                .await
                .is_err()
        );
        // The HTTPS answer for the same session: the same caches in order.
        let api = get_for_tests(&router, "/api/assignment?stream=801&sid=reader-u").await;
        let api: serde_json::Value = serde_json::from_str(&body_text(api)).unwrap();
        let https: Vec<(String, String)> = api["assigned"]
            .as_array()
            .unwrap()
            .iter()
            .map(|cache| {
                (
                    cache["node_id"].as_str().unwrap().to_owned(),
                    cache["playback_base_url"].as_str().unwrap().to_owned(),
                )
            })
            .collect();
        let udp: Vec<(String, String)> = caches
            .iter()
            .map(|cache| (cache.node_id.clone(), cache.playback_base_url.clone()))
            .collect();
        assert_eq!(udp, https);
        assert!(udp.len() >= 2, "{udp:?}");
        assert!(caches.iter().all(|cache| !cache.failover));
        // A skip set is honoured as over HTTPS.
        let first = udp[0].0.clone();
        client
            .send_to(&ask("reader-v", vec![first.clone()]), port)
            .await
            .unwrap();
        let mut len = 0;
        for _ in 0..2 {
            len = tokio::time::timeout(Duration::from_secs(5), client.recv_from(&mut buf))
                .await
                .unwrap()
                .unwrap()
                .0;
        }
        match Control::decode(&buf[..len]) {
            Some(Control::Assigned { caches, .. }) => {
                assert!(!caches.is_empty() && caches.iter().all(|cache| cache.node_id != first))
            }
            other => panic!("{other:?}"),
        }
        assert_eq!(api["client_udp"]["assignments"], 1, "{api:#}");
        // A request without its padding is not answered.
        let short = String::from_utf8(ask("reader-w", Vec::new())).unwrap();
        let short = short.trim_end_matches('.').to_owned() + ".";
        client.send_to(short.as_bytes(), port).await.unwrap();
        assert!(
            tokio::time::timeout(Duration::from_millis(300), client.recv_from(&mut buf))
                .await
                .is_err()
        );
        assert_eq!(
            router.edge_udp_stats.assignments_dropped.load(Ordering::Relaxed),
            1
        );
        // --client-udp-assign false: not answered.
        let (off, _off_shutdown) = start(false).await;
        client.send_to(&ask("reader-x", Vec::new()), off).await.unwrap();
        assert!(
            tokio::time::timeout(Duration::from_millis(300), client.recv_from(&mut buf))
                .await
                .is_err()
        );
        mesh.shutdown();
    }

    /// A reader cache of the test region holding stream 801 at an audio
    /// bit rate (under --assignment-two-path-max-bps).
    fn audio_cache_snapshot_for_tests(
        node_id: &str,
        load_permille: u32,
        head_part: Option<u64>,
    ) -> MeshSnapshot {
        let mut snapshot = reader_cache_snapshot_for_tests(node_id, load_permille, head_part);
        if let Some(edge) = snapshot.edge_service.as_mut() {
            for playlist in &mut edge.playlists {
                playlist.bitrate_bps = Some(96_000);
            }
        }
        snapshot
    }

    async fn start_edge_udp_for_tests(
        router: &AppRouter,
        config: edge_udp::EdgeUdpConfig,
    ) -> (SocketAddr, watch::Sender<()>) {
        let socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let port = socket.local_addr().unwrap();
        let (shutdown_tx, shutdown_rx) = watch::channel(());
        tokio::spawn(edge_udp::run_edge_udp(
            edge_udp::EdgeSockets::single(socket),
            router.clone(),
            config,
            Arc::clone(&router.edge_udp_stats),
            Vec::new(),
            shutdown_rx,
        ));
        (port, shutdown_tx)
    }

    fn names_for_tests(list: &[&str]) -> Vec<String> {
        list.iter().map(|name| (*name).to_owned()).collect()
    }

    /// A UDP `ASSIGN` for stream 801 and its answer: the token, then
    /// `ASSIGNED`.
    #[allow(clippy::too_many_arguments)]
    async fn udp_assign_for_tests(
        client: &UdpSocket,
        edge: SocketAddr,
        session: &str,
        skip: &[&str],
        current: &[&str],
        hold: &[&str],
        paths: u8,
        spare: bool,
    ) -> (u64, av_mesh::client_udp::Control) {
        use av_mesh::client_udp::Control;
        let request = Control::Assign {
            stream_id: 801,
            nonce: 0x7a,
            session: session.into(),
            skip: names_for_tests(skip),
            current: names_for_tests(current),
            paths,
            spare,
            hold: names_for_tests(hold),
            spare_held: None,
            place_at: None,
            token: None,
        }
        .encode();
        client.send_to(&request, edge).await.unwrap();
        let mut buf = vec![0_u8; 2_048];
        let mut token = None;
        loop {
            let (len, _) =
                tokio::time::timeout(Duration::from_secs(5), client.recv_from(&mut buf))
                    .await
                    .expect("an answer")
                    .unwrap();
            match Control::decode(&buf[..len]) {
                Some(Control::Token { token: given, .. }) => token = Some(given),
                Some(answer @ Control::Assigned { .. }) => {
                    return (token.expect("the token comes first"), answer)
                }
                other => panic!("{other:?}"),
            }
        }
    }

    fn assigned_names(api: &serde_json::Value) -> Vec<String> {
        api["assigned"]
            .as_array()
            .unwrap()
            .iter()
            .map(|cache| cache["node_id"].as_str().unwrap().to_owned())
            .collect()
    }

    /// B 2.1, 2.2, 3.6: a listener that asks for two paths and a spare is
    /// given two holders as its legs and a third as its spare, over UDP and
    /// over HTTPS alike; HTTPS charges and remembers the legs, not the spare.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn an_assignment_for_two_paths_names_two_edges_and_a_spare() {
        use av_mesh::client_udp::Control;
        let (router, mesh) = entry_point_for_tests(vec![
            audio_cache_snapshot_for_tests("edge-b", 100, Some(500)),
            audio_cache_snapshot_for_tests("edge-c", 100, Some(500)),
            audio_cache_snapshot_for_tests("edge-d", 100, Some(500)),
        ])
        .await;
        let router = router.with_client_udp_port(Some(19_446));
        let (edge, _shutdown) =
            start_edge_udp_for_tests(&router, edge_udp::EdgeUdpConfig::with_defaults(1_200, 16))
                .await;
        let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let (_, answer) =
            udp_assign_for_tests(&client, edge, "pair-1", &[], &[], &[], 2, true).await;
        let Control::Assigned {
            caches,
            paths,
            spare,
            ..
        } = answer
        else {
            panic!("{answer:?}");
        };
        assert_eq!((paths, spare), (2, true));
        let udp = caches
            .iter()
            .take(3)
            .map(|cache| cache.node_id.clone())
            .collect::<Vec<_>>();
        let mut distinct = udp.clone();
        distinct.sort();
        distinct.dedup();
        assert_eq!(distinct, ["edge-b", "edge-c", "edge-d"], "{caches:?}");
        // Unproven: nothing charged or remembered.
        assert!(router.pending_assignments.is_empty());
        let api: serde_json::Value = serde_json::from_str(&body_text(
            get_for_tests(&router, "/api/assignment?stream=801&sid=pair-1&paths=2&spare=1").await,
        ))
        .unwrap();
        assert_eq!(api["paths"], 2, "{api:#}");
        assert_eq!(assigned_names(&api)[..3], udp[..], "{api:#}");
        assert_eq!(api["assigned"][1]["reason"], "second_path");
        assert_eq!(api["assigned"][2]["reason"], "spare");
        assert_eq!(api["spare"], udp[2].as_str());
        // HTTPS with a session charges and remembers each leg, not the
        // spare.
        assert!(router.pending_assignments.contains_key(&udp[0]));
        assert!(router.pending_assignments.contains_key(&udp[1]));
        assert!(!router.pending_assignments.contains_key(&udp[2]));
        assert_eq!(
            router
                .remembered_assignments
                .get("801/pair-1")
                .map(|entry| entry.0.clone()),
            Some(udp[..2].to_vec())
        );
        // One path asked: one leg, as before.
        let api: serde_json::Value = serde_json::from_str(&body_text(
            get_for_tests(&router, "/api/assignment?stream=801&sid=pair-2").await,
        ))
        .unwrap();
        assert_eq!(api["paths"], 1);
        assert!(api["spare"].is_null());
        assert_eq!(api["assigned"][1]["reason"], "alternate");
        mesh.shutdown();
    }

    /// B 3.6, 3.9: a playlist over --assignment-two-path-max-bps (a 4K
    /// feed) is given one leg whatever the listener asks; its spare still.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_playlist_over_the_bit_rate_gets_one_leg() {
        use av_mesh::client_udp::Control;
        assert_eq!(
            Args::try_parse_from(["av-mesh"])
                .unwrap()
                .assignment_two_path_max_bps,
            8_000_000
        );
        assert_eq!(
            Args::try_parse_from(["av-mesh", "--assignment-two-path-max-bps", "20000000"])
                .unwrap()
                .assignment_two_path_max_bps,
            20_000_000
        );
        // 16 Mbit/s.
        let (router, mesh) = entry_point_for_tests(vec![
            reader_cache_snapshot_for_tests("edge-b", 100, Some(500)),
            reader_cache_snapshot_for_tests("edge-c", 100, Some(500)),
            reader_cache_snapshot_for_tests("edge-d", 100, Some(500)),
        ])
        .await;
        let router = router.with_client_udp_port(Some(19_446));
        let api: serde_json::Value = serde_json::from_str(&body_text(
            get_for_tests(&router, "/api/assignment?stream=801&sid=video-1&paths=2&spare=1").await,
        ))
        .unwrap();
        assert_eq!(api["paths"], 1, "{api:#}");
        assert_eq!(api["why"], "bitrate", "B Y2: the reason of a short grant");
        assert_eq!(api["assigned"][1]["reason"], "spare");
        assert_eq!(api["spare"], api["assigned"][1]["node_id"]);
        // A listener that holds a leg of it is granted none more (B 3.9;
        // the integration's join of Y1 finding 7 and Z3).
        let held = api["assigned"][0]["node_id"].as_str().unwrap().to_owned();
        let api: serde_json::Value = serde_json::from_str(&body_text(
            get_for_tests(
                &router,
                &format!("/api/assignment?stream=801&sid=video-1&paths=1&hold={held}"),
            )
            .await,
        ))
        .unwrap();
        assert_eq!(api["paths"], 0, "{api:#}");
        assert_eq!(api["why"], "bitrate");
        let (edge, _shutdown) =
            start_edge_udp_for_tests(&router, edge_udp::EdgeUdpConfig::with_defaults(1_200, 16))
                .await;
        let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let (_, answer) =
            udp_assign_for_tests(&client, edge, "video-2", &[], &[], &[], 2, true).await;
        assert!(
            matches!(
                answer,
                Control::Assigned {
                    paths: 1,
                    spare: true,
                    why: Some(av_mesh::client_udp::ShortGrant::Bitrate),
                    ..
                }
            ),
            "{answer:?}"
        );
        // Raised over the bit rate: two legs.
        let mut router = router;
        router.assignment_policy.two_path_max_bps = 20_000_000;
        let api: serde_json::Value = serde_json::from_str(&body_text(
            get_for_tests(&router, "/api/assignment?stream=801&sid=video-3&paths=2").await,
        ))
        .unwrap();
        assert_eq!(api["paths"], 2, "{api:#}");
        assert!(api["why"].is_null(), "a full grant gives no reason");
        mesh.shutdown();
    }

    /// Review of B Y2, finding 1: a listener that holds a leg and asks for
    /// one more is told why none is granted, over UDP and HTTPS alike: the
    /// region's other edge drains (`one-edge`), or serves at full load
    /// (`gate`). The entry is itself the edge the listener holds.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_listener_granted_no_second_leg_hears_why() {
        use av_mesh::client_udp::{Control, ShortGrant};
        let mut draining = audio_cache_snapshot_for_tests("edge-c", 100, Some(500));
        draining.node.draining = true;
        if let Some(edge) = draining.edge_service.as_mut() {
            edge.draining = true;
        }
        let at_full = audio_cache_snapshot_for_tests("edge-c", 1_000, Some(500));
        for (other, why) in [(draining, ShortGrant::OneEdge), (at_full, ShortGrant::Gate)] {
            let (router, mesh) = entry_point_for_tests(vec![other]).await;
            let router = router.with_client_udp_port(Some(19_446));
            let (edge, _shutdown) = start_edge_udp_for_tests(
                &router,
                edge_udp::EdgeUdpConfig::with_defaults(1_200, 16),
            )
            .await;
            let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
            let (_, answer) =
                udp_assign_for_tests(&client, edge, "held-1", &[], &[], &["test-node"], 1, false)
                    .await;
            assert!(
                matches!(answer, Control::Assigned { paths: 0, why: Some(given), .. } if given == why),
                "{answer:?}"
            );
            let api: serde_json::Value = serde_json::from_str(&body_text(
                get_for_tests(
                    &router,
                    "/api/assignment?stream=801&sid=held-2&paths=1&hold=test-node",
                )
                .await,
            ))
            .unwrap();
            assert_eq!(api["paths"], 0, "{api:#}");
            assert_eq!(api["why"], why.word(), "{api:#}");
            mesh.shutdown();
        }
    }

    /// B 2.5: a UDP client that names the edge it left as `current` (the
    /// referee's client) is a mover: placed by headroom, away from that
    /// edge, and logged for the apportionment.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_udp_mover_that_names_its_old_edge_as_current_is_a_mover() {
        let (router, mesh) = entry_point_for_tests(vec![
            audio_cache_snapshot_for_tests("edge-b", 100, Some(500)),
            audio_cache_snapshot_for_tests("edge-c", 100, Some(500)),
        ])
        .await;
        let router = router.with_client_udp_port(Some(19_446));
        let movers = |router: &AppRouter| {
            router
                .recent_movers(Instant::now())
                .iter()
                .map(|(_, count)| *count)
                .sum::<u32>()
        };
        let api: serde_json::Value = serde_json::from_str(&body_text(
            get_for_tests(
                &router,
                "/api/assignment?stream=801&sid=mover-1&skip=edge-b&current=edge-b",
            )
            .await,
        ))
        .unwrap();
        let assigned = assigned_names(&api);
        assert!(!assigned.contains(&"edge-b".to_owned()), "{api:#}");
        assert_ne!(api["assigned"][0]["reason"], "sticky", "{api:#}");
        assert_eq!(movers(&router), 1);
        // The same over UDP (unproven: logged, not charged).
        let (edge, _shutdown) =
            start_edge_udp_for_tests(&router, edge_udp::EdgeUdpConfig::with_defaults(1_200, 16))
                .await;
        let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let charged = router.pending_assignments.len();
        let (_, answer) = udp_assign_for_tests(
            &client,
            edge,
            "mover-2",
            &["edge-b"],
            &["edge-b"],
            &[],
            1,
            false,
        )
        .await;
        let av_mesh::client_udp::Control::Assigned { caches, .. } = answer else {
            panic!("{answer:?}");
        };
        assert!(caches.iter().all(|cache| cache.node_id != "edge-b"), "{caches:?}");
        assert_eq!(movers(&router), 2);
        assert_eq!(router.pending_assignments.len(), charged);
        // An LL-HLS reader's current that it has not left still holds it.
        let api: serde_json::Value = serde_json::from_str(&body_text(
            get_for_tests(&router, "/api/assignment?stream=801&sid=reader-1&current=edge-b").await,
        ))
        .unwrap();
        assert_eq!(api["assigned"][0]["node_id"], "edge-b");
        assert_eq!(api["assigned"][0]["reason"], "sticky");
        mesh.shutdown();
    }

    /// B 2.1, 3.6: the legs a listener holds and keeps (`h=`, `hold=`) are
    /// never in its answer, as a leg, a spare or an alternate.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_replacement_is_never_an_edge_the_client_holds() {
        use av_mesh::client_udp::Control;
        let (router, mesh) = entry_point_for_tests(vec![
            audio_cache_snapshot_for_tests("edge-b", 100, Some(500)),
            audio_cache_snapshot_for_tests("edge-c", 100, Some(500)),
            audio_cache_snapshot_for_tests("edge-d", 100, Some(500)),
        ])
        .await;
        let router = router.with_client_udp_port(Some(19_446));
        for index in 0..20 {
            let api: serde_json::Value = serde_json::from_str(&body_text(
                get_for_tests(
                    &router,
                    &format!("/api/assignment?stream=801&sid=held-{index}&hold=edge-b&paths=1&spare=1"),
                )
                .await,
            ))
            .unwrap();
            assert!(!assigned_names(&api).contains(&"edge-b".to_owned()), "{api:#}");
            assert_eq!(api["paths"], 1, "{api:#}");
            assert_eq!(api["assigned"][0]["reason"], "second_path", "{api:#}");
            assert!(api["spare"].is_string(), "{api:#}");
            // Remembered with the leg it keeps: the confirmation does not
            // charge that one again.
            let remembered = router
                .remembered_assignments
                .get(&format!("801/held-{index}"))
                .map(|entry| entry.0.clone())
                .unwrap();
            assert_eq!(remembered[1], "edge-b");
        }
        let (edge, _shutdown) =
            start_edge_udp_for_tests(&router, edge_udp::EdgeUdpConfig::with_defaults(1_200, 16))
                .await;
        let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        for index in 0..20 {
            let (_, answer) = udp_assign_for_tests(
                &client,
                edge,
                &format!("held-udp-{index}"),
                &[],
                &[],
                &["edge-b", "edge-c"],
                0,
                true,
            )
            .await;
            let Control::Assigned {
                caches,
                paths,
                spare,
                ..
            } = answer
            else {
                panic!("{answer:?}");
            };
            assert_eq!((paths, spare), (0, true));
            assert_eq!(caches[0].node_id, "edge-d", "{caches:?}");
            assert!(
                caches
                    .iter()
                    .all(|cache| cache.node_id != "edge-b" && cache.node_id != "edge-c"),
                "{caches:?}"
            );
        }
        mesh.shutdown();
    }

    /// D 5 (seam to B): a listener that holds a leg and asks for another
    /// (`hold=`) is given an edge on another host than the leg it holds;
    /// with none eligible the same-host edge stands and
    /// `second_leg_same_host` counts the listener's answer, not an
    /// operator's look.
    #[tokio::test]
    async fn a_replacement_leg_avoids_the_host_of_the_leg_it_holds() {
        let on_host = |mut snapshot: MeshSnapshot, host: &str| {
            snapshot.edge_service.as_mut().unwrap().host = Some(host.to_owned());
            snapshot
        };
        let edges = |other_host_load: u32| {
            vec![
                on_host(audio_cache_snapshot_for_tests("edge-b", 100, Some(500)), "host-a"),
                on_host(audio_cache_snapshot_for_tests("edge-c", 100, Some(500)), "host-a"),
                on_host(
                    audio_cache_snapshot_for_tests("edge-d", other_host_load, Some(500)),
                    "host-b",
                ),
            ]
        };
        let ask = |router: &AppRouter, query: String| {
            let router = router.clone();
            async move {
                let api: serde_json::Value = serde_json::from_str(&body_text(
                    get_for_tests(&router, &format!("/api/assignment?stream=801&{query}")).await,
                ))
                .unwrap();
                api
            }
        };

        // The entry point is a candidate too: on host-a with the held leg.
        let (router, mesh) = entry_point_for_tests(edges(100)).await;
        let router = router.with_host_tag(Some("host-a".into()));
        for index in 0..20 {
            let api = ask(&router, format!("sid=apart-{index}&hold=edge-b&paths=1")).await;
            assert_eq!(assigned_names(&api)[0], "edge-d", "{api:#}");
            assert_eq!(api["assigned"][0]["host"], "host-b", "{api:#}");
            assert_eq!(api["second_leg_same_host"], 0, "{api:#}");
        }
        mesh.shutdown();

        // The edge on the other host over the gate: the sibling stands.
        let (router, mesh) = entry_point_for_tests(edges(990)).await;
        let router = router.with_host_tag(Some("host-a".into()));
        let api = ask(&router, "hold=edge-b&paths=1".into()).await;
        assert_ne!(assigned_names(&api)[0], "edge-d", "{api:#}");
        assert_eq!(api["assigned"][0]["host"], "host-a", "{api:#}");
        assert_eq!(api["second_leg_same_host"], 0, "an operator's look: {api:#}");
        let api = ask(&router, "sid=together-1&hold=edge-b&paths=1".into()).await;
        assert_ne!(assigned_names(&api)[0], "edge-d", "{api:#}");
        assert_eq!(api["assigned"][0]["host"], "host-a", "{api:#}");
        assert_eq!(api["second_leg_same_host"], 1, "{api:#}");
        mesh.shutdown();
    }

    /// B 3.6: a confirmation names every leg the listener holds; the entry
    /// point charges each leg it had not given the session and that the
    /// client did not say it kept, once, and remembers the legs.
    #[tokio::test]
    async fn the_confirmation_charges_each_new_leg_once() {
        let (router, mesh) = entry_point_for_tests(vec![
            reader_cache_snapshot_for_tests("edge-b", 100, Some(500)),
            reader_cache_snapshot_for_tests("edge-c", 100, Some(500)),
            reader_cache_snapshot_for_tests("edge-d", 100, Some(500)),
        ])
        .await;
        let charged = |node: &str| {
            router
                .pending_assignments
                .get(node)
                .map_or(0, |entry| entry.1)
        };
        let remembered = || {
            router
                .remembered_assignments
                .get("801/pair")
                .map(|entry| entry.0.clone())
                .unwrap_or_default()
        };
        let confirm = |current: &[&str], hold: &[&str], skip: &[&str]| {
            let router = router.clone();
            let (current, hold, skip) = (
                names_for_tests(current),
                names_for_tests(hold),
                names_for_tests(skip),
            );
            async move {
                router
                    .confirm_udp_assignment(801, "pair", &skip, &current, &hold)
                    .await
            }
        };
        let bps = 16_000_000;
        // A join: both legs charged.
        assert!(confirm(&["edge-b", "edge-c"], &[], &[]).await);
        assert_eq!((charged("edge-b"), charged("edge-c")), (bps, bps));
        assert_eq!(remembered(), ["edge-b", "edge-c"]);
        // Its repeat charges nothing.
        assert!(!confirm(&["edge-b", "edge-c"], &[], &[]).await);
        assert_eq!((charged("edge-b"), charged("edge-c")), (bps, bps));
        // edge-b drained: its replacement edge-d is charged, edge-c (kept)
        // is not; a mover is logged once.
        assert!(confirm(&["edge-c", "edge-d"], &["edge-c"], &["edge-b"]).await);
        assert_eq!(
            (charged("edge-b"), charged("edge-c"), charged("edge-d")),
            (bps, bps, bps)
        );
        assert_eq!(remembered(), ["edge-c", "edge-d"]);
        assert_eq!(router.recent_movers(Instant::now()), [("edge-d".to_owned(), 1)]);
        // A leg the client kept is not charged even when the entry point
        // has forgotten it.
        router.remembered_assignments.clear();
        assert!(!confirm(&["edge-c", "edge-d"], &["edge-c", "edge-d"], &[]).await);
        assert_eq!((charged("edge-c"), charged("edge-d")), (bps, bps));
        // A node outside the region is no leg.
        assert!(!confirm(&["elsewhere"], &[], &[]).await);
        mesh.shutdown();
    }

    /// B 3.6: a stream's UDP legs count as its sessions where an edge
    /// advertises its playlists, so a UDP-only stream gets its standby copy.
    #[tokio::test]
    async fn a_udp_only_stream_gets_its_standby_copy() {
        use av_mesh::client_udp::Control;
        let cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 32, 64).await;
        for sequence in 0..6_u64 {
            cache
                .commit_stream_payload(
                    77,
                    encode_test_canonical_fmp4_bundle_with_duration(
                        77,
                        sequence,
                        (sequence == 0).then_some(b"ftyp-fLaC-moov".as_slice()),
                        &[sequence as u8; 400],
                        Some(250),
                        true,
                    ),
                )
                .await
                .unwrap();
        }
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let mut router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));
        let socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let edge = socket.local_addr().unwrap();
        router.client_udp_port = Some(edge.port());
        let sessions = |snapshot: &MeshSnapshot| {
            snapshot
                .edge_service
                .as_ref()
                .unwrap()
                .playlists
                .iter()
                .find(|playlist| playlist.stream_id == 77)
                .map(|playlist| playlist.sessions)
        };
        let own = router.node.node_id.clone();
        let edges = vec![own.clone(), "edge-x".to_owned()];
        let wants = |sessions: u64| {
            wants_standby_copy(
                "edge-x",
                77,
                2,
                &[StandbyHolder {
                    node_id: own.clone(),
                    sessions,
                }],
                &edges,
            )
        };
        assert_eq!(sessions(&router.local_mesh_snapshot().await), Some(0));
        assert!(!wants(0));
        let (_shutdown_tx, shutdown_rx) = watch::channel(());
        tokio::spawn(edge_udp::run_edge_udp(
            edge_udp::EdgeSockets::single(socket),
            router.clone(),
            edge_udp::EdgeUdpConfig::with_defaults(1_200, 16),
            Arc::clone(&router.edge_udp_stats),
            Vec::new(),
            shutdown_rx,
        ));
        let mut clients = Vec::new();
        for _ in 0..2 {
            let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
            let answer = subscribe_udp_for_tests(&client, edge, Some(0)).await;
            assert!(matches!(answer, Control::Subscribed { .. }), "{answer:?}");
            clients.push(client);
        }
        let advertised = sessions(&router.local_mesh_snapshot().await).unwrap();
        assert_eq!(advertised, 2);
        assert!(wants(advertised));
        mesh.shutdown();
    }

    /// B 2.3: confirmations over --client-udp-assign-confirms-per-source
    /// are counted in `assignment_confirms_limited`, not as refused.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn confirmations_over_the_limit_are_counted_apart() {
        use av_mesh::client_udp::Control;
        assert_eq!(
            Args::try_parse_from(["av-mesh"])
                .unwrap()
                .client_udp_assign_confirms_per_source,
            64
        );
        assert_eq!(
            Args::try_parse_from(["av-mesh", "--client-udp-assign-confirms-per-source", "4096"])
                .unwrap()
                .client_udp_assign_confirms_per_source,
            4_096
        );
        let (router, mesh) = entry_point_for_tests(vec![
            audio_cache_snapshot_for_tests("edge-b", 100, Some(500)),
            audio_cache_snapshot_for_tests("edge-c", 100, Some(500)),
        ])
        .await;
        let router = router.with_client_udp_port(Some(19_446));
        let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
        config.assign_confirms_per_source = 3;
        let (edge, _shutdown) = start_edge_udp_for_tests(&router, config).await;
        let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let (token, _) = udp_assign_for_tests(&client, edge, "load-0", &[], &[], &[], 1, false).await;
        let confirm = |session: &str, token: u64| {
            Control::Assign {
                stream_id: 801,
                nonce: 0x7a,
                session: session.into(),
                skip: Vec::new(),
                current: vec!["edge-b".into()],
                paths: 1,
                spare: false,
                hold: Vec::new(),
                spare_held: None,
                place_at: None,
                token: Some(token),
            }
            .encode()
        };
        // Five listeners of one load host confirm in one second, and one
        // confirmation has a bad token.
        for index in 0..5 {
            client
                .send_to(&confirm(&format!("load-{index}"), token), edge)
                .await
                .unwrap();
        }
        client.send_to(&confirm("load-9", token ^ 1), edge).await.unwrap();
        let stats = Arc::clone(&router.edge_udp_stats);
        tokio::time::timeout(Duration::from_secs(5), async {
            while stats.assignment_confirms.load(Ordering::Relaxed)
                + stats.assignment_confirms_refused.load(Ordering::Relaxed)
                + stats.assignment_confirms_limited.load(Ordering::Relaxed)
                < 6
            {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("the confirmations settle");
        // Three in the one-second window, two over it; on a loaded machine
        // the window may turn between the five, and a fourth gets through.
        let confirmed = stats.assignment_confirms.load(Ordering::Relaxed);
        let limited = stats.assignment_confirms_limited.load(Ordering::Relaxed);
        assert_eq!(confirmed + limited, 5);
        assert!((3..=4).contains(&confirmed), "{confirmed} confirmed");
        assert_eq!(stats.assignment_confirms_refused.load(Ordering::Relaxed), 1);
        let api: serde_json::Value = serde_json::from_str(&body_text(
            get_for_tests(&router, "/api/assignment?stream=801").await,
        ))
        .unwrap();
        assert_eq!(api["client_udp"]["assignment_confirms_limited"], limited, "{api:#}");
        mesh.shutdown();
    }

    /// The first leg of an HTTPS answer: its node, reason and load.
    fn first_leg(api: &serde_json::Value) -> (String, String, u64) {
        let leg = &api["assigned"][0];
        (
            leg["node_id"].as_str().unwrap_or_default().to_owned(),
            leg["reason"].as_str().unwrap_or_default().to_owned(),
            leg["load_permille"].as_u64().unwrap_or_default(),
        )
    }

    /// Review of B Z3: a cache the entry point remembers for a session is
    /// given again only where the rule of its place would take it. A
    /// one-path listener whose director gave up a rebalance (it confirmed
    /// edge-c, found it not level and went back to edge-a) is shed again:
    /// edge-c, now over the receiver level, is not its leg, and a two-path
    /// listener does not get it as a redundant leg either.
    #[tokio::test]
    async fn a_remembered_cache_over_the_level_takes_no_rebalanced_listener() {
        let (mut router, mesh) = entry_point_for_tests(vec![
            audio_cache_snapshot_for_tests("edge-a", 850, Some(500)),
            audio_cache_snapshot_for_tests("edge-b", 600, Some(500)),
            audio_cache_snapshot_for_tests("edge-c", 790, Some(500)),
            audio_cache_snapshot_for_tests("edge-d", 500, Some(500)),
        ])
        .await;
        router.cache_mesh_role = CacheMeshRole::Distributor;
        let router = router.with_client_udp_port(Some(19_446));
        let remember = |session: &str, legs: &[&str]| {
            router.remembered_assignments.insert(
                format!("801/{session}"),
                (names_for_tests(legs), now_unix_ms()),
            );
        };
        let ask = |query: String| {
            let router = router.clone();
            async move {
                serde_json::from_str::<serde_json::Value>(&body_text(
                    get_for_tests(&router, &format!("/api/assignment?stream=801&{query}")).await,
                ))
                .unwrap()
            }
        };
        remember("give-up", &["edge-c"]);
        let api = ask("sid=give-up&skip=edge-a".into()).await;
        let (node, reason, load) = first_leg(&api);
        assert_eq!(api["paths"], 1, "{api:#}");
        assert_ne!(node, "edge-c", "{api:#}");
        assert_ne!(reason, "sticky", "{api:#}");
        assert!(load < 725, "{api:#}");
        // A two-path listener that keeps edge-b and is shed off edge-a.
        remember("give-up-2", &["edge-c", "edge-b"]);
        let api = ask("sid=give-up-2&skip=edge-a&hold=edge-b".into()).await;
        assert_eq!(api["paths"], 1, "{api:#}");
        assert_eq!(first_leg(&api).0, "edge-d", "{api:#}");
        // A redundant leg remembered under the gate is kept, as sticky.
        remember("kept-2", &["edge-d", "edge-b"]);
        let api = ask("sid=kept-2&hold=edge-b".into()).await;
        assert_eq!(api["paths"], 1, "{api:#}");
        assert_eq!(
            (first_leg(&api).0.as_str(), first_leg(&api).1.as_str()),
            ("edge-d", "sticky"),
            "{api:#}"
        );
        // Over the gate it is not: edge-c at 790 with no listener's cost
        // counted is under 800, so raise it over.
        router
            .telemetry
            .ingest_snapshot({
                let mut over = audio_cache_snapshot_for_tests("edge-c", 820, Some(500));
                over.updated_unix_ms = now_unix_ms();
                over
            })
            .await;
        *router.regional_view.lock().await = None;
        remember("over-2", &["edge-c", "edge-b"]);
        let api = ask("sid=over-2&hold=edge-b".into()).await;
        assert_ne!(first_leg(&api).0, "edge-c", "{api:#}");
        mesh.shutdown();
    }

    /// Review of B Z3: an edge over its target that is killed still looks
    /// fresh, with its last load, for its last advertisement's life. A
    /// listener that held nothing else is given a cache of its region
    /// though no survivor is under the receiver level; once the dead edge's
    /// advertisement is older than one interval, its listeners are movers of
    /// a lost edge, not rebalanced ones (the redundant gate is 800, not
    /// 725).
    #[tokio::test]
    async fn a_killed_edge_over_the_target_leaves_its_listeners_in_the_region() {
        let (mut router, mesh) = entry_point_for_tests(vec![
            audio_cache_snapshot_for_tests("edge-a", 810, Some(500)),
            audio_cache_snapshot_for_tests("edge-b", 760, Some(500)),
            audio_cache_snapshot_for_tests("edge-c", 760, Some(500)),
        ])
        .await;
        router.cache_mesh_role = CacheMeshRole::Distributor;
        let router = router.with_client_udp_port(Some(19_446));
        let ask = |query: &str| {
            let router = router.clone();
            let query = query.to_owned();
            async move {
                serde_json::from_str::<serde_json::Value>(&body_text(
                    get_for_tests(&router, &format!("/api/assignment?stream=801&{query}")).await,
                ))
                .unwrap()
            }
        };
        // Inside the dead edge's last advertisement interval: taken for a
        // rebalance, which finds no receiver under 725.
        let api = ask("sid=killed-1&skip=edge-a").await;
        assert_eq!(api["paths"], 1, "{api:#}");
        assert!(["edge-b", "edge-c"].contains(&first_leg(&api).0.as_str()), "{api:#}");
        // A two-path listener keeps edge-b: a rebalance's gate gives it no
        // second leg while edge-a looks live.
        let api = ask("sid=killed-2&skip=edge-a&hold=edge-b").await;
        assert_eq!(api["paths"], 0, "{api:#}");
        // edge-a's last advertisement is older than one interval: a lost
        // edge, and the gate is the target's.
        let aged = now_unix_ms().saturating_sub(router.recent_advert_ms() + 1_000);
        router
            .telemetry
            .heard
            .write()
            .unwrap()
            .get_mut("edge-a")
            .unwrap()
            .1 = aged;
        let api = ask("sid=killed-3&skip=edge-a&hold=edge-b").await;
        assert_eq!(api["paths"], 1, "{api:#}");
        assert_eq!(first_leg(&api).0, "edge-c", "{api:#}");
        mesh.shutdown();
    }

    /// B rule R3 at the entry (review of B Z1-Z2, finding 2): an edge under
    /// the target but over its region's mean by half the margin sheds by
    /// `MOVE rebalance`; its listener is a rebalanced one, so a two-path
    /// listener's new leg must pass the receiver level (725), not the
    /// redundant gate of a lost edge's mover (800). With R3 off the same
    /// request is a mover's.
    #[tokio::test]
    async fn a_listener_shed_to_the_mean_is_a_rebalanced_one() {
        let ask = |router: AppRouter, query: String| async move {
            serde_json::from_str::<serde_json::Value>(&body_text(
                get_for_tests(&router, &format!("/api/assignment?stream=801&{query}")).await,
            ))
            .unwrap()
        };
        // edge-a at 700 (under 800) sheds to the mean: (700 + 760 + 100) / 3
        // + 75 = 595.
        let snapshots = || {
            vec![
                audio_cache_snapshot_for_tests("edge-a", 700, Some(500)),
                audio_cache_snapshot_for_tests("edge-b", 760, Some(500)),
                audio_cache_snapshot_for_tests("edge-c", 100, Some(500)),
            ]
        };
        let config = |to_mean| RebalanceConfig {
            target_permille: 800,
            margin_permille: 150,
            interval: Duration::from_secs(3),
            spread: Duration::from_millis(500),
            to_mean,
        };
        for (to_mean, paths) in [(true, 0), (false, 1)] {
            let (mut router, mesh) = entry_point_for_tests(snapshots()).await;
            router.cache_mesh_role = CacheMeshRole::Distributor;
            let router = router
                .with_client_udp_port(Some(19_446))
                .with_rebalance(Some(config(to_mean)));
            // Its other leg is on edge-c: only edge-b (760) is left.
            let api = ask(
                router.clone(),
                format!("sid=mean-{to_mean}&skip=edge-a&hold=edge-c"),
            )
            .await;
            assert_eq!(api["paths"], paths, "to_mean {to_mean}: {api:#}");
            if paths == 1 {
                assert_eq!(first_leg(&api).0, "edge-b", "{api:#}");
            }
            mesh.shutdown();
        }
    }

    /// B 3.6: two legs of one session replaced at once are two movers; a
    /// repeat of the request gets the same two legs and is neither charged
    /// nor logged again, and its confirmation charges nothing.
    #[tokio::test]
    async fn two_replaced_legs_are_two_movers_and_a_repeat_is_none() {
        let (mut router, mesh) = entry_point_for_tests(vec![
            audio_cache_snapshot_for_tests("edge-b", 100, Some(500)),
            audio_cache_snapshot_for_tests("edge-c", 100, Some(500)),
            audio_cache_snapshot_for_tests("edge-d", 100, Some(500)),
            audio_cache_snapshot_for_tests("edge-e", 100, Some(500)),
            audio_cache_snapshot_for_tests("edge-f", 100, Some(500)),
        ])
        .await;
        router.cache_mesh_role = CacheMeshRole::Distributor;
        let router = router.with_client_udp_port(Some(19_446));
        let movers = |router: &AppRouter| {
            router
                .recent_movers(Instant::now())
                .iter()
                .map(|(_, count)| *count)
                .sum::<u32>()
        };
        let pending = |router: &AppRouter| {
            router
                .pending_assignments
                .iter()
                .map(|entry| entry.value().1)
                .sum::<u64>()
        };
        let query = "/api/assignment?stream=801&sid=both&skip=edge-b,edge-c&paths=2";
        let api: serde_json::Value =
            serde_json::from_str(&body_text(get_for_tests(&router, query).await)).unwrap();
        assert_eq!(api["paths"], 2, "{api:#}");
        let legs = assigned_names(&api)[..2].to_vec();
        assert_ne!(legs[0], legs[1]);
        assert!(legs.iter().all(|leg| leg != "edge-b" && leg != "edge-c"), "{api:#}");
        assert_eq!(movers(&router), 2);
        let charged = pending(&router);
        assert!(charged > 0);
        // The repeat (the HTTPS hedge of the same request).
        let again: serde_json::Value =
            serde_json::from_str(&body_text(get_for_tests(&router, query).await)).unwrap();
        assert_eq!(assigned_names(&again)[..2], legs[..], "{again:#}");
        assert_eq!(again["assigned"][0]["reason"], "sticky");
        assert_eq!(again["assigned"][1]["reason"], "sticky");
        assert_eq!(movers(&router), 2);
        assert_eq!(pending(&router), charged);
        // Its confirmation names the same legs: nothing new to charge.
        assert!(
            !router
                .confirm_udp_assignment(
                    801,
                    "both",
                    &names_for_tests(&["edge-b", "edge-c"]),
                    &legs,
                    &[]
                )
                .await
        );
        assert_eq!(movers(&router), 2);
        assert_eq!(pending(&router), charged);
        mesh.shutdown();
    }

    #[tokio::test]
    async fn entry_point_pins_a_reader_to_a_named_cache() {
        let (router, mesh) = entry_point_for_tests(vec![
            reader_cache_snapshot_for_tests("edge-b", 200, Some(500)),
            reader_cache_snapshot_for_tests("edge-c", 990, None),
        ])
        .await;

        let master =
            get_for_tests(&router, "/live/801/master.m3u8?sid=reader-1&cache=edge-c").await;
        assert_eq!(master.status, StatusCode::OK);
        let master = body_text(master);
        let variants = master
            .lines()
            .filter(|line| !line.starts_with('#'))
            .collect::<Vec<_>>();
        assert_eq!(variants, ["https://edge-c.example/live/801/stream.m3u8"]);

        let api = get_for_tests(
            &router,
            "/api/assignment?stream=801&sid=reader-1&cache=edge-c",
        )
        .await;
        let api: serde_json::Value = serde_json::from_str(&body_text(api)).unwrap();
        assert_eq!(api["pinned"], true);
        assert_eq!(api["assigned"][0]["reason"], "pinned");
        assert_eq!(api["assigned"].as_array().unwrap().len(), 1);

        let unknown = get_for_tests(&router, "/live/801/master.m3u8?cache=edge-z").await;
        assert_eq!(unknown.status, StatusCode::NOT_FOUND);
        let unknown = get_for_tests(&router, "/api/assignment?stream=801&cache=edge-z").await;
        assert_eq!(unknown.status, StatusCode::NOT_FOUND);
        mesh.shutdown();
    }

    #[tokio::test]
    async fn steering_keeps_a_reader_on_its_cache_and_moves_it_off_a_drained_cache() {
        let mut edge_b = reader_cache_snapshot_for_tests("edge-b", 995, Some(500));
        edge_b.edge_service.as_mut().unwrap().egress_overloaded = true;
        let (router, mesh) = entry_point_for_tests(vec![
            edge_b.clone(),
            reader_cache_snapshot_for_tests("edge-c", 100, Some(500)),
        ])
        .await;
        let priority = |steering: HandlerResponse| {
            let steering: serde_json::Value = serde_json::from_str(&body_text(steering)).unwrap();
            steering["PATHWAY-PRIORITY"]
                .as_array()
                .unwrap()
                .iter()
                .map(|pathway| pathway.as_str().unwrap().to_owned())
                .collect::<Vec<_>>()
        };

        // edge-b admits no new reader, so a new reader is not sent there.
        let new_reader = get_for_tests(&router, "/live/801/steering.json?sid=reader-2").await;
        assert!(!priority(new_reader).contains(&"edge-b".to_owned()));
        // A reader that is already on edge-b stays there.
        let sticky =
            "/live/801/steering.json?sid=reader-1&_HLS_pathway=edge-b&_HLS_throughput=9000";
        assert_eq!(priority(get_for_tests(&router, sticky).await)[0], "edge-b");

        // edge-b drains. The same reader is told to use another cache.
        edge_b.edge_service.as_mut().unwrap().draining = true;
        router.telemetry.ingest_snapshot(edge_b).await;
        let moved = priority(get_for_tests(&router, sticky).await);
        assert_eq!(moved[0], "edge-c");
        assert!(!moved.contains(&"edge-b".to_owned()));
        mesh.shutdown();
    }

    #[tokio::test]
    async fn draining_cache_moves_its_readers_and_takes_no_new_reader() {
        let (router, mesh) = entry_point_for_tests(vec![reader_cache_snapshot_for_tests(
            "edge-b",
            100,
            Some(500),
        )])
        .await;
        let request = |uri: &str, session: &str| {
            Request::builder()
                .method(Method::GET)
                .uri(uri)
                .header("CMCD-Session", format!("sid=\"{session}\""))
                .body(())
                .unwrap()
        };
        let playlist = "/live/801/stream.m3u8?_HLS_msn=4&_HLS_part=1";
        // The reader is admitted with a plain reload. This node holds no part
        // of the stream, so a reload for a position would wait and end.
        assert_eq!(
            router
                .route(request("/live/801/stream.m3u8", "reader-1"))
                .await
                .unwrap()
                .status,
            StatusCode::OK
        );

        let command = router
            .execute_control(
                ControlKind::DrainNode,
                ControlRequest {
                    node_id: Some("test-node".into()),
                    region: None,
                    stream_id: None,
                },
            )
            .await;
        assert!(command.status.contains("readers move to other caches"));
        assert!(router.local_mesh_snapshot().await.node.draining);

        // The admitted reader is sent to the other cache at its next playlist
        // reload, with the same request.
        let moved = router.route(request(playlist, "reader-1")).await.unwrap();
        assert_eq!(moved.status, StatusCode::TEMPORARY_REDIRECT);
        assert!(moved.headers.iter().any(|(name, value)| {
            name == "location"
                && value == "https://edge-b.example/live/801/stream.m3u8?_HLS_msn=4&_HLS_part=1"
        }));
        // A part that it was already told about is still served here.
        let part = router
            .route(request("/live/801/part999.mp4", "reader-1"))
            .await
            .unwrap();
        assert_ne!(part.status, StatusCode::TEMPORARY_REDIRECT);
        assert_ne!(part.status, StatusCode::TOO_MANY_REQUESTS);
        // The moved reader still fetches here: the drained proof waits for
        // it, though the session gauge no longer counts it. (The part is
        // not here, so its request waited for it: the request was seen at
        // its start, seconds ago.)
        assert_eq!(router.edge_load.admission_snapshot().active_sessions, 0);
        assert_eq!(router.edge_load.moved_seen_within(10_000), 1);

        // A new reader is rejected and told where to go.
        let rejected = router.route(request(playlist, "reader-2")).await.unwrap();
        assert_eq!(rejected.status, StatusCode::TOO_MANY_REQUESTS);
        assert!(rejected.headers.iter().any(|(name, value)| {
            name == "link" && value.contains("https://edge-b.example/live/801/stream.m3u8")
        }));
        // The entry point of the draining node assigns only the other cache.
        let master = body_text(get_for_tests(&router, "/live/801/master.m3u8?sid=reader-3").await);
        assert!(!master.lines().any(|line| line == "stream.m3u8"));
        assert!(master.contains("https://edge-b.example/live/801/stream.m3u8"));

        // A region's resume does not resume it: only its own node id does.
        let command = router
            .execute_control(
                ControlKind::ResumeNode,
                ControlRequest {
                    node_id: None,
                    region: Some("test-region".into()),
                    stream_id: None,
                },
            )
            .await;
        assert!(command.status.contains("local skipped: no node id"));
        assert!(router.local_mesh_snapshot().await.node.draining);
        router
            .execute_control(
                ControlKind::ResumeNode,
                ControlRequest {
                    node_id: Some("test-node".into()),
                    region: None,
                    stream_id: None,
                },
            )
            .await;
        assert_eq!(
            router
                .route(request("/live/801/stream.m3u8", "reader-2"))
                .await
                .unwrap()
                .status,
            StatusCode::OK
        );
        mesh.shutdown();
    }

    #[tokio::test]
    async fn cache_at_its_reader_limit_rejects_a_new_reader_with_alternates() {
        let (mut router, mesh) = entry_point_for_tests(vec![reader_cache_snapshot_for_tests(
            "edge-b",
            100,
            Some(500),
        )])
        .await;
        router.edge_load = EdgeLoad::new(EdgeAdmissionConfig {
            session_limit: 2,
            ..EdgeAdmissionConfig::default()
        });
        let request = |session: &str| {
            Request::builder()
                .method(Method::GET)
                .uri("/live/801/stream.m3u8")
                .header("CMCD-Session", format!("sid=\"{session}\""))
                .body(())
                .unwrap()
        };
        for session in ["reader-1", "reader-2"] {
            assert_eq!(
                router.route(request(session)).await.unwrap().status,
                StatusCode::OK
            );
        }
        let rejected = router.route(request("reader-3")).await.unwrap();
        assert_eq!(rejected.status, StatusCode::TOO_MANY_REQUESTS);
        assert!(rejected.headers.iter().any(|(name, value)| {
            name == "x-needletail-alternate-edges"
                && value == "https://edge-b.example/live/801/stream.m3u8"
        }));
        assert_eq!(
            router.route(request("reader-1")).await.unwrap().status,
            StatusCode::OK
        );
        // The node advertises that it is full, so entry points stop sending
        // new readers to it.
        let advertised = router.local_mesh_snapshot().await.edge_service.unwrap();
        assert_eq!(advertised.session_limit, 2);
        assert_eq!(advertised.active_playback_sessions, 2);
        assert_eq!(advertised.load_permille, 1_000);
        let api = get_for_tests(&router, "/api/assignment?stream=801&sid=reader-4").await;
        let api: serde_json::Value = serde_json::from_str(&body_text(api)).unwrap();
        assert_eq!(api["assigned"].as_array().unwrap().len(), 1);
        assert_eq!(api["assigned"][0]["node_id"], "edge-b");
        mesh.shutdown();
    }

    #[tokio::test]
    async fn a_cold_cache_admits_readers_against_the_rate_that_the_region_advertises() {
        // A distributor of the region advertises the playlist at 16 Mbit/s.
        // This edge does not hold it yet.
        let mut distributor = reader_cache_snapshot_for_tests("dist-a", 0, Some(500));
        distributor.edge_service.as_mut().unwrap().cache_mesh_role = "distributor".into();
        let (mut router, mesh) = entry_point_for_tests(vec![distributor]).await;
        // The edge admits 85% of 40 Mbit/s: two 16 Mbit/s readers.
        router.edge_load = EdgeLoad::new(EdgeAdmissionConfig {
            capacity_bps: 40_000_000,
            ..EdgeAdmissionConfig::default()
        });
        let request = |session: &str| {
            Request::builder()
                .method(Method::GET)
                .uri("/live/801/stream.m3u8")
                .header("CMCD-Session", format!("sid=\"{session}\""))
                .body(())
                .unwrap()
        };
        assert_eq!(router.edge_load.egress.playlist_bps(801), None);
        for session in ["reader-1", "reader-2"] {
            assert_eq!(
                router.route(request(session)).await.unwrap().status,
                StatusCode::OK
            );
        }
        assert_eq!(router.edge_load.egress.playlist_bps(801), Some(16_000_000));
        assert_eq!(
            router.route(request("reader-3")).await.unwrap().status,
            StatusCode::TOO_MANY_REQUESTS
        );
        assert_eq!(
            router.edge_load.admission_snapshot().committed_bps,
            32_000_000
        );
        mesh.shutdown();
    }

    #[test]
    fn entry_point_paths_and_steering_uri() {
        assert_eq!(parse_steering_path("/live/77/steering.json", 1), Some(77));
        assert_eq!(parse_steering_path("/live/steering.json", 1), Some(1));
        assert_eq!(parse_steering_path("/live/77/stream.m3u8", 1), None);
        assert_eq!(parse_steering_path("/live/a/b/steering.json", 1), None);
        assert_eq!(steering_uri(None, None, &[]), "steering.json");
        assert_eq!(
            steering_uri(Some("s"), None, &["edge-1", "us-east"]),
            "steering.json?sid=s&p=edge-1,us-east"
        );
        assert_eq!(
            url_host("https://10.90.0.24:19444/live").as_deref(),
            Some("10.90.0.24")
        );
        assert_eq!(
            url_host("https://edge.example/live").as_deref(),
            Some("edge.example")
        );
        assert_eq!(url_host("ftp://edge.example"), None);
        assert_eq!(
            steering_uri(Some("a b&c"), Some("lon-edge-1"), &[]),
            "steering.json?sid=a%20b%26c&cache=lon-edge-1"
        );
        assert_eq!(playback_stream_ids("/live/77/part3.mp4", None, 1), vec![77]);
        assert_eq!(playback_stream_ids("/live/stream.m3u8", None, 1), vec![1]);
        assert_eq!(
            playback_stream_ids(LLHLS_TAIL_BUNDLE_PATH, Some("streams=2001,2002"), 1),
            vec![2001, 2002]
        );
        assert!(is_playlist_reload_path("/live/77/stream.m3u8"));
        assert!(!is_playlist_reload_path("/live/77/part3.mp4"));
        assert!(!is_playlist_reload_path("/live/77/init.mp4"));
        assert_eq!(
            effective_replication(CacheMeshReplicationArg::Demand, CacheMeshRole::Peer),
            ReplicationMode::All
        );
        assert_eq!(
            effective_replication(CacheMeshReplicationArg::Demand, CacheMeshRole::Edge),
            ReplicationMode::Demand
        );
        assert_eq!(
            effective_replication(CacheMeshReplicationArg::All, CacheMeshRole::Distributor),
            ReplicationMode::All
        );
    }

    /// The client decodes a cache slot exactly as the edge does.
    #[tokio::test]
    async fn the_client_reads_a_slot_as_the_edge_does() {
        let cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 32, 64).await;
        for (stream_id, sequence, init) in [
            (77_u64, 0_u64, Some(b"ftyp-moov".as_slice())),
            (77, 1, None),
        ] {
            cache
                .commit_stream_payload(
                    stream_id,
                    encode_test_canonical_fmp4_bundle_with_duration(
                        stream_id,
                        sequence,
                        init,
                        format!("moof-mdat-{sequence}").as_bytes(),
                        Some(250),
                        true,
                    ),
                )
                .await
                .unwrap();
            let (slot, _) = cache
                .chunk_cache
                .get_for_stream_id(stream_id, sequence as usize)
                .await
                .unwrap();
            let edge = LiveSlotPayload::decode_for_stream(slot.clone(), stream_id);
            let (media, client_init) = av_mesh::client_udp::slot_media(&slot, stream_id)
                .expect("the client reads the slot");
            assert_eq!(media, edge.media());
            assert_eq!(client_init, edge.init());
            assert!(
                av_mesh::client_udp::slot_media(&slot, stream_id + 1).is_none()
                    || !slot.starts_with(b"AVMOBJS1")
            );
        }
    }

    /// Cut-through at the smallest parts: a distributor publishes parts at
    /// the rate of 2.5 ms Opus, 1 ms and 0.25 ms PCM and one-frame 4K video;
    /// the cache mesh carries them to an edge, which forwards each part's
    /// symbols to a UDP client as they arrive. Every part arrives, identical to
    /// the edge's LL-HLS part, and through the cut-through path.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn small_parts_reach_a_udp_client_cut_through_at_their_rate() {
        use av_mesh::client_udp::{
            Control, ObjectKind as UdpObjectKind, ObjectReceiver, RepairPolicy,
        };
        use playlists::mesh::{CacheMesh, CacheMeshConfig, CacheMeshRole as MeshRole};
        use tokio::time::timeout;

        // name, stream, part interval, media bytes, parts
        let cases: [(&str, u64, u64, usize, u64); 4] = [
            ("opus-2.5ms", 3001, 2_500, 60, 400),
            ("pcm-1ms", 4001, 1_000, 288, 1_000),
            ("pcm-0.25ms", 4002, 250, 72, 2_000),
            ("4k-one-frame", 1, 41_667, 70_000, 48),
        ];
        let mut summary = Vec::new();
        // The class-split path (a mesh split by class, a cut-through per
        // class, a client socket pair), the same with each cut-through on a
        // thread of its own, and the single path before them.
        for (split, lane) in [(true, false), (true, true), (false, false)] {
            for (name, stream_id, interval_us, media_bytes, parts) in cases {
                let name = format!(
                    "{name}{}",
                    match (split, lane) {
                        (true, false) => " split",
                        (true, true) => " split+thread",
                        _ => " single",
                    }
                );
                let name = name.as_str();
                let offset = if split { 1_000 } else { 0 };
                let parent_cache =
                    LiveTsCache::new(1, Duration::from_millis(5), 200, 8_000, 512).await;
                let edge_cache =
                    LiveTsCache::new(1, Duration::from_millis(5), 200, 8_000, 512).await;
                let parent_addr = unused_loopback_addr();
                let edge_addr = unused_loopback_addr();
                // The distributor knows the 4K stream as video.
                if stream_id == 1 {
                    parent_cache.stream_classes().mark_video(stream_id);
                }
                let classify = |cache: &Arc<LiveTsCache>| {
                    let classes = cache.stream_classes().clone();
                    Arc::new(move |stream_id| classes.mesh_class(stream_id))
                        as playlists::mesh::CacheMeshStreamClassifier
                };
                let parent_mesh = CacheMesh::new(
                    Arc::clone(&parent_cache.chunk_cache),
                    CacheMeshConfig::new("dist-a", "uk", parent_addr)
                        .with_peer(edge_addr)
                        .with_role(MeshRole::Distributor)
                        .with_announce_interval(Duration::from_millis(40))
                        .with_class_port_offset(offset)
                        .with_stream_classifier(classify(&parent_cache)),
                )
                .start()
                .await
                .unwrap();
                let cuts: Vec<Arc<edge_udp::CutThrough>> = (0..if split { 2 } else { 1 })
                    .map(|_| Arc::new(edge_udp::CutThrough::default()))
                    .collect();
                let observer = |cut: &Arc<edge_udp::CutThrough>,
                                class: &str|
                 -> Arc<dyn CacheMeshReceiveObserver> {
                    if lane {
                        edge_udp::CutThroughLane::start(
                            Arc::clone(cut),
                            class,
                            tokio::runtime::Handle::current(),
                        )
                        .unwrap()
                    } else {
                        Arc::clone(cut) as _
                    }
                };
                let (applied_tx, mut applied_rx) = mpsc::unbounded_channel();
                let mut edge_config = CacheMeshConfig::new("edge-1", "uk", edge_addr)
                    .with_peer(parent_addr)
                    .with_role(MeshRole::Edge)
                    .with_announce_interval(Duration::from_millis(40))
                    .with_applied_tx(applied_tx)
                    .with_receive_observer(observer(&cuts[0], "audio"));
                if split {
                    edge_config = edge_config
                        .with_class_port_offset(offset)
                        .with_stream_classifier(classify(&edge_cache))
                        .with_class_receive_observer(Some(Arc::new(fast_plane::ClassMarker::new(
                            edge_cache.stream_classes().clone(),
                            Some(observer(&cuts[1], "video")),
                        ))));
                }
                let edge_mesh = Arc::new(
                    CacheMesh::new(Arc::clone(&edge_cache.chunk_cache), edge_config)
                        .start()
                        .await
                        .unwrap(),
                );
                let media = |part: u64| -> Vec<u8> {
                    (0..media_bytes)
                        .map(|i| (i as u64 * 31 + part * 7) as u8)
                        .collect()
                };
                let commit = |part: u64| {
                    let cache = Arc::clone(&parent_cache);
                    let body = media(part);
                    async move {
                        cache
                            .commit_stream_payload(
                                stream_id,
                                encode_test_canonical_fmp4_bundle_with_duration(
                                    stream_id,
                                    part,
                                    (part == 0).then_some(b"ftyp-moov".as_slice()),
                                    &body,
                                    Some(5),
                                    true,
                                ),
                            )
                            .await
                            .unwrap();
                    }
                };
                commit(0).await;
                let router = app_router_for_tests(Arc::clone(&edge_cache), Arc::clone(&edge_mesh));
                timeout(Duration::from_secs(5), async {
                    while edge_cache.stream_position_for_id(stream_id).await.is_none() {
                        tokio::time::sleep(Duration::from_millis(5)).await;
                    }
                })
                .await
                .expect("the edge receives the stream over the cache mesh");

                let sockets = if split {
                    bind_edge_class_sockets(
                        "127.0.0.1:0".parse().unwrap(),
                        1 << 20,
                        edge_cache.stream_classes(),
                    )
                    .unwrap()
                } else {
                    edge_udp::EdgeSockets::single(UdpSocket::bind("127.0.0.1:0").await.unwrap())
                };
                let edge = sockets.for_stream(0).local_addr().unwrap();
                let stats: Arc<edge_udp::EdgeUdpStats> = Arc::default();
                let (shutdown_tx, shutdown_rx) = watch::channel(());
                // Every part must arrive: a host stall of more than the
                // default 500 ms playout deadline (seen with the test
                // runner's other tests and builds on the host) would let
                // the cache-fed sender skip parts that it owes.
                let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
                config.playout = Duration::from_secs(5);
                let task = tokio::spawn(edge_udp::run_edge_udp(
                    sockets,
                    router.clone(),
                    config,
                    Arc::clone(&stats),
                    cuts.clone(),
                    shutdown_rx,
                ));
                let client = Arc::new(UdpSocket::bind("127.0.0.1:0").await.unwrap());
                // A client's receive buffer, as needletail-udp-client asks
                // for: this one never NACKs, and with the default 208 KB
                // (under two 70 KB 4K parts of symbols) a loaded host's
                // stall of its task lost parts that the edge had sent
                // (every datagram, cut through: wave 8 stage 3).
                let _ = SockRef::from(&*client).set_recv_buffer_size(4 << 20);
                let subscribe = |token| {
                    Control::Subscribe {
                        stream_id,
                        from_part: None,
                        repair: RepairPolicy::default(),
                        token,
                        fast_lane: false,
                        compact: None,
                        others: Vec::new(),
                        resume: false,
                    }
                    .encode()
                };
                let mut buf = vec![0_u8; 65_536];
                client.send_to(&subscribe(None), edge).await.unwrap();
                let token = loop {
                    let (len, _) = client.recv_from(&mut buf).await.unwrap();
                    if let Some(Control::Token { token, .. }) = Control::decode(&buf[..len]) {
                        break token;
                    }
                };
                client.send_to(&subscribe(Some(token)), edge).await.unwrap();
                loop {
                    let (len, _) = client.recv_from(&mut buf).await.unwrap();
                    if matches!(
                        Control::decode(&buf[..len]),
                        Some(Control::Subscribed { .. })
                    ) {
                        break;
                    }
                }

                // The receiver: every part with its arrival time.
                let receiving = {
                    let client = Arc::clone(&client);
                    tokio::spawn(async move {
                        let mut receiver = ObjectReceiver::new();
                        let mut buf = vec![0_u8; 65_536];
                        let mut arrived = BTreeMap::new();
                        while arrived.len() < parts as usize {
                            let Ok(Ok((len, _))) =
                                timeout(Duration::from_secs(3), client.recv_from(&mut buf)).await
                            else {
                                break;
                            };
                            if let Some(object) = receiver.push(av_mesh::client_compact::LegId::FIRST, &buf[..len]) {
                                if object.kind == UdpObjectKind::Part && object.part >= 1 {
                                    arrived
                                        .entry(object.part)
                                        .or_insert((Instant::now(), object.payload));
                                }
                            }
                        }
                        arrived
                    })
                };

                // The producer: absolute deadlines at the part interval.
                let start = Instant::now() + Duration::from_millis(20);
                let mut published = BTreeMap::new();
                let mut published_us = HashMap::new();
                for part in 1..=parts {
                    tokio::time::sleep_until(
                        (start + Duration::from_micros(interval_us * part)).into(),
                    )
                    .await;
                    published.insert(part, Instant::now());
                    published_us.insert(part as usize, now_unix_us());
                    commit(part).await;
                }
                let producer_ms = start.elapsed().as_secs_f64() * 1e3;
                let arrived = receiving.await.unwrap();
                // When the first datagram of each part reached the edge.
                let mut edge_ms = Vec::new();
                while let Ok(applied) = applied_rx.try_recv() {
                    if let Some(published) = published_us.get(&applied.slot_id) {
                        edge_ms.push(applied.rx_first_us.saturating_sub(*published) as f64 / 1e3);
                    }
                }
                edge_ms.sort_by(f64::total_cmp);
                let edge_p50 = edge_ms.get(edge_ms.len() / 2).copied().unwrap_or(-1.0);
                let edge_p99 = edge_ms
                    .get(edge_ms.len() * 99 / 100)
                    .copied()
                    .unwrap_or(-1.0);
                let mut latencies: Vec<f64> = Vec::new();
                for part in 1..=parts {
                    let (at, payload) = arrived.get(&part).unwrap_or_else(|| {
                        let load = |value: &AtomicU64| value.load(Ordering::Relaxed);
                        panic!(
                            "{name}: part {part} did not arrive ({} of {parts} did; edge: parts {} \
                             datagrams {} cut-through parts {} datagrams {} fallbacks {} queue drops {} \
                             would_block {} send queue drops {} playout skipped {} holes past playout {} \
                             gaps {})",
                            arrived.len(),
                            load(&stats.parts),
                            load(&stats.datagrams),
                            load(&stats.cut_through_parts),
                            load(&stats.cut_through_datagrams),
                            load(&stats.cut_through_fallbacks),
                            load(&stats.cut_through_queue_drops),
                            load(&stats.would_block),
                            load(&stats.send_queue_drops),
                            load(&stats.playout_skipped_parts),
                            load(&stats.holes_past_playout),
                            load(&stats.gaps),
                        )
                    });
                    assert_eq!(
                        payload.as_ref(),
                        media(part).as_slice(),
                        "{name}: part {part}"
                    );
                    latencies.push(at.duration_since(published[&part]).as_secs_f64() * 1e3);
                }
                let http =
                    get_for_tests(&router, &format!("/live/{stream_id}/part{parts}.mp4")).await;
                assert_eq!(http.body.as_deref(), Some(media(parts).as_slice()));
                latencies.sort_by(f64::total_cmp);
                let at = |q: f64| latencies[((latencies.len() - 1) as f64 * q) as usize];
                // What the edge adds: from the first datagram of a part at the
                // edge to the part at the client. (What comes before it is the
                // distributor's publication and the cache mesh.)
                let added = at(0.5) - edge_p50;
                let allowed = if media_bytes > 10_000 { 5.0 } else { 1.0 };
                assert!(
                    added < allowed,
                    "{name}: the edge adds {added:.3} ms at the median"
                );
                let cut_parts = stats.cut_through_parts.load(Ordering::Relaxed);
                // On a thread, the cut-through of a part of one symbol often
                // comes after the cache has the part, and the cache-fed sender
                // sends it; a part of many symbols is cut through all the same.
                let cut_expected = if lane && media_bytes < 10_000 {
                    0
                } else {
                    parts * 9 / 10
                };
                assert!(
                    cut_parts >= cut_expected,
                    "{name}: {cut_parts} of {parts} parts cut through"
                );
                summary.push(format!(
                "{name}: {parts} parts, publish to client p50 {:.3} ms p99 {:.3} ms max {:.3} ms, \
                 {cut_parts} cut through, {} fallbacks, producer {producer_ms:.0} ms for {} ms, \
                 first datagram at the edge p50 {edge_p50:.3} p99 {edge_p99:.3} ms after publication",
                at(0.5),
                at(0.99),
                at(1.0),
                stats.cut_through_fallbacks.load(Ordering::Relaxed),
                interval_us * parts / 1_000
            ));
                if split && stream_id == 1 {
                    assert_eq!(
                        edge_cache.stream_classes().class(stream_id),
                        fast_plane::TrafficClass::Video,
                        "the edge learned the 4K stream's class from the class socket"
                    );
                    assert!(edge_mesh.class_fec_stats().unwrap().rx_decoded_objects >= parts);
                }
                let _ = shutdown_tx.send(());
                task.await.unwrap().unwrap();
                parent_mesh.shutdown();
                edge_mesh.shutdown();
            }
        }
        println!("{}", summary.join("\n"));
    }

    /// An audio stream's cut-through beside a 4K one at the same edge, both
    /// with a UDP client: with the mesh split by class each class has its
    /// own receive task, cut-through and client socket, so the 4K parts'
    /// cut-through bursts do not hold the audio parts back. The audio
    /// publish-to-client latency is printed for the split and the single
    /// path; the split one is held to a bound.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn audio_cut_through_is_not_held_behind_a_4k_cut_through() {
        use av_mesh::client_udp::{
            Control, ObjectKind as UdpObjectKind, ObjectReceiver, RepairPolicy,
        };
        use playlists::mesh::{CacheMesh, CacheMeshConfig, CacheMeshRole as MeshRole};
        use tokio::time::timeout;

        const VIDEO: u64 = 1;
        const AUDIO: u64 = 3001;
        const AUDIO_PARTS: u64 = 400;
        const VIDEO_PART_BYTES: usize = 200_000;
        let mut report = Vec::new();
        let mut split_p99 = f64::MAX;
        let mut single_p99 = 0.0_f64;
        for split in [true, false] {
            let offset = if split { 1_000 } else { 0 };
            let parent_cache = LiveTsCache::new(1, Duration::from_millis(5), 200, 8_000, 512).await;
            let edge_cache = LiveTsCache::new(1, Duration::from_millis(5), 200, 8_000, 512).await;
            parent_cache.stream_classes().mark_video(VIDEO);
            let parent_addr = unused_loopback_addr();
            let edge_addr = unused_loopback_addr();
            let classify = |cache: &Arc<LiveTsCache>| {
                let classes = cache.stream_classes().clone();
                Arc::new(move |stream_id| classes.mesh_class(stream_id))
                    as playlists::mesh::CacheMeshStreamClassifier
            };
            let parent_mesh = CacheMesh::new(
                Arc::clone(&parent_cache.chunk_cache),
                CacheMeshConfig::new("dist-a", "uk", parent_addr)
                    .with_peer(edge_addr)
                    .with_role(MeshRole::Distributor)
                    .with_announce_interval(Duration::from_millis(40))
                    .with_socket_buffer_bytes(8 << 20)
                    .with_class_port_offset(offset)
                    .with_stream_classifier(classify(&parent_cache)),
            )
            .start()
            .await
            .unwrap();
            let cuts: Vec<Arc<edge_udp::CutThrough>> = (0..if split { 2 } else { 1 })
                .map(|_| Arc::new(edge_udp::CutThrough::default()))
                .collect();
            let mut edge_config = CacheMeshConfig::new("edge-1", "uk", edge_addr)
                .with_peer(parent_addr)
                .with_role(MeshRole::Edge)
                .with_announce_interval(Duration::from_millis(40))
                .with_socket_buffer_bytes(8 << 20)
                .with_receive_observer(Arc::clone(&cuts[0]) as _);
            if split {
                edge_config = edge_config
                    .with_class_port_offset(offset)
                    .with_stream_classifier(classify(&edge_cache))
                    .with_class_receive_observer(Some(Arc::new(fast_plane::ClassMarker::new(
                        edge_cache.stream_classes().clone(),
                        Some(Arc::clone(&cuts[1]) as _),
                    ))));
            }
            let edge_mesh = Arc::new(
                CacheMesh::new(Arc::clone(&edge_cache.chunk_cache), edge_config)
                    .start()
                    .await
                    .unwrap(),
            );
            let commit_cache = Arc::clone(&parent_cache);
            let commit = move |stream_id: u64, part: u64, bytes: usize| {
                let cache = Arc::clone(&commit_cache);
                async move {
                    let body: Vec<u8> = (0..bytes)
                        .map(|index| ((index as u64 * 31) ^ part) as u8)
                        .collect();
                    cache
                        .commit_stream_payload(
                            stream_id,
                            encode_test_canonical_fmp4_bundle_with_duration(
                                stream_id,
                                part,
                                (part == 0).then_some(b"ftyp-moov".as_slice()),
                                &body,
                                Some(5),
                                true,
                            ),
                        )
                        .await
                        .unwrap();
                }
            };
            commit(AUDIO, 0, 60).await;
            commit(VIDEO, 0, 1_000).await;
            let router = app_router_for_tests(Arc::clone(&edge_cache), Arc::clone(&edge_mesh));
            timeout(Duration::from_secs(5), async {
                while edge_cache.stream_position_for_id(AUDIO).await.is_none()
                    || edge_cache.stream_position_for_id(VIDEO).await.is_none()
                {
                    tokio::time::sleep(Duration::from_millis(5)).await;
                }
            })
            .await
            .expect("the edge receives both streams");
            let sockets = if split {
                bind_edge_class_sockets(
                    "127.0.0.1:0".parse().unwrap(),
                    4 << 20,
                    edge_cache.stream_classes(),
                )
                .unwrap()
            } else {
                edge_udp::EdgeSockets::single(UdpSocket::bind("127.0.0.1:0").await.unwrap())
            };
            let edge = sockets.for_stream(AUDIO).local_addr().unwrap();
            let stats: Arc<edge_udp::EdgeUdpStats> = Arc::default();
            let (shutdown_tx, shutdown_rx) = watch::channel(());
            let task = tokio::spawn(edge_udp::run_edge_udp(
                sockets,
                router.clone(),
                edge_udp::EdgeUdpConfig::with_defaults(1_200, 16),
                Arc::clone(&stats),
                cuts.clone(),
                shutdown_rx,
            ));
            // One client per stream.
            let mut clients = Vec::new();
            for stream_id in [AUDIO, VIDEO] {
                let client = Arc::new(UdpSocket::bind("127.0.0.1:0").await.unwrap());
                let _ = SockRef::from(client.as_ref()).set_recv_buffer_size(8 << 20);
                let subscribe = |token| {
                    Control::Subscribe {
                        stream_id,
                        from_part: None,
                        repair: RepairPolicy::default(),
                        token,
                        fast_lane: false,
                        compact: None,
                        others: Vec::new(),
                        resume: false,
                    }
                    .encode()
                };
                let mut buf = vec![0_u8; 65_536];
                client.send_to(&subscribe(None), edge).await.unwrap();
                let token = loop {
                    let (len, _) = client.recv_from(&mut buf).await.unwrap();
                    if let Some(Control::Token { token, .. }) = Control::decode(&buf[..len]) {
                        break token;
                    }
                };
                client.send_to(&subscribe(Some(token)), edge).await.unwrap();
                loop {
                    let (len, _) = client.recv_from(&mut buf).await.unwrap();
                    if matches!(
                        Control::decode(&buf[..len]),
                        Some(Control::Subscribed { .. })
                    ) {
                        break;
                    }
                }
                clients.push(client);
            }
            let receive = |client: Arc<UdpSocket>, parts: u64| {
                tokio::spawn(async move {
                    let mut receiver = ObjectReceiver::new();
                    let mut buf = vec![0_u8; 65_536];
                    let mut arrived = BTreeMap::new();
                    while (arrived.len() as u64) < parts {
                        let Ok(Ok((len, _))) =
                            timeout(Duration::from_secs(2), client.recv_from(&mut buf)).await
                        else {
                            break;
                        };
                        if let Some(object) = receiver.push(av_mesh::client_compact::LegId::FIRST, &buf[..len]) {
                            if object.kind == UdpObjectKind::Part && object.part >= 1 {
                                arrived.entry(object.part).or_insert_with(Instant::now);
                            }
                        }
                    }
                    arrived
                })
            };
            let audio_receiving = receive(Arc::clone(&clients[0]), AUDIO_PARTS);
            let video_receiving = receive(Arc::clone(&clients[1]), 24);
            // 4K frames at 24 fps; audio: 2.5 ms parts, for 1 s.
            let video = {
                let commit = commit.clone();
                tokio::spawn(async move {
                    let start = Instant::now();
                    for part in 1..=24_u64 {
                        tokio::time::sleep_until(
                            (start + Duration::from_micros(41_667 * part)).into(),
                        )
                        .await;
                        commit(VIDEO, part, VIDEO_PART_BYTES).await;
                    }
                })
            };
            let mut published = BTreeMap::new();
            let start = Instant::now() + Duration::from_millis(5);
            for part in 1..=AUDIO_PARTS {
                tokio::time::sleep_until((start + Duration::from_micros(2_500 * part)).into())
                    .await;
                published.insert(part, Instant::now());
                commit(AUDIO, part, 60).await;
            }
            video.await.unwrap();
            let arrived = audio_receiving.await.unwrap();
            let video_arrived = video_receiving.await.unwrap();
            let mut latencies: Vec<f64> = published
                .iter()
                .filter_map(|(part, at)| {
                    arrived
                        .get(part)
                        .map(|arrived| arrived.duration_since(*at).as_secs_f64() * 1e3)
                })
                .collect();
            latencies.sort_by(f64::total_cmp);
            let name = if split { "split" } else { "single" };
            assert!(
                latencies.len() as u64 >= AUDIO_PARTS * 98 / 100,
                "{name}: {} of {AUDIO_PARTS} audio parts reached the client",
                latencies.len()
            );
            let at = |q: f64| latencies[((latencies.len() - 1) as f64 * q) as usize];
            report.push(format!(
                "{name}: audio publish to UDP client p50 {:.3} ms p99 {:.3} ms max {:.3} ms beside a 4K client ({} 4K parts, {} parts cut through)",
                at(0.5),
                at(0.99),
                at(1.0),
                video_arrived.len(),
                stats.cut_through_parts.load(Ordering::Relaxed),
            ));
            if split {
                split_p99 = at(0.99);
                assert!(video_arrived.len() >= 20, "{}", report.join("\n"));
            } else {
                single_p99 = at(0.99);
            }
            let _ = shutdown_tx.send(());
            task.await.unwrap().unwrap();
            parent_mesh.shutdown();
            edge_mesh.shutdown();
        }
        println!("{}", report.join("\n"));
        assert!(split_p99 < 3.0, "{}", report.join("\n"));
        assert!(
            split_p99 * 2.0 < single_p99,
            "the class path does not isolate the audio:\n{}",
            report.join("\n")
        );
    }

    /// RaptorQ FEC UDP to a client at an edge: every part that the edge's
    /// cache holds reaches the client bit for bit as its LL-HLS part, with a
    /// third of the datagrams lost; a new part follows live; a drain sends
    /// the client away. Before the client UDP port existed an edge had no
    /// way to send its cache to a UDP client at all.
    #[tokio::test]
    async fn an_edge_sends_its_cached_parts_to_a_udp_client_bit_for_bit() {
        use av_mesh::client_udp::{
            Control, ObjectKind as UdpObjectKind, ObjectReceiver, RepairPolicy,
        };
        use tokio::time::timeout;

        let cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 32, 64).await;
        let commit = |sequence: u64| {
            let cache = Arc::clone(&cache);
            async move {
                cache
                    .commit_stream_payload(
                        77,
                        encode_test_canonical_fmp4_bundle_with_duration(
                            77,
                            sequence,
                            (sequence == 0).then_some(b"ftyp-fLaC-moov".as_slice()),
                            &vec![sequence as u8; 3_000 + sequence as usize * 1_000],
                            Some(250),
                            true,
                        ),
                    )
                    .await
                    .unwrap();
            }
        };
        for sequence in 0..5 {
            commit(sequence).await;
        }
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));
        let socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let edge = socket.local_addr().unwrap();
        let (shutdown_tx, shutdown_rx) = watch::channel(());
        // Parts of 250 ms: no playout deadline, so that the client takes
        // every cached part from the one it names
        // (a_moved_udp_client_resumes_within_its_playout_deadline).
        let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
        config.playout = Duration::ZERO;
        let task = tokio::spawn(edge_udp::run_edge_udp(
            edge_udp::EdgeSockets::single(socket),
            router.clone(),
            config,
            Arc::default(),
            Vec::new(),
            shutdown_rx,
        ));

        let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let subscribe = |token| Control::Subscribe {
            stream_id: 77,
            from_part: Some(0),
            repair: RepairPolicy {
                permille: 500,
                min_symbols: 4,
                loss_ppm: 0,
            },
            token,
            fast_lane: false,
            compact: None,
            others: Vec::new(),
            resume: false,
        };
        let mut buf = vec![0_u8; 65_536];
        // A first request gets a token and nothing else: an address that
        // does not receive cannot be sent media.
        client
            .send_to(&subscribe(None).encode(), edge)
            .await
            .unwrap();
        let (len, _) = timeout(Duration::from_secs(2), client.recv_from(&mut buf))
            .await
            .unwrap()
            .unwrap();
        let token = match Control::decode(&buf[..len]) {
            Some(Control::Token { token, .. }) => token,
            other => panic!("expected a token, got {other:?}"),
        };
        assert!(len <= subscribe(None).encode().len());
        assert!(
            timeout(Duration::from_millis(300), client.recv_from(&mut buf))
                .await
                .is_err(),
            "nothing follows a token"
        );
        // A wrong token gets another token, not media.
        client
            .send_to(&subscribe(Some(token ^ 1)).encode(), edge)
            .await
            .unwrap();
        let (len, _) = client.recv_from(&mut buf).await.unwrap();
        assert!(matches!(
            Control::decode(&buf[..len]),
            Some(Control::Token { .. })
        ));
        client
            .send_to(&subscribe(Some(token)).encode(), edge)
            .await
            .unwrap();
        let mut receiver = ObjectReceiver::new();
        let mut parts = BTreeMap::new();
        let mut init = None;
        let mut subscribed = None;
        let mut index = 0_usize;
        while parts.len() < 5 {
            let (len, peer) = timeout(Duration::from_secs(5), client.recv_from(&mut buf))
                .await
                .expect("the edge sends parts")
                .unwrap();
            assert_eq!(peer, edge);
            if let Some(control) = Control::decode(&buf[..len]) {
                if matches!(control, Control::Subscribed { .. }) {
                    subscribed = Some(control);
                }
                continue;
            }
            index += 1;
            if index % 3 == 0 {
                continue; // a third of the datagrams are lost
            }
            if let Some(object) = receiver.push(av_mesh::client_compact::LegId::FIRST, &buf[..len]) {
                match object.kind {
                    UdpObjectKind::Init => init = Some(object.payload),
                    UdpObjectKind::Part => {
                        parts.insert(object.part, object.payload);
                    }
                    UdpObjectKind::Gap => panic!("no part is missing at the edge"),
                }
            }
        }
        assert_eq!(
            subscribed,
            Some(Control::Subscribed {
                stream_id: 77,
                next_part: 0,
                compact: false,
            })
        );
        assert!(receiver.recovered_objects > 0);
        let http_init = get_for_tests(&router, "/live/77/init.mp4").await;
        assert_eq!(init, http_init.body);
        for (part, payload) in &parts {
            let http = get_for_tests(&router, &format!("/live/77/part{part}.mp4")).await;
            assert_eq!(http.status, StatusCode::OK);
            assert_eq!(Some(payload.clone()), http.body, "part {part}");
        }

        // A part published now follows live.
        commit(5).await;
        let part5 = loop {
            let (len, _) = timeout(Duration::from_secs(5), client.recv_from(&mut buf))
                .await
                .expect("the new part arrives")
                .unwrap();
            if let Some(object) = receiver.push(av_mesh::client_compact::LegId::FIRST, &buf[..len]) {
                if object.part == 5 && object.kind == UdpObjectKind::Part {
                    break object.payload;
                }
            }
        };
        assert_eq!(
            Some(part5),
            get_for_tests(&router, "/live/77/part5.mp4").await.body
        );

        // A draining edge sends its clients to the next cache.
        router.lifecycle.drain(node_status::DrainReason::Operator);
        let moved = timeout(Duration::from_secs(5), async {
            loop {
                let (len, _) = client.recv_from(&mut buf).await.unwrap();
                if let Some(Control::Move { reason, .. }) = Control::decode(&buf[..len]) {
                    break reason;
                }
            }
        })
        .await
        .expect("the client is told to move");
        assert_eq!(moved, "draining");

        let _ = shutdown_tx.send(());
        task.await.unwrap().unwrap();
        mesh.shutdown();
    }

    /// Subscribe a test client to stream 77 of `edge` (the token dance) and
    /// return the edge's answer: `Subscribed` or `Refused`.
    async fn subscribe_udp_for_tests(
        client: &UdpSocket,
        edge: SocketAddr,
        from_part: Option<u64>,
    ) -> av_mesh::client_udp::Control {
        use av_mesh::client_udp::{Control, RepairPolicy};
        let subscribe = |token| {
            Control::Subscribe {
                stream_id: 77,
                from_part,
                repair: RepairPolicy {
                    permille: 0,
                    min_symbols: 0,
                    loss_ppm: 0,
                },
                token,
                fast_lane: false,
                compact: None,
                others: Vec::new(),
                resume: false,
            }
            .encode()
        };
        let mut buf = vec![0_u8; 65_536];
        client.send_to(&subscribe(None), edge).await.unwrap();
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let (len, _) = client.recv_from(&mut buf).await.unwrap();
                match Control::decode(&buf[..len]) {
                    Some(Control::Token { token, .. }) => {
                        client.send_to(&subscribe(Some(token)), edge).await.unwrap();
                    }
                    Some(answer @ (Control::Subscribed { .. } | Control::Refused { .. })) => {
                        break answer
                    }
                    _ => {}
                }
            }
        })
        .await
        .expect("the edge answers the subscription")
    }

    /// Phase AM item 8: what the client UDP lanes send is the edge's
    /// egress (its advertised load and free capacity, and its overload),
    /// an overloaded edge refuses a new subscription but takes a client
    /// that moves to it, and the live gauges (subscribers, draining, HLS
    /// sessions) are on /api/assignment and /api/mesh/local.
    #[tokio::test]
    async fn client_udp_egress_is_in_the_load_and_its_gauges_are_live() {
        use av_mesh::client_udp::Control;

        let cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 32, 64).await;
        for sequence in 0..6_u64 {
            cache
                .commit_stream_payload(
                    77,
                    encode_test_canonical_fmp4_bundle_with_duration(
                        77,
                        sequence,
                        (sequence == 0).then_some(b"ftyp-fLaC-moov".as_slice()),
                        &[sequence as u8; 4_000],
                        Some(250),
                        true,
                    ),
                )
                .await
                .unwrap();
        }
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let mut router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));
        // 200 kbit/s: a few clients' cached parts overload it.
        router.edge_load = EdgeLoad::new(EdgeAdmissionConfig {
            capacity_bps: 200_000,
            window_seconds: 2,
            min_sustained_seconds: 1,
            ..EdgeAdmissionConfig::default()
        });
        let socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let edge = socket.local_addr().unwrap();
        router.client_udp_port = Some(edge.port());
        let stats = Arc::clone(&router.edge_udp_stats);
        router
            .edge_load
            .egress
            .add_egress_counter(Arc::new(move || stats.egress_wire_bytes()));
        // No load before any client.
        let api: serde_json::Value = serde_json::from_slice(
            get_for_tests(&router, "/api/assignment?stream=77")
                .await
                .body
                .as_ref()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(api["client_udp"]["load_permille"], 0, "{api:#}");
        assert!(api["client_udp"]["subscribers"].is_null(), "not serving yet: {api:#}");
        let (shutdown_tx, shutdown_rx) = watch::channel(());
        let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
        config.playout = Duration::ZERO;
        let task = tokio::spawn(edge_udp::run_edge_udp(
            edge_udp::EdgeSockets::single(socket),
            router.clone(),
            config,
            Arc::clone(&router.edge_udp_stats),
            Vec::new(),
            shutdown_rx,
        ));
        // Three clients, each sent the six cached parts.
        let mut clients = Vec::new();
        for _ in 0..3 {
            let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
            let answer = subscribe_udp_for_tests(&client, edge, Some(0)).await;
            assert!(matches!(answer, Control::Subscribed { .. }), "{answer:?}");
            clients.push(client);
        }
        let stats = Arc::clone(&router.edge_udp_stats);
        tokio::time::timeout(Duration::from_secs(5), async {
            while stats.bytes.load(Ordering::Relaxed) < 3 * 6 * 4_000 {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("the parts go out");
        let wire = stats.egress_wire_bytes();
        assert_eq!(
            wire,
            stats.bytes.load(Ordering::Relaxed)
                + stats.datagrams.load(Ordering::Relaxed) * edge_udp::UDP_IP_HEADER_BYTES
        );
        let api: serde_json::Value = serde_json::from_slice(
            get_for_tests(&router, "/api/assignment?stream=77")
                .await
                .body
                .as_ref()
                .unwrap(),
        )
        .unwrap();
        let block = &api["client_udp"];
        assert_eq!(block["subscribers"], 3, "{api:#}");
        assert_eq!(block["draining"], false);
        assert_eq!(block["hls_sessions"], 0);
        assert!(block["egress_wire_bytes"].as_u64().unwrap() >= wire, "{api:#}");
        // ~73 kB in a window of at most 2 s: more than the 170 kbit/s that
        // the edge admits.
        assert!(block["egress_observed_bps"].as_u64().unwrap() >= 290_000, "{api:#}");
        assert!(block["load_permille"].as_u64().unwrap() >= 1_000, "{api:#}");
        let local: serde_json::Value = serde_json::from_slice(
            get_for_tests(&router, "/api/mesh/local")
                .await
                .body
                .as_ref()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(local["client_udp"]["subscribers"], 3, "{local:#}");
        let own = local["edge_services"]
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["node_id"] == router.node.node_id)
            .unwrap()
            .clone();
        assert_eq!(own["udp_subscribers"], 3);
        assert!(own["egress_observed_bps"].as_u64().unwrap() >= 290_000, "{own:#}");
        let snapshot = router.edge_load.admission_snapshot();
        assert!(snapshot.overloaded, "{snapshot:?}");
        // Overloaded: a new listener is refused, a moving one is taken.
        let newcomer = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        match subscribe_udp_for_tests(&newcomer, edge, None).await {
            Control::Refused { reason, .. } => assert_eq!(reason, "edge-busy"),
            other => panic!("expected edge-busy, got {other:?}"),
        }
        assert_eq!(stats.load_refusals.load(Ordering::Relaxed), 1);
        let mover = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let answer = subscribe_udp_for_tests(&mover, edge, Some(5)).await;
        assert!(matches!(answer, Control::Subscribed { .. }), "{answer:?}");
        assert_eq!(stats.live_subscribers(), Some(4));
        // Draining shows on the gauges.
        router.lifecycle.drain(node_status::DrainReason::Operator);
        let api: serde_json::Value = serde_json::from_slice(
            get_for_tests(&router, "/api/assignment?stream=77")
                .await
                .body
                .as_ref()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(api["client_udp"]["draining"], true, "{api:#}");
        let _ = shutdown_tx.send(());
        task.await.unwrap().unwrap();
        mesh.shutdown();
    }

    /// An edge serving client UDP for stream 77 (four 250 ms parts cached)
    /// with `config`, for the tests of moves (B unit Z).
    struct UdpEdgeForTests {
        cache: Arc<LiveTsCache>,
        mesh: Arc<CacheMeshHandle>,
        router: AppRouter,
        edge: SocketAddr,
        shutdown_tx: watch::Sender<()>,
        task: tokio::task::JoinHandle<anyhow::Result<()>>,
    }

    impl UdpEdgeForTests {
        async fn start(config: edge_udp::EdgeUdpConfig) -> Self {
            let cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 32, 64).await;
            for sequence in 0..4_u64 {
                cache
                    .commit_stream_payload(
                        77,
                        encode_test_canonical_fmp4_bundle_with_duration(
                            77,
                            sequence,
                            (sequence == 0).then_some(b"ftyp-fLaC-moov".as_slice()),
                            &[sequence as u8; 400],
                            Some(250),
                            true,
                        ),
                    )
                    .await
                    .unwrap();
            }
            let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
            let mut router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));
            let socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
            let edge = socket.local_addr().unwrap();
            router.client_udp_port = Some(edge.port());
            let (shutdown_tx, shutdown_rx) = watch::channel(());
            let task = tokio::spawn(edge_udp::run_edge_udp(
                edge_udp::EdgeSockets::single(socket),
                router.clone(),
                config,
                Arc::clone(&router.edge_udp_stats),
                Vec::new(),
                shutdown_rx,
            ));
            Self {
                cache,
                mesh,
                router,
                edge,
                shutdown_tx,
                task,
            }
        }

        fn stats(&self) -> &edge_udp::EdgeUdpStats {
            &self.router.edge_udp_stats
        }

        /// Publish part `sequence` of stream 77.
        async fn commit(&self, sequence: u64) {
            self.cache
                .commit_stream_payload(
                    77,
                    encode_test_canonical_fmp4_bundle_with_duration(
                        77,
                        sequence,
                        None,
                        &[sequence as u8; 400],
                        Some(250),
                        true,
                    ),
                )
                .await
                .unwrap();
        }

        /// A client subscribed from part 0, and its token.
        async fn client(&self) -> (UdpSocket, u64) {
            self.client_with(&[]).await
        }

        /// A client subscribed from part 0 that names `others` as its
        /// other legs (`o=`), and its token.
        async fn client_with(&self, others: &[&str]) -> (UdpSocket, u64) {
            use av_mesh::client_udp::Control;
            let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
            client
                .send_to(&udp_subscribe_for_tests(None, None), self.edge)
                .await
                .unwrap();
            let mut buf = vec![0_u8; 65_536];
            let token = loop {
                let (len, _) =
                    tokio::time::timeout(Duration::from_secs(5), client.recv_from(&mut buf))
                        .await
                        .expect("a token")
                        .unwrap();
                if let Some(Control::Token { token, .. }) = Control::decode(&buf[..len]) {
                    break token;
                }
            };
            let mut subscribe = udp_subscribe_for_tests(Some(token), Some(0));
            if !others.is_empty() {
                subscribe = Control::Subscribe {
                    stream_id: 77,
                    from_part: Some(0),
                    repair: av_mesh::client_udp::RepairPolicy {
                        permille: 0,
                        min_symbols: 0,
                        loss_ppm: 0,
                    },
                    token: Some(token),
                    fast_lane: false,
                    compact: None,
                    others: others.iter().map(|node| (*node).to_owned()).collect(),
                    resume: false,
                }
                .encode();
            }
            client.send_to(&subscribe, self.edge).await.unwrap();
            loop {
                let (len, _) =
                    tokio::time::timeout(Duration::from_secs(5), client.recv_from(&mut buf))
                        .await
                        .expect("an answer")
                        .unwrap();
                match Control::decode(&buf[..len]) {
                    Some(Control::Subscribed { .. }) => break,
                    Some(other @ Control::Refused { .. }) => panic!("{other:?}"),
                    _ => {}
                }
            }
            (client, token)
        }

        async fn stop(self) {
            let _ = self.shutdown_tx.send(());
            self.task.await.unwrap().unwrap();
            self.mesh.shutdown();
        }
    }

    /// A `SUB` of stream 77 (RaptorQ lane, no repair).
    fn udp_subscribe_for_tests(token: Option<u64>, from_part: Option<u64>) -> Vec<u8> {
        use av_mesh::client_udp::{Control, RepairPolicy};
        Control::Subscribe {
            stream_id: 77,
            from_part,
            repair: RepairPolicy {
                permille: 0,
                min_symbols: 0,
                loss_ppm: 0,
            },
            token,
            fast_lane: false,
            compact: None,
            others: Vec::new(),
            resume: false,
        }
        .encode()
    }

    /// What a test client receives within `wait`: the control datagrams,
    /// each with when it came, and the media datagrams counted.
    async fn udp_receive_for_tests(
        client: &UdpSocket,
        wait: Duration,
    ) -> (Vec<(Instant, av_mesh::client_udp::Control)>, usize) {
        let mut buf = vec![0_u8; 65_536];
        let until = Instant::now() + wait;
        let (mut controls, mut media) = (Vec::new(), 0);
        while let Ok(Ok((len, _))) =
            tokio::time::timeout_at(until.into(), client.recv_from(&mut buf)).await
        {
            match av_mesh::client_udp::Control::decode(&buf[..len]) {
                Some(control) => controls.push((Instant::now(), control)),
                None => media += 1,
            }
        }
        (controls, media)
    }

    fn is_move_for_tests(control: &av_mesh::client_udp::Control, reason: &str) -> bool {
        matches!(control, av_mesh::client_udp::Control::Move { reason: got, .. } if got == reason)
    }

    /// Wait (at most `wait`) for `MOVE <reason>`; `false` if none came.
    async fn udp_wait_for_move_for_tests(client: &UdpSocket, reason: &str, wait: Duration) -> bool {
        let mut buf = vec![0_u8; 65_536];
        let until = Instant::now() + wait;
        while let Ok(Ok((len, _))) =
            tokio::time::timeout_at(until.into(), client.recv_from(&mut buf)).await
        {
            if av_mesh::client_udp::Control::decode(&buf[..len])
                .is_some_and(|control| is_move_for_tests(&control, reason))
            {
                return true;
            }
        }
        false
    }

    /// B rules 1 to 4: a client that a draining edge sent `MOVE` is still
    /// sent the stream's new parts until it leaves: with its `UNSUB` at
    /// once (a completed move), and one that only refreshes (each refresh
    /// answered `MOVE`) at the grace (an expired move).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_moved_subscriber_is_kept_until_its_unsub_or_the_grace() {
        use av_mesh::client_udp::Control;

        let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
        config.playout = Duration::ZERO;
        config.drain_spread = Duration::ZERO;
        config.move_grace = Duration::from_millis(1_500);
        let edge = UdpEdgeForTests::start(config).await;
        let (leaver, leaver_token) = edge.client().await;
        let (stayer, stayer_token) = edge.client().await;
        // The cached parts arrive.
        udp_receive_for_tests(&leaver, Duration::from_millis(300)).await;
        udp_receive_for_tests(&stayer, Duration::from_millis(300)).await;
        edge.router.lifecycle.drain(node_status::DrainReason::Operator);
        let marked_by = Instant::now();
        for client in [&leaver, &stayer] {
            assert!(
                udp_wait_for_move_for_tests(client, "draining", Duration::from_millis(1_200)).await
            );
        }
        assert_eq!(edge.stats().live_subscribers(), Some(2));
        assert_eq!(edge.stats().legs().unwrap().leaving, 2);
        // A part published after the MOVE still reaches both.
        edge.commit(4).await;
        for client in [&leaver, &stayer] {
            let (_, media) = udp_receive_for_tests(client, Duration::from_millis(300)).await;
            assert!(media > 0, "served after its MOVE");
        }
        // UNSUB: gone at once, a completed move.
        leaver
            .send_to(
                &Control::Unsubscribe {
                    stream_id: 77,
                    token: leaver_token,
                }
                .encode(),
                edge.edge,
            )
            .await
            .unwrap();
        tokio::time::timeout(Duration::from_secs(2), async {
            while edge.stats().live_subscribers() != Some(1) {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("the UNSUB removes it");
        assert_eq!(edge.stats().moves_completed.load(Ordering::Relaxed), 1);
        // The other refreshes: answered MOVE, and cut at the grace anyway.
        let mut answered_move = 0;
        let mut buf = vec![0_u8; 65_536];
        while edge.stats().live_subscribers() == Some(1) {
            assert!(
                marked_by.elapsed() < Duration::from_secs(5),
                "cut at the grace"
            );
            stayer
                .send_to(
                    &udp_subscribe_for_tests(Some(stayer_token), None),
                    edge.edge,
                )
                .await
                .unwrap();
            if let Ok(Ok((len, _))) =
                tokio::time::timeout(Duration::from_millis(200), stayer.recv_from(&mut buf)).await
            {
                if Control::decode(&buf[..len])
                    .is_some_and(|control| is_move_for_tests(&control, "draining"))
                {
                    answered_move += 1;
                }
            }
        }
        assert!(answered_move >= 3, "{answered_move}");
        assert_eq!(edge.stats().moves_expired.load(Ordering::Relaxed), 1);
        assert_eq!(edge.stats().moves.load(Ordering::Relaxed), 2);
        edge.stop().await;
    }

    /// B rule 3: a leaving subscriber that neither leaves nor refreshes is
    /// sent `MOVE` again every 250 ms until the grace. Timing-sensitive on
    /// a loaded machine (the gaps' upper bound is four ticks): run it again
    /// alone before calling it a failure.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn move_is_repeated_to_a_subscriber_that_stays() {
        let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
        config.playout = Duration::ZERO;
        config.drain_spread = Duration::ZERO;
        config.move_grace = Duration::from_millis(4_000);
        let edge = UdpEdgeForTests::start(config).await;
        let (client, _) = edge.client().await;
        edge.router.lifecycle.drain(node_status::DrainReason::Operator);
        // The first within a housekeeping second, then one every 250 ms
        // (the sender looks at least every keepalive, 80 ms).
        assert!(
            udp_wait_for_move_for_tests(&client, "draining", Duration::from_millis(1_200)).await
        );
        let first = Instant::now();
        let (controls, _) = udp_receive_for_tests(&client, Duration::from_millis(2_000)).await;
        let moves: Vec<Instant> = std::iter::once(first)
            .chain(
                controls
                    .iter()
                    .filter(|(_, control)| is_move_for_tests(control, "draining"))
                    .map(|(at, _)| *at),
            )
            .collect();
        let gaps: Vec<Duration> = moves.windows(2).map(|pair| pair[1] - pair[0]).collect();
        assert!(moves.len() >= 5, "{gaps:?}");
        for gap in &gaps {
            assert!(*gap >= Duration::from_millis(200), "{gaps:?}");
            assert!(*gap <= Duration::from_millis(1_000), "{gaps:?}");
        }
        assert_eq!(
            edge.stats().moves.load(Ordering::Relaxed),
            1,
            "one move, reminded"
        );
        assert_eq!(edge.stats().live_subscribers(), Some(1));
        edge.stop().await;
    }

    /// B rule 6: an edge that stops tells every subscriber still there to
    /// move.
    #[tokio::test]
    async fn a_stopping_edge_sends_move_to_whoever_is_left() {
        let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
        config.playout = Duration::ZERO;
        let edge = UdpEdgeForTests::start(config).await;
        let (first, _) = edge.client().await;
        let (second, _) = edge.client().await;
        udp_receive_for_tests(&first, Duration::from_millis(200)).await;
        udp_receive_for_tests(&second, Duration::from_millis(200)).await;
        edge.stop().await;
        for client in [&first, &second] {
            let (controls, _) = udp_receive_for_tests(client, Duration::from_millis(500)).await;
            assert!(
                controls
                    .iter()
                    .any(|(_, control)| is_move_for_tests(control, "draining")),
                "{controls:?}"
            );
        }
    }

    /// Phase AM item 9 and B rules 1 to 4: a draining edge with 1,000 UDP
    /// subscribers sends them `MOVE` spread over --client-udp-drain-spread-ms
    /// (2 s) and serves each until it leaves: the leaving gauge rises
    /// across at least 1.5 s, the live gauge holds until the first grace
    /// ends, a client's UNSUB takes it out at once, the rest go at their
    /// grace. With the spread at 0 they are all marked at once; with the
    /// grace at 0 they all go at once, as before B. Timing-sensitive on a
    /// loaded machine (the gauges are polled, and the upper bounds allow a
    /// second of lateness): run it again alone before calling it a failure.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_draining_edge_serves_its_udp_clients_until_they_have_left() {
        use av_mesh::client_udp::Control;

        struct Drained {
            /// From the drain: the first and last rise of the leaving gauge,
            /// the first fall of the live gauge, and when it reached 0.
            marked: (Duration, Duration),
            first_gone: Duration,
            all_gone: Duration,
            completed: u64,
            expired: u64,
        }

        async fn drain(spread_ms: u64, grace_ms: u64) -> Drained {
            let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 2_000);
            config.playout = Duration::ZERO;
            config.drain_spread = Duration::from_millis(spread_ms);
            config.move_grace = Duration::from_millis(grace_ms);
            let edge = UdpEdgeForTests::start(config).await;
            let stats = edge.stats();
            let (client, token) = edge.client().await;
            // 999 more, with no client behind them: privileged ports that no
            // socket of another test (ephemeral, any address) can hold.
            let crowd: Vec<SocketAddr> = (1..=999_u16)
                .map(|port| SocketAddr::from(([127, 0, 0, 3], port)))
                .collect();
            edge_udp::insert_test_subscribers(&stats.table.get().unwrap().0, 77, &crowd, 4);
            assert_eq!(stats.live_subscribers(), Some(1_000));
            let moves_before = stats.moves.load(Ordering::Relaxed);
            edge.router.lifecycle.drain(node_status::DrainReason::Operator);
            let started = Instant::now();
            let (mut first_mark, mut last_mark, mut first_gone) = (None, None, None);
            let (mut leaving_seen, mut unsubscribed) = (0, false);
            let mut buf = vec![0_u8; 65_536];
            let all_gone = loop {
                let count = stats.live_subscribers().unwrap_or(0);
                let leaving = stats.legs().map_or(0, |legs| legs.leaving);
                if leaving > leaving_seen {
                    first_mark.get_or_insert(started.elapsed());
                    last_mark = Some(started.elapsed());
                    leaving_seen = leaving;
                }
                if count < 1_000 && (!unsubscribed || count < 999) {
                    first_gone.get_or_insert(started.elapsed());
                }
                if count == 0 {
                    break started.elapsed();
                }
                assert!(started.elapsed() < Duration::from_secs(10), "{count} left");
                // The real client: served after its MOVE, then leaves.
                if !unsubscribed {
                    if let Ok(Ok((len, _))) =
                        tokio::time::timeout(Duration::from_millis(1), client.recv_from(&mut buf))
                            .await
                    {
                        if Control::decode(&buf[..len])
                            .is_some_and(|control| is_move_for_tests(&control, "draining"))
                            && grace_ms > 0
                        {
                            edge.commit(4).await;
                            let (_, media) =
                                udp_receive_for_tests(&client, Duration::from_millis(300)).await;
                            assert!(media > 0, "served after its MOVE");
                            let unsubscribe = Control::Unsubscribe {
                                stream_id: 77,
                                token,
                            };
                            client
                                .send_to(&unsubscribe.encode(), edge.edge)
                                .await
                                .unwrap();
                            unsubscribed = true;
                        }
                    }
                } else {
                    tokio::time::sleep(Duration::from_millis(5)).await;
                }
            };
            assert_eq!(stats.moves.load(Ordering::Relaxed) - moves_before, 1_000);
            let drained = Drained {
                marked: (
                    first_mark.unwrap_or_default(),
                    last_mark.unwrap_or_default(),
                ),
                first_gone: first_gone.unwrap_or_default(),
                all_gone,
                completed: stats.moves_completed.load(Ordering::Relaxed),
                expired: stats.moves_expired.load(Ordering::Relaxed),
            };
            edge.stop().await;
            drained
        }

        let spread = drain(2_000, 1_500).await;
        let across = spread.marked.1 - spread.marked.0;
        assert!(
            across >= Duration::from_millis(1_500),
            "marked across {across:?}"
        );
        assert!(
            across <= Duration::from_millis(4_000),
            "marked across {across:?}"
        );
        // Nobody is cut before the grace of the first mark.
        assert!(
            spread.first_gone >= spread.marked.0 + Duration::from_millis(1_000),
            "first gone at {:?}, first marked at {:?}",
            spread.first_gone,
            spread.marked.0
        );
        assert!(
            spread.all_gone <= spread.marked.1 + Duration::from_millis(3_500),
            "{:?}",
            spread.all_gone
        );
        assert_eq!(spread.completed, 1);
        assert_eq!(spread.expired, 999);
        // Spread 0: every one marked in one round, cut at the grace.
        let at_once = drain(0, 1_500).await;
        assert!(at_once.marked.1 - at_once.marked.0 < Duration::from_millis(500));
        assert!(at_once.first_gone >= at_once.marked.0 + Duration::from_millis(1_000));
        // Grace 0: removed at the MOVE, all in one round, as before B.
        let before = drain(0, 0).await;
        assert!(
            before.all_gone < Duration::from_millis(2_500),
            "{:?}",
            before.all_gone
        );
        assert_eq!(before.expired, 0);
        assert_eq!(before.completed, 0);
    }

    /// B 2.2: the leaving subscribers and the moves' outcomes are on
    /// /api/assignment beside the other gauges.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn the_gauges_show_leaving_subscribers() {
        use av_mesh::client_udp::Control;

        let args = Args::try_parse_from(["av-mesh"]).unwrap();
        assert_eq!(args.client_udp_move_grace_ms, 10_000);
        let args = Args::try_parse_from(["av-mesh", "--client-udp-move-grace-ms", "0"]).unwrap();
        assert_eq!(args.client_udp_move_grace_ms, 0);

        let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
        config.playout = Duration::ZERO;
        config.drain_spread = Duration::ZERO;
        config.move_grace = Duration::from_millis(1_500);
        let edge = UdpEdgeForTests::start(config).await;
        let (client, token) = edge.client().await;
        let crowd: Vec<SocketAddr> = (1..=3_u16)
            .map(|port| SocketAddr::from(([127, 0, 0, 4], port)))
            .collect();
        edge_udp::insert_test_subscribers(&edge.stats().table.get().unwrap().0, 77, &crowd, 4);
        let gauges = || async {
            let api: serde_json::Value = serde_json::from_slice(
                get_for_tests(&edge.router, "/api/assignment?stream=77")
                    .await
                    .body
                    .as_ref()
                    .unwrap(),
            )
            .unwrap();
            api["client_udp"].clone()
        };
        let block = gauges().await;
        assert_eq!(block["leaving"], 0, "{block:#}");
        assert_eq!(block["move_grace_ms"], 1_500, "{block:#}");
        edge.router.lifecycle.drain(node_status::DrainReason::Operator);
        tokio::time::timeout(Duration::from_secs(3), async {
            while edge.stats().legs().unwrap().leaving != 4 {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("all four are marked");
        let block = gauges().await;
        assert_eq!(block["subscribers"], 4, "{block:#}");
        assert_eq!(block["leaving"], 4, "{block:#}");
        client
            .send_to(
                &Control::Unsubscribe {
                    stream_id: 77,
                    token,
                }
                .encode(),
                edge.edge,
            )
            .await
            .unwrap();
        tokio::time::timeout(Duration::from_secs(4), async {
            while edge.stats().live_subscribers() != Some(0) {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("the rest are cut at the grace");
        let block = gauges().await;
        assert_eq!(block["subscribers"], 0, "{block:#}");
        assert_eq!(block["leaving"], 0, "{block:#}");
        assert_eq!(block["moves_completed"], 1, "{block:#}");
        assert_eq!(block["moves_expired"], 3, "{block:#}");
        assert_eq!(block["moves_taken_back"], 0, "{block:#}");
        edge.stop().await;
    }

    /// B 2.3: the edge counts its subscribers that name no other leg, and
    /// those by the other node they name, matched against the region's
    /// advertised nodes ("" for one it does not know); a refresh that names
    /// another set moves the count.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn the_gauges_count_legs_by_their_other_edge() {
        let args = Args::try_parse_from(["av-mesh"]).unwrap();
        assert!(args.client_udp_rebalance_to_mean);
        let args =
            Args::try_parse_from(["av-mesh", "--client-udp-rebalance-to-mean", "false"]).unwrap();
        assert!(!args.client_udp_rebalance_to_mean);

        let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
        config.playout = Duration::ZERO;
        let edge = UdpEdgeForTests::start(config).await;
        let mut other = telemetry_snapshot_for_tests(
            "edge-b",
            &edge.router.node.region,
            "test-continent",
            51.6,
            -0.2,
            Vec::new(),
            77,
        );
        other.edge_service = Some(EdgeServiceSnapshot::from_node(
            &other.node,
            None,
            "edge",
            EdgeLoadSnapshot::default(),
        ));
        edge.router.telemetry.ingest_snapshot(other).await;
        let _alone = edge.client().await;
        let _beside_b = edge.client_with(&["edge-b"]).await;
        let (both, both_token) = edge.client_with(&["edge-b", "edge-unknown"]).await;
        let gauges = || async {
            let api: serde_json::Value = serde_json::from_slice(
                get_for_tests(&edge.router, "/api/assignment?stream=77")
                    .await
                    .body
                    .as_ref()
                    .unwrap(),
            )
            .unwrap();
            api["client_udp"].clone()
        };
        let block = gauges().await;
        assert_eq!(block["subscribers"], 3, "{block:#}");
        assert_eq!(block["single_legs"], 1, "{block:#}");
        assert_eq!(
            block["legs_by_other"],
            serde_json::json!({"edge-b": 2, "": 1}),
            "{block:#}"
        );
        assert_eq!(block["redundant_refusals"], 0, "{block:#}");
        // Its other leg went: the refresh says so.
        both.send_to(&udp_subscribe_for_tests(Some(both_token), None), edge.edge)
            .await
            .unwrap();
        tokio::time::timeout(Duration::from_secs(2), async {
            while edge.stats().legs().unwrap().single != 2 {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("the refresh updates its other legs");
        let block = gauges().await;
        assert_eq!(
            block["legs_by_other"],
            serde_json::json!({"edge-b": 1}),
            "{block:#}"
        );
        edge.stop().await;
    }

    /// B rules 5 and R2 on a running edge: a subscriber that a rebalance
    /// marked is answered `MOVE` to a plain refresh; when it asks again
    /// with a part (its client gave up on a replacement that was not level)
    /// it is taken back: answered `OK`, no longer leaving nor reminded,
    /// counted in `moves_taken_back`, and its share goes back to the round
    /// that sent it.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_rebalanced_subscriber_that_asks_with_a_part_is_taken_back_and_its_share_returned()
    {
        use av_mesh::client_udp::Control;

        let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
        config.playout = Duration::ZERO;
        let edge = UdpEdgeForTests::start(config).await;
        let (client, token) = edge.client().await;
        udp_receive_for_tests(&client, Duration::from_millis(200)).await;
        // A round of four, sent now: to this client and three more that
        // stay where they went.
        let since = Instant::now();
        {
            let mut state = edge.router.rebalance_state.lock().unwrap();
            state.start_round(since, 4, Vec::new());
            let due = state.reserve(since, Duration::ZERO);
            state.settle(since, due, 4);
            assert!(!state.active());
        }
        let table = &edge.stats().table.get().unwrap().0;
        assert_eq!(
            edge_udp::mark_test_subscribers(table, 77, "rebalance", since),
            1
        );
        assert_eq!(edge.stats().legs().unwrap().leaving, 1);
        // A plain refresh: MOVE.
        client
            .send_to(&udp_subscribe_for_tests(Some(token), None), edge.edge)
            .await
            .unwrap();
        assert!(
            udp_wait_for_move_for_tests(&client, "rebalance", Duration::from_secs(2)).await
        );
        assert_eq!(edge.stats().legs().unwrap().leaving, 1);
        // With a part: taken back (a reminder may come before the answer).
        client
            .send_to(&udp_subscribe_for_tests(Some(token), Some(3)), edge.edge)
            .await
            .unwrap();
        let mut buf = vec![0_u8; 65_536];
        loop {
            let (len, _) = tokio::time::timeout(Duration::from_secs(2), client.recv_from(&mut buf))
                .await
                .expect("an answer")
                .unwrap();
            if let Some(Control::Subscribed { .. }) = Control::decode(&buf[..len]) {
                break;
            }
        }
        assert_eq!(edge.stats().moves_taken_back.load(Ordering::Relaxed), 1);
        assert_eq!(edge.stats().legs().unwrap().leaving, 0);
        assert_eq!(edge.stats().live_subscribers(), Some(1));
        assert!(
            edge.router.rebalance_state.lock().unwrap().active(),
            "its share is the round's again"
        );
        // No reminder after the take-back (they come every 250 ms; one
        // collected just before it may still be on its way).
        udp_receive_for_tests(&client, Duration::from_millis(300)).await;
        let (controls, _) = udp_receive_for_tests(&client, Duration::from_millis(600)).await;
        assert!(
            !controls
                .iter()
                .any(|(_, control)| is_move_for_tests(control, "rebalance")),
            "{controls:?}"
        );
        edge.stop().await;
    }

    /// Without the counter (--client-udp-egress-load false) and with
    /// --client-udp-admit-by-load false, the edge is as before: no load
    /// from UDP and every new subscription taken.
    #[tokio::test]
    async fn without_the_am8_flags_udp_egress_is_not_load() {
        use av_mesh::client_udp::Control;

        let cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 32, 64).await;
        for sequence in 0..6_u64 {
            cache
                .commit_stream_payload(
                    77,
                    encode_test_canonical_fmp4_bundle_with_duration(
                        77,
                        sequence,
                        (sequence == 0).then_some(b"ftyp-fLaC-moov".as_slice()),
                        &[sequence as u8; 4_000],
                        Some(250),
                        true,
                    ),
                )
                .await
                .unwrap();
        }
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let mut router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));
        router.edge_load = EdgeLoad::new(EdgeAdmissionConfig {
            capacity_bps: 1_000,
            window_seconds: 2,
            min_sustained_seconds: 1,
            ..EdgeAdmissionConfig::default()
        });
        let socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let edge = socket.local_addr().unwrap();
        router.client_udp_port = Some(edge.port());
        let (shutdown_tx, shutdown_rx) = watch::channel(());
        let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
        config.playout = Duration::ZERO;
        config.admit_by_load = false;
        let task = tokio::spawn(edge_udp::run_edge_udp(
            edge_udp::EdgeSockets::single(socket),
            router.clone(),
            config,
            Arc::clone(&router.edge_udp_stats),
            Vec::new(),
            shutdown_rx,
        ));
        for from_part in [Some(0), None, None] {
            let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
            let answer = subscribe_udp_for_tests(&client, edge, from_part).await;
            assert!(matches!(answer, Control::Subscribed { .. }), "{answer:?}");
            tokio::time::sleep(Duration::from_millis(200)).await;
        }
        let snapshot = router.edge_load.admission_snapshot();
        assert_eq!(snapshot.observed_bps, 0);
        assert!(!snapshot.overloaded);
        assert_eq!(router.edge_udp_stats.live_subscribers(), Some(3));
        let _ = shutdown_tx.send(());
        task.await.unwrap().unwrap();
        mesh.shutdown();
    }

    /// A client that moves to an edge names a part that is past its playout
    /// deadline: the edge starts it at the oldest part within the deadline,
    /// not at the named part (which would make it wait behind a backlog).
    /// Without a deadline it resumes at the named part, as before.
    #[tokio::test]
    async fn a_moved_udp_client_resumes_within_its_playout_deadline() {
        use av_mesh::client_udp::{Control, RepairPolicy};
        use tokio::time::timeout;

        async fn first_part(playout_ms: u64, resume_from_request: bool) -> (u64, u64) {
            let cache = LiveTsCache::new(1, Duration::from_millis(250), 4, 32, 64).await;
            for sequence in 0..10_u64 {
                cache
                    .commit_stream_payload(
                        77,
                        encode_test_canonical_fmp4_bundle_with_duration(
                            77,
                            sequence,
                            (sequence == 0).then_some(b"ftyp-fLaC-moov".as_slice()),
                            &[sequence as u8; 2_000],
                            Some(250),
                            true,
                        ),
                    )
                    .await
                    .unwrap();
            }
            let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
            let router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));
            let socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
            let edge = socket.local_addr().unwrap();
            let (shutdown_tx, shutdown_rx) = watch::channel(());
            let stats = Arc::new(edge_udp::EdgeUdpStats::default());
            let mut config = edge_udp::EdgeUdpConfig::with_defaults(1_200, 16);
            config.playout = Duration::from_millis(playout_ms);
            config.resume_from_request = resume_from_request;
            let task = tokio::spawn(edge_udp::run_edge_udp(
                edge_udp::EdgeSockets::single(socket),
                router.clone(),
                config,
                Arc::clone(&stats),
                Vec::new(),
                shutdown_rx,
            ));
            let client = UdpSocket::bind("127.0.0.1:0").await.unwrap();
            let subscribe = |token| {
                Control::Subscribe {
                    stream_id: 77,
                    from_part: Some(1),
                    repair: RepairPolicy {
                        permille: 0,
                        min_symbols: 0,
                        loss_ppm: 0,
                    },
                    token,
                    fast_lane: false,
                    compact: None,
                    others: Vec::new(),
                    resume: false,
                }
                .encode()
            };
            let mut buf = vec![0_u8; 65_536];
            client.send_to(&subscribe(None), edge).await.unwrap();
            let next = timeout(Duration::from_secs(5), async {
                loop {
                    let (len, _) = client.recv_from(&mut buf).await.unwrap();
                    match Control::decode(&buf[..len]) {
                        Some(Control::Token { token, .. }) => {
                            client.send_to(&subscribe(Some(token)), edge).await.unwrap();
                        }
                        Some(Control::Subscribed { next_part, .. }) => break next_part,
                        _ => {}
                    }
                }
            })
            .await
            .expect("the edge takes the client");
            let _ = shutdown_tx.send(());
            task.await.unwrap().unwrap();
            mesh.shutdown();
            (next, stats.playout_skipped_parts.load(Ordering::Relaxed))
        }
        // Parts of 250 ms, the head at 9: 500 ms is the two parts behind it
        // (--client-udp-resume-from-request false, before wave 8).
        assert_eq!(first_part(500, false).await, (7, 6));
        assert_eq!(first_part(0, false).await, (1, 0));
        // Wave 8 S2: a client that moved here resumes at the part it names
        // while the cache holds it, late rather than missing.
        assert_eq!(first_part(500, true).await, (1, 0));
    }

