    #[test]
    fn the_low_latency_flags_default_to_the_new_behaviour_and_can_be_turned_off() {
        let args = Args::try_parse_from(["av-mesh"])
            .unwrap()
            .normalized()
            .unwrap();
        assert!(args.relay_forward_nonblocking);
        // Unset, the journal holds 30 s of 2.5 ms parts, and no less than
        // the fixed default.
        assert_eq!(args.hop_journal_capacity, None);
        assert_eq!(DEFAULT_HOP_JOURNAL_CAPACITY, 262_144);
        assert_eq!(
            hop_journal_capacity_for(args.part_us, args.hop_journal_seconds),
            DEFAULT_HOP_JOURNAL_CAPACITY
        );

        let args = Args::try_parse_from([
            "av-mesh",
            "--relay-forward-nonblocking=false",
            "--hop-journal-capacity",
            "0",
        ])
        .unwrap()
        .normalized()
        .unwrap();
        assert!(!args.relay_forward_nonblocking);
        assert_eq!(args.hop_journal_capacity, Some(0));

        // The mesh always sends on publish: there is no flag to turn it off.
        assert!(Args::try_parse_from(["av-mesh", "--mesh-sync-on-publish", "true"]).is_err());
        // A bare flag is not accepted, so that `false` cannot be lost.
        assert!(Args::try_parse_from(["av-mesh", "--relay-forward-nonblocking"]).is_err());

        // The journal reaches the cache-mesh configuration.
        let journal = Arc::new(HopJournal::new("n", 8));
        let config = with_low_latency_mesh_options(
            CacheMeshConfig::new("n", "uk", unused_loopback_addr()),
            &journal,
        );
        assert!(format!("{config:?}").contains("send_observer: Some(..)"));
        let config = with_low_latency_mesh_options(
            CacheMeshConfig::new("n", "uk", unused_loopback_addr()),
            &Arc::new(HopJournal::new("n", 0)),
        );
        assert!(format!("{config:?}").contains("send_observer: None"));
    }

    async fn relay_forward_test_children(
        count: usize,
    ) -> (Arc<RelayDownstreamForwarder>, Vec<UdpSocket>) {
        let mut receivers = Vec::with_capacity(count);
        let mut endpoints = Vec::with_capacity(count);
        for _ in 0..count {
            let receiver = UdpSocket::bind((Ipv4Addr::LOCALHOST, 0)).await.unwrap();
            endpoints.push(RelayForwardEndpoint {
                bind: SocketAddr::from((Ipv4Addr::LOCALHOST, 0)),
                target: receiver.local_addr().unwrap(),
                role: RelayForwardRole::All,
            });
            receivers.push(receiver);
        }
        let forwarder = RelayDownstreamForwarder::bind(&endpoints)
            .await
            .unwrap()
            .unwrap();
        (forwarder, receivers)
    }

    async fn receive_relay_test_datagram(receiver: &UdpSocket) -> Vec<u8> {
        let mut buf = [0_u8; 2_048];
        let (len, _) = tokio::time::timeout(Duration::from_secs(2), receiver.recv_from(&mut buf))
            .await
            .expect("every child must receive every datagram")
            .unwrap();
        buf[..len].to_vec()
    }

    fn take_relay_forward_attempts(
        forwarder: &RelayDownstreamForwarder,
    ) -> Vec<(usize, RelayForwardAttempt)> {
        std::mem::take(
            &mut *forwarder
                .test_attempts
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner),
        )
    }

    #[tokio::test]
    async fn relay_forward_sends_to_every_child_before_waiting_for_a_full_one() {
        let (forwarder, receivers) = relay_forward_test_children(3).await;
        assert!(forwarder.nonblocking.load(Ordering::Relaxed));
        // Let the reactor see that the new sockets are writable, as it has
        // long before the first media datagram on a running relay.
        for _ in 0..3 {
            forwarder
                .forward(b"warm", MediaDatagramRole::Source, None)
                .await;
        }
        for receiver in &receivers {
            for _ in 0..3 {
                assert_eq!(receive_relay_test_datagram(receiver).await, b"warm");
            }
        }
        take_relay_forward_attempts(&forwarder);

        // The socket of the first child is full. The other children get the
        // datagram at once, and only then does the relay wait for the first.
        forwarder.test_would_block.store(0b001, Ordering::Relaxed);
        forwarder
            .forward(b"datagram-1", MediaDatagramRole::Source, None)
            .await;
        assert_eq!(
            take_relay_forward_attempts(&forwarder),
            vec![
                (0, RelayForwardAttempt::WouldBlock),
                (1, RelayForwardAttempt::Immediate),
                (2, RelayForwardAttempt::Immediate),
                (0, RelayForwardAttempt::Awaited),
            ]
        );
        for receiver in &receivers {
            assert_eq!(receive_relay_test_datagram(receiver).await, b"datagram-1");
        }

        // Two full children are waited for in the order of the paths.
        forwarder.test_would_block.store(0b101, Ordering::Relaxed);
        forwarder
            .forward(b"datagram-2", MediaDatagramRole::Source, None)
            .await;
        assert_eq!(
            take_relay_forward_attempts(&forwarder),
            vec![
                (0, RelayForwardAttempt::WouldBlock),
                (1, RelayForwardAttempt::Immediate),
                (2, RelayForwardAttempt::WouldBlock),
                (0, RelayForwardAttempt::Awaited),
                (2, RelayForwardAttempt::Awaited),
            ]
        );
        for receiver in &receivers {
            assert_eq!(receive_relay_test_datagram(receiver).await, b"datagram-2");
        }

        // With the flag off the relay waits for each child in turn.
        forwarder.test_would_block.store(0, Ordering::Relaxed);
        forwarder.set_nonblocking(false);
        forwarder
            .forward(b"datagram-3", MediaDatagramRole::Source, None)
            .await;
        assert_eq!(
            take_relay_forward_attempts(&forwarder),
            vec![
                (0, RelayForwardAttempt::Awaited),
                (1, RelayForwardAttempt::Awaited),
                (2, RelayForwardAttempt::Awaited),
            ]
        );
        for receiver in &receivers {
            assert_eq!(receive_relay_test_datagram(receiver).await, b"datagram-3");
        }
        let snapshot = forwarder.snapshot();
        assert_eq!(snapshot.source_datagrams, 6 * 3);
        assert_eq!(snapshot.errors, 0);
    }

    #[tokio::test]
    async fn relay_forward_delivers_every_datagram_to_every_child_in_order() {
        for nonblocking in [true, false] {
            let (forwarder, receivers) = relay_forward_test_children(4).await;
            forwarder.set_nonblocking(nonblocking);
            // A repair-only child takes repair symbols and never a source.
            let mut sent = 0_u64;
            for batch in 0..40_u64 {
                for index in 0..50_u64 {
                    let sequence = batch * 50 + index;
                    let datagram = format!("relay-datagram-{sequence:06}");
                    forwarder
                        .forward(
                            datagram.as_bytes(),
                            if sequence % 3 == 0 {
                                MediaDatagramRole::Repair
                            } else {
                                MediaDatagramRole::Source
                            },
                            None,
                        )
                        .await;
                    sent += 1;
                }
                // Drain each batch so that no receive buffer overflows.
                for receiver in &receivers {
                    for index in 0..50_u64 {
                        let expected = format!("relay-datagram-{:06}", batch * 50 + index);
                        assert_eq!(
                            receive_relay_test_datagram(receiver).await,
                            expected.into_bytes(),
                            "nonblocking={nonblocking}"
                        );
                    }
                }
            }
            let snapshot = forwarder.snapshot();
            assert_eq!(
                snapshot.source_datagrams + snapshot.repair_datagrams,
                sent * 4,
                "nonblocking={nonblocking}"
            );
            assert_eq!(snapshot.errors, 0);
            if nonblocking {
                // After the first datagrams nothing had to wait.
                let awaited = take_relay_forward_attempts(&forwarder)
                    .iter()
                    .filter(|(_, attempt)| *attempt == RelayForwardAttempt::Awaited)
                    .count();
                assert!(awaited < 100, "{awaited} sends were awaited");
            }
        }
    }

    /// A forwarder whose children all share one source socket, as when the
    /// topology gives every child of a relay the same --relay-forward bind.
    async fn relay_forward_shared_children(
        roles: &[RelayForwardRole],
    ) -> (Arc<RelayDownstreamForwarder>, Vec<UdpSocket>, SocketAddr) {
        let bind = unused_loopback_addr();
        let mut receivers = Vec::with_capacity(roles.len());
        let mut endpoints = Vec::with_capacity(roles.len());
        for role in roles {
            let receiver = UdpSocket::bind((Ipv4Addr::LOCALHOST, 0)).await.unwrap();
            endpoints.push(RelayForwardEndpoint {
                bind,
                target: receiver.local_addr().unwrap(),
                role: *role,
            });
            receivers.push(receiver);
        }
        let forwarder = RelayDownstreamForwarder::bind(&endpoints)
            .await
            .unwrap()
            .unwrap();
        (forwarder, receivers, bind)
    }

    async fn receive_relay_test_datagram_from(receiver: &UdpSocket) -> (Vec<u8>, SocketAddr) {
        let mut buf = [0_u8; 2_048];
        let (len, from) =
            tokio::time::timeout(Duration::from_secs(2), receiver.recv_from(&mut buf))
                .await
                .expect("every child must receive every datagram")
                .unwrap();
        (buf[..len].to_vec(), from)
    }

    #[tokio::test]
    async fn relay_forward_batching_is_inert_when_every_child_has_its_own_bind() {
        // The Linode deploy renders one carrier link per child, each with a
        // source port of its own (often ECMP-hunted):
        // --relay-forward <relay ip>:<port of the link>=<child>,<lane>.
        let mut receivers = Vec::new();
        let mut endpoints = Vec::new();
        for lane in ["all", "source", "repair"] {
            let receiver = UdpSocket::bind((Ipv4Addr::LOCALHOST, 0)).await.unwrap();
            endpoints.push(
                parse_relay_forward_endpoint(&format!(
                    "{}={},{lane}",
                    unused_loopback_addr(),
                    receiver.local_addr().unwrap()
                ))
                .unwrap(),
            );
            receivers.push(receiver);
        }
        let forwarder = RelayDownstreamForwarder::bind(&endpoints)
            .await
            .unwrap()
            .unwrap();
        assert!(forwarder.batch.load(Ordering::Relaxed));
        assert_eq!(forwarder.socket_groups.len(), 3);
        assert_eq!(forwarder.shared_socket_count(), 0);
        let report = fast_path::FastPath::new(0, true);
        report.record_relay_forward_sockets(
            forwarder.socket_groups.len(),
            forwarder.shared_socket_count(),
        );
        let snapshot = report.snapshot();
        assert!(snapshot.relay_forward_batch);
        assert!(!snapshot.relay_forward_batch_effective);
        assert_eq!(snapshot.relay_forward_sockets, 3);

        // Every child gets a send of its own, as without the setting.
        for path in &forwarder.paths {
            path.socket.writable().await.unwrap();
        }
        take_relay_forward_attempts(&forwarder);
        forwarder
            .forward(b"datagram-1", MediaDatagramRole::Source, None)
            .await;
        let attempts = take_relay_forward_attempts(&forwarder);
        assert!(!attempts.is_empty());
        assert!(attempts
            .iter()
            .all(|(_, attempt)| *attempt == RelayForwardAttempt::Immediate));

        // Children that share a bind are where it takes effect.
        let (shared, _receivers, _bind) =
            relay_forward_shared_children(&[RelayForwardRole::All; 2]).await;
        assert_eq!(shared.shared_socket_count(), 1);
    }

    #[tokio::test]
    async fn relay_forward_batches_the_children_of_a_shared_socket_into_one_call() {
        let (forwarder, receivers, bind) =
            relay_forward_shared_children(&[RelayForwardRole::All; 3]).await;
        assert!(forwarder.batch.load(Ordering::Relaxed));
        assert_eq!(forwarder.socket_groups, vec![vec![0, 1, 2]]);
        // Let the reactor see that the socket is writable.
        forwarder.paths[0].socket.writable().await.unwrap();
        take_relay_forward_attempts(&forwarder);

        forwarder
            .forward(b"datagram-1", MediaDatagramRole::Source, None)
            .await;
        assert_eq!(
            take_relay_forward_attempts(&forwarder),
            vec![
                (0, RelayForwardAttempt::Batched),
                (1, RelayForwardAttempt::Batched),
                (2, RelayForwardAttempt::Batched),
            ]
        );
        for receiver in &receivers {
            // Each child sees the one address it knows its parent by.
            assert_eq!(
                receive_relay_test_datagram_from(receiver).await,
                (b"datagram-1".to_vec(), bind)
            );
        }

        // A full child is left out of the batch and waited for after the
        // others have the datagram.
        forwarder.test_would_block.store(0b010, Ordering::Relaxed);
        forwarder
            .forward(b"datagram-2", MediaDatagramRole::Source, None)
            .await;
        assert_eq!(
            take_relay_forward_attempts(&forwarder),
            vec![
                (1, RelayForwardAttempt::WouldBlock),
                (0, RelayForwardAttempt::Batched),
                (2, RelayForwardAttempt::Batched),
                (1, RelayForwardAttempt::Awaited),
            ]
        );
        for receiver in &receivers {
            assert_eq!(receive_relay_test_datagram(receiver).await, b"datagram-2");
        }
        forwarder.test_would_block.store(0, Ordering::Relaxed);

        // With the flag off each child gets a send of its own.
        forwarder.set_batch(false);
        forwarder
            .forward(b"datagram-3", MediaDatagramRole::Source, None)
            .await;
        assert_eq!(
            take_relay_forward_attempts(&forwarder),
            vec![
                (0, RelayForwardAttempt::Immediate),
                (1, RelayForwardAttempt::Immediate),
                (2, RelayForwardAttempt::Immediate),
            ]
        );
        // Batching needs the non-blocking path; awaited sends stay one by one.
        forwarder.set_batch(true);
        forwarder.set_nonblocking(false);
        forwarder
            .forward(b"datagram-4", MediaDatagramRole::Source, None)
            .await;
        assert_eq!(
            take_relay_forward_attempts(&forwarder),
            vec![
                (0, RelayForwardAttempt::Awaited),
                (1, RelayForwardAttempt::Awaited),
                (2, RelayForwardAttempt::Awaited),
            ]
        );
        for receiver in &receivers {
            assert_eq!(receive_relay_test_datagram(receiver).await, b"datagram-3");
            assert_eq!(receive_relay_test_datagram(receiver).await, b"datagram-4");
        }
        let snapshot = forwarder.snapshot();
        assert_eq!(snapshot.source_datagrams, 4 * 3);
        assert_eq!(snapshot.errors, 0);
    }

    #[tokio::test]
    async fn relay_forward_batch_keeps_roles_order_and_every_datagram() {
        // A source child, a repair child and a child that takes both, on one
        // shared socket, next to a child with a socket of its own.
        let shared_bind = unused_loopback_addr();
        let mut receivers = Vec::new();
        let mut endpoints = Vec::new();
        for (bind, role) in [
            (shared_bind, RelayForwardRole::Source),
            (
                SocketAddr::from((Ipv4Addr::LOCALHOST, 0)),
                RelayForwardRole::All,
            ),
            (shared_bind, RelayForwardRole::Repair),
            (shared_bind, RelayForwardRole::All),
        ] {
            let receiver = UdpSocket::bind((Ipv4Addr::LOCALHOST, 0)).await.unwrap();
            endpoints.push(RelayForwardEndpoint {
                bind,
                target: receiver.local_addr().unwrap(),
                role,
            });
            receivers.push(receiver);
        }
        let forwarder = RelayDownstreamForwarder::bind(&endpoints)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(forwarder.socket_groups, vec![vec![0, 2, 3], vec![1]]);
        let wants = |child: usize, sequence: u64| match child {
            0 => sequence % 3 != 0,
            2 => sequence % 3 == 0,
            _ => true,
        };
        let mut expected_total = 0_u64;
        for round in 0..20_u64 {
            for index in 0..50_u64 {
                let sequence = round * 50 + index;
                let role = if sequence % 3 == 0 {
                    MediaDatagramRole::Repair
                } else {
                    MediaDatagramRole::Source
                };
                forwarder
                    .forward(
                        format!("batched-{sequence:06}").as_bytes(),
                        role,
                        None,
                    )
                    .await;
                expected_total += (0..4).filter(|child| wants(*child, sequence)).count() as u64;
            }
            for (child, receiver) in receivers.iter().enumerate() {
                for index in 0..50_u64 {
                    let sequence = round * 50 + index;
                    if wants(child, sequence) {
                        assert_eq!(
                            receive_relay_test_datagram(receiver).await,
                            format!("batched-{sequence:06}").into_bytes(),
                            "child {child}"
                        );
                    }
                }
            }
        }
        let attempts = take_relay_forward_attempts(&forwarder);
        assert!(attempts
            .iter()
            .any(|(index, attempt)| *index == 0 && *attempt == RelayForwardAttempt::Batched));
        assert!(attempts
            .iter()
            .all(|(index, attempt)| *index != 1 || *attempt != RelayForwardAttempt::Batched));
        let snapshot = forwarder.snapshot();
        assert_eq!(
            snapshot.source_datagrams + snapshot.repair_datagrams,
            expected_total
        );
        assert_eq!(snapshot.errors, 0);
    }

    #[tokio::test]
    async fn warm_sources_replay_to_a_promoted_child_in_one_batch_or_one_by_one() {
        for batch in [true, false] {
            let (forwarder, receivers, _) =
                relay_forward_shared_children(&[RelayForwardRole::All, RelayForwardRole::Repair])
                    .await;
            forwarder.set_batch(batch);
            forwarder.paths[0].socket.writable().await.unwrap();
            // Ten objects of ten symbols; the warm buffer keeps the newest
            // objects, more datagrams than one sendmmsg call carries.
            let payload = |object: u64, symbol: u64| format!("warm-{object:03}-{symbol:02}");
            for object in 0..10_u64 {
                let key = media_object::ObjectKey::for_payload(
                    "default",
                    "1",
                    "muxed-fmp4",
                    1,
                    0,
                    object,
                    1,
                    b"object",
                )
                .unwrap();
                for symbol in 0..10_u64 {
                    forwarder
                        .forward(
                            payload(object, symbol).as_bytes(),
                            MediaDatagramRole::Source,
                            Some(&key),
                        )
                        .await;
                }
            }
            for object in 0..10_u64 {
                for symbol in 0..10_u64 {
                    assert_eq!(
                        receive_relay_test_datagram(&receivers[0]).await,
                        payload(object, symbol).into_bytes()
                    );
                }
            }
            let buffered = forwarder.snapshot().warm_source_buffered_datagrams;
            let kept_objects = RELAY_WARM_SOURCE_REPLAY_MAX_OBJECTS_PER_CHILD as u64;
            assert_eq!(buffered, kept_objects * 10);
            assert!(buffered as usize > fast_path::MAX_BATCH_MESSAGES);
            let target = receivers[1].local_addr().unwrap();
            assert_eq!(
                forwarder.apply_failover_mode(target, FailoverForwardMode::SourceAndRepair, false),
                Some(true)
            );
            forwarder.replay_warm_sources(target).await;
            for object in (10 - kept_objects)..10 {
                for symbol in 0..10_u64 {
                    assert_eq!(
                        receive_relay_test_datagram(&receivers[1]).await,
                        payload(object, symbol).into_bytes(),
                        "batch={batch}"
                    );
                }
            }
            let snapshot = forwarder.snapshot();
            assert_eq!(snapshot.warm_source_replayed_datagrams, buffered);
            assert_eq!(snapshot.warm_source_buffered_datagrams, 0);
            assert_eq!(snapshot.errors, 0);
        }
    }

    #[test]
    fn the_fast_path_flags_and_children_may_share_a_bind() {
        let args = Args::try_parse_from(["av-mesh"])
            .unwrap()
            .normalized()
            .unwrap();
        assert!(args.relay_forward_batch);
        // Busy polling is off until a measurement shows that it helps.
        assert_eq!(args.busy_poll_us, 0);
        assert_eq!(args.media_cpu, None);
        let args = Args::try_parse_from(["av-mesh", "--busy-poll-us", "50"])
            .unwrap()
            .normalized()
            .unwrap();
        assert_eq!(args.busy_poll_us, 50);

        let args = Args::try_parse_from([
            "av-mesh",
            "--relay-forward-batch=false",
            "--busy-poll-us",
            "0",
            "--media-cpu",
            "2",
        ])
        .unwrap()
        .normalized()
        .unwrap();
        assert!(!args.relay_forward_batch);
        assert_eq!(args.busy_poll_us, 0);
        assert_eq!(args.media_cpu, Some(2));
        assert!(Args::try_parse_from(["av-mesh", "--relay-forward-batch"]).is_err());

        // Two children with one bind share a socket; one target twice is
        // still refused.
        let args = Args::try_parse_from([
            "av-mesh",
            "--relay-forward",
            "127.0.0.1:7100=127.0.0.1:7201,all",
            "--relay-forward",
            "127.0.0.1:7100=127.0.0.1:7202,repair",
        ])
        .unwrap()
        .normalized()
        .unwrap();
        assert_eq!(args.relay_forwards.len(), 2);
        let error = Args::try_parse_from([
            "av-mesh",
            "--relay-forward",
            "127.0.0.1:7100=127.0.0.1:7201,all",
            "--relay-forward",
            "127.0.0.1:7101=127.0.0.1:7201,repair",
        ])
        .unwrap()
        .normalized()
        .unwrap_err();
        assert!(error
            .to_string()
            .contains("duplicate RelaySession forward target"));
    }

    #[tokio::test]
    async fn socket_buffers_past_the_host_limit_are_forced_or_left_as_they_were() {
        let limit = std::fs::read_to_string("/proc/sys/net/core/rmem_max")
            .ok()
            .and_then(|value| value.trim().parse::<usize>().ok())
            .unwrap_or(212_992);
        let socket = UdpSocket::bind("127.0.0.1:0").await.unwrap();
        // Linux reports twice the value it was asked for, so ask for more
        // than twice the limit to be capped.
        let requested = limit * 4;
        let state = configure_udp_socket_buffers(&socket, requested, "test").unwrap();
        if state.forced {
            assert!(state.receive_bytes >= requested);
            assert!(state.send_bytes >= requested);
        } else {
            // Unprivileged: the kernel limit stands.
            assert!(state.receive_bytes < requested);
        }
    }

    #[tokio::test]
    async fn relay_forward_journals_the_first_symbol_of_each_object_once() {
        let (forwarder, receivers) = relay_forward_test_children(2).await;
        let journal = Arc::new(HopJournal::new("relay-primary", 64));
        forwarder.set_hop_journal(Arc::clone(&journal));
        let key = |object: u64| {
            media_object::ObjectKey::for_payload(
                "default",
                "4001",
                "muxed-fmp4",
                0,
                0,
                object,
                1,
                b"payload",
            )
            .unwrap()
        };
        let before = now_unix_us();
        for object in [7_u64, 7, 7, 8] {
            forwarder
                .forward(
                    b"symbol",
                    MediaDatagramRole::Source,
                    Some(&key(object)),
                )
                .await;
        }
        // An AEP1 datagram has no object identity and is not journaled.
        forwarder
            .forward(b"aep1", MediaDatagramRole::Source, None)
            .await;
        for receiver in &receivers {
            for _ in 0..5 {
                receive_relay_test_datagram(receiver).await;
            }
        }
        let events = journal.events(HopQuery::default());
        assert_eq!(events.len(), 2);
        for (event, object) in events.iter().zip([7_u64, 8]) {
            assert_eq!(event.stage, HopStage::RelayForward);
            assert_eq!((event.stream, event.seq), (4001, object));
            assert_eq!(event.peer, Some(receivers[0].local_addr().unwrap()));
            assert!(event.t_us >= before);
        }
    }

    async fn journaled_test_cache(node: &str) -> Arc<LiveTsCache> {
        let cache = canonical_gap_test_cache().await;
        cache.set_hop_journal(Arc::new(HopJournal::new(node, 4_096)));
        cache
    }

    #[tokio::test]
    async fn a_canonical_commit_journals_committed_and_each_part_the_watermark_reaches() {
        let cache = journaled_test_cache("distributor").await;
        let stream_id = 77;
        let peer: SocketAddr = "10.0.0.2:12001".parse().unwrap();
        let key = media_object::ObjectKey::for_payload(
            "default",
            "77",
            "muxed-fmp4",
            0,
            0,
            3,
            1,
            b"payload",
        )
        .unwrap();
        journal_relay_symbol(&cache, &key, peer, 100);
        journal_relay_symbol(&cache, &key, peer, 120);
        journal_relay_symbol(&cache, &key, peer, 130);
        journal_relay_decoded(&cache, key.stream(), key.object(), peer, 140);
        let firsts = hop_events(&cache, HopStage::RelayFirst, stream_id);
        assert_eq!(firsts.len(), 1);
        assert_eq!(
            (firsts[0].seq, firsts[0].t_us, firsts[0].peer),
            (3, 100, Some(peer))
        );
        let decoded = hop_events(&cache, HopStage::RelayDecoded, stream_id);
        assert_eq!(decoded.len(), 1);
        assert_eq!((decoded[0].seq, decoded[0].t_us), (3, 140));

        // Part 1 is late: the watermark stops at 0 until it arrives, and
        // then reaches 1 and 2 at once.
        for sequence in [0_u64, 2] {
            commit_canonical_gap_test_part(&cache, stream_id, sequence).await;
        }
        let watermark_seqs = |cache: &LiveTsCache| {
            hop_events(cache, HopStage::Watermark, stream_id)
                .iter()
                .map(|event| event.seq)
                .collect::<Vec<_>>()
        };
        assert_eq!(watermark_seqs(&cache), vec![0]);
        commit_canonical_gap_test_part(&cache, stream_id, 1).await;
        let mut seqs = watermark_seqs(&cache);
        seqs.sort_unstable();
        assert_eq!(seqs, vec![0, 1, 2]);
        let committed = hop_events(&cache, HopStage::Committed, stream_id);
        let mut committed_seqs: Vec<u64> = committed.iter().map(|event| event.seq).collect();
        committed_seqs.sort_unstable();
        assert_eq!(committed_seqs, vec![0, 1, 2]);
        // The watermark of a part is never before its commit.
        for event in hop_events(&cache, HopStage::Watermark, stream_id) {
            let commit = committed
                .iter()
                .find(|commit| commit.seq == event.seq)
                .unwrap();
            assert!(event.t_us >= commit.t_us);
        }
        // A retry of a stored part is no new part and journals nothing more.
        assert_eq!(
            cache
                .commit_stream_payload(
                    stream_id,
                    encode_test_canonical_fmp4_object(
                        stream_id,
                        1,
                        ObjectKind::Media,
                        false,
                        &canonical_gap_test_payload(1),
                    ),
                )
                .await
                .unwrap(),
            Committed::AlreadyPresent(1)
        );
        assert_eq!(hop_events(&cache, HopStage::Committed, stream_id).len(), 3);

        // The part response reports when this node committed the part and
        // when it answered, and journals the first replies.
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));
        let commit_of_one = committed.iter().find(|event| event.seq == 1).unwrap().t_us;
        for request in 1..=6_u32 {
            let started = now_unix_us();
            let response = get_for_tests(&router, "/live/77/part1.mp4").await;
            assert_eq!(response.status, StatusCode::OK);
            assert_eq!(
                hop_header(&response, "x-needletail-edge-committed-unix-us"),
                Some(commit_of_one.to_string().as_str()),
                "request {request}"
            );
            let reply: u64 = hop_header(&response, "x-needletail-reply-unix-us")
                .unwrap()
                .parse()
                .unwrap();
            assert!(reply >= started && reply <= now_unix_us());
            assert!(hop_header(&response, "x-needletail-cache-available-unix-us").is_some());
        }
        let replies: Vec<Option<u32>> = hop_events(&cache, HopStage::Reply, stream_id)
            .iter()
            .map(|event| event.n)
            .collect();
        assert_eq!(
            replies,
            vec![Some(1), Some(2), Some(3), Some(4)],
            "at most the first four replies of a part are journaled"
        );
        mesh.shutdown();
    }

    #[tokio::test]
    async fn hops_api_serves_the_journal_as_ndjson_without_a_session() {
        let cache = journaled_test_cache("edge-a").await;
        let journal = cache.hop_journal.get().unwrap();
        journal.record_part(HopStage::EdgeCommitted, 77, 1, 1_000);
        journal.record_part(HopStage::EdgeCommitted, 78, 1, 1_500);
        journal.record_part(HopStage::EdgePlaylist, 77, 1, 2_000);
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));

        let response = router
            .route(
                Request::builder()
                    .method(Method::GET)
                    .uri("/api/hops?since_us=1200&stream=77")
                    .header("CMCD-Session", "sid=\"hop-reader\"")
                    .body(())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status, StatusCode::OK);
        assert_eq!(
            response.content_type.as_deref(),
            Some("application/x-ndjson")
        );
        let body = String::from_utf8(response.body.unwrap().to_vec()).unwrap();
        assert_eq!(
            body,
            "{\"node\":\"edge-a\",\"stage\":\"edge_playlist\",\"stream\":77,\"seq\":1,\"t_us\":2000}\n"
        );

        let all = get_for_tests(&router, "/api/hops").await;
        let lines: Vec<serde_json::Value> = String::from_utf8(all.body.unwrap().to_vec())
            .unwrap()
            .lines()
            .map(|line| serde_json::from_str(line).unwrap())
            .collect();
        let times: Vec<u64> = lines
            .iter()
            .map(|line| line["t_us"].as_u64().unwrap())
            .collect();
        assert_eq!(times, vec![1_000, 1_500, 2_000]);

        let bad = get_for_tests(&router, "/api/hops?stream=seventy-seven").await;
        assert_eq!(bad.status, StatusCode::BAD_REQUEST);

        // Reading the journal is not playback: no session, no reader, and
        // no demand for a playlist.
        assert_eq!(router.edge_load.egress.snapshot().active_sessions, 0);
        assert!(router.edge_load.egress.sessions_by_playlist().is_empty());
        assert!(cache.stream_position_for_id(78).await.is_none());

        // A node without a journal answers with nothing.
        let quiet = LiveTsCache::new(1, Duration::from_millis(5), 2, 64, 64).await;
        let quiet_router = app_router_for_tests(Arc::clone(&quiet), Arc::clone(&mesh));
        let response = get_for_tests(&quiet_router, "/api/hops").await;
        assert_eq!(response.status, StatusCode::OK);
        assert!(response.body.unwrap().is_empty());
        mesh.shutdown();
    }

    #[tokio::test]
    async fn stalls_endpoint_filters_by_since_us() {
        // The process's journal: other tests' fast-plane threads record
        // into it when the machine stalls under them, and an event merges
        // with one of its kind and thread that ended less than 10 ms before
        // it began, or that begins less than 10 ms after it. This test's
        // events are short, of durations a real event is unlikely to have,
        // and are recorded again (at most five times, 30 ms apart) until
        // neither has merged with another.
        let journal = stall_journal::install(Arc::new(StallJournal::new("stalls-test", 4_096)));
        const PASS_US: u64 = 2_347;
        const RX_US: u64 = 2_351;
        let video = stall_journal::StallThread::Video;
        let ours = |kind: stall_journal::StallKind, dur_us: u64| {
            journal
                .query(None)
                .events
                .iter()
                .rev()
                .map(|line| line.event)
                .find(|event| event.kind == kind && event.thread == video && event.dur_us == dur_us)
        };
        // As another test's stalled fast plane would: a pass of the video
        // thread just before, with page faults of its own. The first try
        // merges with it.
        journal.record(stall_journal::StallKind::ClassPass, video, 3_000, 647, 0);
        let mut first_t_us = None;
        for _ in 0..5 {
            journal.record(stall_journal::StallKind::ClassPass, video, PASS_US, 3, 0);
            journal.record(stall_journal::StallKind::RxLate, video, RX_US, 0, 0);
            tokio::time::sleep(Duration::from_millis(30)).await;
            let pass = ours(stall_journal::StallKind::ClassPass, PASS_US);
            let rx = ours(stall_journal::StallKind::RxLate, RX_US);
            if let (Some(pass), Some(rx)) = (pass, rx) {
                if pass.n == 1 && rx.n == 1 {
                    first_t_us = Some(pass.t_us);
                    break;
                }
            }
        }
        let first_t_us = first_t_us.expect("the test's events stand apart from real ones");
        let marked = |body: &str| -> Vec<serde_json::Value> {
            body.lines()
                .map(|line| serde_json::from_str::<serde_json::Value>(line).unwrap())
                .filter(|line| {
                    line["thread"] == "video"
                        && line["t_us"].as_u64().is_some_and(|t_us| t_us >= first_t_us)
                        && line["dur_us"]
                            .as_u64()
                            .is_some_and(|dur| dur == PASS_US || dur == RX_US)
                })
                .collect()
        };
        let cache = LiveTsCache::new(1, Duration::from_millis(5), 2, 64, 64).await;
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));

        let all = get_for_tests(&router, "/api/stalls").await;
        assert_eq!(all.status, StatusCode::OK);
        assert_eq!(all.content_type.as_deref(), Some("application/x-ndjson"));
        let lines = marked(&String::from_utf8(all.body.unwrap().to_vec()).unwrap());
        let kinds: Vec<&str> = lines
            .iter()
            .map(|line| line["kind"].as_str().unwrap())
            .collect();
        assert_eq!(kinds, vec!["class_pass", "rx_late"], "oldest first");
        assert_eq!(lines[0]["thread"], "video");
        assert_eq!(lines[0]["minflt"], 3);
        assert_eq!(lines[0]["t_us"], first_t_us);
        assert!(lines[0]["node"].is_string());
        // No tick of its CPU was stopped under it: the thread's own work.
        assert_eq!(lines[0]["cause"], "own");
        assert_eq!(lines[1]["thread"], "video");
        assert_eq!(lines[1]["cause"], "waited");

        let since = format!("/api/stalls?since_us={}", first_t_us + 1);
        let later = get_for_tests(&router, &since).await;
        assert_eq!(later.status, StatusCode::OK);
        let lines = marked(&String::from_utf8(later.body.unwrap().to_vec()).unwrap());
        assert_eq!(lines.len(), 1, "{lines:?}");
        assert_eq!(lines[0]["kind"], "rx_late");
        let at = format!("/api/stalls?since_us={first_t_us}");
        let from = get_for_tests(&router, &at).await;
        assert_eq!(
            marked(&String::from_utf8(from.body.unwrap().to_vec()).unwrap()).len(),
            2,
            "since_us is inclusive"
        );

        let bad = get_for_tests(&router, "/api/stalls?since_us=yesterday").await;
        assert_eq!(bad.status, StatusCode::BAD_REQUEST);

        // The node's snapshot carries the journal's counters.
        let local: serde_json::Value = serde_json::from_slice(
            get_for_tests(&router, "/api/mesh/local")
                .await
                .body
                .as_ref()
                .unwrap(),
        )
        .unwrap();
        assert!(
            local["stall"]["events"].as_u64().unwrap() >= 2,
            "{:#}",
            local["stall"]
        );
        assert!(local["stall"]["tick_threads"].is_u64());

        // A process without a journal answers with nothing.
        let none = AppRouter::stalls_response(None, Some("since_us=5")).await;
        assert_eq!(none.status, StatusCode::OK);
        assert!(none.body.unwrap().is_empty());
        mesh.shutdown();
    }

    #[tokio::test]
    async fn the_node_warm_file_reaches_the_snapshot() {
        // D 2.4: the boot check's record, read at start, is `node_warm` of
        // /api/mesh/local and /api/node; D 2.3: `memory` beside it. The
        // record is complete, so no other test of this process loses its
        // readiness to it.
        let path = std::env::temp_dir().join(format!(
            "needletail-node-warm-test-{}-{}.json",
            std::process::id(),
            now_unix_us()
        ));
        std::fs::write(
            &path,
            r#"{"schema":"needletail.node-warm.v2","complete":true,"verdict":"ok","unix_us":1795383000000000,"warm":{"ran":true,"finished":true,"gib":3.31,"seconds":2.84,"worst_page_us":310,"pages_over_1ms":0,"pages_over_100ms":0},"check":{"seconds":60,"cpus":2,"stops_over_20ms":0,"stop_max_ms":0,"stopped_ms":0,"steal_permille":0,"late_max_us":180}}"#,
        )
        .unwrap();
        node_warm::install(Some(&path));
        std::fs::remove_file(&path).unwrap();
        let cache = LiveTsCache::new(1, Duration::from_millis(5), 2, 64, 64).await;
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        // As main() builds the status source: the record read at start.
        let router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh)).with_node_status(
            NodeStatusSource {
                node_warm: node_warm::installed().cloned(),
                ..NodeStatusSource::default()
            },
        );
        let json = |response: HandlerResponse| -> serde_json::Value {
            serde_json::from_slice(response.body.as_ref().unwrap()).unwrap()
        };
        let local = json(get_for_tests(&router, "/api/mesh/local").await);
        let warm = &local["node_warm"];
        assert_eq!(warm["configured"], true, "{local:#}");
        assert_eq!(warm["complete"], true);
        assert_eq!(warm["verdict"], "ok");
        assert_eq!(warm["warm"]["gib"], 3.31);
        assert_eq!(warm["check"]["late_max_us"], 180);
        let memory = &local["memory"];
        assert_eq!(memory["mode"], "rings", "{memory:#}");
        for field in [
            "prefaulted_bytes",
            "mappings_populated_bytes",
            "locked_bytes",
            "lock_refused_bytes",
            "vm_size_kb",
            "vm_rss_kb",
            "vm_lck_kb",
        ] {
            assert!(memory[field].is_u64(), "{field}: {memory:#}");
        }
        assert!(memory["thp"].is_string() && memory["allocator_tuned"].is_boolean());
        let node = json(get_for_tests(&router, NODE_STATUS_PATH).await);
        assert_eq!(node["node_warm"], *warm);
        assert!(
            !node["not_ready"]
                .as_array()
                .unwrap()
                .iter()
                .any(|reason| reason == "node warm check not complete"),
            "{node:#}"
        );
        mesh.shutdown();
    }

    /// A distributor and an edge on loopback, each with a journal, with the
    /// edge's router and its applied-part task running.
    struct HopMeshPair {
        distributor: Arc<LiveTsCache>,
        edge: Arc<LiveTsCache>,
        router: AppRouter,
        distributor_addr: SocketAddr,
        edge_addr: SocketAddr,
        distributor_mesh: CacheMeshHandle,
        edge_mesh: Arc<CacheMeshHandle>,
        shutdown_tx: watch::Sender<()>,
    }

    impl HopMeshPair {
        /// The distributor knows the edge from its configuration, so the
        /// first tick of its sync task, at start, chooses the edge as a
        /// child. With a long `sync_interval` no other tick comes during a
        /// test: a part reaches the edge only if it is sent on publication.
        async fn start(sync_interval: Duration) -> Self {
            let distributor_addr = unused_loopback_addr();
            let edge_addr = unused_loopback_addr();
            let distributor = journaled_test_cache("distributor").await;
            let edge = journaled_test_cache("edge").await;
            let distributor_journal = Arc::clone(distributor.hop_journal.get().unwrap());
            let mut distributor_config = with_low_latency_mesh_options(
                CacheMeshConfig::new("hop-distributor", "uk", distributor_addr)
                    .with_role(CacheMeshRole::Distributor)
                    .with_peer(edge_addr),
                &distributor_journal,
            );
            distributor_config.sync_interval = sync_interval;
            let (applied_tx, applied_rx) = mpsc::unbounded_channel();
            let edge_mesh = Arc::new(
                CacheMesh::new(
                    Arc::clone(&edge.chunk_cache),
                    CacheMeshConfig::new("hop-edge", "uk", edge_addr)
                        .with_role(CacheMeshRole::Edge)
                        .with_peer(distributor_addr)
                        .with_applied_tx(applied_tx),
                )
                .start()
                .await
                .unwrap(),
            );
            let distributor_mesh =
                CacheMesh::new(Arc::clone(&distributor.chunk_cache), distributor_config)
                    .start()
                    .await
                    .unwrap();
            let router = app_router_for_tests(Arc::clone(&edge), Arc::clone(&edge_mesh));
            let (shutdown_tx, shutdown_rx) = watch::channel(());
            tokio::spawn(run_mesh_applied_parts(
                Arc::clone(&edge),
                router.edge_load.clone(),
                applied_rx,
                None,
                shutdown_rx,
            ));
            // Let the first tick run.
            tokio::time::sleep(Duration::from_millis(50)).await;
            Self {
                distributor,
                edge,
                router,
                distributor_addr,
                edge_addr,
                distributor_mesh,
                edge_mesh,
                shutdown_tx,
            }
        }

        async fn commit(&self, stream_id: u64, sequence: u64) {
            self.distributor
                .commit_stream_payload(
                    stream_id,
                    encode_test_published_fmp4_part(stream_id, 5, sequence, sequence == 0, 5),
                )
                .await
                .unwrap();
        }

        fn shutdown(self) {
            let _ = self.shutdown_tx.send(());
            self.distributor_mesh.shutdown();
            self.edge_mesh.shutdown();
        }
    }

    #[tokio::test]
    async fn the_journals_of_a_distributor_and_an_edge_join_on_each_part() {
        use tokio::time::timeout;

        // No tick after the first one: every part must leave on publication.
        let pair = HopMeshPair::start(Duration::from_secs(60)).await;
        let (distributor, edge, router) = (&pair.distributor, &pair.edge, &pair.router);
        let stream_id = 77;
        for sequence in 0..4_u64 {
            pair.commit(stream_id, sequence).await;
            // Apart, so that each part is a publication of its own.
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        timeout(Duration::from_secs(3), async {
            while hop_events(edge, HopStage::EdgePlaylist, stream_id).len() < 4 {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("the edge must put every part in its playlist without a tick");
        for sequence in 0..4_u64 {
            let response =
                get_for_tests(router, &format!("/live/{stream_id}/part{sequence}.mp4")).await;
            assert_eq!(response.status, StatusCode::OK);
            let committed: u64 = hop_header(&response, "x-needletail-edge-committed-unix-us")
                .unwrap()
                .parse()
                .unwrap();
            let reply: u64 = hop_header(&response, "x-needletail-reply-unix-us")
                .unwrap()
                .parse()
                .unwrap();
            assert!(committed <= reply);
            assert!(hop_header(&response, "x-needletail-published-unix-us").is_some());
        }

        let first = |cache: &LiveTsCache, stage: HopStage, sequence: u64| {
            hop_events(cache, stage, stream_id)
                .into_iter()
                .filter(|event| event.seq == sequence)
                .map(|event| event.t_us)
                .min()
                .unwrap_or_else(|| panic!("no {} event for part {sequence}", stage.as_str()))
        };
        let mut latencies = Vec::new();
        for sequence in 0..4_u64 {
            // One clock on one host, so the hops are in order.
            let hops = [
                first(distributor, HopStage::Committed, sequence),
                first(distributor, HopStage::Watermark, sequence),
                first(distributor, HopStage::MeshSent, sequence),
                first(edge, HopStage::MeshFirst, sequence),
                first(edge, HopStage::MeshDecoded, sequence),
                first(edge, HopStage::EdgeCommitted, sequence),
                first(edge, HopStage::EdgePlaylist, sequence),
                first(edge, HopStage::Reply, sequence),
            ];
            assert!(
                hops.windows(2).all(|pair| pair[0] <= pair[1]),
                "hops of part {sequence} out of order: {hops:?}"
            );
            latencies.push(hops[5] - hops[0]);
        }
        // Sent on publication: a part is at the edge within a few
        // milliseconds of its commit, as the specification asks.
        latencies.sort_unstable();
        assert!(
            latencies[latencies.len() / 2] < 5_000,
            "commit to edge, us: {latencies:?}"
        );
        assert!(
            latencies.iter().all(|latency| *latency < 25_000),
            "commit to edge, us: {latencies:?}"
        );
        let sent = hop_events(distributor, HopStage::MeshSent, stream_id);
        assert!(sent.iter().all(|event| event.peer == Some(pair.edge_addr)));
        let received = hop_events(edge, HopStage::MeshFirst, stream_id);
        assert!(received
            .iter()
            .all(|event| event.peer == Some(pair.distributor_addr)));
        pair.shutdown();
    }

    /// A reader blocked on the next part is woken by the cache write. On an
    /// edge that happens before the applied part reaches
    /// `observe_mesh_part`, and the response must still say when the part
    /// was committed.
    #[tokio::test]
    async fn a_reader_blocked_on_a_part_is_told_when_the_edge_committed_it() {
        let distributor = journaled_test_cache("distributor").await;
        let edge = journaled_test_cache("edge").await;
        let stream_id = 77;
        for sequence in 0..2_u64 {
            distributor
                .commit_stream_payload(
                    stream_id,
                    encode_test_published_fmp4_part(stream_id, 5, sequence, sequence == 0, 5),
                )
                .await
                .unwrap();
        }
        let slot = |sequence: usize| {
            let distributor = Arc::clone(&distributor);
            async move {
                distributor
                    .chunk_cache
                    .get_for_stream_id(stream_id, sequence)
                    .await
                    .unwrap()
                    .0
            }
        };
        // Part 0 arrived as the mesh delivers it: written, then recorded.
        edge.chunk_cache
            .add_for_stream_id(stream_id, 0, slot(0).await)
            .await
            .unwrap();
        edge.observe_mesh_part(stream_id, 0, None).await.unwrap();
        let part_one = slot(1).await;
        let mesh = mesh_handle_for_tests(Arc::clone(&edge.chunk_cache)).await;
        let router = app_router_for_tests(Arc::clone(&edge), Arc::clone(&mesh));

        let part_path = format!("/live/{stream_id}/part1.mp4");
        let mut written_after = 0;
        let (response, ()) = tokio::join!(get_for_tests(&router, &part_path), async {
            tokio::time::sleep(Duration::from_millis(50)).await;
            written_after = now_unix_us();
            // The mesh writes part 1; nothing records it in the
            // playlist state before the reader answers.
            edge.chunk_cache
                .add_for_stream_id(stream_id, 1, part_one)
                .await
                .unwrap();
        });
        assert_eq!(response.status, StatusCode::OK);
        assert!(edge
            .state
            .read()
            .await
            .stream_parts
            .get(&stream_id)
            .is_none_or(|parts| !parts.contains_key(&1)));
        let committed: u64 = hop_header(&response, "x-needletail-edge-committed-unix-us")
            .expect("the edge-committed header of a part the reader waited for")
            .parse()
            .unwrap();
        assert_eq!(
            Some(committed),
            edge.chunk_cache.written_unix_us_for_stream_id(stream_id, 1)
        );
        let reply: u64 = hop_header(&response, "x-needletail-reply-unix-us")
            .unwrap()
            .parse()
            .unwrap();
        assert!(written_after <= committed && committed <= reply);
        assert!(hop_header(&response, "x-needletail-cache-available-unix-us").is_some());

        // When the applied part is recorded, the journal and later responses
        // report the same commit time.
        let parent: SocketAddr = "10.0.0.9:7000".parse().unwrap();
        let applied = AppliedSlot {
            stream_id,
            slot_id: 1,
            bytes: 0,
            rx_first_us: 0,
            decoded_us: 0,
            committed_us: reply,
            parent,
        };
        let journaled = mesh_applied_committed_us(&edge, &applied);
        assert_eq!(journaled, committed);
        journal_mesh_applied(&edge, &applied, journaled);
        edge.observe_mesh_part(stream_id, 1, Some(journaled))
            .await
            .unwrap();
        let events = hop_events(&edge, HopStage::EdgeCommitted, stream_id);
        assert_eq!(events.len(), 1);
        assert_eq!(events[0].t_us, committed);
        let again = get_for_tests(&router, &format!("/live/{stream_id}/part1.mp4")).await;
        assert_eq!(
            hop_header(&again, "x-needletail-edge-committed-unix-us"),
            Some(committed.to_string().as_str())
        );
        mesh.shutdown();
    }

    /// Collecting a full journal must not stop the runtime: on a runtime
    /// with one thread, another task keeps running while the journal is
    /// copied, sorted and formatted.
    #[tokio::test(flavor = "current_thread")]
    async fn hops_api_renders_a_full_journal_off_the_runtime_thread() {
        use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};

        let cache = canonical_gap_test_cache().await;
        let journal = Arc::new(HopJournal::new("edge-full", DEFAULT_HOP_JOURNAL_CAPACITY));
        for sequence in 0..DEFAULT_HOP_JOURNAL_CAPACITY as u64 {
            journal.record(
                HopEvent::new(HopStage::Reply, 77, sequence, 1_000_000 + sequence)
                    .with_peer(Some("10.0.0.2:12001".parse().unwrap())),
            );
        }
        cache.set_hop_journal(Arc::clone(&journal));
        let mesh = mesh_handle_for_tests(Arc::clone(&cache.chunk_cache)).await;
        let router = app_router_for_tests(Arc::clone(&cache), Arc::clone(&mesh));

        let done = Arc::new(AtomicBool::new(false));
        let longest_gap_us = Arc::new(AtomicU64::new(0));
        let ticker = tokio::spawn({
            let done = Arc::clone(&done);
            let longest_gap_us = Arc::clone(&longest_gap_us);
            async move {
                let mut last = Instant::now();
                while !done.load(Ordering::Acquire) {
                    tokio::task::yield_now().await;
                    let now = Instant::now();
                    let gap = now.duration_since(last).as_micros() as u64;
                    longest_gap_us.fetch_max(gap, Ordering::Relaxed);
                    last = now;
                }
            }
        });
        tokio::task::yield_now().await;
        let started = Instant::now();
        let response = get_for_tests(&router, "/api/hops").await;
        let took_us = started.elapsed().as_micros() as u64;
        done.store(true, Ordering::Release);
        ticker.await.unwrap();

        assert_eq!(response.status, StatusCode::OK);
        let body = response.body.unwrap();
        assert_eq!(
            body.iter().filter(|byte| **byte == b'\n').count(),
            DEFAULT_HOP_JOURNAL_CAPACITY
        );
        let longest_gap_us = longest_gap_us.load(Ordering::Relaxed);
        assert!(
            longest_gap_us * 2 < took_us,
            "the runtime stalled for {longest_gap_us} us of a {took_us} us read"
        );
        mesh.shutdown();
    }

    // ---- AM1: the timeline in microseconds ----

    #[test]
    fn the_k3d_nodes_use_the_time_based_defaults() {
        // Explicit counts of parts win over --segment-ms and --window-ms, so
        // counts sized for the old 50 ms part made a 60 ms window of 2.5 ms
        // parts. The manifest pins none.
        let manifest = include_str!("../deploy/k3d/av-mesh.yaml");
        let mut nodes = 0;
        let mut lines = manifest.lines().peekable();
        while let Some(line) = lines.next() {
            if line.trim() != "args:" {
                continue;
            }
            let mut argv = vec!["av-mesh".to_string()];
            while let Some(arg) = lines.peek().and_then(|line| line.trim().strip_prefix("- ")) {
                argv.push(arg.trim_matches('"').to_string());
                lines.next();
            }
            let args = Args::try_parse_from(&argv).unwrap().normalized().unwrap();
            assert_eq!(args.part_us, DEFAULT_PART_US, "{argv:?}");
            assert_eq!(args.parts_per_segment, 400, "{argv:?}");
            assert_eq!(args.window_parts, 4_800, "{argv:?}");
            nodes += 1;
        }
        assert_eq!(nodes, 2);
    }

    #[test]
    fn the_node_timeline_defaults_to_the_smallest_parts_and_time_windows() {
        let args = Args::try_parse_from(["av-mesh"])
            .unwrap()
            .normalized()
            .unwrap();
        assert_eq!(args.part_us, 2_500);
        assert_eq!(args.segment_ms, 1_000);
        assert_eq!(args.window_ms, 12_000);
        // A second of 2.5 ms parts, and twelve seconds of them.
        assert_eq!(args.parts_per_segment, 400);
        assert_eq!(args.window_parts, 4_800);
        assert_eq!(args.part_hold_back_ms, 0);

        // --part-ms is an alias in whole milliseconds; segments and windows
        // stay lengths of time.
        let args = Args::try_parse_from(["av-mesh", "--part-ms", "5"])
            .unwrap()
            .normalized()
            .unwrap();
        assert_eq!(args.part_us, 5_000);
        assert_eq!(args.parts_per_segment, 200);
        assert_eq!(args.window_parts, 2_400);

        // --part-us wins over --part-ms.
        let args = Args::try_parse_from(["av-mesh", "--part-ms", "5", "--part-us", "250"])
            .unwrap()
            .normalized()
            .unwrap();
        assert_eq!(args.part_us, 250);
        assert_eq!(args.parts_per_segment, 4_000);
        assert_eq!(args.window_parts, 48_000);

        // Explicit counts win, as the deploy passes them today.
        let args = Args::try_parse_from([
            "av-mesh",
            "--part-ms",
            "5",
            "--parts-per-segment",
            "200",
            "--window-parts",
            "2400",
            "--segment-ms",
            "2000",
            "--window-ms",
            "60000",
        ])
        .unwrap()
        .normalized()
        .unwrap();
        assert_eq!(args.parts_per_segment, 200);
        assert_eq!(args.window_parts, 2_400);

        let args = Args::try_parse_from([
            "av-mesh",
            "--part-us",
            "1000",
            "--segment-ms",
            "2000",
            "--window-ms",
            "6000",
            "--part-hold-back-ms",
            "250",
        ])
        .unwrap()
        .normalized()
        .unwrap();
        assert_eq!(args.parts_per_segment, 2_000);
        assert_eq!(args.window_parts, 6_000);
        assert_eq!(args.part_hold_back_ms, 250);

        assert!(Args::try_parse_from(["av-mesh", "--part-us", "0"])
            .unwrap()
            .normalized()
            .is_err());
        // A tail response is a whole number of parts.
        assert!(Args::try_parse_from(["av-mesh", "--response-ms", "5"])
            .unwrap()
            .normalized()
            .is_ok());
        assert!(
            Args::try_parse_from(["av-mesh", "--part-us", "3000", "--response-ms", "10"])
                .unwrap()
                .normalized()
                .is_err()
        );
    }

    fn encode_test_timed_opaque_part(
        stream_id: u64,
        sequence: u64,
        metadata: &[(&str, String)],
    ) -> Bytes {
        let payload = format!("opaque-part-{stream_id}-{sequence}").into_bytes();
        let key = media_object::ObjectKey::for_payload(
            "default",
            stream_id.to_string(),
            "opaque-audio",
            0,
            0,
            sequence,
            1,
            &payload,
        )
        .unwrap();
        let mut builder = MediaObject::builder(key, ObjectKind::Media, payload.clone())
            .with_metadata("container", b"opaque".to_vec())
            .with_metadata("payload-format", b"opaque-part-v1".to_vec())
            .with_metadata("content-type", b"application/octet-stream".to_vec())
            .with_metadata("file-extension", b"bin".to_vec());
        for (name, value) in metadata {
            builder = builder.with_metadata(*name, value.clone().into_bytes());
        }
        Bytes::from(media_object::encode(&builder.build().unwrap()).unwrap())
    }

    fn timed_test_object(metadata: &[(&str, &str)]) -> MediaObject {
        let payload = b"part".to_vec();
        let key = media_object::ObjectKey::for_payload(
            "default",
            "77",
            "opaque-audio",
            0,
            0,
            1,
            1,
            &payload,
        )
        .unwrap();
        let mut builder = MediaObject::builder(key, ObjectKind::Media, payload);
        for (name, value) in metadata {
            builder = builder.with_metadata(*name, value.as_bytes().to_vec());
        }
        builder.build().unwrap()
    }

    #[test]
    fn part_durations_and_stamps_prefer_the_exact_microsecond_keys() {
        // 2.5 ms Opus: the old key rounds to 3 ms; the new one is exact.
        let object = timed_test_object(&[("duration-ms", "3"), ("duration-us", "2500")]);
        assert_eq!(object_duration_us(&object), Some(2_500));
        // Samples at a rate, rounded to the microsecond.
        let object = timed_test_object(&[
            ("duration-ms", "0"),
            ("duration-samples", "12"),
            ("sample-rate", "48000"),
        ]);
        assert_eq!(object_duration_us(&object), Some(250));
        let object = timed_test_object(&[("duration-samples", "44"), ("sample-rate", "44100")]);
        assert_eq!(object_duration_us(&object), Some(998));
        // An older contributor: whole milliseconds.
        let object = timed_test_object(&[("duration-ms", "5")]);
        assert_eq!(object_duration_us(&object), Some(5_000));
        // A zero is no value.
        let object = timed_test_object(&[("duration-us", "0"), ("duration-ms", "0")]);
        assert_eq!(object_duration_us(&object), None);

        let stamp = |keys: &[(&str, &str)]| {
            let mut all = vec![("hls-msn", "7"), ("hls-part", "3")];
            all.extend_from_slice(keys);
            object_part_stamp(&timed_test_object(&all))
        };
        assert_eq!(
            stamp(&[
                ("hls-part-target-ms", "3"),
                ("hls-part-target-us", "2500"),
                ("hls-target-duration-ms", "1000"),
                ("hls-target-duration-us", "1000000"),
            ]),
            Some(PartStamp {
                msn: 7,
                part: 3,
                part_target_us: 2_500,
                target_duration_us: 1_000_000,
            })
        );
        // A 0.25 ms part target that the old key rounds to 0 is kept.
        assert_eq!(
            stamp(&[
                ("hls-part-target-ms", "0"),
                ("hls-part-target-us", "250"),
                ("hls-target-duration-ms", "1000"),
            ])
            .map(|stamp| (stamp.part_target_us, stamp.target_duration_us)),
            Some((250, 1_000_000))
        );
        assert_eq!(
            stamp(&[
                ("hls-part-target-ms", "5"),
                ("hls-target-duration-ms", "1000")
            ])
            .map(|stamp| (stamp.part_target_us, stamp.target_duration_us)),
            Some((5_000, 1_000_000))
        );
        assert_eq!(stamp(&[("hls-part-target-ms", "0")]), None);
    }

    /// The RFC 8216bis rules for parts that a standard player relies on.
    /// Returns the number of whole segments.
    fn assert_valid_ll_hls(playlist: &str) -> usize {
        use playlists::m3u8_manifest::parse_seconds_us;
        let attribute = |line: &str, name: &str| -> Option<String> {
            line.split(|c| c == ':' || c == ',')
                .find_map(|field| field.strip_prefix(&format!("{name}=")))
                .map(str::to_owned)
        };
        let mut part_target_us = None;
        let mut target_duration = None;
        let mut segment_parts: Vec<u64> = Vec::new();
        let mut whole_segments = 0;
        for line in playlist.lines() {
            if let Some(value) = line.strip_prefix("#EXT-X-TARGETDURATION:") {
                target_duration = value.parse::<u64>().ok();
            } else if line.starts_with("#EXT-X-PART-INF:") {
                part_target_us = attribute(line, "PART-TARGET").and_then(|v| parse_seconds_us(&v));
            } else if line.starts_with("#EXT-X-SERVER-CONTROL:") {
                let hold_back = attribute(line, "PART-HOLD-BACK")
                    .and_then(|v| parse_seconds_us(&v))
                    .expect("PART-HOLD-BACK");
                assert!(hold_back >= 2 * part_target_us.expect("PART-TARGET first"));
            } else if line.starts_with("#EXT-X-PART:") {
                segment_parts.push(
                    attribute(line, "DURATION")
                        .and_then(|v| parse_seconds_us(&v))
                        .expect("DURATION"),
                );
            } else if let Some(value) = line.strip_prefix("#EXTINF:") {
                let extinf_us = parse_seconds_us(value.trim_end_matches(',')).expect("EXTINF");
                let target = target_duration.expect("TARGETDURATION");
                assert!((extinf_us + 500_000) / 1_000_000 <= target, "{line}");
                if !segment_parts.is_empty() {
                    let part_target_us = part_target_us.unwrap();
                    assert_eq!(segment_parts.iter().sum::<u64>(), extinf_us, "{line}");
                    let last = segment_parts.len() - 1;
                    for (index, part_us) in segment_parts.iter().enumerate() {
                        assert!(*part_us <= part_target_us);
                        if index != last {
                            assert!(part_us * 100 >= part_target_us * 85);
                        }
                    }
                }
                segment_parts.clear();
                whole_segments += 1;
            }
        }
        whole_segments
    }

    async fn commit_timed_stamped_parts(
        cache: &LiveTsCache,
        stream_id: u64,
        part_us: u64,
        parts_per_segment: u64,
        parts: u64,
    ) {
        for sequence in 0..parts {
            let metadata = [
                ("duration-ms", (part_us / 1_000).to_string()),
                ("duration-us", part_us.to_string()),
                ("hls-msn", (sequence / parts_per_segment).to_string()),
                ("hls-part", (sequence % parts_per_segment).to_string()),
                ("hls-part-target-ms", (part_us / 1_000).to_string()),
                ("hls-part-target-us", part_us.to_string()),
                ("hls-target-duration-ms", "1000".to_string()),
                ("hls-target-duration-us", "1000000".to_string()),
            ];
            cache
                .commit_stream_payload(
                    stream_id,
                    encode_test_timed_opaque_part(stream_id, sequence, &metadata),
                )
                .await
                .unwrap();
        }
    }

    #[tokio::test]
    async fn a_playlist_of_two_and_a_half_millisecond_opus_parts_is_exact_and_valid() {
        let cache =
            LiveTsCache::with_slots(1, Duration::from_micros(2_500), 400, 4_800, 64, 2).await;
        // Two whole segments of one second and the start of a third.
        commit_timed_stamped_parts(&cache, 77, 2_500, 400, 810).await;
        let playlist = cache.playlist_for_stream_id(77).await;
        assert!(playlist.contains("#EXT-X-TARGETDURATION:1\n"), "{playlist}");
        assert!(playlist.contains("#EXT-X-PART-INF:PART-TARGET=0.0025\n"));
        assert!(playlist.contains("PART-HOLD-BACK=0.0075,HOLD-BACK=3.000"));
        assert!(playlist.contains("#EXT-X-PART:DURATION=0.0025,URI=\"part809.bin\""));
        // 400 parts of 2.5 ms are one second exactly, where 400 parts of a
        // rounded 3 ms were 1.2 s.
        assert!(playlist.contains("#EXTINF:1.000,\nseg0.bin"));
        assert!(playlist.contains("#EXTINF:1.000,\nseg1.bin"));
        assert!(!playlist.contains("DURATION=0.003"));
        assert_eq!(assert_valid_ll_hls(&playlist), 2);
        // The gap hold of one second is 400 parts of this stream, not 334.
        assert_eq!(cache.state.read().await.stream_part_us(77), 2_500);
        assert_eq!(cache.state.read().await.stream_part_target_us(77), 2_500);

        // A floor for PART-HOLD-BACK, for players that need more room.
        cache.set_part_hold_back_floor(Duration::from_millis(250));
        cache.invalidate_cached_playlist(77);
        let playlist = cache.playlist_for_stream_id(77).await;
        assert!(
            playlist.contains("PART-HOLD-BACK=0.250,HOLD-BACK=3.000"),
            "{playlist}"
        );
        assert_eq!(assert_valid_ll_hls(&playlist), 2);
    }

    #[tokio::test]
    async fn playlists_of_one_half_and_quarter_millisecond_pcm_parts_are_valid() {
        for (part_us, rendered) in [(1_000, "0.001"), (500, "0.0005"), (250, "0.00025")] {
            let parts_per_segment = 1_000_000 / part_us;
            let cache = LiveTsCache::with_slots(
                1,
                Duration::from_micros(part_us),
                parts_per_segment as usize,
                (parts_per_segment * 3) as usize,
                64,
                2,
            )
            .await;
            commit_timed_stamped_parts(
                &cache,
                77,
                part_us,
                parts_per_segment,
                parts_per_segment * 2 + 3,
            )
            .await;
            let playlist = cache.playlist_for_stream_id(77).await;
            assert!(
                playlist.contains(&format!("#EXT-X-PART-INF:PART-TARGET={rendered}\n")),
                "{part_us}"
            );
            assert!(playlist.contains(&format!("#EXT-X-PART:DURATION={rendered},")));
            assert!(!playlist.contains("=0.000,"), "{part_us}");
            assert!(playlist.contains("#EXTINF:1.000,\nseg1.bin"), "{part_us}");
            assert_eq!(assert_valid_ll_hls(&playlist), 2, "{part_us}");
        }
    }

    /// Microseconds that a playlist covers: its whole segments and the parts
    /// of the open one.
    fn playlist_duration_us(playlist: &str) -> u64 {
        use playlists::m3u8_manifest::parse_seconds_us;
        let mut whole_us = 0;
        let mut open_us = 0;
        for line in playlist.lines() {
            if let Some(value) = line.strip_prefix("#EXTINF:") {
                whole_us += parse_seconds_us(value.trim_end_matches(',')).expect("EXTINF");
                open_us = 0;
            } else if let Some(rest) = line.strip_prefix("#EXT-X-PART:DURATION=") {
                open_us += parse_seconds_us(rest.split(',').next().unwrap()).expect("DURATION");
            }
        }
        whole_us + open_us
    }

    #[tokio::test]
    async fn short_pcm_parts_on_a_node_of_two_and_a_half_ms_parts_keep_a_window_in_time() {
        // The default node: 2.5 ms nominal parts, 1 s segments, a 12 s
        // window, and a ring sized for parts down to 0.25 ms.
        let ring = cache_ring_parts(2_500, 400, 4_800, DEFAULT_MIN_PART_US);
        assert_eq!(ring, 60_000);
        assert_eq!(cache_ring_parts(2_500, 400, 4_800, 0), 19_200);
        assert_eq!(cache_ring_parts(2_500, 400, 4_800, 2_500), 19_200);
        for (part_us, window_parts, seconds) in [(500, 24_000, 5), (250, 44_000, 5)] {
            let cache =
                LiveTsCache::with_ring(1, Duration::from_micros(2_500), 400, 4_800, 64, 2, ring)
                    .await;
            let parts_per_segment = 1_000_000 / part_us;
            commit_timed_stamped_parts(
                &cache,
                77,
                part_us,
                parts_per_segment,
                parts_per_segment * seconds + 3,
            )
            .await;
            {
                let state = cache.state.read().await;
                // 12 s of these parts, or as many as the ring holds beside
                // the three target durations kept after the window; not the
                // 4,800 parts (2.4 s, 1.2 s) of the nominal window.
                assert_eq!(
                    state.stream_window_parts(77, 4_800),
                    window_parts,
                    "{part_us}"
                );
                assert!(state.stream_retained_parts(77, 4_800) <= ring, "{part_us}");
            }
            let playlist = cache.playlist_for_stream_id(77).await;
            assert!(playlist.contains("#EXT-X-TARGETDURATION:1\n"), "{part_us}");
            assert!(playlist.contains("HOLD-BACK=3.000"), "{part_us}");
            // Every committed second is still listed: five whole segments
            // and the open one.
            assert_eq!(
                assert_valid_ll_hls(&playlist),
                seconds as usize,
                "{part_us}"
            );
            assert!(playlist.contains("#EXT-X-MEDIA-SEQUENCE:0\n"), "{part_us}");
            assert!(
                playlist_duration_us(&playlist) >= 3 * 1_000_000,
                "{part_us}: {} µs",
                playlist_duration_us(&playlist)
            );
            // Parts are listed for the last three target durations only.
            assert!(!playlist.contains("URI=\"part0.bin\""), "{part_us}");
        }
    }

    #[test]
    fn the_window_of_a_stream_of_short_parts_follows_time_up_to_the_ring() {
        let declare = |part_us: u32, target_us: u32| {
            let mut state = LiveState::new();
            state.nominal_part_us = 2_500;
            state.ring_parts = 60_000;
            state.stream_declared_us.insert(77, (part_us, target_us));
            state
        };
        // Nominal and longer parts keep the configured count at most.
        assert_eq!(
            declare(2_500, 1_000_000).stream_window_parts(77, 4_800),
            4_800
        );
        assert_eq!(
            declare(33_367, 2_000_000).stream_window_parts(77, 4_800),
            560
        );
        // 1 ms parts: 12 s.
        assert_eq!(
            declare(1_000, 1_000_000).stream_window_parts(77, 4_800),
            12_000
        );
        // A ring of four nominal windows only: still three target durations
        // for 0.25 ms parts, where the ring holds them.
        let mut state = declare(250, 1_000_000);
        state.ring_parts = 19_200;
        let window = state.stream_window_parts(77, 4_800);
        assert_eq!(window, 12_000);
        assert!(state.stream_retained_parts(77, 4_800) <= 19_200);
        // A stream without stamps of short parts keeps four of its windows
        // in the ring.
        let mut state = LiveState::new();
        state.nominal_part_us = 2_500;
        state.ring_parts = 60_000;
        state.stream_max_part_duration_us.insert(77, 250);
        assert_eq!(state.stream_window_parts(77, 4_800), 15_000);
        state.ring_parts = 0;
        assert_eq!(state.stream_window_parts(77, 4_800), 4_800);
    }

